        private static readonly Rect LowerStagingField = new(-5.65f, -10.05f, 11.30f, 2.75f);
        // Terrain is explicit game data.  It is deliberately not inferred from the map pixels:
        // that was the source of the old "a grassy road looks like a hill" and black-mask bugs.
        // A zone is an impassable cliff for ground units, but a separate deployable island for a
        // unit that is summoned on it.  The oval footprint matches the visible raised plateaus.
        private readonly struct HighGroundZone
        {
            public readonly Vector2 Center;
            public readonly Vector2 Radius;
            public readonly Vector2[] Contour;

            public HighGroundZone(float x, float y, float radiusX, float radiusY)
            {
                Center = new Vector2(x, y);
                Radius = new Vector2(radiusX, radiusY);
                Contour = null;
            }

            public HighGroundZone(Vector2 center, Vector2[] contour)
            {
                Center = center;
                Contour = contour;
                var radius = Vector2.zero;
                foreach (var point in contour)
                {
                    radius.x = Mathf.Max(radius.x, Mathf.Abs(point.x - center.x));
                    radius.y = Mathf.Max(radius.y, Mathf.Abs(point.y - center.y));
                }
                Radius = radius;
            }

            public bool Contains(Vector2 point, float inset = 0f)
            {
                if (Contour != null && Contour.Length >= 3)
                    return PointInside(InsetContour(inset), point);
                var radiusX = Mathf.Max(.08f, Radius.x - inset);
                var radiusY = Mathf.Max(.08f, Radius.y - inset);
                var delta = point - Center;
                return delta.x * delta.x / (radiusX * radiusX) +
                       delta.y * delta.y / (radiusY * radiusY) <= 1f;
            }

            public Vector2 NearestInside(Vector2 requested, float inset)
            {
                if (Contour == null || Contour.Length < 3)
                {
                    var usableRadius = new Vector2(Mathf.Max(.08f, Radius.x - inset),
                        Mathf.Max(.08f, Radius.y - inset));
                    var delta = requested - Center;
                    var normalized = delta.x * delta.x / (usableRadius.x * usableRadius.x) +
                                     delta.y * delta.y / (usableRadius.y * usableRadius.y);
                    if (normalized <= 1f) return requested;
                    return delta.sqrMagnitude < .0001f
                        ? Center
                        : Center + delta / Mathf.Sqrt(normalized) * .985f;
                }

                var contour = InsetContour(inset);
                if (PointInside(contour, requested)) return requested;
                var closest = Center;
                var best = float.MaxValue;
                for (var i = 0; i < contour.Length; i++)
                {
                    var a = contour[i];
                    var b = contour[(i + 1) % contour.Length];
                    var segment = b - a;
                    var t = segment.sqrMagnitude < .000001f
                        ? 0f
                        : Mathf.Clamp01(Vector2.Dot(requested - a, segment) / segment.sqrMagnitude);
                    var candidate = a + segment * t;
                    var distance = (candidate - requested).sqrMagnitude;
                    if (distance >= best) continue;
                    best = distance;
                    closest = candidate;
                }
                return Vector2.Lerp(closest, Center, .012f);
            }

            private Vector2[] InsetContour(float inset)
            {
                if (Contour == null || inset <= .0001f) return Contour;
                var result = new Vector2[Contour.Length];
                for (var i = 0; i < Contour.Length; i++)
                {
                    var delta = Contour[i] - Center;
                    result[i] = Center + delta * Mathf.Clamp01((delta.magnitude - inset) /
                                                                Mathf.Max(.001f, delta.magnitude));
                }
                return result;
            }

            private static bool PointInside(IReadOnlyList<Vector2> contour, Vector2 point)
            {
                if (contour == null || contour.Count < 3) return false;
                var inside = false;
                for (int i = 0, j = contour.Count - 1; i < contour.Count; j = i++)
                {
                    var a = contour[i];
                    var b = contour[j];
                    if ((a.y > point.y) == (b.y > point.y)) continue;
                    var crossingX = (b.x - a.x) * (point.y - a.y) / (b.y - a.y) + a.x;
                    if (point.x < crossingX) inside = !inside;
                }
                return inside;
            }
        }

