        private float BottomHudHeight => showFormationPanel && Phase == GamePhase.Preparation ? 178f :
            Phase == GamePhase.Battle && activeAugmentReadyAt.Count > 0 ? 132f : 76f;
        private float TopHudHeight => FindBoss() != null ? 146f : 112f;
        private float UiScale => Mathf.Max(.65f, Screen.width / 540f);
        private float GuiWidth => Screen.width / UiScale;
        private float GuiHeight => Screen.height / UiScale;
        private Rect SafeGuiRect
        {
            get
            {
                var scale = UiScale;
                if (simulateSafeArea)
                    return new Rect(34f / scale, 54f / scale,
                        Mathf.Max(1f, Screen.width - 68f) / scale,
                        Mathf.Max(1f, Screen.height - 104f) / scale);
                var safe = Screen.safeArea;
                return new Rect(safe.xMin / scale, (Screen.height - safe.yMax) / scale,
                    safe.width / scale, safe.height / scale);
            }
        }

        private bool MainMenuBaseInputEnabled =>
            !showSettings && !showMissionPanel && !showShopPanel && !showSkinPanel &&
            !showGuidePanel && !showExitConfirm && !showResumePrompt &&
            (IsQaMode() || Time.unscaledTime >= mainMenuInputReadyAt);

