        private void ConfigureSettingsPreview()
        {
            showMainMenu = true;
            showSettings = true;
            showSkinPanel = false;
        }

        private void ConfigureSkinVaultPreview()
        {
            foreach (var product in monetization.Products.Where(product =>
                         product.Category != ShopCategory.Utility))
                monetization.GrantForQa(product.Id);
            showMainMenu = true;
            showSkinPanel = true;
            skinCategory = HasCommandLineArgument("-qaSkinUnitView")
                ? ShopCategory.Unit
                : ShopCategory.Castle;
            skinUnit = HasCommandLineArgument("-qaSkinArcherView")
                ? UnitArchetype.Archer
                : HasCommandLineArgument("-qaSkinAreaMageView")
                    ? UnitArchetype.AreaMage
                    : HasCommandLineArgument("-qaSkinMeleeView")
                        ? UnitArchetype.Melee
                        : HasCommandLineArgument("-qaSkinSingleMageView")
                            ? UnitArchetype.SingleMage
                            : HasCommandLineArgument("-qaSkinMusketeerView")
                                ? UnitArchetype.Musketeer
                                : UnitArchetype.Tank;
        }

        private IEnumerator QaAugmentRevamp250Routine()
        {
            yield return null;
            var tiers = new[]
            {
                AugmentTier.Bronze, AugmentTier.Silver, AugmentTier.Gold,
                AugmentTier.Platinum, AugmentTier.Diamond
            };
            var forbiddenGateKeys = new HashSet<string>
            {
                "GateHeal", "GateRepair", "LastStand", "Fortress", "GateHealMajor", "ActiveFortify"
            };
            var allTemplates = tiers.SelectMany(tier => GetAugmentPool(tier)
                    .Concat(FixedRecruitAugments(tier)))
                .GroupBy(card => card.EffectKey).Select(group => group.First()).ToArray();
            var gateCardsRemoved = allTemplates.All(card => !forbiddenGateKeys.Contains(card.EffectKey));

            var rolesComplete = RoleFor(UnitArchetype.Tank) == DefenderRole.Tank &&
                                RoleFor(UnitArchetype.Melee) == DefenderRole.Melee &&
                                RoleFor(UnitArchetype.Lancer) == DefenderRole.Melee &&
                                RoleFor(UnitArchetype.Archer) == DefenderRole.Ranged &&
                                RoleFor(UnitArchetype.Bombardier) == DefenderRole.Ranged &&
                                RoleFor(UnitArchetype.Musketeer) == DefenderRole.Ranged &&
                                RoleFor(UnitArchetype.AreaMage) == DefenderRole.Mage &&
                                RoleFor(UnitArchetype.SingleMage) == DefenderRole.Mage &&
                                RoleFor(UnitArchetype.Druid) == DefenderRole.Support &&
                                RoleFor(UnitArchetype.Oracle) == DefenderRole.Support;

            var goldRecruits = FixedRecruitAugments(AugmentTier.Gold).Select(card => card.EffectKey)
                .OrderBy(key => key).SequenceEqual(new[] { "UnlockBombardier", "UnlockMusketeer" });
            var platinumRecruits = FixedRecruitAugments(AugmentTier.Platinum).Select(card => card.EffectKey)
                .OrderBy(key => key).SequenceEqual(new[] { "UnlockDruid", "UnlockLancer" });
            var diamondRecruit = FixedRecruitAugments(AugmentTier.Diamond).Single().EffectKey == "UnlockOracle";
            var tierSeparation = TierPower(AugmentTier.Bronze) <= .24f &&
                                 TierPower(AugmentTier.Diamond) <= 1.28f &&
                                 TierPower(AugmentTier.Diamond) / TierPower(AugmentTier.Bronze) >= 5f;

            acquiredAugments.Clear();
            var uniqueKeys = allTemplates.Where(card => IsUniqueAugmentKey(card.EffectKey))
                .Select(card => card.EffectKey).Distinct().ToArray();
            var uniqueSuppression = true;
            foreach (var key in uniqueKeys)
            {
                var tier = tiers.First(candidate => GetAugmentPool(candidate)
                    .Concat(FixedRecruitAugments(candidate)).Any(card => card.EffectKey == key));
                uniqueSuppression &= GetAvailableAugmentTemplates(tier).Any(card => card.EffectKey == key);
                acquiredAugments[key] = new AugmentOffer(key, key, key, tier, TierPower(tier));
                uniqueSuppression &= GetAvailableAugmentTemplates(tier).All(card => card.EffectKey != key);
            }
            var fallbackPoolsSafe = tiers.All(tier => GetAvailableAugmentTemplates(tier).Count >= 3);

            augmentPower.Clear();
            augmentPower["TankUnbroken"] = TierPower(AugmentTier.Diamond);
            augmentPower["MeleeEdge"] = TierPower(AugmentTier.Bronze);
            augmentPower["RangedBarrage"] = TierPower(AugmentTier.Diamond);
            augmentPower["MageCataclysm"] = TierPower(AugmentTier.Diamond);
            augmentPower["SupportAscension"] = TierPower(AugmentTier.Diamond);
            var tank = new GameObject("QA 250 Tank").AddComponent<PlayerUnit>();
            tank.Initialize(this, UnitArchetype.Tank, definitions[UnitArchetype.Tank], new Vector2(-2f, -5f));
