        private IEnumerator QaAugmentBalance251Routine()
        {
            yield return null;
            var tiers = new[]
            {
                AugmentTier.Bronze, AugmentTier.Silver, AugmentTier.Gold,
                AugmentTier.Platinum, AugmentTier.Diamond
            };
            var allTemplates = tiers.SelectMany(tier => GetAugmentPool(tier).Concat(FixedRecruitAugments(tier)))
                .GroupBy(card => card.EffectKey).Select(group => group.First()).ToArray();
            var poolCounts = tiers.Select(tier => GetAugmentPool(tier).Length + FixedRecruitAugments(tier).Count())
                .ToArray();
            var poolsExpanded = poolCounts.SequenceEqual(new[] { 12, 13, 15, 14, 14 }) &&
                                allTemplates.Length == 68;

            float DiamondRate(AugmentTier previous, bool boss, int pity)
            {
                const int samples = 20000;
                var diamonds = 0;
                for (var i = 0; i < samples; i++)
                    if (ResolveAugmentTier(previous, boss, pity, (i + .5f) / samples) == AugmentTier.Diamond)
                        diamonds++;
                return diamonds / (float)samples;
            }

            var normalDiamondMax = tiers.Max(tier => DiamondRate(tier, false, 0));
            var bossDiamondMax = tiers.Max(tier => DiamondRate(tier, true, 0));
            var pityDiamond = DiamondRate(AugmentTier.Bronze, false, 4);
            var diamondRare = normalDiamondMax <= .021f && bossDiamondMax <= .04f &&
                              pityDiamond >= .029f && pityDiamond <= .031f;
            var powerTuned = Mathf.Abs(TierPower(AugmentTier.Bronze) - .22f) < .001f &&
                             Mathf.Abs(TierPower(AugmentTier.Diamond) - 1.16f) < .001f &&
                             TierPower(AugmentTier.Diamond) / TierPower(AugmentTier.Bronze) < 5.5f;

            augmentPower.Clear();
            augmentPower["SupportAscension"] = TierPower(AugmentTier.Diamond);
            augmentPower["SupportMiracle"] = TierPower(AugmentTier.Diamond);
            var support = new GameObject("QA 251 Support").AddComponent<PlayerUnit>();
            support.Initialize(this, UnitArchetype.Oracle, definitions[UnitArchetype.Oracle], new Vector2(2f, -5f));
            var supportIdentity = Mathf.Abs(GetRoleDamageMultiplier(support) - 1f) < .001f &&
                                  GetRoleSkillCooldownMultiplier(support) < 1f;

            augmentPower.Clear();
            augmentPower["TankAnchor"] = TierPower(AugmentTier.Bronze);
            augmentPower["MeleeMarch"] = TierPower(AugmentTier.Bronze);
            augmentPower["RangedSpotter"] = TierPower(AugmentTier.Bronze);
            augmentPower["MageConserve"] = TierPower(AugmentTier.Bronze);
            var tank = new GameObject("QA 251 Tank").AddComponent<PlayerUnit>();
            tank.Initialize(this, UnitArchetype.Tank, definitions[UnitArchetype.Tank], new Vector2(-2f, -5f));
            tank.Stop();
            var melee = new GameObject("QA 251 Melee").AddComponent<PlayerUnit>();
            melee.Initialize(this, UnitArchetype.Melee, definitions[UnitArchetype.Melee], new Vector2(-1f, -5f));
            var ranged = new GameObject("QA 251 Ranged").AddComponent<PlayerUnit>();
            ranged.Initialize(this, UnitArchetype.Archer, definitions[UnitArchetype.Archer], new Vector2(0f, -5f));
            var mage = new GameObject("QA 251 Mage").AddComponent<PlayerUnit>();
            mage.Initialize(this, UnitArchetype.AreaMage, definitions[UnitArchetype.AreaMage], new Vector2(1f, -5f));
            var roleMechanics = GetRoleDefenseBonus(tank) > 0f && GetRoleMoveSpeedMultiplier(melee) > 1f &&
                                GetRoleDetectionRangeBonus(ranged) > 0f &&
                                GetRoleSkillCooldownMultiplier(mage) < 1f;

            acquiredAugments.Clear();
            var uniqueKeys = allTemplates.Where(card => IsUniqueAugmentKey(card.EffectKey))
                .Select(card => card.EffectKey).Distinct().ToArray();
            var uniqueSuppression = true;
            foreach (var key in uniqueKeys)
            {
                var tier = tiers.First(candidate => GetAugmentPool(candidate).Concat(FixedRecruitAugments(candidate))
                    .Any(card => card.EffectKey == key));
                acquiredAugments[key] = new AugmentOffer(key, key, key, tier, TierPower(tier));
                uniqueSuppression &= GetAvailableAugmentTemplates(tier).All(card => card.EffectKey != key);
            }

            var supportKeys = new[]
            {
                "SupportTriage", "SupportCooldown", "SupportRenewal", "SupportAura", "SupportHaste",
                "SupportSanctuary", "SupportRescue", "SupportAscension", "SupportMiracle"
            };
            GameLocalization.Current = GameLanguage.Korean;
            var koreanSupportClean = supportKeys.All(key =>
                !GameLocalization.AugmentDescription(key, 1f, "__MISSING__").Contains("서포터 피해"));
            var koreanComplete = allTemplates.All(card =>
                GameLocalization.AugmentName(card.EffectKey, "__MISSING__") != "__MISSING__" &&
                GameLocalization.AugmentDescription(card.EffectKey, 1f, "__MISSING__") != "__MISSING__");
            GameLocalization.Current = GameLanguage.English;
            var englishSupportClean = supportKeys.All(key =>
                !GameLocalization.AugmentDescription(key, 1f, "__MISSING__").Contains("Support damage"));
            var englishComplete = allTemplates.All(card =>
                GameLocalization.AugmentName(card.EffectKey, "__MISSING__") != "__MISSING__" &&
                GameLocalization.AugmentDescription(card.EffectKey, 1f, "__MISSING__") != "__MISSING__");
            GameLocalization.Current = GameLanguage.Korean;
            var localizationComplete = koreanSupportClean && englishSupportClean && koreanComplete && englishComplete;

            var passed = poolsExpanded && diamondRare && powerTuned && supportIdentity && roleMechanics &&
                         uniqueSuppression && uniqueKeys.Length == 24 && localizationComplete;
            Debug.Log($"QA_AUGMENT_BALANCE_251 cards={allTemplates.Length} " +
                      $"pools={string.Join(":", poolCounts)} support={supportIdentity} " +
                      $"power={powerTuned}:{TierPower(AugmentTier.Bronze):0.00}-{TierPower(AugmentTier.Diamond):0.00} " +
                      $"chance={diamondRare}:{normalDiamondMax:0.0000}:{bossDiamondMax:0.0000}:{pityDiamond:0.0000} " +
                      $"roles={roleMechanics} unique={uniqueSuppression}:{uniqueKeys.Length} " +
                      $"locale={localizationComplete}:{koreanComplete}:{englishComplete}");
            Application.Quit(passed ? 0 : 91);
        }

