                      $"skin={defaultHasNoSignature}:{purchasedHasSilhouette}:{defaultRestored} " +
                      $"challenges={longTermChallenges}:{items.Count} modal={skinModalBlocksMenu}");
            Application.Quit(passed ? 0 : 61);
