            var bosses = bossVariantSprites.Count == 10 && bossBackVariantSprites.Count == 10 &&
                         Enumerable.Range(0, 10).All(chapter =>
                         {
                             var profile = EnemyVariantCatalog.ForChapterStage(chapter, 4);
                             return bossVariantSprites.ContainsKey(profile.Id) &&
                                    bossBackVariantSprites.ContainsKey(profile.Id);
                         });
            var waveCurve = WaveEnemyCount(1) == 12 && WaveEnemyCount(5) == 24 &&
                            WaveEnemyCount(6) == 22 && WaveEnemyCount(50) == 88 &&
                            Enumerable.Range(0, 10).All(chapter =>
                            {
                                var opener = WaveEnemyCount(chapter * 5 + 1);
                                return WaveEnemyCount(chapter * 5 + 2) > opener &&
                                       WaveEnemyCount(chapter * 5 + 3) > WaveEnemyCount(chapter * 5 + 2) &&
                                       WaveEnemyCount(chapter * 5 + 4) > WaveEnemyCount(chapter * 5 + 3) &&
                                       WaveEnemyCount(chapter * 5 + 5) >= opener;
                            });
            var inwardPaths = paths.Count >= 2 &&
                              Mathf.Abs(paths[0][0].x) > Mathf.Abs(paths[0][70].x) &&
                              Mathf.Abs(paths[1][0].x) > Mathf.Abs(paths[1][70].x);
            var pathSamplesSafe = paths.All(path =>
                path.Where((_, index) => index % 7 == 0).All(point => IsAuthoredPathOffsetSafe(point)));
            var recruitTiers = FixedRecruitAugments(AugmentTier.Gold).Select(card => card.EffectKey)
                                   .OrderBy(key => key).SequenceEqual(new[]
                                   { "UnlockBombardier", "UnlockMusketeer" }) &&
                               FixedRecruitAugments(AugmentTier.Platinum).Select(card => card.EffectKey)
                                   .OrderBy(key => key).SequenceEqual(new[]
                                   { "UnlockDruid", "UnlockLancer" }) &&
                               FixedRecruitAugments(AugmentTier.Diamond).Single().EffectKey == "UnlockOracle";

