            var jellyBoss = new GameObject("QA 221 King Slime").AddComponent<EnemyUnit>();
            jellyBoss.Initialize(this, 0, 2600f, true, 0, jellyBossProfile.CombatClass, jellyBossProfile);
            var bossHudOnly = jellyBoss.HasBossPresentation && !jellyBoss.HasWorldHealthBar &&
                              jellyBoss.BossAuraAlpha <= .001f;
            var jellyMageProfile = EnemyVariantCatalog.ForChapterStage(0, 2);
            var jellyMage = new GameObject("QA 221 Jelly Mage").AddComponent<EnemyUnit>();
            jellyMage.Initialize(this, 1, 300f, false, 0, jellyMageProfile.CombatClass, jellyMageProfile);
            var directional = jellyMage.HasDirectionalBackPresentation &&
                              jellyMage.AnimationFrameCount >= 7;

            var passed = menuArt && bosses && waveCurve && inwardPaths && pathSamplesSafe &&
                         recruitTiers && bossHudOnly && directional;
            Debug.Log($"QA_RELEASE_221 menu={menuArt} bosses={bosses}:{bossVariantSprites.Count}/{bossBackVariantSprites.Count} " +
                      $"waves={waveCurve}:{WaveEnemyCount(1)}-{WaveEnemyCount(50)} " +
                      $"paths={inwardPaths}:{pathSamplesSafe} recruits={recruitTiers} " +
                      $"bossHud={bossHudOnly} direction={directional}");
            Application.Quit(passed ? 0 : 62);
        }

