            var bossProfile = EnemyVariantCatalog.ForChapterStage(4, 4);
            var boss = new GameObject("QA 222 Native Boss").AddComponent<EnemyUnit>();
            boss.Initialize(this, 1, 2600f, true, 1, bossProfile.CombatClass, bossProfile);
            enemies.Add(boss);
            var bossNativeColor = Vector4.Distance(boss.PresentationTint, Color.white) < .015f &&
                                  !boss.HasForbiddenCircularOverlay;
            var generousBossHit = boss.ContainsPointer(boss.Position + Vector2.up * boss.Radius * 3.15f);

            var hillOrigin = HighGroundZones[0].Center;
            var hillClone = FindOpenPositionNear(hillOrigin, .25f);
            var groundOrigin = paths[0][Mathf.Min(52, paths[0].Count - 1)];
            var groundClone = FindOpenPositionNear(groundOrigin, .25f);
            var cloneTerrainLocked = hillClone.HasValue && groundClone.HasValue &&
                                     GetHighGroundZone(hillClone.Value, .1f) ==
                                     GetHighGroundZone(hillOrigin, .1f) &&
                                     GetHighGroundZone(groundClone.Value, .1f) < 0 &&
                                     GetNavigationRegion(groundClone.Value) == GetNavigationRegion(groundOrigin);

