            recovery.ForcePositionForQa(HighGroundZones[3].Center);

            Phase = GamePhase.Battle;
            gateHealth = GateMaxHealth;
            minor.ForceAtGateForQa();
            activeAugmentReadyAt["ActiveFreeze"] = 0f;
            augmentPower["ActiveFreeze"] = TierPower(AugmentTier.Platinum);
            var gateBeforeFreeze = gateHealth;
            UseActiveAugment("ActiveFreeze");
            yield return new WaitForSeconds(.45f);
            var completeFreeze = EnemyActionsFrozen && minor.IsTimeFrozen &&
                                 Mathf.Abs(gateHealth - gateBeforeFreeze) < .01f;
            yield return new WaitForSeconds(1.35f);
            var forwardRecovery = IsWalkableWithClearance(recovery.Position, recovery.Radius * .42f) &&
                                  !IsHighGround(recovery.Position) && recovery.StallRecoveryCount >= 0;

            var augmentTuned = TierPower(AugmentTier.Bronze) <= .24f &&
                               TierPower(AugmentTier.Diamond) <= 1.28f;
            var passed = koreanLocalization && englishLocalization && generatedArt && noCircleOverlay &&
                         bossNativeColor && generousBossHit && cloneTerrainLocked && redesignedSkin &&
                         completeFreeze && forwardRecovery && augmentTuned;
