                      $"circle={noCircleOverlay} boss={bossNativeColor}:hit={generousBossHit} " +
                      $"clone={cloneTerrainLocked} skin={redesignedSkin}:{skinned.SkinSignaturePartCount} " +
                      $"freeze={completeFreeze} recovery={forwardRecovery}:{recovery.Position} " +
                      $"augment={augmentTuned}:{TierPower(AugmentTier.Bronze):0.00}-{TierPower(AugmentTier.Diamond):0.00}");
            Application.Quit(passed ? 0 : 63);
        }

        private IEnumerator QaRelease223Routine()
        {
            yield return null;
            var roster = new[]
            {
                UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Archer,
                UnitArchetype.AreaMage, UnitArchetype.SingleMage, UnitArchetype.Bombardier,
                UnitArchetype.Lancer, UnitArchetype.Druid, UnitArchetype.Musketeer, UnitArchetype.Oracle
            };
            var directionalScaleStable = true;
            var directionalFramesComplete = true;
            var allSkinPairsLive = true;
            var distinctSkinPalettes = true;
            for (var index = 0; index < roster.Length; index++)
            {
                var archetype = roster[index];
                var actor = new GameObject($"QA 223 {archetype}").AddComponent<PlayerUnit>();
                actor.Initialize(this, archetype, definitions[archetype],
                    new Vector2(-4.2f + index * .85f, -5.7f));
                units.Add(actor);
                directionalScaleStable &= actor.DirectionScaleSpread < .001f;
                directionalFramesComplete &= actor.HasCompleteDirectionalAnimation;

                for (var variant = 1; variant <= 2; variant++)
                {
                    var suffix = variant == 1 ? ".a" : ".b";
                    var prefix = archetype switch
                    {
                        UnitArchetype.AreaMage => "area_mage",
                        UnitArchetype.SingleMage => "single_mage",
                        _ => archetype.ToString().ToLowerInvariant()
                    };
                    var product = monetization.FindProduct($"crownfront.unit.{prefix}{suffix}");
                    if (product == null)
                    {
                        allSkinPairsLive = false;
                        continue;
                    }
                    monetization.GrantForQa(product.Id);
                    monetization.Equip(product);
                    actor.RefreshCosmeticPresentation();
                    allSkinPairsLive &= actor.SkinVariant == variant &&
                                        actor.SkinSignaturePartCount >= 14 &&
                                        actor.HasAuthoredSkinPresentation;
                    distinctSkinPalettes &= actor.HasAuthoredSkinPresentation;
                }
                actor.AddExperience(9999f);
                directionalScaleStable &= actor.DirectionScaleSpread < .001f;
                directionalFramesComplete &= actor.HasCompleteDirectionalAnimation;
            }

            Phase = GamePhase.Battle;
            var targetProfile = EnemyVariantCatalog.ForChapterStage(0, 2);
            var target = new GameObject("QA 223 Focus Target").AddComponent<EnemyUnit>();
            target.Initialize(this, 0, 900f, false, 0, targetProfile.CombatClass, targetProfile);
            target.ForcePositionForQa(new Vector2(0f, -4.7f));
            enemies.Add(target);
            SelectOnly(units[0]);
            CommandAttack(target);
            var iconOnlyFocus = attackOrderTarget == target && AttackOrderMarkerPartCount >= 7 &&
                                !AttackOrderMarkerHasText;
            var noRoleBlocks = !target.HasPersistentRoleBlock;

            showMainMenu = false;
            showSystemMenu = true;
            showSettings = false;
            Time.timeScale = 0f;
            OpenSettingsFromSystemMenu();
            var settingsPaused = showSettings && !showSystemMenu &&
                                 Mathf.Approximately(Time.timeScale, 0f);
            CloseSettingsPanel();
            var settingsResumed = !showSettings && Mathf.Approximately(Time.timeScale, 1f);

            activeAugmentReadyAt["ActiveVolley"] = 0f;
            augmentPower["ActiveVolley"] = TierPower(AugmentTier.Silver);
            var activeBefore = activeSkillEffectCount;
            UseActiveAugment("ActiveVolley");
            var upgradedActiveVfx = activeSkillEffectCount == activeBefore + 1;
            var archerPreviewReady = archerSkinReferenceTexture != null &&
                                     archerSkinReferenceTexture.width >= 1024 &&
                                     archerSkinReferenceTexture.height >= 1024;

            var passed = directionalScaleStable && directionalFramesComplete &&
                         allSkinPairsLive && distinctSkinPalettes && iconOnlyFocus &&
                         noRoleBlocks && settingsPaused && settingsResumed &&
                         upgradedActiveVfx && archerPreviewReady;
            Debug.Log($"QA_RELEASE_223 direction={directionalScaleStable}:{directionalFramesComplete} " +
                      $"skins={allSkinPairsLive}:{distinctSkinPalettes}:preview={archerPreviewReady} " +
                      $"focus={iconOnlyFocus}:{AttackOrderMarkerPartCount}:text={AttackOrderMarkerHasText} " +
                      $"roleBlocks={noRoleBlocks} settings={settingsPaused}:{settingsResumed} " +
                      $"activeVfx={upgradedActiveVfx}:{activeSkillEffectCount}");
            Application.Quit(passed ? 0 : 64);
        }

