                new Rect(74f / 1254f, 669f / 1254f, 553f / 1254f, 485f / 1254f),
                new Rect(627f / 1254f, 627f / 1254f, 617f / 1254f, 601f / 1254f),
                new Rect(54f / 1254f, 56f / 1254f, 573f / 1254f, 511f / 1254f),
                new Rect(627f / 1254f, 0f, 617f / 1254f, 627f / 1254f)
            };
            var archerCropsValid = archerUvBounds.All(uv =>
                uv.xMin >= 0f && uv.yMin >= 0f && uv.xMax <= 1f && uv.yMax <= 1f);
            var previewRoster = new[]
            {
                UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Archer,
                UnitArchetype.AreaMage, UnitArchetype.SingleMage, UnitArchetype.Bombardier,
                UnitArchetype.Lancer, UnitArchetype.Druid, UnitArchetype.Musketeer, UnitArchetype.Oracle
            };
            var everyHeroPanelReady = previewRoster.All(unit =>
                GetUnitCardSprite(unit) != null && GetHeroSprite(unit) != null);
            var everySkinPairReady = previewRoster.All(unit =>
                monetization.Products.Count(product =>
                    product.Category == ShopCategory.Unit && product.TargetUnit == unit) == 2);

            monetization.GrantAllProductsForTesting();
            var qaUnlockReady = monetization.AllProductsOwnedForTesting &&
                                monetization.Products.All(product => monetization.IsOwned(product.Id));
            var castlePreviewContinuous = new Rect(0f, .54f, 1f, .46f).yMax <= 1f;
            var passed = slotsContained && archerCropsValid && everyHeroPanelReady &&
                         everySkinPairReady && qaUnlockReady && castlePreviewContinuous;
            Debug.Log($"QA_RELEASE_224 layout={slotsContained} archerCrop={archerCropsValid} " +
