                      $"unlockAll={qaUnlockReady}:{monetization.Products.Count} " +
                      $"castleSingleCrop={castlePreviewContinuous}");
            Application.Quit(passed ? 0 : 65);
        }

        private IEnumerator QaRelease225Routine()
        {
            yield return null;
            var roster = new[]
            {
                UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Archer,
                UnitArchetype.AreaMage, UnitArchetype.SingleMage, UnitArchetype.Bombardier,
                UnitArchetype.Lancer, UnitArchetype.Druid, UnitArchetype.Musketeer, UnitArchetype.Oracle
            };
            var allAuthoredSheetsLoaded = roster.All(HasAuthoredUnitSkin);
            var allFortyFormsReady = true;
            var allLiveEquipsAuthored = true;
            foreach (var archetype in roster)
            {
                for (var variant = 1; variant <= 2; variant++)
                {
                    var normal = GetAuthoredUnitSkinSprite(archetype, variant, false);
                    var hero = GetAuthoredUnitSkinSprite(archetype, variant, true);
                    allFortyFormsReady &= normal != null && hero != null &&
                                         normal.rect.width > 120f && normal.rect.height > 120f &&
                                         hero.rect.width > 120f && hero.rect.height > 120f &&
                                         normal.name != hero.name;
                    var prefix = archetype switch
                    {
                        UnitArchetype.AreaMage => "area_mage",
                        UnitArchetype.SingleMage => "single_mage",
                        _ => archetype.ToString().ToLowerInvariant()
                    };
                    var suffix = variant == 1 ? ".a" : ".b";
                    var product = monetization.FindProduct($"crownfront.unit.{prefix}{suffix}");
                    if (product == null)
                    {
                        allLiveEquipsAuthored = false;
                        continue;
                    }
                    monetization.GrantForQa(product.Id);
                    monetization.Equip(product);
                    var actor = new GameObject($"QA 225 {archetype} {variant}").AddComponent<PlayerUnit>();
                    actor.Initialize(this, archetype, definitions[archetype],
                        new Vector2(-3.8f + (int)archetype * .68f, -5.6f));
                    units.Add(actor);
                    actor.RefreshCosmeticPresentation();
                    allLiveEquipsAuthored &= actor.SkinVariant == variant &&
                                            actor.HasAuthoredSkinPresentation;
                    actor.AddExperience(9999f);
                    allLiveEquipsAuthored &= actor.IsHero && actor.HasAuthoredSkinPresentation;
                }
            }
            var passed = allAuthoredSheetsLoaded && allFortyFormsReady && allLiveEquipsAuthored;
            Debug.Log($"QA_RELEASE_225 sheets={allAuthoredSheetsLoaded}:{unitSkinReferenceTextures.Count} " +
                      $"forms={allFortyFormsReady}:40 live={allLiveEquipsAuthored} " +
                      "archerDefaultColor=original heroPreviewFacing=mirrored");
            Application.Quit(passed ? 0 : 66);
        }

        private IEnumerator QaRelease226Routine()
        {
            yield return null;
            var roster = new[]
            {
                (UnitArchetype.Tank, "tank"),
                (UnitArchetype.Melee, "melee"),
                (UnitArchetype.Archer, "archer"),
                (UnitArchetype.AreaMage, "area-mage"),
                (UnitArchetype.SingleMage, "single-mage"),
                (UnitArchetype.Bombardier, "bombardier"),
                (UnitArchetype.Lancer, "lancer"),
                (UnitArchetype.Druid, "druid"),
                (UnitArchetype.Musketeer, "musketeer"),
                (UnitArchetype.Oracle, "oracle")
            };
            var allCanonicalRigsLoaded = roster.All(entry =>
                Resources.Load<Texture2D>($"skin-rig-{entry.Item2}-v2") != null);
            var allFortyInvariantSets = authoredSkinAnimations.Count == 40;
            var allDirectionsComplete = true;
            var walkFramesArticulated = true;
            var attackWeaponsPixelInvariant = true;
            var alphaRetentionStable = true;
            var liveCardsAndActorsMatch = true;
            foreach (var entry in roster)
            for (var variant = 1; variant <= 2; variant++)
            foreach (var hero in new[] { false, true })
            {
                var set = GetAuthoredSkinAnimation(entry.Item1, variant, hero);
                if (set == null)
                {
                    allDirectionsComplete = false;
                    continue;
                }

                foreach (var frames in new[] { set.Down, set.Side, set.Up })
                {
                    allDirectionsComplete &= frames.Length == 17 &&
                                             frames.All(frame => frame != null) &&
                                             frames.All(frame => frame.texture.name.Contains("-invariant-"));
                    if (frames.Length < 17) continue;
                    walkFramesArticulated &= frames[1] != frames[0] && frames[3] != frames[0];
                    attackWeaponsPixelInvariant &= frames.Skip(8).All(frame => frame == frames[0]);
                    var idleAlpha = CountOpaquePixels(frames[0]);
                    var leftAlpha = CountOpaquePixels(frames[1]);
                    var rightAlpha = CountOpaquePixels(frames[3]);
                    var lower = idleAlpha * .94f;
                    var upper = idleAlpha * 1.06f;
                    alphaRetentionStable &= idleAlpha > 1000 &&
                                            leftAlpha >= lower && leftAlpha <= upper &&
                                            rightAlpha >= lower && rightAlpha <= upper;
                }

                var suffix = variant == 1 ? ".a" : ".b";
                var prefix = entry.Item1 switch
                {
                    UnitArchetype.AreaMage => "area_mage",
                    UnitArchetype.SingleMage => "single_mage",
                    _ => entry.Item1.ToString().ToLowerInvariant()
                };
                var product = monetization.FindProduct($"crownfront.unit.{prefix}{suffix}");
                if (product == null)
                {
                    liveCardsAndActorsMatch = false;
                    continue;
                }
                monetization.GrantForQa(product.Id);
                monetization.Equip(product);
                var card = GetEquippedUnitCardSprite(entry.Item1, hero);
                liveCardsAndActorsMatch &= card != null &&
                                           (card == set.Down[0] ||
                                            card.texture.name.Contains("-canonical-card"));
                var actor = new GameObject($"QA 226 {entry.Item1} {variant} {hero}").AddComponent<PlayerUnit>();
                actor.Initialize(this, entry.Item1, definitions[entry.Item1], new Vector2(0f, -5.6f));
                units.Add(actor);
                if (hero) actor.AddExperience(9999f);
                actor.RefreshCosmeticPresentation();
                liveCardsAndActorsMatch &= actor.SkinVariant == variant &&
                                           actor.HasCompleteDirectionalAnimation &&
                                           actor.HasAuthoredSkinPresentation &&
                                           actor.CurrentFrameTextureName.Contains("-invariant-");
            }

            var passed = allCanonicalRigsLoaded && allFortyInvariantSets &&
                         allDirectionsComplete && walkFramesArticulated &&
                         attackWeaponsPixelInvariant && alphaRetentionStable &&
                         liveCardsAndActorsMatch;
            Debug.Log($"QA_RELEASE_226 rigs={allCanonicalRigsLoaded}:10 sets={allFortyInvariantSets}:{authoredSkinAnimations.Count} " +
                      $"directions={allDirectionsComplete} walk={walkFramesArticulated} " +
                      $"weaponInvariant={attackWeaponsPixelInvariant} alpha={alphaRetentionStable} " +
                      $"cardLiveMatch={liveCardsAndActorsMatch}");
            Application.Quit(passed ? 0 : 67);
        }

        private IEnumerator QaRelease235Routine()
        {
            yield return null;
            var release237 = HasCommandLineArgument("-qaRelease237");
            var release236 = HasCommandLineArgument("-qaRelease236");
            var roster = new[]
            {
                UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Archer,
                UnitArchetype.AreaMage, UnitArchetype.SingleMage, UnitArchetype.Bombardier,
                UnitArchetype.Lancer, UnitArchetype.Druid, UnitArchetype.Musketeer, UnitArchetype.Oracle
            };

            var octants = System.Enum.GetValues(typeof(FacingOctant)).Cast<FacingOctant>().ToArray();
            var octantCoverage = octants.Select(EightWayFacing.VectorFor)
                .Select(EightWayFacing.FromVector).Distinct().Count() == 8;
            var base64 = roster.All(unit => unitDirectionalAnimations.TryGetValue(unit, out var set) &&
                set.SupportsEightDirections && octants.All(octant => set.FramesFor(octant).Length == 64));
            var hero64 = roster.All(unit => heroDirectionalAnimations.TryGetValue(unit, out var set) &&
                set.SupportsEightDirections && octants.All(octant => set.FramesFor(octant).Length == 64));
            var skins64 = authoredSkinAnimations.Count == 40 && authoredSkinAnimations.Values.All(set =>
                set.SupportsEightDirections && octants.All(octant => set.FramesFor(octant).Length == 64) &&
                set.Down.Take(16).Distinct().Count() >= 14 &&
                set.Down.Skip(16).Take(16).Distinct().Count() >= 14 &&
                set.Down.Skip(32).Take(16).Distinct().Count() >= 14 &&
                set.Down.Skip(48).Take(16).Distinct().Count() >= 14);
            var enemies72 = enemyAnimationSets.Count >= 8 &&
                            enemyAnimationSets.Values.All(frames => frames.Length == 72);

            int CardMetric(Sprite sprite, string marker)
            {
                var name = sprite?.texture?.name ?? string.Empty;
                var start = name.LastIndexOf(marker, StringComparison.Ordinal);
                if (start < 0) return -1;
                start += marker.Length;
                var end = start;
                while (end < name.Length && char.IsDigit(name[end])) end++;
                return int.TryParse(name.Substring(start, end - start), out var value) ? value : -1;
            }

            var skinCardGeometry = canonicalSkinCardSprites.Count == 40;
            var defaultCardGeometry = canonicalDefaultCardSprites.Count == 20;
            foreach (var unit in roster)
            {
                foreach (var variant in new[] { 1, 2 })
                {
                    var normalKey = AuthoredSkinAnimationKey(unit, variant, false);
                    var heroKey = AuthoredSkinAnimationKey(unit, variant, true);
                    canonicalSkinCardSprites.TryGetValue(normalKey, out var normal);
                    canonicalSkinCardSprites.TryGetValue(heroKey, out var hero);
                    var normalHeight = CardMetric(normal, "-h");
                    var heroHeight = CardMetric(hero, "-h");
                    Debug.Log($"QA_CARD_METRIC skin={unit}:{variant} normal={normalHeight} hero={heroHeight} " +
                              $"normalRect={normal?.rect.size} heroRect={hero?.rect.size}");
                    skinCardGeometry &= normal != null && hero != null &&
                                        normal.rect.size == new Vector2(384f, 320f) &&
                                        hero.rect.size == new Vector2(384f, 320f) &&
                                        CardMetric(normal, "-b") == 24 && CardMetric(hero, "-b") == 24 &&
                                        normalHeight >= 178 && heroHeight >= normalHeight + 10;
                }
                canonicalDefaultCardSprites.TryGetValue($"{unit}:0:0", out var defaultNormal);
                canonicalDefaultCardSprites.TryGetValue($"{unit}:0:1", out var defaultHero);
                var defaultNormalHeight = CardMetric(defaultNormal, "-h");
                var defaultHeroHeight = CardMetric(defaultHero, "-h");
                Debug.Log($"QA_CARD_METRIC default={unit} normal={defaultNormalHeight} hero={defaultHeroHeight} " +
                          $"normalRect={defaultNormal?.rect.size} heroRect={defaultHero?.rect.size}");
                defaultCardGeometry &= defaultNormal != null && defaultHero != null &&
                                       defaultNormal.rect.size == new Vector2(384f, 320f) &&
                                       defaultHero.rect.size == new Vector2(384f, 320f) &&
                                       CardMetric(defaultNormal, "-b") == 24 &&
                                       CardMetric(defaultHero, "-b") == 24 &&
                                       defaultNormalHeight >= 178 &&
                                       defaultHeroHeight >= defaultNormalHeight + 10;
            }
            var slots = SkinPairSlots(new Rect(0f, 0f, 100f, 100f));
            var equalSlots = Mathf.Abs(slots.normal.width - slots.hero.width) < .01f &&
                             Mathf.Abs(slots.normal.height - slots.hero.height) < .01f &&
                             Mathf.Abs(slots.normal.yMax - slots.hero.yMax) < .01f &&
                             slots.normal.xMax <= slots.hero.xMin;

            var waveFamiliesPure = true;
            var waveProgression = true;
            for (var round = 1; round <= MaxRounds; round++)
            {
                var chapter = (round - 1) / 5;
                var stage = (round - 1) % 5;
                var profiles = Enumerable.Range(0, 20)
                    .Select(index => EnemyVariantCatalog.ForWaveMember(round, index)).ToArray();
                var family = EnemyVariantCatalog.ForChapterStage(chapter, 0).FamilyClass;
                waveFamiliesPure &= profiles.All(profile => profile.FamilyClass == family);
                var expectedVariety = Mathf.Min(stage + 1, 4);
                waveProgression &= profiles.Select(profile => profile.Id).Distinct().Count() == expectedVariety;
            }

            var coreMenuArt = Resources.Load<Texture2D>("main-menu-core-v5");
            var sunriseMenuArt = Resources.Load<Texture2D>("main-menu-sunrise-v5");
            var moonlitMenuArt = Resources.Load<Texture2D>("main-menu-moonlit-v6");
            var loadingArtTexture = Resources.Load<Texture2D>("loading-screen-v3");
            var menuArt = coreMenuArt != null && sunriseMenuArt != null && moonlitMenuArt != null &&
                          coreMenuArt.width == sunriseMenuArt.width &&
                          coreMenuArt.height == sunriseMenuArt.height &&
                          coreMenuArt.width == moonlitMenuArt.width &&
                          coreMenuArt.height == moonlitMenuArt.height &&
                          coreMenuArt.height > coreMenuArt.width;
            var loadingArt = loadingArtTexture != null && loadingArtTexture.height > loadingArtTexture.width;

            showMainMenu = false;
            bool DistinctAnchors(Vector2[] points, Vector2 center, float maximumDistance) =>
                points.All(point => !float.IsNaN(point.x) && !float.IsNaN(point.y) &&
                                    Vector2.Distance(point, center) <= maximumDistance) &&
                points.Select(point =>
                        $"{Mathf.RoundToInt(point.x * 1000f)}:{Mathf.RoundToInt(point.y * 1000f)}")
                    .Distinct().Count() == 8;

            var originalSkins = roster.ToDictionary(unit => unit,
                unit => monetization.EquippedUnitSkin(unit));
            var playerDirectionStable = true;
            var playerOrigins = true;
            var playerWeaponMuzzles = true;
            var playerAccentsClean = true;
            var playerWalkDynamic = true;
            var playerActionsDynamic = true;
            var playerGrounded = true;
            var playerFacingCorrect = true;
            var playerTorsoDynamic = true;
            var playerCadenceNatural = true;
            var playerVariantsChecked = 0;
            float PoseDistance(Vector4 a, Vector4 b) => Vector4.Distance(a, b);
            bool ProbePlayer(UnitArchetype archetype, bool hero, string label)
            {
                var actor = new GameObject($"QA 231 Player {label} {archetype} {(hero ? "Hero" : "Normal")}")
                    .AddComponent<PlayerUnit>();
                actor.Initialize(this, archetype, definitions[archetype], new Vector2(0f, -5.6f));
                if (hero) actor.AddExperience(9999f);
                var walkPhases = new[] { .125f, .375f, .625f, .875f };
                var heights = octants.SelectMany(octant => walkPhases.Select(phase =>
                        actor.PreviewDirectionHeightForQa(EightWayFacing.VectorFor(octant), phase)))
                    .ToArray();
                var stable = heights.Min() > .01f && heights.Max() / heights.Min() <= 1.018f;
                var origins = octants.Select(octant =>
                {
                    var direction = EightWayFacing.VectorFor(octant);
                    return actor.AttackOriginFor(actor.Position + direction * 3f);
                }).ToArray();
                var anchored = DistinctAnchors(origins, actor.Position, actor.Radius * 2.55f);
                var isRangedWeapon = archetype is UnitArchetype.Archer or UnitArchetype.Musketeer or
                    UnitArchetype.Bombardier or UnitArchetype.AreaMage or UnitArchetype.SingleMage or
                    UnitArchetype.Druid or UnitArchetype.Oracle;
                var weaponMuzzle = !isRangedWeapon || octants.All(octant =>
                    actor.AttackOriginForwardProjectionForQa(EightWayFacing.VectorFor(octant)) >=
                    actor.Radius * .26f);
                var accentClean = !actor.ActionAccentUsesSolidCircleForQa;
                var walkDynamic = octants.All(octant =>
                {
                    var direction = EightWayFacing.VectorFor(octant);
                    var poses = walkPhases
                        .Select(phase => actor.PreviewMotionPoseForQa(direction, 0, phase)).ToArray();
                    return poses.SelectMany((pose, index) => poses.Skip(index + 1)
                            .Select(other => PoseDistance(pose, other)))
                        .DefaultIfEmpty(0f).Max() >= .055f;
                });
                var torsoDynamic = actor.UsesSeamSafeWholeBodyAnimationForQa;
                var isDefault = label == "Default";
                var eastMirror = actor.PreviewFacingMirrorForQa(Vector2.right);
                var westMirror = actor.PreviewFacingMirrorForQa(Vector2.left);
                var facingCorrect = isDefault
                    ? !eastMirror && westMirror
                    : eastMirror && !westMirror;
                var footContacts = octants.SelectMany(octant =>
                    walkPhases.Select(phase =>
                        actor.PreviewGroundContactForQa(EightWayFacing.VectorFor(octant), phase))).ToArray();
                var silhouetteBottoms = octants.SelectMany(octant =>
                    walkPhases.Select(phase =>
                        actor.PreviewSilhouetteBottomForQa(EightWayFacing.VectorFor(octant), phase))).ToArray();
                var silhouetteGrounded = silhouetteBottoms.Length > 0 &&
                                         silhouetteBottoms.All(contact =>
                                             contact <= actor.GroundPlaneLocalYForQa + actor.Radius * .06f &&
                                             contact >= actor.GroundPlaneLocalYForQa - actor.Radius * .35f);
                var grounded = footContacts.Length > 0 &&
                               footContacts.Max() - footContacts.Min() <= actor.Radius * .006f &&
                               footContacts.All(contact =>
                                   Mathf.Abs(contact - actor.GroundPlaneLocalYForQa) <= actor.Radius * .008f) &&
                               silhouetteGrounded;
                var cadenceNatural = actor.GaitCyclesPerSecondForQa is >= .8f and <= 1.55f;
                var actionsDynamic = octants.All(octant =>
                {
                    var direction = EightWayFacing.VectorFor(octant);
                    var attackWindup = actor.PreviewMotionPoseForQa(direction, 1, .18f);
                    var attackContact = actor.PreviewMotionPoseForQa(direction, 1, .48f);
                    var skillContact = actor.PreviewMotionPoseForQa(direction, 2, .48f);
                    var ultimateContact = actor.PreviewMotionPoseForQa(direction, 3, .48f);
                    return PoseDistance(attackWindup, attackContact) >= .075f &&
                           PoseDistance(attackContact, skillContact) >= .018f &&
                           PoseDistance(skillContact, ultimateContact) >= .026f;
                });
                var debugDirection = Vector2.down;
                var debugAttackWindup = actor.PreviewMotionPoseForQa(debugDirection, 1, .18f);
                var debugAttackContact = actor.PreviewMotionPoseForQa(debugDirection, 1, .48f);
                var debugSkillContact = actor.PreviewMotionPoseForQa(debugDirection, 2, .48f);
                var debugUltimateContact = actor.PreviewMotionPoseForQa(debugDirection, 3, .48f);
                playerDirectionStable &= stable;
                playerOrigins &= anchored;
                playerWeaponMuzzles &= weaponMuzzle;
                playerAccentsClean &= accentClean;
                playerWalkDynamic &= walkDynamic;
                playerActionsDynamic &= actionsDynamic;
                playerGrounded &= grounded;
                playerFacingCorrect &= facingCorrect;
                playerTorsoDynamic &= torsoDynamic;
                playerCadenceNatural &= cadenceNatural;
                playerVariantsChecked++;
                if (!stable || !anchored || !weaponMuzzle || !accentClean || !walkDynamic || !actionsDynamic || !grounded ||
                    !facingCorrect || !torsoDynamic || !cadenceNatural)
                    Debug.Log($"QA_235_PLAYER_VARIANT_FAIL unit={archetype} hero={hero} skin={label} " +
                              $"heightRatio={heights.Max() / Mathf.Max(.001f, heights.Min()):0.000} " +
                              $"anchor={anchored} muzzle={weaponMuzzle} accent={accentClean} " +
                              $"walk={walkDynamic} actions={actionsDynamic} " +
                              $"grounded={grounded}:span={footContacts.Max() - footContacts.Min():0.0000}:" +
                              $"silhouette={silhouetteGrounded}:" +
                              $"{silhouetteBottoms.Min():0.0000}-{silhouetteBottoms.Max():0.0000}:" +
                              $"plane={actor.GroundPlaneLocalYForQa:0.0000} facing={facingCorrect}:" +
                              $"eastFlip={eastMirror}:westFlip={westMirror} torso={torsoDynamic} " +
                              $"cadence={cadenceNatural}:{actor.GaitCyclesPerSecondForQa:0.00} " +
                              $"actionDistances={PoseDistance(debugAttackWindup, debugAttackContact):0.000}/" +
                              $"{PoseDistance(debugAttackContact, debugSkillContact):0.000}/" +
                              $"{PoseDistance(debugSkillContact, debugUltimateContact):0.000}");
                actor.gameObject.SetActive(false);
                Destroy(actor.gameObject);
                return stable && anchored;
            }

            foreach (var archetype in roster)
            {
                monetization.EquipDefault(ShopCategory.Unit, archetype);
                ProbePlayer(archetype, false, "Default");
                ProbePlayer(archetype, true, "Default");
                var prefix = archetype switch
                {
                    UnitArchetype.AreaMage => "area_mage",
                    UnitArchetype.SingleMage => "single_mage",
                    _ => archetype.ToString().ToLowerInvariant()
                };
                foreach (var suffix in new[] { ".a", ".b" })
                {
                    var product = monetization.FindProduct($"crownfront.unit.{prefix}{suffix}");
                    if (product == null)
                    {
                        playerDirectionStable = false;
                        playerOrigins = false;
                        continue;
                    }
                    monetization.GrantForQa(product.Id);
                    monetization.Equip(product);
                    ProbePlayer(archetype, false, suffix);
                    ProbePlayer(archetype, true, suffix);
                }
            }
            foreach (var archetype in roster)
            {
                var original = originalSkins[archetype];
                if (string.IsNullOrEmpty(original)) monetization.EquipDefault(ShopCategory.Unit, archetype);
                else monetization.Equip(monetization.FindProduct(original));
            }

            var enemyDirectionStable = true;
            var enemyOrigins = true;
            var enemyWalkDynamic = true;
            var enemyActionsDynamic = true;
            var enemyGrounded = true;
            var enemyVariantsChecked = 0;
            void ProbeEnemy(EnemyClass enemyClass, bool boss, EnemyVariantProfile profile, string label)
            {
                var actor = new GameObject($"QA 231 Enemy {label}").AddComponent<EnemyUnit>();
                actor.Initialize(this, 0, boss ? 3600f : 900f, boss, 0, enemyClass, profile);
                var heights = octants.Select(octant =>
                        actor.PreviewDirectionHeightForQa(EightWayFacing.VectorFor(octant)))
                    .ToArray();
                var hovering = actor.IsFlying || actor.Class == EnemyClass.Wisp;
                var footContacts = hovering
                    ? Array.Empty<float>()
                    : octants.SelectMany(octant =>
                        new[] { .12f, .37f, .62f, .87f }.Select(phase =>
                            actor.PreviewGroundContactForQa(EightWayFacing.VectorFor(octant), phase))).ToArray();
                var groundStable = hovering
                    ? actor.GroundVisualOffset is >= .1f and <= .3f
                    : footContacts.Length > 0 &&
                      footContacts.Max() - footContacts.Min() <= actor.Radius * .006f;
                var stable = heights.Min() > .01f && heights.Max() / heights.Min() <= 1.025f && groundStable;
                var origins = octants.Select(octant =>
                {
                    var direction = EightWayFacing.VectorFor(octant);
                    return actor.AttackOriginFor(actor.Position + direction * 3f);
                }).ToArray();
                var anchored = DistinctAnchors(origins, actor.Position, actor.Radius * 2.55f);
                var authoredBoss = actor.HasAuthoredBossDirectionalAnimationForQa;
                var walkDynamic = authoredBoss
                    ? actor.DistinctAnimationSpritesForQa(0) >= 5
                    : octants.All(octant =>
                    {
                        var direction = EightWayFacing.VectorFor(octant);
                        var poses = new[] { .12f, .37f, .62f, .87f }
                            .Select(phase => actor.PreviewMotionPoseForQa(direction, 0, phase)).ToArray();
                        return poses.SelectMany((pose, index) => poses.Skip(index + 1)
                                .Select(other => PoseDistance(pose, other)))
                            .DefaultIfEmpty(0f).Max() >= .012f;
                    });
                walkDynamic &= actor.UsesSeamSafeWholeBodyAnimationForQa;
                var actionsDynamic = authoredBoss
                    ? actor.DistinctAnimationSpritesForQa(1) >= 4 &&
                      actor.DistinctAnimationSpritesForQa(2) >= 4 &&
                      octants.All(octant =>
                      {
                          var direction = EightWayFacing.VectorFor(octant);
                          var stateSprites = new HashSet<int>();
                          for (var state = 0; state < 3; state++)
                          {
                              actor.PreviewMotionPoseForQa(direction, state, .52f);
                              stateSprites.Add(actor.CurrentSpriteIdForQa);
                          }
                          return stateSprites.Count == 3;
                      })
                    : octants.All(octant =>
                    {
                        var direction = EightWayFacing.VectorFor(octant);
                        var attackWindup = actor.PreviewMotionPoseForQa(direction, 1, .18f);
                        var attackContact = actor.PreviewMotionPoseForQa(direction, 1, .5f);
                        var skillWindup = actor.PreviewMotionPoseForQa(direction, 2, .18f);
                        var skillContact = actor.PreviewMotionPoseForQa(direction, 2, .5f);
                        return PoseDistance(attackWindup, attackContact) >= .07f &&
                               PoseDistance(skillWindup, skillContact) >= .035f;
                    });
                var debugAttackWindup = actor.PreviewMotionPoseForQa(Vector2.down, 1, .18f);
                var debugAttackContact = actor.PreviewMotionPoseForQa(Vector2.down, 1, .5f);
                var debugSkillWindup = actor.PreviewMotionPoseForQa(Vector2.down, 2, .18f);
                var debugSkillContact = actor.PreviewMotionPoseForQa(Vector2.down, 2, .5f);
                enemyDirectionStable &= stable;
                enemyOrigins &= anchored;
                enemyWalkDynamic &= walkDynamic;
                enemyActionsDynamic &= actionsDynamic;
                enemyGrounded &= groundStable;
                enemyVariantsChecked++;
                if (!stable || !anchored || !walkDynamic || !actionsDynamic)
                    Debug.Log($"QA_235_ENEMY_VARIANT_FAIL enemy={label} class={enemyClass} boss={boss} " +
                              $"heightRatio={heights.Max() / Mathf.Max(.001f, heights.Min()):0.000} " +
                              $"ground={actor.GroundVisualOffset:0.000} anchor={anchored} " +
                              $"groundSpan={(hovering ? 0f : footContacts.Max() - footContacts.Min()):0.0000} " +
                              $"walk={walkDynamic} actions={actionsDynamic} " +
                              $"actionDistances={PoseDistance(debugAttackWindup, debugAttackContact):0.000}/" +
                              $"{PoseDistance(debugSkillWindup, debugSkillContact):0.000}");
                actor.gameObject.SetActive(false);
                Destroy(actor.gameObject);
            }
            var combatClasses = System.Enum.GetValues(typeof(EnemyClass)).Cast<EnemyClass>()
                .Where(enemyClass => enemyClass != EnemyClass.Boss).ToArray();
            foreach (var enemyClass in combatClasses)
                ProbeEnemy(enemyClass, false, default, enemyClass.ToString());
            for (var chapter = 0; chapter < 10; chapter++)
            {
                var profile = EnemyVariantCatalog.ForChapterStage(chapter, 4);
                ProbeEnemy(profile.CombatClass, true, profile, profile.Id);
            }
            var measuredMeleeRange = definitions.TryGetValue(UnitArchetype.Melee, out var meleeDefinition)
                ? meleeDefinition.Range
                : -1f;
            var meleeRangeCorrected = measuredMeleeRange is >= .62f and <= .7f &&
                                      measuredMeleeRange < definitions[UnitArchetype.Tank].Range;
            var eightWayMotion = octantCoverage && playerOrigins && playerDirectionStable &&
                                 playerWeaponMuzzles && playerAccentsClean && meleeRangeCorrected &&
                                 enemyDirectionStable && enemyOrigins && playerWalkDynamic &&
                                 playerActionsDynamic && playerGrounded && playerFacingCorrect &&
                                 playerTorsoDynamic && playerCadenceNatural && enemyWalkDynamic &&
                                 enemyActionsDynamic && enemyGrounded;

            Phase = GamePhase.Battle;
            var ultimateBefore = ultimateImpactFlashCount;
            SpawnUltimateImpactFlash(Vector2.zero, new Color(.28f, .78f, 1f), UnitArchetype.Tank);
            yield return null;
            var ultimateProbe = GameObject.Find("Hero Ultimate Impact Tank");
            var ultimateLayers = ultimateProbe != null
                ? ultimateProbe.GetComponentsInChildren<SpriteRenderer>(true).Length
                : 0;
            var ultimateVisible = ultimateImpactFlashCount == ultimateBefore + 1 &&
                                  ultimateLayers >= (release237 ? 56 : 47);

            var routeFaces = Enumerable.Range(0, paths.Count)
                .Select(lane => GetGateAttackPoint(lane)).ToArray();
            var sixRoutePressure = paths.Count == 6 && routeFaces.Length == 6 &&
                                   routeFaces.Select(face => Mathf.RoundToInt(face.x * 100f)).Distinct().Count() == 6 &&
                                   routeFaces.Max(face => face.x) - routeFaces.Min(face => face.x) >= 3.9f &&
                                   Enumerable.Range(0, 6).Select(DeploymentLaneForIndex).Distinct().Count() == 6;
            var squadPressure = WaveEnemyCount(1) == 12 && WaveEnemyCount(5) == 24 &&
                                WaveEnemyCount(6) == 22 && WaveEnemyCount(50) == 88 &&
                                WaveSquadSize(1) == 4 && WaveSquadSize(50) == 10 &&
                                WaveMemberInterval(1) < .08f && WaveSquadInterval(1) < .65f;
            var authoredGolemDesigns = true;
            var authoredDesignCodes = new HashSet<int>();
            for (var stage = 0; stage < 5; stage++)
            {
                var profile = EnemyVariantCatalog.ForChapterStage(3, stage);
                var golem = new GameObject($"QA 237 Authored Golem {stage}").AddComponent<EnemyUnit>();
                golem.Initialize(this, stage, 1200f, false, stage % Mathf.Max(1, LaneCount),
                    profile.CombatClass, profile);
                authoredDesignCodes.Add(golem.AuthoredVariantDesignCode);
                authoredGolemDesigns &= golem.UsesAuthoredVariantArt && golem.UsesAuthoredVariantBackArt &&
                                        golem.AnimationFrameCount == 72;
                golem.gameObject.SetActive(false);
                Destroy(golem.gameObject);
            }
            authoredGolemDesigns &= authoredDesignCodes.Count == 5 && enemyVariantSprites.Count == 5 &&
                                     enemyVariantBackSprites.Count == 5;
            var musketeerMatteClean = musketeerCheckerPixelsRemoved > 1000 &&
                                       musketeerLowerMattePixelsRemoved > 40;
            var augmentNerfed = TierPower(AugmentTier.Bronze) <= .52f &&
                                TierPower(AugmentTier.Diamond) <= .94f &&
                                TierPower(AugmentTier.Diamond) / TierPower(AugmentTier.Bronze) < 1.85f;
            var release237Systems = !release237 || sixRoutePressure && squadPressure && authoredGolemDesigns &&
                                    musketeerMatteClean && augmentNerfed;

            var passed = base64 && hero64 && skins64 && enemies72 && eightWayMotion &&
                         skinCardGeometry && defaultCardGeometry && equalSlots &&
                         waveFamiliesPure && waveProgression && menuArt && loadingArt && ultimateVisible &&
                         release237Systems;
            var releaseLabel = release237 ? "QA_RELEASE_237" : release236 ? "QA_RELEASE_236" : "QA_RELEASE_235";
            Debug.Log($"{releaseLabel} base64={base64} hero64={hero64} skins64={skins64}:{authoredSkinAnimations.Count} " +
                      $"enemy72={enemies72}:{enemyAnimationSets.Count} skinCards={skinCardGeometry}:{canonicalSkinCardSprites.Count} " +
                      $"defaultCards={defaultCardGeometry}:{canonicalDefaultCardSprites.Count} slots={equalSlots} " +
                      $"familyPure={waveFamiliesPure} progression={waveProgression} menuV4AndSkins={menuArt} " +
                      $"loadingV3={loadingArt} eightWay={eightWayMotion}:octants={octantCoverage}:" +
                      $"playerScale={playerDirectionStable}:playerOrigin={playerOrigins}:weaponMuzzle={playerWeaponMuzzles}:" +
                      $"accentClean={playerAccentsClean}:meleeRange={meleeRangeCorrected}:{measuredMeleeRange:0.00}:" +
                      $"playerVariants={playerVariantsChecked}:" +
                      $"playerWalk={playerWalkDynamic}:playerTorso={playerTorsoDynamic}:playerFacing={playerFacingCorrect}:" +
                      $"playerCadence={playerCadenceNatural}:" +
                      $"playerActions={playerActionsDynamic}:playerGround={playerGrounded}:" +
                      $"enemyScale={enemyDirectionStable}:enemyOrigin={enemyOrigins}:enemyVariants={enemyVariantsChecked}:" +
                      $"enemyWalk={enemyWalkDynamic}:enemyActions={enemyActionsDynamic}:enemyGround={enemyGrounded} " +
                      $"ultimate={ultimateVisible}:{ultimateImpactFlashCount}:layers={ultimateLayers} " +
                      $"routes={sixRoutePressure}:{paths.Count}:spread=" +
                      $"{(routeFaces.Length > 0 ? routeFaces.Max(face => face.x) - routeFaces.Min(face => face.x) : 0f):0.00} " +
                      $"squads={squadPressure}:{WaveEnemyCount(1)}-{WaveEnemyCount(50)}:" +
                      $"{WaveSquadSize(1)}-{WaveSquadSize(50)} golems={authoredGolemDesigns}:" +
                      $"{enemyVariantSprites.Count}/{enemyVariantBackSprites.Count}:{authoredDesignCodes.Count} " +
                      $"musketeerMatte={musketeerMatteClean}:{musketeerCheckerPixelsRemoved}:" +
                      $"{musketeerLowerMattePixelsRemoved} augmentNerf={augmentNerfed}:" +
                      $"{TierPower(AugmentTier.Bronze):0.00}-{TierPower(AugmentTier.Diamond):0.00}");
            Application.Quit(passed ? 0 : 71);
        }

        private IEnumerator QaRelease227Routine()
        {
            yield return null;
            var roster = new[]
            {
                UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Archer,
                UnitArchetype.AreaMage, UnitArchetype.SingleMage, UnitArchetype.Bombardier,
                UnitArchetype.Lancer, UnitArchetype.Druid, UnitArchetype.Musketeer, UnitArchetype.Oracle
            };
            var baseTimelines = roster.All(unit =>
                unitDirectionalAnimations.TryGetValue(unit, out var set) &&
                set.Down.Length >= 17 && set.Side.Length >= 17 && set.Up.Length >= 17);
            var heroTimelines = roster.All(unit =>
                heroDirectionalAnimations.TryGetValue(unit, out var set) &&
                set.Down.Length >= 17 && set.Side.Length >= 17 && set.Up.Length >= 17);
            var skinTimelines = authoredSkinAnimations.Count == 40 &&
                                authoredSkinAnimations.Values.All(set =>
                                    set.Down.Length == 17 && set.Side.Length == 17 && set.Up.Length == 17);
            var enemyTimelines = enemyAnimationSets.Count >= 8 &&
                                 enemyAnimationSets.Values.All(frames => frames.Length >= 16);
            var skinCards = canonicalSkinCardSprites.Count == 40 &&
                            canonicalSkinCardSprites.Values.All(sprite =>
                                sprite != null && sprite.texture != null &&
                                sprite.texture.name.Contains("-canonical-card"));
            var slots = SkinPairSlots(new Rect(0f, 0f, 100f, 100f));
            var slotsSeparated = slots.normal.xMax <= slots.hero.xMin + .01f &&
                                 slots.hero.height > slots.normal.height * 1.12f;
            var loadingReady = Resources.Load<Texture2D>("loading-screen-v3") != null;
            var cleanKingReady = bossVariantSprites.TryGetValue("jelly_king", out var cleanKing) &&
                                 cleanKing != null && cleanKing.texture != null &&
                                 cleanKing.texture.name.Contains("boss-jelly-king-clean-v1") &&
                                 bossBackVariantSprites.TryGetValue("jelly_king", out var cleanKingBack) &&
                                 cleanKingBack != null;

            showMainMenu = false;
            var actor = new GameObject("QA 227 Horizontal Direction").AddComponent<PlayerUnit>();
            actor.Initialize(this, UnitArchetype.Tank, definitions[UnitArchetype.Tank],
                new Vector2(0f, -5.9f));
            units.Add(actor);
            actor.MoveTo(new Vector2(1.2f, -5.9f));
            yield return new WaitForSecondsRealtime(.32f);
            var rightMovementUnflipped = actor.VisualFacing.x > .25f && !actor.VisualSpriteFlipped;
            actor.MoveTo(new Vector2(-1.2f, -5.9f));
            yield return new WaitForSecondsRealtime(.72f);
            var leftMovementFlipped = actor.VisualFacing.x < -.25f && actor.VisualSpriteFlipped;
            var playerDirectionCorrect = rightMovementUnflipped && leftMovementFlipped;

            var scaleProbe = new GameObject("QA 227 Enemy Direction Scale").AddComponent<EnemyUnit>();
            scaleProbe.Initialize(this, 0, 900f, false, 0, EnemyClass.Melee);
            enemies.Add(scaleProbe);
            var directionHeights = new[]
            {
                scaleProbe.PreviewDirectionHeightForQa(Vector2.down),
                scaleProbe.PreviewDirectionHeightForQa(Vector2.up),
                scaleProbe.PreviewDirectionHeightForQa(Vector2.left),
                scaleProbe.PreviewDirectionHeightForQa(Vector2.right)
            };
            var minHeight = directionHeights.Min();
            var maxHeight = directionHeights.Max();
            var enemyDirectionScaleStable = minHeight > .01f &&
                                            maxHeight / minHeight <= 1.025f &&
                                            Mathf.Abs(scaleProbe.GroundVisualOffset) <= .002f;

            var kingScaleProbe = new GameObject("QA 227 King Direction Scale").AddComponent<EnemyUnit>();
            var kingProfile = EnemyVariantCatalog.ForChapterStage(0, 4);
            kingScaleProbe.Initialize(this, 1, 3600f, true, 0,
                kingProfile.CombatClass, kingProfile);
            enemies.Add(kingScaleProbe);
            var kingFrontHeight = kingScaleProbe.PreviewDirectionHeightForQa(Vector2.down);
            var kingBackHeight = kingScaleProbe.PreviewDirectionHeightForQa(Vector2.up);
            var kingDirectionScaleStable = Mathf.Min(kingFrontHeight, kingBackHeight) > .01f &&
                                           Mathf.Max(kingFrontHeight, kingBackHeight) /
                                           Mathf.Min(kingFrontHeight, kingBackHeight) <= 1.025f &&
                                           Mathf.Abs(kingScaleProbe.GroundVisualOffset) <= .002f;

            var passed = baseTimelines && heroTimelines && skinTimelines && enemyTimelines &&
                         skinCards && slotsSeparated && loadingReady && cleanKingReady &&
                         playerDirectionCorrect && enemyDirectionScaleStable &&
                         kingDirectionScaleStable;
            Debug.Log($"QA_RELEASE_227 base17={baseTimelines} hero17={heroTimelines} " +
                      $"skin17={skinTimelines}:{authoredSkinAnimations.Count} " +
                      $"enemy16={enemyTimelines}:{enemyAnimationSets.Count} cards={skinCards} " +
                      $"slots={slotsSeparated} loading={loadingReady} cleanKing={cleanKingReady} " +
                      $"rightNoFlip={rightMovementUnflipped} leftFlip={leftMovementFlipped} " +
                      $"enemyScale={enemyDirectionScaleStable}:{minHeight:F3}-{maxHeight:F3} " +
                      $"kingScale={kingDirectionScaleStable}:{kingFrontHeight:F3}/{kingBackHeight:F3}");
            Application.Quit(passed ? 0 : 69);
        }

