        private IEnumerator QaCombatPresentation236Routine()
        {
            yield return null;
            showMainMenu = false;
            showFormationPanel = false;
            Phase = GamePhase.Preparation;

            (PlayerUnit actor, EnemyUnit target) CreatePair(UnitArchetype archetype, Vector2 sourcePosition,
                Vector2 targetPosition, int index)
            {
                monetization.EquipDefault(ShopCategory.Unit, archetype);
                var actor = new GameObject($"QA 236 Combat {archetype}").AddComponent<PlayerUnit>();
                actor.Initialize(this, archetype, definitions[archetype], sourcePosition);
                units.Add(actor);
                var profile = EnemyVariantCatalog.ForChapterStage(0, index);
                var target = new GameObject($"QA 236 Combat Target {archetype}").AddComponent<EnemyUnit>();
                target.Initialize(this, index, 9999f, false, index, profile.CombatClass, profile);
                target.ForcePositionForQa(targetPosition);
                enemies.Add(target);
                actor.TriggerAttackMotionForQa(target.Position);
                PerformAttack(actor, target, definitions[archetype]);
                return (actor, target);
            }

            var melee = CreatePair(UnitArchetype.Melee, new Vector2(-1.8f, -5f), new Vector2(-1.15f, -4.9f), 0);
            var archer = CreatePair(UnitArchetype.Archer, new Vector2(-.5f, -5f), new Vector2(1.4f, -4.7f), 1);
            var mage = CreatePair(UnitArchetype.AreaMage, new Vector2(.1f, -4f), new Vector2(1.65f, -3.75f), 2);
            yield return new WaitForSecondsRealtime(.08f);

            var swing = GameObject.Find("Melee Weapon Swing");
            var swingLayers = swing != null ? swing.GetComponentsInChildren<SpriteRenderer>(true).Length : 0;
            var swingBuilt = swingLayers == 7;
            yield return new WaitForSecondsRealtime(.23f);

            var archerMuzzle = GameObject.Find("Archer Weapon Muzzle Flash");
            var mageMuzzle = GameObject.Find("AreaMage Weapon Muzzle Flash");
            var archerExpected = archer.actor.AttackOriginFor(archer.target.Position);
            var mageExpected = mage.actor.AttackOriginFor(mage.target.Position);
            var muzzleAnchored = archerMuzzle != null && mageMuzzle != null &&
                                 Vector2.Distance(archerMuzzle.transform.position, archerExpected) <= .035f &&
                                 Vector2.Distance(mageMuzzle.transform.position, mageExpected) <= .035f;
            var muzzleLayered = archerMuzzle != null && mageMuzzle != null &&
                                archerMuzzle.GetComponentsInChildren<SpriteRenderer>(true).Length >= 6 &&
                                mageMuzzle.GetComponentsInChildren<SpriteRenderer>(true).Length >= 6;
            var noSolidPurple = FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None)
                .Where(renderer => renderer != null &&
                                   (renderer.name.Contains("Weapon Contact") ||
                                    renderer.transform.root.name.Contains("Weapon Muzzle")))
                .All(renderer => renderer.sprite != CircleSprite);
            var meleeRange = definitions[UnitArchetype.Melee].Range;
            var passed = swingBuilt && muzzleAnchored && muzzleLayered && noSolidPurple &&
                         meleeRange is >= .62f and <= .7f;
            Debug.Log($"QA_COMBAT_PRESENTATION_236 swing={swingBuilt}:{swingLayers} " +
                      $"muzzle={muzzleAnchored}:layers={muzzleLayered} solidCircleFree={noSolidPurple} " +
                      $"meleeRange={meleeRange:0.00}");
            Application.Quit(passed ? 0 : 72);
        }

        private static int CountOpaquePixels(Sprite sprite)
        {
            if (sprite == null || sprite.texture == null) return 0;
            var marker = sprite.texture.name.LastIndexOf("-opaque-", StringComparison.Ordinal);
            if (marker >= 0 && int.TryParse(sprite.texture.name[(marker + 8)..], out var recorded))
                return recorded;
            try
            {
                return sprite.texture.GetPixels32().Count(pixel => pixel.a > 18);
            }
            catch (Exception)
            {
                return 0;
            }
        }

