        private IEnumerator CaptureFullFrameRoutine(string fileName)
        {
            yield return new WaitForEndOfFrame();
            var width = Mathf.Max(1, Screen.width);
            var height = Mathf.Max(1, Screen.height);
            var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
            texture.ReadPixels(new Rect(0f, 0f, width, height), 0, 0);
            texture.Apply();
            var output = Path.GetFullPath(Path.Combine(Application.dataPath, "..", fileName));
            var pixels = texture.GetPixels32();
            using (var stream = File.Create(output))
            {
                var header = System.Text.Encoding.ASCII.GetBytes($"P6\n{width} {height}\n255\n");
                stream.Write(header, 0, header.Length);
                for (var y = height - 1; y >= 0; y--)
                for (var x = 0; x < width; x++)
                {
                    var pixel = pixels[y * width + x];
                    stream.WriteByte(pixel.r);
                    stream.WriteByte(pixel.g);
                    stream.WriteByte(pixel.b);
                }
            }
            Destroy(texture);
            Debug.Log($"QA_FULL_FRAME_CAPTURE {output} {width}x{height}");
        }

