        private IEnumerator QaRelease217Routine()
        {
            yield return null;
            var profileIds = new HashSet<string>();
            var profileNames = new HashSet<string>();
            var familyBlocks = true;
            var stageCurve = true;
            for (var chapter = 0; chapter < 10; chapter++)
            {
                var family = EnemyVariantCatalog.ForChapterStage(chapter, 0).FamilyClass;
                var previousHealth = 0f;
                for (var stage = 0; stage < 5; stage++)
                {
                    var profile = EnemyVariantCatalog.ForChapterStage(chapter, stage);
                    profileIds.Add(profile.Id);
                    profileNames.Add(profile.KoreanName);
                    familyBlocks &= profile.FamilyClass == family;
                    stageCurve &= profile.HealthMultiplier >= previousHealth;
                    previousHealth = profile.HealthMultiplier;
                }
            }
            var enemyRoster = profileIds.Count == 50 && profileNames.Count == 50 &&
                              familyBlocks && stageCurve &&
                              MonsterClassForRound(1) == EnemyClass.Melee &&
                              MonsterClassForRound(6) == EnemyClass.Skeleton;

            var unitSkins = monetization.Products.Where(product => product.Category == ShopCategory.Unit).ToArray();
            var individualSkins = unitSkins.Length == 20 &&
                                  unitSkins.GroupBy(product => product.TargetUnit).Count() == 10 &&
                                  unitSkins.GroupBy(product => product.TargetUnit).All(group => group.Count() == 2);
            var challenges = BuildChallengeItems().Count == 48 && ChallengeKeys.Length == 48;

            var previousLanguage = GameLocalization.Current;
            GameLocalization.Current = GameLanguage.English;
            definitions.Clear();
            BuildDefinitions();
            var englishGameplay = definitions.Values.All(definition =>
                !definition.Name.Any(character => character is >= '\uAC00' and <= '\uD7A3')) &&
                GameLocalization.AugmentName("TankHealth", string.Empty) == "Reinforced Shield";
            GameLocalization.Current = previousLanguage;
            definitions.Clear();
            BuildDefinitions();

            foreach (var enemy in enemies.ToArray()) if (enemy != null) Destroy(enemy.gameObject);
            enemies.Clear();
            Round = 5;
            Phase = GamePhase.Battle;
            var wave = StartCoroutine(SpawnWaveRoutine(WaveEnemyCount(Round)));
            yield return new WaitForSecondsRealtime(.8f);
            var bossDelayed = FindBoss() == null && enemies.Count > 0;
            yield return new WaitForSecondsRealtime(5.2f);
            var bossArrived = FindBoss() != null && bossFormationSpawnCount == 4;
            if (wave != null) StopCoroutine(wave);

            var passed = enemyRoster && individualSkins && challenges && englishGameplay &&
                         bossDelayed && bossArrived;
            Debug.Log($"QA_RELEASE_217 enemyRoster={enemyRoster} profiles={profileIds.Count} " +
                      $"individualSkins={individualSkins} unitSkins={unitSkins.Length} " +
                      $"challenges={challenges} english={englishGameplay} " +
                      $"bossDelayed={bossDelayed} bossArrived={bossArrived}");
            Application.Quit(passed ? 0 : 57);
        }

        private void Update()
        {
            UpdateBattlefieldMood();
            UpdateAttackOrderMarker();
            UpdateRunCheckpointAutosave();
            if (Input.GetKeyDown(KeyCode.Escape))
            {
                HandleBackButton();
                return;
            }
            if (showGuidePanel) UpdateGuideTouchInput();
            if (showMissionPanel) UpdateChallengeTouchInput();
            if (showMainMenu || showSystemMenu || showReturnToMainMenuSavePrompt || showSettings || showExitConfirm || showMissionPanel ||
                showShopPanel || showSkinPanel || showGuidePanel) return;
            if (Input.GetKeyDown(KeyCode.S)) StopSelected();
            if (Phase is GamePhase.Preparation or GamePhase.Battle)
            {
                var controllingCamera = UpdateCameraControls();
                if (!controllingCamera) UpdatePointerControls();
            }
            if (Phase == GamePhase.Battle) UpdateBattleAugments();
            if (Phase == GamePhase.Battle && !spawning && enemies.Count == 0) CompleteRound();
        }

        private void LoadChallengeCollection()
        {
            lifetimeRoundsCleared = PlayerPrefs.GetInt("Crownfront.Lifetime.Rounds", 0);
            lifetimeMonstersDefeated = PlayerPrefs.GetInt("Crownfront.Lifetime.Kills", 0);
            lifetimeUnitsPlaced = PlayerPrefs.GetInt("Crownfront.Lifetime.Placements", 0);
            lifetimeSkillsCast = PlayerPrefs.GetInt("Crownfront.Lifetime.Skills", 0);
            lifetimeHeroesEvolved = PlayerPrefs.GetInt("Crownfront.Lifetime.Heroes", 0);
            lifetimeBossesDefeated = PlayerPrefs.GetInt("Crownfront.Lifetime.Bosses", 0);
            foreach (var key in ChallengeKeys)
                if (PlayerPrefs.GetInt("Crownfront.Challenge." + key, 0) == 1) completedMissionKeys.Add(key);
        }

        private void SaveLifetimeProgress()
        {
            // Runtime QA mutates counters thousands of times and must remain deterministic even
            // in locked-down CI sandboxes where desktop PlayerPrefs (the registry on Windows)
            // is intentionally read-only. The dedicated checkpoint probe still exercises the
            // real persistence path because persistence is its subject under test.
            if (IsQaMode() && !HasCommandLineArgument("-qaCheckpoint266")) return;
            PlayerPrefs.SetInt("Crownfront.Lifetime.Rounds", lifetimeRoundsCleared);
            PlayerPrefs.SetInt("Crownfront.Lifetime.Kills", lifetimeMonstersDefeated);
            PlayerPrefs.SetInt("Crownfront.Lifetime.Placements", lifetimeUnitsPlaced);
            PlayerPrefs.SetInt("Crownfront.Lifetime.Skills", lifetimeSkillsCast);
            PlayerPrefs.SetInt("Crownfront.Lifetime.Heroes", lifetimeHeroesEvolved);
            PlayerPrefs.SetInt("Crownfront.Lifetime.Bosses", lifetimeBossesDefeated);
            PlayerPrefs.Save();
            SavePortableProgressBackup();
        }

        private static bool IsQaMode()
        {
            foreach (var arg in Environment.GetCommandLineArgs())
                if (arg.StartsWith("-qa", StringComparison.OrdinalIgnoreCase) &&
                    !string.Equals(arg, "-qaScreenshot", StringComparison.OrdinalIgnoreCase) &&
                    !string.Equals(arg, "-qaDelay", StringComparison.OrdinalIgnoreCase)) return true;
            return false;
        }

        private void HandleBackButton()
        {
            if (showReturnToMainMenuSavePrompt)
            {
                CancelReturnToMainMenu();
                return;
            }
            if (showResumePrompt)
            {
                showResumePrompt = false;
                return;
            }
            if (showExitConfirm)
            {
                showExitConfirm = false;
                // A second Android Back must dismiss the entire modal stack and resume play.
                // Restoring a hidden system menu here left Time.timeScale at zero on some phones.
                showSystemMenu = false;
                showSettings = false;
                settingsResumeBattleOnClose = false;
                exitConfirmFromSystemMenu = false;
                Time.timeScale = 1f;
                return;
            }
            if (showSettings)
            {
                CloseSettingsPanel();
                showSystemMenu = false;
                return;
            }
            if (showShopPanel)
            {
                showShopPanel = false;
                return;
            }
            if (showSkinPanel)
            {
                showSkinPanel = false;
                return;
            }
            if (showMissionPanel)
            {
                showMissionPanel = false;
                return;
            }
            if (showGuidePanel)
            {
                showGuidePanel = false;
                return;
            }
            if (showSystemMenu)
            {
                showSystemMenu = false;
                Time.timeScale = 1f;
                return;
            }
            if (showMainMenu)
            {
                showExitConfirm = true;
                return;
            }
            if (buildMode != UnitArchetype.None)
            {
                CancelBuildMode();
                return;
            }
            showSystemMenu = true;
            Time.timeScale = 0f;
        }

        private void ReturnToMainMenu(bool saveCheckpoint)
        {
            if (saveCheckpoint) SaveRunCheckpoint();
            else ClearRunCheckpoint();
            monetization?.NotifyRunEnded();
            runInProgress = false;
            Time.timeScale = 1f;
            RestartGame(false);
            showSystemMenu = false;
            showReturnToMainMenuSavePrompt = false;
            showSettings = false;
            settingsResumeBattleOnClose = false;
            showExitConfirm = false;
            showMissionPanel = false;
            showShopPanel = false;
            showSkinPanel = false;
            showGuidePanel = false;
            exitConfirmFromSystemMenu = false;
            showMainMenu = true;
            mainMenuInputReadyAt = Time.unscaledTime + .42f;
            voiceBarks?.SetBattleMusic(false, true);
        }

        private void OpenSettingsFromSystemMenu()
        {
            showSystemMenu = false;
            showSettings = true;
            settingsResumeBattleOnClose = true;
            Time.timeScale = 0f;
        }

        private void CloseSettingsPanel()
        {
            showSettings = false;
            if (!settingsResumeBattleOnClose) return;
            settingsResumeBattleOnClose = false;
            if (!showSystemMenu && !showExitConfirm) Time.timeScale = 1f;
        }

        private void QuitApplication()
        {
            SaveRunCheckpoint();
            // The confirm panel now exclusively owns the tap area (the paused system menu is
            // hidden before it opens), so Unity's supported cross-platform Android exit path
            // receives the press instead of a covered button.
            var adRequested = monetization != null && monetization.NotifyRunEnded();
            if (!adRequested)
            {
                Application.Quit();
                return;
            }
            StartCoroutine(QuitAfterInterstitialRoutine());
        }

        private IEnumerator QuitAfterInterstitialRoutine()
        {
            var closed = false;
            void MarkClosed() => closed = true;
            monetization.InterstitialClosed += MarkClosed;
            var timeoutAt = Time.realtimeSinceStartup + 15f;
            while (!closed && Time.realtimeSinceStartup < timeoutAt) yield return null;
            monetization.InterstitialClosed -= MarkClosed;
            Application.Quit();
        }

        public void PlayUnitVoice(Transform emitter, UnitArchetype archetype, VoiceCue cue)
        {
            voiceBarks?.Play(emitter, (int)archetype + 1, cue);
        }

        public void PlayEnemyVoice(Transform emitter, EnemyClass enemyClass, VoiceCue cue)
        {
            voiceBarks?.Play(emitter, 100 + (int)enemyClass, cue, enemyClass == EnemyClass.Boss ? 1f : .78f);
        }

        private IEnumerator QaTerrainRoutine()
        {
            // The former terrain routine sampled a retired three-lane lower plaza.  This map has
            // four diagonal gates and intentional raised islands, so exercising those obsolete
            // coordinates only produced false failures.  Keep the regression test aligned with
            // the real traversable surface and live four-gate movement instead.
            yield return QaFourGateTerrainAudit();
            yield break;

            yield return null;
            // This is deliberately a repeated, live movement test rather than a one-off
            // grid probe. Each defender crosses multiple bends in both directions while the
            // navigation layer verifies that visual rocks, shrubs and cliff pixels never
            // become a collision target.
            Money = 40;
            // Spawn the live path test in the new shared lower plaza before sending each
            // defender through a different branch.
            TryPlaceUnit(UnitArchetype.Tank, new Vector2(-.82f, -5.48f));
            TryPlaceUnit(UnitArchetype.Archer, new Vector2(0f, -5.62f));
            TryPlaceUnit(UnitArchetype.Melee, new Vector2(.82f, -5.48f));
            var left = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Tank);
            var middle = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Archer);
            var right = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Melee);
            if (left == null || middle == null || right == null)
            {
                Debug.LogError("QA_TERRAIN_SETUP_FAILED");
                Application.Quit(9);
                yield break;
            }

            var roadRegion = GetNavigationRegion(left.Position);
            var regionReady = roadRegion > 0 && GetNavigationRegion(middle.Position) == roadRegion &&
                              GetNavigationRegion(right.Position) == roadRegion;
            var stagingPoints = new[]
            {
                new Vector2(-1.10f, -5.52f), new Vector2(0f, -5.92f),
                new Vector2(1.10f, -5.52f), new Vector2(0f, -4.52f),
                new Vector2(-1.76f, -6.52f), new Vector2(-1.84f, -5.62f),
                new Vector2(-2.08f, -4.12f), new Vector2(1.76f, -6.52f),
                new Vector2(1.84f, -5.62f), new Vector2(2.08f, -4.12f),
                new Vector2(-2.18f, -4.82f), new Vector2(2.18f, -4.82f)
            };
            var stagingOpen = stagingPoints.All(point => GetNavigationRegion(point) == roadRegion &&
                                                        IsWalkableWithClearance(point, .18f));
            // The full staging list also samples cells physically covered by the roster. Those
            // remain navigable, but this list specifically covers the exposed red-marked bays.
            var visibleTapPoints = new[]
            {
                new Vector2(-2.08f, -4.12f), new Vector2(-2.18f, -4.82f),
                new Vector2(2.08f, -4.12f), new Vector2(2.18f, -4.82f)
            };
            var stagingClickable = visibleTapPoints.All(point =>
                !IsHudPointer((Vector2)gameCamera.WorldToScreenPoint(point)));
            foreach (var point in visibleTapPoints)
            {
                var screenPoint = (Vector2)gameCamera.WorldToScreenPoint(point);
                var guiPoint = new Vector2(screenPoint.x / UiScale, (Screen.height - screenPoint.y) / UiScale);
                Debug.Log($"QA_TERRAIN_TAP point={point} gui={guiPoint} hud={IsHudPointer(screenPoint)} bottom={IsInteractiveBottomHud(guiPoint)} formation={showFormationPanel}");
            }
            // Sweep the whole exposed portion of each marked bay—not only its centre—so a
            // narrow artificial corridor cannot pass QA while normal player taps still stick.
            var bayPathProbes = new[]
            {
                new Vector2(-2.52f, -4.08f), new Vector2(-2.34f, -4.52f), new Vector2(-1.78f, -4.40f), new Vector2(-1.54f, -4.84f),
                new Vector2(2.52f, -4.08f), new Vector2(2.34f, -4.52f), new Vector2(1.78f, -4.40f), new Vector2(1.54f, -4.84f)
            };
            var bayPathsValid = bayPathProbes.All(point =>
                IsWalkableWithClearance(point, .18f) && FindWalkPath(middle.Position, point, .18f).Count > 0);
            Debug.Log($"QA_TERRAIN_BAY_SWEEP count={bayPathProbes.Length} valid={bayPathsValid}");
            // Dense audit of the complete flat lower field shown on the phone, rather than a
            // handful of hand-picked dots. Every sampled cell must have clearance and a path.
            var lowlandSamples = 0;
            var lowlandReachable = 0;
            for (var y = -5.56f; y <= -2.82f; y += .34f)
            for (var x = -3.16f; x <= 3.16f; x += .34f)
            {
                lowlandSamples++;
                var point = new Vector2(x, y);
                if (GetNavigationRegion(point) == roadRegion && IsWalkableWithClearance(point, .18f) &&
                    FindWalkPath(middle.Position, point, .18f).Count > 0)
                    lowlandReachable++;
            }
            var lowlandWholeOpen = lowlandReachable == lowlandSamples;
            Debug.Log($"QA_TERRAIN_LOWER_FIELD samples={lowlandReachable}/{lowlandSamples} open={lowlandWholeOpen}");
            Debug.Log($"QA_TERRAIN_STAGING open={stagingOpen} clickable={stagingClickable}");
            var leftRoute = new[]
            {
                new Vector2(-3.42f, -4.20f), new Vector2(-3.10f, -2.25f),
                new Vector2(-2.68f, -.15f), new Vector2(-1.62f, 3.12f)
            };
            var middleRoute = new[]
            {
                new Vector2(0f, -4.20f), new Vector2(.02f, -2.25f),
                new Vector2(-.02f, -.15f), new Vector2(-.04f, 3.12f)
            };
            var rightRoute = new[]
            {
                new Vector2(3.42f, -4.20f), new Vector2(3.10f, -2.25f),
                new Vector2(2.68f, -.15f), new Vector2(1.62f, 3.12f)
            };
            var unitsUnderTest = new[] { left, middle, right };
            var routes = new[] { leftRoute, middleRoute, rightRoute };
            var liveMovementPassed = regionReady;
            var completedLegs = 0;

            // Two full passes up the hill and back down exercise 48 independent path plans.
            for (var pass = 0; pass < 2; pass++)
            {
                for (var leg = 0; leg < leftRoute.Length * 2; leg++)
                {
                    var routeIndex = leg < leftRoute.Length ? leg : leftRoute.Length * 2 - leg - 1;
                    for (var i = 0; i < unitsUnderTest.Length; i++)
                        unitsUnderTest[i].MoveTo(routes[i][routeIndex]);
                    // The finer route grid follows the real curved road rather than cutting
                    // diagonally across a shoulder, so long uphill legs need the time that a
                    // real shield bearer needs to walk the curve.
                    yield return new WaitForSecondsRealtime(5.4f);

                    for (var i = 0; i < unitsUnderTest.Length; i++)
                    {
                        var unit = unitsUnderTest[i];
                        var reached = Vector2.Distance(unit.Position, routes[i][routeIndex]) < .38f;
                        var remainedOnRoad = GetNavigationRegion(unit.Position) == roadRegion &&
                                            IsWalkableWithClearance(unit.Position, unit.Radius * .5f);
                        if (!reached || unit.IsMoving || !remainedOnRoad) liveMovementPassed = false;
                    }
                    completedLegs++;
                    Debug.Log($"QA_TERRAIN_LEG pass={pass + 1} leg={leg + 1} reached={liveMovementPassed}");
                }
            }

            // Exercise the exact left/right paved side spurs in live movement, not merely as
            // grid cells. This catches a disconnected-looking deployment island immediately.
            var spursReached = true;
            var spurTargetSets = new[]
            {
                new[] { new Vector2(-2.08f, -4.12f), new Vector2(0f, -4.52f), new Vector2(2.08f, -4.12f) },
                new[] { new Vector2(-2.18f, -4.82f), new Vector2(0f, -5.92f), new Vector2(2.18f, -4.82f) },
                // Exact centres of the two black-circled phone coordinates plus their centre
                // counterpart: these must use the direct flat-field movement branch.
                new[] { new Vector2(-1.92f, -3.03f), new Vector2(0f, -3.03f), new Vector2(1.61f, -2.92f) }
            };
            for (var targetSet = 0; targetSet < spurTargetSets.Length; targetSet++)
            {
                for (var i = 0; i < unitsUnderTest.Length; i++) unitsUnderTest[i].MoveTo(spurTargetSets[targetSet][i]);
                yield return new WaitForSecondsRealtime(4.8f);
                for (var i = 0; i < unitsUnderTest.Length; i++)
                {
                    var reached = Vector2.Distance(unitsUnderTest[i].Position, spurTargetSets[targetSet][i]) < .38f &&
                                  !unitsUnderTest[i].IsMoving;
                    spursReached &= reached;
                    Debug.Log($"QA_TERRAIN_SPUR set={targetSet + 1} unit={unitsUnderTest[i].Archetype} reached={reached}");
                }
            }

            // Off-road click requests may snap to the closest authored road, but they must never
            // lead a unit onto a hill or into decorative collision geometry.
            var forbidden = new[] { new Vector2(-1.50f, 0f), new Vector2(-1.30f, -1.50f), new Vector2(1.50f, 0f) };
            for (var i = 0; i < unitsUnderTest.Length; i++)
                unitsUnderTest[i].MoveTo(forbidden[i]);
            yield return new WaitForSecondsRealtime(6f);
            var offRoadSafe = forbidden.All(point => !IsWalkable(point));
            foreach (var unit in unitsUnderTest)
            {
                var remainedOnRoad = GetNavigationRegion(unit.Position) == roadRegion &&
                                    IsWalkableWithClearance(unit.Position, unit.Radius * .5f);
                Debug.Log($"QA_TERRAIN_OFFROAD unit={unit.Archetype} pos={unit.Position} " +
                          $"road={remainedOnRoad} moving={unit.IsMoving}");
                offRoadSafe &= remainedOnRoad && !unit.IsMoving;
            }

            Debug.Log($"QA_TERRAIN_COMPLETE regionReady={regionReady} stagingOpen={stagingOpen} clickable={stagingClickable} bayPaths={bayPathsValid} lowerField={lowlandWholeOpen} spursReached={spursReached} legs={completedLegs} " +
                      $"liveMovement={liveMovementPassed} offRoadSafe={offRoadSafe}");
            Application.Quit(regionReady && stagingOpen && stagingClickable && bayPathsValid && lowlandWholeOpen && spursReached && liveMovementPassed && offRoadSafe && completedLegs == 16 ? 0 : 6);
        }

