        private IEnumerator QaExpandedMapRoutine()
        {
            yield return null;
            showFormationPanel = false;
            cameraMapCenter = Vector2.zero;
            cameraZoom = cameraZoomTarget = MapHeight * .5f;
            ApplyCameraPose();

            var roster = new[]
            {
                UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Archer,
                UnitArchetype.AreaMage, UnitArchetype.SingleMage,
                UnitArchetype.Bombardier, UnitArchetype.Lancer, UnitArchetype.Druid,
                UnitArchetype.Musketeer, UnitArchetype.Oracle
            };
            var positions = new[]
            {
                new Vector2(-5.0f, -8.55f), new Vector2(-3.0f, -8.55f),
                new Vector2(-1.0f, -8.55f), new Vector2(1.0f, -8.55f),
                new Vector2(3.0f, -8.55f), new Vector2(5.0f, -8.55f),
                new Vector2(-4.0f, -9.45f), new Vector2(-2.0f, -9.45f),
                new Vector2(0f, -9.45f), new Vector2(2.0f, -9.45f)
            };
            for (var i = 0; i < roster.Length; i++)
            {
                var actor = new GameObject("QA 2D " + roster[i]).AddComponent<PlayerUnit>();
                actor.Initialize(this, roster[i], definitions[roster[i]], positions[i]);
                units.Add(actor);
            }

            for (var lane = 0; lane < paths.Count; lane++)
            {
                var enemy = new GameObject("QA Lane " + lane).AddComponent<EnemyUnit>();
                enemy.Initialize(this, lane, 60f, false, lane + 1, lane % 2 == 0 ? EnemyClass.Melee : EnemyClass.Skeleton);
                enemies.Add(enemy);
            }

            yield return null;
            var defendersAreSprites = units.Count == roster.Length && units.All(unit =>
                unit != null &&
                unit.GetComponentInChildren<CrownfrontModelUnitVisual>(true) == null &&
                unit.GetComponentsInChildren<SpriteRenderer>(true)
                    .Any(renderer => renderer.enabled &&
                                     (renderer.name == "Character" || renderer.name == "Upper Body")));
            var enemiesAreSprites = enemies.Count == paths.Count && enemies.All(enemy =>
                enemy != null &&
                enemy.GetComponentInChildren<KayKit2p5DUnitVisual>(true) == null &&
                enemy.GetComponentsInChildren<SpriteRenderer>(true)
                    .Any(renderer => renderer.enabled &&
                                     (renderer.name == "Monster" || renderer.name == "Upper Body")));
            var laneSamplesOpen = paths.All(lane => lane.All(point => IsWalkableWithClearance(point, .18f)));
            var laneRoutesConnected = paths.All(lane =>
            {
                var route = FindWalkPath(lane[0], lane[^1], .18f);
                return route.Count > 0 && Vector2.Distance(route[^1], lane[^1]) < .42f;
            });
            var castleSeparated = !IsWalkable(new Vector2(0f, 9.12f)) &&
                                  paths.All(lane => lane[^1].y < CentralKeepFootprint[0].y - .3f);
            var expanded = MapWidth >= 14f && MapHeight >= 21f &&
                           PlayableHalfWidth >= 6.7f && PlayableHalfHeight >= 10f;
            var passed = mapTexture != null && defendersAreSprites && enemiesAreSprites &&
                         laneSamplesOpen && laneRoutesConnected && castleSeparated && expanded;
            Debug.Log($"QA_EXPANDED_MAP sprites={defendersAreSprites}/{enemiesAreSprites} " +
                      $"lanes={laneSamplesOpen}/{laneRoutesConnected} castleSeparated={castleSeparated} " +
                      $"expanded={expanded} map={MapWidth:0.0}x{MapHeight:0.0}");
            yield return new WaitForSecondsRealtime(11f);
            Application.Quit(passed ? 0 : 21);
        }

        private IEnumerator QaExpandedBattleRoutine()
        {
            yield return null;
            showFormationPanel = false;
            cameraMapCenter = new Vector2(0f, 4.55f);
            cameraZoom = cameraZoomTarget = 4.45f;
            ApplyCameraPose();

            var formation = new[]
            {
                (UnitArchetype.Tank, new Vector2(-1.55f, 6.15f)),
                (UnitArchetype.Melee, new Vector2(-.78f, 5.58f)),
                (UnitArchetype.Archer, new Vector2(0f, 6.18f)),
                (UnitArchetype.AreaMage, new Vector2(.78f, 5.58f)),
                (UnitArchetype.SingleMage, new Vector2(1.55f, 6.15f))
            };
            foreach (var (archetype, position) in formation)
            {
                var actor = new GameObject("QA Battle " + archetype).AddComponent<PlayerUnit>();
                actor.Initialize(this, archetype, definitions[archetype], position);
                units.Add(actor);
            }

            var gateBefore = gateHealth;
            StartWave();
            yield return new WaitForSecondsRealtime(8.5f);
            var spriteDefenders = units.Where(unit => unit != null && unit.IsAlive).All(unit =>
                unit.GetComponentInChildren<CrownfrontModelUnitVisual>(true) == null &&
                unit.GetComponentsInChildren<SpriteRenderer>(true)
                    .Any(renderer => renderer.name == "Character" && renderer.enabled));
            var spriteEnemies = enemies.Where(enemy => enemy != null && enemy.IsAlive).All(enemy =>
                enemy.GetComponentInChildren<KayKit2p5DUnitVisual>(true) == null &&
                enemy.GetComponentsInChildren<SpriteRenderer>(true)
                    .Any(renderer => renderer.name == "Monster" && renderer.enabled));
            var progressed = enemies.Count > 0 && enemies.Any(enemy => enemy != null && enemy.PathIndex > 3);
            var stayedBelowCastle = enemies.All(enemy => enemy == null || !enemy.IsAlive ||
                                                         enemy.Position.y < CentralKeepFootprint[0].y);
            var prematureGateDamage = gateHealth < gateBefore;
            var passed = Phase == GamePhase.Battle && spriteDefenders && spriteEnemies &&
                         progressed && stayedBelowCastle && !prematureGateDamage;
            Debug.Log($"QA_EXPANDED_BATTLE phase={Phase} enemies={enemies.Count} progressed={progressed} " +
                      $"sprites={spriteDefenders}/{spriteEnemies} belowCastle={stayedBelowCastle} " +
                      $"gateUntouched={!prematureGateDamage}");
            Application.Quit(passed ? 0 : 22);
        }

        private IEnumerator QaMovementPolishRoutine()
        {
            yield return null;
            showFormationPanel = false;
            cameraMapCenter = new Vector2(0f, -8.55f);
            cameraZoom = cameraZoomTarget = 3.15f;
            ApplyCameraPose();

            var order = new[]
            {
                UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Archer,
                UnitArchetype.AreaMage, UnitArchetype.SingleMage
            };
            for (var i = 0; i < order.Length; i++)
            {
                var position = new Vector2(-2.1f + i * 1.05f, -8.45f);
                var actor = new GameObject("QA Movement " + order[i]).AddComponent<PlayerUnit>();
                actor.Initialize(this, order[i], definitions[order[i]], position);
                units.Add(actor);
            }

            SpriteRenderer CharacterRenderer(PlayerUnit unit) =>
                unit.GetComponentsInChildren<SpriteRenderer>(true)
                    .FirstOrDefault(renderer => renderer.name == "Character");

            var sideFrames = units.ToDictionary(unit => unit, _ => new HashSet<Sprite>());
            var downFrames = units.ToDictionary(unit => unit, _ => new HashSet<Sprite>());
            var sawLegacyMeshDust = false;

            SpawnMoveCommandPing(new Vector2(0f, -7.72f), units.Count);
            // Let the ping coroutine apply its first eased world-space frame before measuring.
            yield return new WaitForSecondsRealtime(.04f);
            var ping = GameObject.Find("Move Command Ping");
            var outerRipple = ping != null ? ping.transform.Find("Destination Ring Outer") : null;
            var cleanPing = ping != null && outerRipple != null && CommandRingSprite != null &&
                            outerRipple.localScale.y < outerRipple.localScale.x * .7f;

            foreach (var unit in units) unit.MoveTo(unit.Position + Vector2.right * 1.32f);
            for (var sample = 0; sample < 19; sample++)
            {
                yield return new WaitForSecondsRealtime(.065f);
                foreach (var unit in units)
                {
                    var renderer = CharacterRenderer(unit);
                    if (renderer != null && renderer.sprite != null) sideFrames[unit].Add(renderer.sprite);
                }
                sawLegacyMeshDust |= FindObjectsByType<Stylized2p5DMeshEffect>(FindObjectsSortMode.None).Length > 0;
            }

            foreach (var unit in units) unit.MoveTo(unit.Position + Vector2.down * 1.25f);
            for (var sample = 0; sample < 19; sample++)
            {
                yield return new WaitForSecondsRealtime(.065f);
                foreach (var unit in units)
                {
                    var renderer = CharacterRenderer(unit);
                    if (renderer != null && renderer.sprite != null) downFrames[unit].Add(renderer.sprite);
                }
                sawLegacyMeshDust |= FindObjectsByType<Stylized2p5DMeshEffect>(FindObjectsSortMode.None).Length > 0;
            }

            var nonTank = units.Where(unit => unit.Archetype != UnitArchetype.Tank).ToArray();
            var sideAnimated = nonTank.All(unit => sideFrames[unit].Count >= 4);
            var downAnimated = nonTank.All(unit => downFrames[unit].Count >= 4);
            var eightWayLoaded = nonTank.All(unit =>
            {
                var set = GetDirectionalAnimation(unit.Archetype, false);
                return set.SupportsEightDirections &&
                       System.Enum.GetValues(typeof(FacingOctant)).Cast<FacingOctant>()
                           .All(octant => set.FramesFor(octant).Length >= 48);
            });
            var passed = cleanPing && !sawLegacyMeshDust && sideAnimated && downAnimated && eightWayLoaded;
            Debug.Log($"QA_MOVEMENT_POLISH ping={cleanPing} legacyDust={!sawLegacyMeshDust} " +
                      $"side={sideAnimated} down={downAnimated} eightWay={eightWayLoaded} " +
                      $"sideFrames={string.Join(",", nonTank.Select(unit => sideFrames[unit].Count))} " +
                      $"downFrames={string.Join(",", nonTank.Select(unit => downFrames[unit].Count))}");
            Application.Quit(passed ? 0 : 23);
        }

        private IEnumerator QaWeaponConsistencyRoutine()
        {
            yield return null;
            showFormationPanel = false;
            cameraMapCenter = new Vector2(0f, -7.55f);
            cameraZoom = cameraZoomTarget = 4.35f;
            ApplyCameraPose();

            var checks = new[]
            {
                (UnitArchetype.Tank, false, "walk-tank-consistent-v1"),
                (UnitArchetype.Melee, false, "walk-melee-consistent-v1"),
                (UnitArchetype.SingleMage, false, "walk-single-mage-consistent-v1"),
                (UnitArchetype.SingleMage, true, "walk-hero-single-mage-consistent-v1")
            };
            var provenance = true;
            var stableCoverage = true;
            for (var checkIndex = 0; checkIndex < checks.Length; checkIndex++)
            {
                var check = checks[checkIndex];
                // Provenance checks the canonical base weapon sheet, independent of the skin
                // a previous QA player (or developer) left equipped in PlayerPrefs.
                monetization.EquipDefault(ShopCategory.Unit, check.Item1);
                var set = GetDirectionalAnimation(check.Item1, check.Item2);
                var sourceTexture = Resources.Load<Texture2D>(check.Item3);
                var directions = new[] { set.Down.Take(4).ToArray(), set.Side.Take(4).ToArray() };
                for (var directionIndex = 0; directionIndex < directions.Length; directionIndex++)
                {
                    var frames = directions[directionIndex];
                    provenance &= frames.Length == 4 && frames.All(frame =>
                        frame != null && frame.texture.name.Contains(check.Item3));
                    var widths = Enumerable.Range(0, 4)
                        .Select(column => VisibleCellWidth(sourceTexture, directionIndex, 2, column, 4))
                        .ToArray();
                    var minimum = widths.Length > 0 ? widths.Min() : 0;
                    var maximum = widths.Length > 0 ? widths.Max() : int.MaxValue;
                    stableCoverage &= minimum > 48 && maximum <= minimum * 1.58f;

                    for (var frameIndex = 0; frameIndex < frames.Length; frameIndex++)
                    {
                        var root = new GameObject($"QA {check.Item1} {(check.Item2 ? "Hero" : "Base")} " +
                                                  $"{directionIndex}-{frameIndex}");
                        root.transform.position = new Vector3(-2.15f + frameIndex * 1.43f,
                            -4.95f - (checkIndex * 2 + directionIndex) * .78f, -2.2f);
                        var renderer = CreateSpriteChild(root.transform, "Verified Walk Frame",
                            frames[frameIndex], Color.white, .66f, 20);
                        renderer.transform.localPosition = Vector3.zero;
                    }
                }
            }

            var passed = provenance && stableCoverage;
            Debug.Log($"QA_WEAPON_CONSISTENCY provenance={provenance} stableCoverage={stableCoverage} " +
                      $"sets={checks.Length} frames={checks.Length * 8}");
            yield return new WaitForSecondsRealtime(2.2f);
            Application.Quit(passed ? 0 : 24);
        }

        private static int VisibleCellWidth(Texture2D texture, int topRow, int rows, int column, int columns)
        {
            if (texture == null) return 0;
            Color32[] pixels;
            try { pixels = texture.GetPixels32(); }
            catch (UnityException) { return 0; }
            var left = Mathf.RoundToInt(column * texture.width / (float)columns);
            var right = Mathf.RoundToInt((column + 1) * texture.width / (float)columns);
            var bottom = Mathf.RoundToInt(texture.height - (topRow + 1) * texture.height / (float)rows);
            var top = Mathf.RoundToInt(texture.height - topRow * texture.height / (float)rows);
            var minX = right;
            var maxX = -1;
            for (var y = bottom; y < top; y++)
            for (var x = left; x < right; x++)
            {
                if (pixels[y * texture.width + x].a <= 14) continue;
                minX = Mathf.Min(minX, x);
                maxX = Mathf.Max(maxX, x);
            }
            return maxX >= minX ? maxX - minX + 1 : 0;
        }

        private IEnumerator QaProductionRosterRoutine()
        {
            yield return null;
            cameraMapCenter = new Vector2(0f, -4.10f);
            cameraZoom = cameraZoomTarget = 6.30f;
            ApplyCameraPose();

            var roster = new[]
            {
                UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Archer,
                UnitArchetype.AreaMage, UnitArchetype.SingleMage,
                UnitArchetype.Bombardier, UnitArchetype.Lancer, UnitArchetype.Druid,
                UnitArchetype.Musketeer, UnitArchetype.Oracle
            };
            var requested = new[]
            {
                new Vector2(-3.30f, -5.95f), new Vector2(-3.16f, -4.72f),
                new Vector2(-3.05f, -3.48f), new Vector2(3.30f, -5.95f),
                new Vector2(3.16f, -4.72f), new Vector2(3.05f, -3.48f),
                new Vector2(0f, -5.95f), new Vector2(0f, -4.72f),
                new Vector2(0f, -3.48f), new Vector2(0f, -2.25f)
            };

            for (var i = 0; i < roster.Length; i++)
            {
                var definition = definitions[roster[i]];
                var position = NearestWalkable(requested[i], definition.Radius * .55f);
                var actor = new GameObject("QA " + roster[i]).AddComponent<PlayerUnit>();
                actor.Initialize(this, roster[i], definition, position);
                units.Add(actor);
                actor.AddExperience(999f);
                actor.PreviewProductionAction(i);
                Debug.Log($"QA_PRODUCTION_POSITION role={roster[i]} requested={requested[i]} actual={position}");
            }

            yield return null;
            var visuals = units
                .Where(unit => unit != null)
                .Select(unit => unit.GetComponentInChildren<CrownfrontModelUnitVisual>(true))
                .Where(visual => visual != null)
                .ToArray();
            var completeRigs = visuals.Count(visual => visual.HasCompleteRig);
            var authoredColliders = visuals.Count(visual => visual.HasAuthoredCollider);
            var heroParts = visuals.Count(visual => visual.HeroPartCount >= 3);
            var allResources = roster.All(CrownfrontModelUnitVisual.HasProductionModel);
            var actionCounts = roster.Select(CrownfrontModelUnitVisual.ImportedActionCount).ToArray();
            var allActions = actionCounts.All(count => count >= 8);
            var sizeNormalized = visuals.All(visual => visual.VisualHeight is >= .38f and <= 1.45f);
            // A boot may be lifted by the sampled walk frame; up to .13 world units is under
            // one sixth of the narrowest lane and still overlaps its contact shadow.
            var grounded = visuals.All(visual => visual.FootOffset is >= -.42f and <= .13f);
            var initialPoses = visuals.Select(visual => visual.PoseSignature).ToArray();
            foreach (var visual in visuals)
                Debug.Log($"QA_PRODUCTION_METRIC height={visual.VisualHeight:0.000} " +
                          $"foot={visual.FootOffset:0.000} heroParts={visual.HeroPartCount}");
            Debug.Log($"QA_PRODUCTION_ROSTER units={units.Count} visuals={visuals.Length} " +
                      $"rigs={completeRigs} colliders={authoredColliders} heroes={heroParts} " +
                      $"resources={allResources} clips=[{string.Join(",", actionCounts)}] " +
                      $"sizes={sizeNormalized} grounded={grounded}");

            yield return new WaitForSecondsRealtime(1.15f);
            for (var i = 0; i < units.Count; i++)
            {
                units[i].PreviewProductionAction(i + 1);
                var direction = i < 5 ? Vector2.up : Vector2.down;
                units[i].MoveTo(units[i].Position + direction * .55f);
            }

            yield return new WaitForSecondsRealtime(.24f);
            var animated = 0;
            for (var i = 0; i < visuals.Length; i++)
                if (Mathf.Abs(visuals[i].PoseSignature - initialPoses[i]) > .015f) animated++;
            Debug.Log($"QA_PRODUCTION_ANIMATION changed={animated}/{roster.Length}");

            var passed = units.Count == roster.Length && visuals.Length == roster.Length &&
                         completeRigs == roster.Length && authoredColliders == roster.Length &&
                         heroParts == roster.Length && allResources && allActions &&
                         sizeNormalized && grounded && animated == roster.Length;
            yield return new WaitForSecondsRealtime(10f);
            Application.Quit(passed ? 0 : 17);
        }

        private IEnumerator QaDiagonalCitadelRoutine()
        {
            yield return null;
            // Live regression for all four distant diagonal gates. Each defender starts in a
            // different quadrant, reaches its own keep face, then rotates through the inner
            // ring. This specifically catches shared-gate clipping and short side spawns.
            Money = 64;
            var starts = new[]
            {
                new Vector2(-3.20f, 3.02f), new Vector2(3.20f, 3.02f),
                new Vector2(-3.20f, -3.02f), new Vector2(3.20f, -3.02f)
            };
            TryPlaceUnit(UnitArchetype.Tank, starts[0]);
            TryPlaceUnit(UnitArchetype.Archer, starts[1]);
            TryPlaceUnit(UnitArchetype.Melee, starts[2]);
            TryPlaceUnit(UnitArchetype.AreaMage, starts[3]);
            var squads = new[]
            {
                units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Tank),
                units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Archer),
                units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Melee),
                units.Find(unit => unit != null && unit.Archetype == UnitArchetype.AreaMage)
            };
            if (squads.Any(unit => unit == null))
            {
                Debug.LogError("QA_DIAGONAL_SETUP_FAILED");
                Application.Quit(9);
                yield break;
            }

            // Elevation regression: a hill is deployable but not part of the road graph.  A
            // ground squad cannot climb to it, a hill squad cannot descend, and only an enemy
            // explicitly allowed to attack high ground can acquire that squad.
            var highGroundPoint = HighGroundZones[0].Center;
            var unitCountBeforeHillPlacement = units.Count;
            TryPlaceUnit(UnitArchetype.Tank, highGroundPoint);
            var hillUnit = units.Count > unitCountBeforeHillPlacement ? units[^1] : null;
            var highPlacement = hillUnit != null && hillUnit.IsOnHighGround &&
                                Vector2.Distance(hillUnit.Position, highGroundPoint) < .08f;
            var groundCannotClimb = FindWalkPath(squads[0].Position, highGroundPoint, squads[0].Radius * .5f).Count == 0;
            var hillCannotDescend = hillUnit != null &&
                                    FindWalkPath(hillUnit.Position, starts[0], hillUnit.Radius * .5f).Count == 0;
            var highGroundTargeting = hillUnit != null &&
                                    FindDefenderTarget(highGroundPoint, .7f, false) == null &&
                                    FindDefenderTarget(highGroundPoint, .7f, true) == hillUnit;

            var region = GetNavigationRegion(squads[0].Position);
            var faces = new[]
            {
                GetGateAttackPoint(0), GetGateAttackPoint(1), GetGateAttackPoint(2), GetGateAttackPoint(3)
            };
            var outerApproaches = new[]
            {
                GetPathTarget(0, 56, 0f, 0f), GetPathTarget(1, 56, 0f, 0f),
                GetPathTarget(2, 56, 0f, 0f), GetPathTarget(3, 56, 0f, 0f)
            };
            var diagonalRoutes = Enumerable.Range(0, 4).All(lane =>
            {
                var approach = outerApproaches[lane];
                return GetNavigationRegion(approach) == region &&
                       IsWalkableWithClearance(approach, .2f) &&
                       IsWalkableWithClearance(faces[lane], .2f) &&
                       FindWalkPath(approach, faces[lane], .2f).Count > 0;
            });
            // Wide surface regression for the 2.5D ground layer.  These routes cross the old
            // black-mask trouble spots in both directions; none may become a one-way or
            // "cannot go down" strip merely because it is away from a painted road spline.
            var broadSurfaceRoutes = new[]
            {
                (new Vector2(-3.55f, 5.72f), new Vector2(-3.55f, -5.72f)),
                (new Vector2(3.55f, 5.72f), new Vector2(3.55f, -5.72f)),
                (new Vector2(-3.78f, -5.42f), new Vector2(3.78f, -5.42f)),
                (new Vector2(-3.78f, 2.22f), new Vector2(3.78f, 2.22f)),
                (new Vector2(-3.78f, -2.22f), new Vector2(3.78f, -2.22f))
            }.All(route => FindWalkPath(route.Item1, route.Item2, .2f).Count > 0 &&
                           FindWalkPath(route.Item2, route.Item1, .2f).Count > 0);
            var keepBlocked = new[]
            {
                GatePosition, new Vector2(1.45f, 0f), new Vector2(-1.45f, 0f),
                new Vector2(0f, 1.45f), new Vector2(0f, -1.45f),
                new Vector2(1.55f, 1.55f), new Vector2(-1.55f, -1.55f)
            }.All(point => !IsWalkable(point));

            var live = region > 0;
            for (var i = 0; i < squads.Length; i++) squads[i].MoveTo(faces[i]);
            yield return new WaitForSecondsRealtime(6.5f);
            for (var i = 0; i < squads.Length; i++)
            {
                var reached = Vector2.Distance(squads[i].Position, faces[i]) < .48f && !squads[i].IsMoving;
                live &= reached && IsWalkableWithClearance(squads[i].Position, squads[i].Radius * .5f);
                Debug.Log($"QA_DIAGONAL_FACE lane={i} reached={reached} pos={squads[i].Position}");
            }

            for (var i = 0; i < squads.Length; i++) squads[i].MoveTo(faces[(i + 1) % faces.Length]);
            yield return new WaitForSecondsRealtime(8.5f);
            for (var i = 0; i < squads.Length; i++)
            {
                var target = faces[(i + 1) % faces.Length];
                var reached = Vector2.Distance(squads[i].Position, target) < .5f && !squads[i].IsMoving;
                live &= reached && IsWalkableWithClearance(squads[i].Position, squads[i].Radius * .5f);
                Debug.Log($"QA_DIAGONAL_RING lane={i} reached={reached} pos={squads[i].Position}");
            }

            var separateGateFaces = true;
            var gateEnemies = new List<EnemyUnit>();
            for (var lane = 0; lane < 4; lane++)
            {
                var enemy = new GameObject($"QA Diagonal Gate {lane}").AddComponent<EnemyUnit>();
                enemy.Initialize(this, lane, 100f, false, lane, EnemyClass.Melee);
                enemy.ForceAtGateForQa();
                gateEnemies.Add(enemy);
            }
            for (var i = 0; i < gateEnemies.Count; i++)
            for (var j = i + 1; j < gateEnemies.Count; j++)
                if (Vector2.Distance(gateEnemies[i].Position, gateEnemies[j].Position) < 1.4f)
                    separateGateFaces = false;
            var gateFacesOutsideKeep = gateEnemies.All(enemy =>
                enemy.Position.magnitude > 2.62f && IsWalkableWithClearance(enemy.Position, .2f));

            Debug.Log($"QA_DIAGONAL_CITADEL_COMPLETE routes={diagonalRoutes} broadSurface={broadSurfaceRoutes} keepBlocked={keepBlocked} live={live} separated={separateGateFaces} facesOutsideKeep={gateFacesOutsideKeep} highPlacement={highPlacement} groundLocked={groundCannotClimb} hillLocked={hillCannotDescend} highTargeting={highGroundTargeting} regions={CountNavigationRegions()}");
            Application.Quit(diagonalRoutes && broadSurfaceRoutes && keepBlocked && live && separateGateFaces && gateFacesOutsideKeep && highPlacement && groundCannotClimb && hillCannotDescend && highGroundTargeting && CountNavigationRegions() == 1 ? 0 : 6);
        }

        private IEnumerator QaFourGatesRoutine()
        {
            yield return null;
            // Regression test for the wide Four Gates tactical map. It verifies every
            // deployment cell in the South muster field, all gate sectors, and live walks
            // through the South, West and East approaches to the North Citadel.
            Money = 40;
            TryPlaceUnit(UnitArchetype.Tank, new Vector2(-.72f, -5.72f));
            TryPlaceUnit(UnitArchetype.Archer, new Vector2(0f, -5.86f));
            TryPlaceUnit(UnitArchetype.Melee, new Vector2(.72f, -5.72f));
            var tank = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Tank);
            var archer = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Archer);
            var melee = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Melee);
            if (tank == null || archer == null || melee == null)
            {
                Debug.LogError("QA_FOUR_GATES_SETUP_FAILED");
                Application.Quit(9);
                yield break;
            }

            var region = GetNavigationRegion(archer.Position);
            var southSamples = 0;
            var southReachable = 0;
            for (var y = -6.48f; y <= -4.70f; y += .26f)
            for (var x = -2.12f; x <= 2.12f; x += .26f)
            {
                southSamples++;
                var point = new Vector2(x, y);
                if (GetNavigationRegion(point) == region && IsWalkableWithClearance(point, .18f) &&
                    FindWalkPath(archer.Position, point, .18f).Count > 0)
                    southReachable++;
            }
            var southOpen = southReachable == southSamples;
            var sectors = new[]
            {
                new Vector2(0f, -4.56f), new Vector2(0f, -2.68f), new Vector2(0f, -.68f),
                new Vector2(0f, 1.28f), new Vector2(0f, 3.05f), new Vector2(-3.12f, 4.48f),
                new Vector2(3.12f, 4.48f), new Vector2(0f, 4.62f)
            };
            var sectorPaths = sectors.All(point => GetNavigationRegion(point) == region &&
                                                     IsWalkableWithClearance(point, .18f) &&
                                                     FindWalkPath(archer.Position, point, .18f).Count > 0);
            var cliffsBlocked = HillShoulderBlockers.All(blocker => !IsWalkable(new Vector2(blocker.x, blocker.y)));

            var squads = new[] { tank, archer, melee };
            var liveTargets = new[]
            {
                new[] { new Vector2(0f, -4.56f), new Vector2(-3.12f, 4.48f), new Vector2(0f, 4.62f), new Vector2(0f, -5.05f) },
                new[] { new Vector2(0f, -4.56f), new Vector2(0f, 3.05f), new Vector2(0f, 4.62f), new Vector2(0f, -5.05f) },
                new[] { new Vector2(0f, -4.56f), new Vector2(3.12f, 4.48f), new Vector2(0f, 4.62f), new Vector2(0f, -5.05f) }
            };
            var waitTimes = new[] { 4.5f, 12f, 6.5f, 12f };
            var liveMovement = region > 0;
            for (var leg = 0; leg < waitTimes.Length; leg++)
            {
                for (var i = 0; i < squads.Length; i++) squads[i].MoveTo(liveTargets[i][leg]);
                yield return new WaitForSecondsRealtime(waitTimes[leg]);
                for (var i = 0; i < squads.Length; i++)
                {
                    var unit = squads[i];
                    var reached = Vector2.Distance(unit.Position, liveTargets[i][leg]) < .52f && !unit.IsMoving;
                    var valid = GetNavigationRegion(unit.Position) == region &&
                                IsWalkableWithClearance(unit.Position, unit.Radius * .5f);
                    liveMovement &= reached && valid;
                    Debug.Log($"QA_FOUR_GATES_LEG leg={leg + 1} unit={unit.Archetype} reached={reached} pos={unit.Position}");
                }
            }
            Debug.Log($"QA_FOUR_GATES_COMPLETE south={southReachable}/{southSamples} southOpen={southOpen} sectors={sectorPaths} cliffsBlocked={cliffsBlocked} live={liveMovement}");
            Application.Quit(southOpen && sectorPaths && cliffsBlocked && liveMovement ? 0 : 6);
        }

        private IEnumerator QaBackMenuRoutine()
        {
            yield return null;
            // Reproduce Android: system menu -> exit confirmation -> second Back.
            showMainMenu = false;
            showSystemMenu = true;
            showExitConfirm = true;
            showSettings = false;
            exitConfirmFromSystemMenu = true;
            Time.timeScale = 0f;
            HandleBackButton();
            var confirmDismissed = !showExitConfirm && !showSystemMenu && !showSettings &&
                                   Mathf.Approximately(Time.timeScale, 1f);

            showSystemMenu = true;
            Time.timeScale = 0f;
            HandleBackButton();
            var menuDismissed = !showSystemMenu && Mathf.Approximately(Time.timeScale, 1f);
            Debug.Log($"QA_BACK_MENU confirmDismissed={confirmDismissed} menuDismissed={menuDismissed}");
            Application.Quit(confirmDismissed && menuDismissed ? 0 : 10);
        }

        private IEnumerator QaRelease213Routine()
        {
            yield return null;
            var families = new HashSet<EnemyClass>();
            var familyBlocksValid = true;
            var countCurveValid = true;
            for (var round = 1; round <= MaxRounds; round++)
            {
                var family = MonsterClassForRound(round);
                families.Add(family);
                var blockStart = ((round - 1) / 5) * 5 + 1;
                familyBlocksValid &= MonsterClassForRound(blockStart) == family &&
                                     MonsterClassForRound(blockStart + 4) == family;
                countCurveValid &= WaveEnemyCount(round) is >= 12 and <= 96;
            }

            for (var chapter = 0; chapter < 10; chapter++)
            {
                var opener = WaveEnemyCount(chapter * 5 + 1);
                var stage2 = WaveEnemyCount(chapter * 5 + 2);
                var stage3 = WaveEnemyCount(chapter * 5 + 3);
                var stage4 = WaveEnemyCount(chapter * 5 + 4);
                var bossBudget = WaveEnemyCount(chapter * 5 + 5);
                countCurveValid &= stage2 > opener && stage3 > stage2 && stage4 > stage3 &&
                                   bossBudget >= opener && bossBudget <= stage4 + 8;
                if (chapter > 0)
                    countCurveValid &= opener > WaveEnemyCount((chapter - 1) * 5 + 1);
            }

            var distinctSpecialArt =
                GetEnemyStaticSprite(EnemyClass.Shaman, false) != GetEnemyStaticSprite(EnemyClass.Mage, false) &&
                GetEnemyStaticSprite(EnemyClass.Piercer, false) != GetEnemyStaticSprite(EnemyClass.Runner, false) &&
                GetEnemyStaticSprite(EnemyClass.Wisp, false) != GetEnemyStaticSprite(EnemyClass.Mage, false);

            showMissionPanel = true;
            var missionBlocksBase = !MainMenuBaseInputEnabled;
            showMissionPanel = false;
            showSettings = true;
            var settingsBlockBase = !MainMenuBaseInputEnabled;
            showSettings = false;
            showShopPanel = true;
            var shopBlocksBase = !MainMenuBaseInputEnabled;
            showShopPanel = false;
            showGuidePanel = true;
            var guideBlocksBase = !MainMenuBaseInputEnabled;
            showGuidePanel = false;

            var catalogValid = monetization != null && monetization.Products.Count >= 7 &&
                               monetization.Products.Any(product =>
                                   product.Id == CrownfrontMonetization.RemoveAdsId &&
                                   product.FallbackPrice.Contains("4,900")) &&
                               Enum.GetValues(typeof(ShopCategory)).Cast<ShopCategory>().All(category =>
                                   monetization.Products.Any(product => product.Category == category));

            Phase = GamePhase.Battle;
            var beforeFeedback = hitFeedbackCount;
            SpawnHitFeedback(Vector2.zero, Vector2.left, new Color(1f, .65f, .18f), 1.4f);
            yield return new WaitForSecondsRealtime(.32f);
            var hitFeedbackVisible = hitFeedbackCount == beforeFeedback + 1;
            var passed = families.Count == 10 && familyBlocksValid && countCurveValid && distinctSpecialArt &&
                         missionBlocksBase && settingsBlockBase && shopBlocksBase && guideBlocksBase && catalogValid &&
                         hitFeedbackVisible && WaveEnemyCount(50) > WaveEnemyCount(5);
            Debug.Log($"QA_RELEASE_213 families={families.Count} blocks={familyBlocksValid} " +
                      $"counts={countCurveValid}:{WaveEnemyCount(1)}-{WaveEnemyCount(50)} " +
                      $"specialArt={distinctSpecialArt} modal={missionBlocksBase && settingsBlockBase && shopBlocksBase && guideBlocksBase} " +
                      $"catalog={catalogValid} hit={hitFeedbackVisible}");
            Application.Quit(passed ? 0 : 31);
        }

        private IEnumerator QaEnemyAnimationsV2Routine()
        {
            yield return null;
            Phase = GamePhase.Battle;
            var classes = new[]
            {
                EnemyClass.Melee, EnemyClass.Mage, EnemyClass.Skeleton, EnemyClass.Runner, EnemyClass.Brute,
                EnemyClass.Shaman, EnemyClass.Siege, EnemyClass.Piercer, EnemyClass.Wisp, EnemyClass.Flyer
            };
            var distinctArt = new HashSet<Sprite>();
            var bossProfiles = new HashSet<string>();
            var completeFrames = true;
            var separatedStates = true;
            var actualWalkMotion = true;
            var actualActionMotion = true;
            var actualBossMotion = true;
            var seamSafeWholeBodies = true;
            float AnimationPoseDistance(Vector4 a, Vector4 b) => Vector4.Distance(a, b);
            var effectsBefore = enemyClassEffectCount;
            for (var i = 0; i < classes.Length; i++)
            {
                var enemyClass = classes[i];
                var frames = GetEnemyAnimationFrames(enemyClass);
                completeFrames &= frames.Length == 72;
                if (frames.Length > 0) distinctArt.Add(frames[0]);

                var probe = new GameObject($"QA {enemyClass} Animation").AddComponent<EnemyUnit>();
                probe.Initialize(this, i, 1500f, false, i % Mathf.Max(1, LaneCount), enemyClass);
                probe.ForcePositionForQa(new Vector2(-4.4f + i * .92f, -1.6f + (i % 2) * .8f));
                var walkFrame = probe.PreviewAnimationForQa(0);
                var attackFrame = probe.PreviewAnimationForQa(1);
                var skillFrame = probe.PreviewAnimationForQa(2);
                Debug.Log($"QA_ENEMY_ANIMATION_STATE class={enemyClass} frames={frames.Length} " +
                          $"walk={walkFrame} attack={attackFrame} skill={skillFrame}");
                separatedStates &= walkFrame >= 0 && walkFrame <= 23 &&
                                   attackFrame is >= 24 and <= 47 &&
                                   skillFrame is >= 48 and <= 71 &&
                                   attackFrame != skillFrame;
                var walkPoses = new[] { .12f, .37f, .62f, .87f }
                    .Select(phase => probe.PreviewMotionPoseForQa(Vector2.down, 0, phase)).ToArray();
                var walkPoseRange = walkPoses.SelectMany((pose, index) => walkPoses.Skip(index + 1)
                    .Select(other => AnimationPoseDistance(pose, other))).DefaultIfEmpty(0f).Max();
                var attackA = probe.PreviewMotionPoseForQa(Vector2.down, 1, .18f);
                var attackB = probe.PreviewMotionPoseForQa(Vector2.down, 1, .5f);
                var skillA = probe.PreviewMotionPoseForQa(Vector2.down, 2, .18f);
                var skillB = probe.PreviewMotionPoseForQa(Vector2.down, 2, .5f);
                actualWalkMotion &= walkPoseRange >= .012f;
                actualActionMotion &= AnimationPoseDistance(attackA, attackB) >= .07f &&
                                      AnimationPoseDistance(skillA, skillB) >= .035f;
                seamSafeWholeBodies &= probe.UsesSeamSafeWholeBodyAnimationForQa;
                SpawnEnemyClassEffect(probe.Position, probe.Position + Vector2.up * .55f, enemyClass, true);

                var bossProbe = new GameObject($"QA {enemyClass} Boss Profile").AddComponent<EnemyUnit>();
                bossProbe.Initialize(this, i + 30, 2200f, true, i % Mathf.Max(1, LaneCount), enemyClass);
                bossProfiles.Add(bossProbe.BossSkillProfileId);
                var bossWalkPoses = new[] { .12f, .37f, .62f, .87f }
                    .Select(phase => bossProbe.PreviewMotionPoseForQa(Vector2.down, 0, phase)).ToArray();
                var bossWalkPoseRange = bossWalkPoses.SelectMany((pose, index) => bossWalkPoses.Skip(index + 1)
                    .Select(other => AnimationPoseDistance(pose, other))).DefaultIfEmpty(0f).Max();
                var bossAttackA = bossProbe.PreviewMotionPoseForQa(Vector2.down, 1, .18f);
                var bossAttackB = bossProbe.PreviewMotionPoseForQa(Vector2.down, 1, .5f);
                var bossSkillA = bossProbe.PreviewMotionPoseForQa(Vector2.down, 2, .18f);
                var bossSkillB = bossProbe.PreviewMotionPoseForQa(Vector2.down, 2, .5f);
                actualBossMotion &= bossWalkPoseRange >= .012f &&
                                    AnimationPoseDistance(bossAttackA, bossAttackB) >= .07f &&
                                    AnimationPoseDistance(bossSkillA, bossSkillB) >= .035f;
                seamSafeWholeBodies &= bossProbe.UsesSeamSafeWholeBodyAnimationForQa;
            }

            yield return new WaitForSecondsRealtime(.18f);
            var effects = enemyClassEffectCount - effectsBefore;
            var passed = completeFrames && separatedStates && actualWalkMotion && actualActionMotion && seamSafeWholeBodies &&
                         actualBossMotion && distinctArt.Count == classes.Length &&
                         bossProfiles.Count == classes.Length && effects == classes.Length;
            Debug.Log($"QA_ENEMY_ANIMATIONS_V2 families={classes.Length} art={distinctArt.Count} " +
                      $"frames={completeFrames} states={separatedStates} walkMotion={actualWalkMotion} " +
                      $"actionMotion={actualActionMotion} seamSafeWholeBodies={seamSafeWholeBodies} " +
                      $"bossMotion={actualBossMotion} bossSkills={bossProfiles.Count} " +
                      $"effects={effects}");
            Application.Quit(passed ? 0 : 35);
        }

        private IEnumerator QaBossPresentationRoutine()
        {
            yield return null;
            Phase = GamePhase.Battle;

            var defender = new GameObject("QA Focus Defender").AddComponent<PlayerUnit>();
            defender.Initialize(this, UnitArchetype.Archer, definitions[UnitArchetype.Archer],
                NearestWalkable(new Vector2(0f, -6.8f), .18f));
            units.Add(defender);
            var target = new GameObject("QA Focus Target").AddComponent<EnemyUnit>();
            target.Initialize(this, 0, 800f, false, 0, EnemyClass.Melee);
            target.SetSummonedPosition(NearestWalkable(new Vector2(0f, -5.4f), .18f), 0);
            enemies.Add(target);
            SelectOnly(defender);
            CommandAttack(target);
            var focusMarked = MarkedAttackTarget == target && AttackOrderMarkerPartCount >= 7 &&
                              defender.HasForcedAttackOrderOn(target);

            Round = 5;
            ApplyBattlefieldMood(EnemyClass.Shaman, true);
            var bossProfile = EnemyVariantCatalog.ForChapterStage(0, 4);
            var escortProfile = EnemyVariantCatalog.ForChapterStage(0, 3);
            var baseHealth = BaseEnemyHealth(Round);
            SpawnBossFormation(bossProfile, escortProfile, baseHealth * 4.65f, baseHealth);
            yield return null;
            var boss = FindBoss();
            var entranceUnits = enemies.Count(enemy => enemy != null && enemy.UsesBossEntrance);
            var entranceClear = bossEntrancePath.Count > 10 &&
                                bossEntrancePath.All(point => IsWalkableWithClearance(point, .28f));
            var bossReady = boss != null && boss.IsBoss && boss.Radius >= .62f &&
                            boss.HasBossPresentation && boss.UsesBossEntrance && boss.Position.y < -8.9f;
            var formationReady = bossFormationSpawnCount == 6 && entranceUnits == 6;
            var moodReady = battlefieldMoodClass == EnemyClass.Shaman &&
                            battlefieldMoodTarget.g > battlefieldMoodTarget.r &&
                            battlefieldMoodWash != null && battlefieldMoodGlow != null;
            var passed = focusMarked && bossReady && formationReady && entranceClear && moodReady;
            Debug.Log($"QA_BOSS_PRESENTATION focus={focusMarked}:{AttackOrderMarkerPartCount} " +
                      $"boss={bossReady}:{(boss != null ? boss.Radius : 0f):0.00} " +
                      $"formation={entranceUnits}/{bossFormationSpawnCount} entrance={entranceClear}:{bossEntrancePath.Count} " +
                      $"mood={moodReady}:{battlefieldMoodClass}");
            Application.Quit(passed ? 0 : 36);
        }

        private IEnumerator QaSpecialEnemiesRoutine()
        {
            yield return null;
            Money = 30;
            TryPlaceUnit(UnitArchetype.Tank, new Vector2(-3.4f, -4.6f));
            TryPlaceUnit(UnitArchetype.Archer, new Vector2(0f, -4.6f));
            var tank = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Tank);
            var archer = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Archer);
            var wisp = new GameObject("QA Wisp").AddComponent<EnemyUnit>();
            wisp.Initialize(this, 0, 180f, false, 1, EnemyClass.Wisp);
            enemies.Add(wisp);
            var wispHealth = wisp.Health;
            wisp.TakeDamage(60f, tank, DamageType.Physical);
            var resistedPhysical = Mathf.Abs(wisp.Health - wispHealth) < .01f;
            wisp.TakeDamage(60f, archer, DamageType.Magic);
            var acceptedMagic = wisp.Health < wispHealth;
            var flyer = new GameObject("QA Flyer").AddComponent<EnemyUnit>();
            flyer.Initialize(this, 1, 180f, false, 2, EnemyClass.Flyer);
            enemies.Add(flyer);
            var targetRules = tank != null && archer != null && !CanUnitTargetEnemy(tank, flyer) && CanUnitTargetEnemy(archer, flyer);
            Debug.Log($"QA_SPECIAL_ENEMIES wispPhysical={resistedPhysical} wispMagic={acceptedMagic} flyerRules={targetRules}");
            Application.Quit(resistedPhysical && acceptedMagic && targetRules ? 0 : 8);
        }

        private IEnumerator QaRangedGateRoutine()
        {
            yield return null;
            Phase = GamePhase.Battle;
            var siege = new GameObject("QA Magic Golem").AddComponent<EnemyUnit>();
            siege.Initialize(this, 0, 220f, false, 1, EnemyClass.Siege);
            enemies.Add(siege);
            siege.ForceNearGateForQa(2.9f);
            var before = gateHealth;
            yield return new WaitForSecondsRealtime(3.3f);
            var passed = siege.IsAlive && !siege.IsAtGate && gateHealth < before;
            Debug.Log($"QA_RANGED_GATE distant={!siege.IsAtGate} damaged={gateHealth < before} before={before:0} after={gateHealth:0}");
            Application.Quit(passed ? 0 : 14);
        }

        private IEnumerator QaNavigationCombatRoutine()
        {
            yield return null;
            Phase = GamePhase.Battle;
            var laneGeometryValid = true;
            for (var lane = 0; lane < paths.Count; lane++)
            {
                for (var index = 0; index < paths[lane].Count; index++)
                {
                    var point = GetPathTarget(lane, index, index % 3 == 0 ? .3f : -.3f, index * .17f);
                    var walkable = IsWalkableWithClearance(point, .14f);
                    var onHill = HighGroundZones.Any(zone => zone.Contains(point));
                    var inFortress = ExteriorFortressBlockers.Any(zone => zone.Contains(point));
                    if (!walkable || onHill || inFortress)
                        Debug.Log($"QA_NAVIGATION_SAMPLE_BLOCKED lane={lane} index={index} point={point} " +
                                  $"walkable={walkable} hill={onHill} fortress={inFortress}");
                    laneGeometryValid &= walkable && !onHill && !inFortress;
                }
            }

            var walkers = new List<EnemyUnit>();
            for (var lane = 0; lane < paths.Count; lane++)
            {
                var walker = new GameObject($"QA Navigation Walker {lane}").AddComponent<EnemyUnit>();
                walker.Initialize(this, lane, 5000f, false, lane, EnemyClass.Melee);
                enemies.Add(walker);
                walkers.Add(walker);
            }

            var startsSafe = walkers.All(enemy =>
                IsWalkableWithClearance(enemy.Position, enemy.Radius * .42f) &&
                !ExteriorFortressBlockers.Any(blocker => blocker.Contains(enemy.Position)));
            var reportedShelvesBlocked = new[]
            {
                new Vector2(4.18f, -1.95f), new Vector2(-4.18f, -1.95f),
                new Vector2(3.02f, 1.38f), new Vector2(-3.02f, 1.45f),
                new Vector2(2.72f, -3.72f), new Vector2(-2.72f, -3.72f)
            }.All(point => !IsWalkableWithClearance(point, .14f));
            var forecourtWallsBlocked = new[]
            {
                new Vector2(-3.72f, 7.82f), new Vector2(-2.72f, 7.18f),
                new Vector2(-1.48f, 6.78f), new Vector2(1.48f, 6.78f),
                new Vector2(2.72f, 7.18f), new Vector2(3.72f, 7.82f)
            }.All(point => !IsWalkableWithClearance(point, .12f));
            var riverBanksBlocked = new[]
            {
                new Vector2(-5.37f, 3.77f), new Vector2(5.37f, 3.77f),
                new Vector2(-4.81f, .39f), new Vector2(4.81f, .39f)
            }.All(point => !IsWalkableWithClearance(point, .12f));
            var forecourtOpeningClear = new[]
            {
                new Vector2(-.28f, 6.65f), new Vector2(.28f, 6.65f),
                new Vector2(0f, 7.12f)
            }.All(point => IsWalkableWithClearance(point, .12f));
            var markedCentersBlocked = new[]
            {
                new Vector2(-1.8419f, 4.5209f), new Vector2(1.8f, 4.6465f),
                new Vector2(-3.7674f, 1.8419f), new Vector2(-.1674f, 1.0884f),
                new Vector2(3.307f, 1.7581f), new Vector2(4.3535f, .7535f),
                new Vector2(0f, -3.1395f), new Vector2(-1.9674f, -4.186f),
                new Vector2(1.8837f, -4.2279f)
            }.All(point => IsManualNavigationBlocked(point) && !IsWalkable(point));
            var paintedCells = 0;
            var paintedLeaks = 0;
            for (var y = 0; y < NavigationHeight; y++)
            for (var x = 0; x < NavigationWidth; x++)
            {
                var point = NavigationCellToWorld(x, y);
                if (!IsManualNavigationBlocked(point)) continue;
                paintedCells++;
                if (navigationMask[x, y]) paintedLeaks++;
            }
            var paintedMaskExact = manualNavigationBlockMask != null && paintedCells >= 1400 && paintedLeaks == 0;
            var travelSafe = startsSafe;
            var startProgress = walkers.Select(enemy => enemy.PathIndex).ToArray();
            for (var sample = 0; sample < 360; sample++)
            {
                yield return null;
                foreach (var enemy in walkers)
                {
                    if (enemy == null || !enemy.IsAlive) continue;
                    travelSafe &= !IsHighGround(enemy.Position) &&
                                  enemy.Position.y < CentralKeepFootprint[0].y &&
                                  !ExteriorFortressBlockers.Any(blocker => blocker.Contains(enemy.Position)) &&
                                  IsWalkableWithClearance(enemy.Position, enemy.Radius * .42f);
                }
            }
            var allProgressed = walkers.Select((enemy, index) =>
                enemy != null && enemy.PathIndex > startProgress[index] + 3).All(value => value);

            var melee = walkers[0];
            melee.ForceNearGateForQa(1.15f);
            var remoteBefore = gateHealth;
            DamageGate(melee);
            var remoteMeleeBlocked = Mathf.Approximately(gateHealth, remoteBefore);
            melee.ForceAtGateForQa();
            var contactBefore = gateHealth;
            DamageGate(melee);
            var contactMeleeDamaged = gateHealth < contactBefore;

            var passed = laneGeometryValid && startsSafe && reportedShelvesBlocked && forecourtWallsBlocked &&
                         riverBanksBlocked && forecourtOpeningClear && markedCentersBlocked &&
                         paintedMaskExact && travelSafe && allProgressed &&
                         remoteMeleeBlocked && contactMeleeDamaged && CountNavigationRegions() == 1;
            Debug.Log($"QA_NAVIGATION_COMBAT lanes={laneGeometryValid} starts={startsSafe} " +
                      $"shelves={reportedShelvesBlocked} walls={forecourtWallsBlocked} " +
                      $"water={riverBanksBlocked} opening={forecourtOpeningClear} " +
                      $"marked={markedCentersBlocked} painted={paintedCells} leaks={paintedLeaks} " +
                      $"travel={travelSafe} progressed={allProgressed} remoteMeleeBlocked={remoteMeleeBlocked} " +
                      $"contactMeleeDamaged={contactMeleeDamaged} regions={CountNavigationRegions()}");
            Application.Quit(passed ? 0 : 23);
        }

        private IEnumerator QaEnemyFlowRoutine()
        {
            yield return null;
            Money = 200;
            gateHealth = 99999f;
            var defenders = new List<PlayerUnit>();
            for (var lane = 0; lane < paths.Count; lane++)
            {
                // Paired south routes share their first half by design.  Intercept after their
                // inner/outer split so every one of the six tactical sectors gets an independent
                // stationary defender instead of failing placement overlap at the spawn gate.
                var interceptionIndex = Mathf.Max(0, paths[lane].Count - 50);
                var interception = NearestWalkable(GetPathTarget(lane, interceptionIndex, 0f, 0f), .13f);
                var defender = new GameObject($"QA Sector Defender {lane}").AddComponent<PlayerUnit>();
                defender.Initialize(this, UnitArchetype.Tank, definitions[UnitArchetype.Tank], interception);
                units.Add(defender);
                defender.Stop();
                defenders.Add(defender);
            }

            var walkers = new List<EnemyUnit>();
            for (var lane = 0; lane < paths.Count; lane++)
            {
                var walker = new GameObject($"QA Continuous Enemy {lane}").AddComponent<EnemyUnit>();
                walker.Initialize(this, lane, 6000f, false, lane,
                    lane == 1 ? EnemyClass.Brute : EnemyClass.Melee);
                enemies.Add(walker);
                walkers.Add(walker);
            }

            Phase = GamePhase.Battle;
            spawning = true;
            var startingProgress = walkers.Select(enemy => enemy.PathIndex).ToArray();
            var sawEngagement = new bool[walkers.Count];
            var neverIdle = true;
            var stayedLegal = true;
            Time.timeScale = 3f;
            for (var sample = 0; sample < 150; sample++)
            {
                yield return new WaitForSecondsRealtime(.08f);
                for (var i = 0; i < walkers.Count; i++)
                {
                    var enemy = walkers[i];
                    if (enemy == null || !enemy.IsAlive) continue;
                    sawEngagement[i] |= enemy.IsEngagingDefender;
                    neverIdle &= enemy.IsEngagingDefender || enemy.IsAtGate || enemy.IdleDuration < 1.25f;
                    stayedLegal &= enemy.IsFlying ||
                                   (IsWalkableWithClearance(enemy.Position, enemy.Radius * .42f) &&
                                    !IsHighGround(enemy.Position));
                }
            }
            Time.timeScale = 1f;
            var advancedOrEngaged = walkers.Select((enemy, index) =>
                enemy != null && enemy.IsAlive &&
                (enemy.PathIndex > startingProgress[index] + 10 || sawEngagement[index] || enemy.IsAtGate)).All(value => value);
            var recoveries = walkers.Sum(enemy => enemy != null ? enemy.StallRecoveryCount : 0);
            var passed = defenders.Count == paths.Count && neverIdle && stayedLegal && advancedOrEngaged;
            Debug.Log($"QA_ENEMY_FLOW defenders={defenders.Count}/{paths.Count} idleFree={neverIdle} " +
                      $"legal={stayedLegal} advancedOrEngaged={advancedOrEngaged} recoveries={recoveries}");
            Application.Quit(passed ? 0 : 25);
        }

