        private IEnumerator QaCameraShakeBudget237Routine()
        {
            yield return null;
            showMainMenu = false;
            Phase = GamePhase.Battle;
            cameraShakeEnergy = 0f;
            cameraShakeTimeRemaining = 0f;
            activeCameraShakeCap = 0f;
            lastStandardShakeRequestAt = -10f;
            cameraShakeDriverStarts = 0;
            coalescedCameraShakeRequests = 0;
            peakCameraShakeEnergy = 0f;

            for (var i = 0; i < 160; i++)
                RequestCameraImpulse(.014f, .115f, CameraShakePriority.Standard);
            var standardPeak = cameraShakeEnergy;
            var standardBounded = standardPeak <= StandardCameraShakeCap + .0001f;
            var foldedBurst = coalescedCameraShakeRequests >= 150 && cameraShakeDriverStarts == 1;

            RequestCameraImpulse(.061f, .3f, CameraShakePriority.Heavy);
            var heavyPeak = cameraShakeEnergy;
            var heavyBounded = heavyPeak <= HeavyCameraShakeCap + .0001f;
            RequestCameraImpulse(.128f, .62f, CameraShakePriority.Ultimate);
            var ultimatePeak = cameraShakeEnergy;
            var ultimateBounded = ultimatePeak <= UltimateCameraShakeCap + .0001f;
            yield return new WaitForSecondsRealtime(.82f);
            var settled = !cameraShakeDriverRunning && cameraShakeEnergy <= .00035f;
            var passed = standardBounded && foldedBurst && heavyBounded && ultimateBounded && settled;
            Debug.Log($"QA_CAMERA_SHAKE_BUDGET_237 standard={standardBounded}:{standardPeak:0.000} " +
                      $"folded={foldedBurst}:{coalescedCameraShakeRequests}:drivers={cameraShakeDriverStarts} " +
                      $"heavy={heavyBounded}:{heavyPeak:0.000} ultimate={ultimateBounded}:{ultimatePeak:0.000} " +
                      $"settled={settled}");
            Application.Quit(passed ? 0 : 78);
        }

