        private IEnumerator QaPolish243Routine()
        {
            yield return null;

            var tipCount = CrownfrontBootLoader.LoadingTipCountForQa;
            var everyFirstTipReachable = Enumerable.Range(0, tipCount)
                .Select(seed => CrownfrontBootLoader.NextTipIndexForQa(-1, seed))
                .Distinct().Count() == tipCount;
            var tipsNeverRepeat = true;
            for (var current = 0; current < tipCount && tipsNeverRepeat; current++)
            for (var seed = 0; seed < tipCount * 2; seed++)
                if (CrownfrontBootLoader.NextTipIndexForQa(current, seed) == current)
                    tipsNeverRepeat = false;
            var loadingTipsReady = tipCount >= 10 && everyFirstTipReachable && tipsNeverRepeat;

            var archer = definitions[UnitArchetype.Archer];
            var areaMage = definitions[UnitArchetype.AreaMage];
            var singleMage = definitions[UnitArchetype.SingleMage];
            var archerHit = archer.AttackPower;
            var areaHit = areaMage.MagicPower * .26f;
            var singleHit = singleMage.MagicPower * .55f;
            var roleRanges = archer.Range > singleMage.Range && singleMage.Range > areaMage.Range;
            var roleCadence = archer.AttackDelay < areaMage.AttackDelay &&
                              areaMage.AttackDelay < singleMage.AttackDelay;
            var roleDamage = singleHit >= archerHit * 2f && singleHit >= areaHit * 3f &&
                             singleHit / singleMage.AttackDelay > archerHit / archer.AttackDelay;
            var roleSplash = areaMage.SplashRadius >= 1.4f && singleMage.SplashRadius <= .01f;

            var portraitProbe = new GameObject("QA 243 Fixed Portrait").AddComponent<PlayerUnit>();
            portraitProbe.Initialize(this, UnitArchetype.Archer, archer,
                NearestWalkable(new Vector2(0f, -7.8f), .18f));
            var normalCard = FixedSelectionPortrait(portraitProbe);
            portraitProbe.PreviewMotionPoseForQa(Vector2.right, 8, .62f);
            var fixedThroughDirectionChange = FixedSelectionPortrait(portraitProbe) == normalCard;
            portraitProbe.AddExperience(9999f);
            var heroCard = FixedSelectionPortrait(portraitProbe);
            var fixedPortraits = normalCard != null && heroCard != null && normalCard != heroCard &&
                                 fixedThroughDirectionChange &&
                                 canonicalDefaultCardSprites.Count == 20 && canonicalSkinCardSprites.Count == 40;
            Destroy(portraitProbe.gameObject);

            Phase = GamePhase.Battle;
            SpawnCombatImpact(Vector2.zero, UnitArchetype.SingleMage, new Color(.24f, .82f, 1f), .9f);
            var impactRoot = GameObject.Find("SingleMage Basic VFX Animation");
            var frameRenderers = impactRoot == null
                ? Array.Empty<SpriteRenderer>()
                : impactRoot.GetComponentsInChildren<SpriteRenderer>(true)
                    .Where(renderer => renderer.name.Contains("Animated Impact Frame")).ToArray();
            var firstFrame = frameRenderers.Length > 0 ? frameRenderers[0].sprite : null;
            var transientSpawned = TransientBattleEffect.ActiveCount > 0;
            var startsAsAnticipation = frameRenderers.Length == 2 && frameRenderers.All(renderer => renderer.color.a <= .05f);
            yield return new WaitForSecondsRealtime(.16f);
            var peakAlpha = frameRenderers.Length == 0 ? 0f : frameRenderers.Max(renderer => renderer.color.a);
            var advancedFrame = frameRenderers.Any(renderer => renderer.sprite != null && renderer.sprite != firstFrame && renderer.color.a > .05f);
            var peakReadable = peakAlpha >= .35f;
            yield return new WaitForSecondsRealtime(.06f);
            var animatedFrames = impactRoot == null
                ? Array.Empty<SpriteRenderer>()
                : impactRoot.GetComponentsInChildren<SpriteRenderer>(true)
                    .Where(renderer => renderer.name.Contains("Animated Impact Frame")).ToArray();
            var noArtificialFragments = impactRoot == null || impactRoot.GetComponentsInChildren<SpriteRenderer>(true)
                .All(renderer => !renderer.name.Contains("Motif Fragment"));
            var vfxAuthored = combatVfxAnimations.Count == 30 &&
                              CombatVfxAnimationFor(UnitArchetype.SingleMage, CombatVfxTier.Basic).Length == CombatVfxFrameCount &&
                              frameRenderers.Length == 2 && startsAsAnticipation && peakReadable && advancedFrame &&
                              animatedFrames.Length == 2 && noArtificialFragments;
            ClearTransientBattlePresentation();
            var transientCleared = TransientBattleEffect.ActiveCount == 0 &&
                                   (impactRoot == null || !impactRoot.activeSelf) &&
                                   activeEnemyClassEffects == 0 && activeHitFeedbackEffects == 0;

            var passed = loadingTipsReady && roleRanges && roleCadence && roleDamage && roleSplash && fixedPortraits &&
                         vfxAuthored && transientSpawned && transientCleared;
            Debug.Log($"QA_POLISH_243 tips={loadingTipsReady}:{tipCount}:unique={everyFirstTipReachable}:repeat={tipsNeverRepeat} " +
                      $"roles=range:{roleRanges}:cadence:{roleCadence}:damage:{roleDamage}:splash:{roleSplash} " +
                      $"hits={archerHit:0.0}/{areaHit:0.0}/{singleHit:0.0} portraits={fixedPortraits}:cards={canonicalDefaultCardSprites.Count}/{canonicalSkinCardSprites.Count} " +
                      $"vfx={vfxAuthored}:sequences={combatVfxAnimations.Count}:alpha={peakAlpha:0.00}:frames={animatedFrames.Length}:advanced={advancedFrame}:noFragments={noArtificialFragments} " +
                      $"lifecycle={transientSpawned}/{transientCleared}");
            Application.Quit(passed ? 0 : 85);
        }

