        private static bool VfxSpriteBorderIsClear(Sprite sprite)
        {
            if (sprite == null || sprite.texture == null || !sprite.texture.isReadable) return false;
            var pixels = sprite.texture.GetPixels32();
            var left = Mathf.RoundToInt(sprite.rect.xMin);
            var right = Mathf.RoundToInt(sprite.rect.xMax) - 1;
            var bottom = Mathf.RoundToInt(sprite.rect.yMin);
            var top = Mathf.RoundToInt(sprite.rect.yMax) - 1;
            for (var x = left; x <= right; x++)
                if (pixels[bottom * sprite.texture.width + x].a > 8 ||
                    pixels[top * sprite.texture.width + x].a > 8) return false;
            for (var y = bottom; y <= top; y++)
                if (pixels[y * sprite.texture.width + left].a > 8 ||
                    pixels[y * sprite.texture.width + right].a > 8) return false;
            return true;
        }

        private static bool VfxSpritePivotMatchesAlpha(Sprite sprite, bool groundAnchor)
        {
            if (sprite == null || sprite.texture == null || !sprite.texture.isReadable) return false;
            var pixels = sprite.texture.GetPixels32();
            var left = Mathf.RoundToInt(sprite.rect.xMin);
            var right = Mathf.RoundToInt(sprite.rect.xMax) - 1;
            var bottom = Mathf.RoundToInt(sprite.rect.yMin);
            var top = Mathf.RoundToInt(sprite.rect.yMax) - 1;
            var alphaLeft = right;
            var alphaRight = left - 1;
            var alphaBottom = top;
            var alphaTop = bottom - 1;
            for (var y = bottom; y <= top; y++)
            for (var x = left; x <= right; x++)
            {
                if (pixels[y * sprite.texture.width + x].a <= 2) continue;
                alphaLeft = Mathf.Min(alphaLeft, x);
                alphaRight = Mathf.Max(alphaRight, x);
                alphaBottom = Mathf.Min(alphaBottom, y);
                alphaTop = Mathf.Max(alphaTop, y);
            }
            if (alphaRight < alphaLeft || alphaTop < alphaBottom) return true;
            var expectedX = (alphaLeft + alphaRight + 1f) * .5f - left;
            var expectedY = groundAnchor
                ? alphaBottom - bottom + (alphaTop - alphaBottom + 1f) * .08f
                : (alphaBottom + alphaTop + 1f) * .5f - bottom;
            return Mathf.Abs(sprite.pivot.x - expectedX) <= 1.1f &&
                   Mathf.Abs(sprite.pivot.y - expectedY) <= 1.1f;
        }

        private IEnumerator QaRelease249Routine()
        {
            yield return PrewarmBossPresentations();
            var prewarmed = LoadedBossDirectionalCountForQa == 10;
            var metricMissesBefore = EnemyUnit.OpaqueMetricCacheMisses;
            var bossArtClean = true;
            var maxSpawnMilliseconds = 0L;
            for (var chapter = 0; chapter < 10; chapter++)
            {
                var profile = EnemyVariantCatalog.ForChapterStage(chapter, 4);
                var watch = System.Diagnostics.Stopwatch.StartNew();
                var boss = new GameObject($"QA 249 Boss {profile.Id}").AddComponent<EnemyUnit>();
                boss.Initialize(this, chapter, 1800f, true, chapter % Mathf.Max(1, LaneCount),
                    profile.CombatClass, profile);
                watch.Stop();
                maxSpawnMilliseconds = System.Math.Max(maxSpawnMilliseconds, watch.ElapsedMilliseconds);
                bossArtClean &= boss.HasAuthoredBossDirectionalAnimationForQa &&
                                boss.CurrentSpriteUsesStrictAtlasCellForQa &&
                                boss.CurrentSpriteHasSafeCellMarginForQa &&
                                !boss.HasForbiddenCircularOverlay && boss.AnimationFrameCount == 72;
                Destroy(boss.gameObject);
            }
            yield return null;
            var metricStable = EnemyUnit.OpaqueMetricCacheMisses == metricMissesBefore;
            var spawnBudget = maxSpawnMilliseconds <= 120L;

            Phase = GamePhase.Preparation;
            var oracle = new GameObject("QA 249 Moonlight Oracle").AddComponent<PlayerUnit>();
            oracle.Initialize(this, UnitArchetype.Oracle, definitions[UnitArchetype.Oracle],
                new Vector2(0f, -6.2f));
            var oracleRight = oracle.PreviewFacingMirrorForQa(Vector2.right);
            var oracleLeft = oracle.PreviewFacingMirrorForQa(Vector2.left);
            var oracleDirection = oracleRight && !oracleLeft;

            var plainTank = new GameObject("QA 249 Plain Tank").AddComponent<PlayerUnit>();
            plainTank.Initialize(this, UnitArchetype.Tank, definitions[UnitArchetype.Tank],
                new Vector2(-2.2f, -6.2f));
            var fortifiedTank = new GameObject("QA 249 Fortified Tank").AddComponent<PlayerUnit>();
            fortifiedTank.Initialize(this, UnitArchetype.Tank, definitions[UnitArchetype.Tank],
                new Vector2(-1.2f, -6.2f));
            fortifiedTank.ApplyDefensiveStance(3.8f, .34f, 24f, 20f);
            var plainBefore = plainTank.Health;
            var fortifiedBefore = fortifiedTank.Health;
            plainTank.TakeDamage(100f, DamageType.Physical);
            fortifiedTank.TakeDamage(100f, DamageType.Physical);
            var plainLoss = plainBefore - plainTank.Health;
            var fortifiedLoss = fortifiedBefore - fortifiedTank.Health;
            var tankDefence = fortifiedTank.HasDefensiveStanceForQa && fortifiedLoss < plainLoss * .7f;

            var armorProbe = new GameObject("QA 249 Armor Break").AddComponent<EnemyUnit>();
            armorProbe.Initialize(this, 0, 800f, false, 0, EnemyClass.Brute);
            var armorBefore = armorProbe.Armor;
            armorProbe.ApplyArmorBreak(4.5f, 16f);
            var expectedArmorLoss = Mathf.Min(16f, armorBefore);
            var coralIdentity = definitions[UnitArchetype.Melee].MaxHealth >= 138f &&
                                definitions[UnitArchetype.Melee].AttackPower >= 34f &&
                                armorProbe.Armor <= armorBefore - expectedArmorLoss + .1f;

            var lancer = new GameObject("QA 249 Emerald Lancer").AddComponent<PlayerUnit>();
            lancer.Initialize(this, UnitArchetype.Lancer, definitions[UnitArchetype.Lancer],
                new Vector2(-2.4f, -6.1f));
            lancer.AddExperience(9999f);
            var densityTargets = new List<EnemyUnit>();
            var densityPoints = new[]
            {
                new Vector2(1.15f, -6.0f), new Vector2(1.35f, -6.08f),
                new Vector2(1.55f, -5.92f), new Vector2(1.25f, -5.72f),
                new Vector2(1.58f, -5.68f), new Vector2(-1.15f, -6.1f)
            };
            for (var i = 0; i < densityPoints.Length; i++)
            {
                var enemy = new GameObject($"QA 249 Density {i}").AddComponent<EnemyUnit>();
                enemy.Initialize(this, i, 900f, false, i % Mathf.Max(1, LaneCount), EnemyClass.Melee);
                enemy.ForcePositionForQa(densityPoints[i]);
                enemies.Add(enemy);
                densityTargets.Add(enemy);
            }
            var denseTarget = FindDensestEnemyTarget(lancer, 5.8f, 1.52f, out var denseCount);
            var lancerDensity = denseTarget != null && denseTarget.Position.x > .8f && denseCount >= 5;

            var hill = HighGroundZones[3];
            var projected = NearestWalkableOnSameTerrain(hill.Center + Vector2.down * 5f,
                hill.Center, .12f);
            var projectedPath = FindWalkPath(hill.Center, hill.Center + Vector2.down * 5f, .12f);
            var hillProjection = hill.Contains(projected, .12f) &&
                                 Vector2.Distance(projected, hill.Center) > .32f &&
                                 projectedPath.Count == 1 && hill.Contains(projectedPath[0], .12f);

            Phase = GamePhase.Battle;
            SpawnDefensiveStanceEffect(fortifiedTank, new Color(.3f, .72f, 1f), .3f);
            SpawnLancerDiveEffect(lancer.Position, densityTargets[0].Position, new Color(.16f, 1f, .72f));
            SpawnBossSignatureEffect(Vector2.zero, Color.magenta, 1.2f, 2);
            SpawnActiveSkillCrest(new Vector2(0f, -5f), Color.cyan, 1);
            var effectsReadable = GameObject.Find("Royal Bulwark Defensive Field") != null &&
                                  GameObject.Find("Emerald Dragon Dive Corridor") != null &&
                                  GameObject.Find("Boss Signature 2") != null &&
                                  GameObject.Find("Clock Stop Animation") != null &&
                                  CombatVfxTierScale(CombatVfxTier.Ultimate) >= 2f &&
                                  ActiveCommandVfxScale(1) >= 2.5f;

            var passed = prewarmed && metricStable && spawnBudget && bossArtClean && oracleDirection &&
                         tankDefence && coralIdentity && lancerDensity && hillProjection && effectsReadable;
            Debug.Log($"QA_RELEASE_249 prewarm={prewarmed}:{LoadedBossDirectionalCountForQa} " +
                      $"bossSpawnMs={maxSpawnMilliseconds}:budget={spawnBudget}:art={bossArtClean}:metrics={metricStable} " +
                      $"oracle={oracleDirection}:R={oracleRight}:L={oracleLeft} tank={tankDefence}:{fortifiedLoss:0.0}/{plainLoss:0.0} " +
                      $"coral={coralIdentity}:armor={armorBefore:0.0}->{armorProbe.Armor:0.0} " +
                      $"lancer={lancerDensity}:cluster={denseCount} hill={hillProjection}:projected={projected} " +
                      $"vfx={effectsReadable}");
            Application.Quit(passed ? 0 : 89);
        }

        private IEnumerator QaBossDirectional248Routine()
        {
            yield return null;
            Phase = GamePhase.Preparation;
            var profiles = Enumerable.Range(0, 10)
                .Select(chapter => EnemyVariantCatalog.ForChapterStage(chapter, 4)).ToArray();
            var directions = new[]
            {
                Vector2.down,
                new Vector2(1f, -1f).normalized,
                Vector2.right,
                new Vector2(1f, 1f).normalized,
                Vector2.up
            };
            var loaded = true;
            var strictCells = true;
            var safeCellMargins = true;
            var wholeBodies = true;
            var directionStatesDistinct = true;
            var walkPosesDistinct = true;
            var actionPosesDistinct = true;
            var rootSynthesizerNeutral = true;
            var weaponAnchorsDirectional = true;
            foreach (var profile in profiles)
            {
                var probe = new GameObject($"QA 248 {profile.Id} Directional Boss").AddComponent<EnemyUnit>();
                probe.Initialize(this, 0, 5000f, true, 0, profile.CombatClass, profile);
                probe.ForcePositionForQa(Vector2.zero);
                loaded &= probe.HasAuthoredBossDirectionalAnimationForQa && probe.AnimationFrameCount == 72;
                wholeBodies &= probe.UsesSeamSafeWholeBodyAnimationForQa &&
                               !probe.HasArticulatedLimbRigForQa;
                foreach (var direction in directions)
                {
                    var stateSprites = new HashSet<int>();
                    for (var state = 0; state < 3; state++)
                    {
                        probe.PreviewMotionPoseForQa(direction, state, .52f);
                        stateSprites.Add(probe.CurrentSpriteIdForQa);
                        strictCells &= probe.CurrentSpriteUsesStrictAtlasCellForQa;
                        safeCellMargins &= probe.CurrentSpriteHasSafeCellMarginForQa;
                    }
                    directionStatesDistinct &= stateSprites.Count == 3;
                    var target = probe.Position + direction * 3f;
                    var origin = probe.AttackOriginFor(target);
                    // A hand, mouth or cannon muzzle may sit above the actor's ground origin even
                    // while aiming south. It must not be the actor centre, and the actual shot
                    // vector from that anchor must still travel toward the requested direction.
                    weaponAnchorsDirectional &= (origin - probe.Position).magnitude >= probe.Radius * .42f &&
                                                Vector2.Dot(target - origin, direction) > 0f;
                }

                var walkSprites = new HashSet<int>();
                var walkRootPoses = new List<Vector4>();
                foreach (var phase in new[] { .04f, .22f, .4f, .58f, .76f, .94f })
                {
                    walkRootPoses.Add(probe.PreviewMotionPoseForQa(Vector2.down, 0, phase));
                    walkSprites.Add(probe.CurrentSpriteIdForQa);
                    safeCellMargins &= probe.CurrentSpriteHasSafeCellMarginForQa;
                }
                walkPosesDistinct &= probe.DistinctAnimationSpritesForQa(0) >= 5;
                // Frame-specific foot anchoring legitimately changes local Y. The forbidden
                // synthetic animation is root X drift, rotation or scale pulsing layered over
                // authored whole-body frames.
                rootSynthesizerNeutral &= walkRootPoses.All(pose =>
                    Mathf.Abs(pose.x - walkRootPoses[0].x) <= .003f &&
                    Mathf.Abs(pose.z - walkRootPoses[0].z) <= .003f);
                for (var state = 1; state <= 2; state++)
                {
                    var actionSprites = new HashSet<int>();
                    var actionRootPoses = new List<Vector4>();
                    foreach (var phase in new[] { .04f, .22f, .4f, .58f, .76f, .94f })
                    {
                        actionRootPoses.Add(probe.PreviewMotionPoseForQa(Vector2.down, state, phase));
                        actionSprites.Add(probe.CurrentSpriteIdForQa);
                        safeCellMargins &= probe.CurrentSpriteHasSafeCellMarginForQa;
                    }
                    actionPosesDistinct &= probe.DistinctAnimationSpritesForQa(state) >= 4;
                    rootSynthesizerNeutral &= actionRootPoses.All(pose =>
                        Mathf.Abs(pose.x - actionRootPoses[0].x) <= .003f &&
                        Mathf.Abs(pose.z - actionRootPoses[0].z) <= .003f);
                }
                Debug.Log($"QA_BOSS_DIRECTIONAL_248_PROFILE id={profile.Id} frames={probe.AnimationFrameCount} " +
                          $"walkPoses={probe.DistinctAnimationSpritesForQa(0)} " +
                          $"attackPoses={probe.DistinctAnimationSpritesForQa(1)} " +
                          $"skillPoses={probe.DistinctAnimationSpritesForQa(2)} " +
                          $"strict={probe.CurrentSpriteUsesStrictAtlasCellForQa} " +
                          $"wholeBody={probe.UsesSeamSafeWholeBodyAnimationForQa}");
            }

            var passed = loaded && strictCells && safeCellMargins && wholeBodies && directionStatesDistinct &&
                         walkPosesDistinct && actionPosesDistinct && rootSynthesizerNeutral && weaponAnchorsDirectional;
            Debug.Log($"QA_BOSS_DIRECTIONAL_248 loaded={loaded} strictCells={strictCells} safeMargins={safeCellMargins} " +
                      $"wholeBodies={wholeBodies} stateSprites={directionStatesDistinct} " +
                      $"walkPoses={walkPosesDistinct} actionPoses={actionPosesDistinct} rootNeutral={rootSynthesizerNeutral} " +
                      $"anchors={weaponAnchorsDirectional}");
            Application.Quit(passed ? 0 : 89);
        }

        private IEnumerator QaLancerThrust247Routine()
        {
            yield return null;
            showMainMenu = false;
            showFormationPanel = false;
            Phase = GamePhase.Battle;
            cameraMapCenter = new Vector2(0f, -5.9f);
            cameraZoom = cameraZoomTarget = 3.75f;
            ApplyCameraPose();

            foreach (var enemy in enemies.Where(enemy => enemy != null).ToArray()) Destroy(enemy.gameObject);
            enemies.Clear();
            foreach (var unit in units.Where(unit => unit != null).ToArray()) Destroy(unit.gameObject);
            units.Clear();
            yield return null;

            var definition = definitions[UnitArchetype.Lancer];
            var originalRange = definition.Range;
            var probe = new GameObject("QA 247 Lancer Motion Probe").AddComponent<PlayerUnit>();
            probe.Initialize(this, UnitArchetype.Lancer, definition,
                NearestWalkable(new Vector2(0f, -6f), .18f));

            var samplePhases = new[] { 0f, .06f, .12f, .18f, .28f, .4f, .48f, .58f, .7f, .84f, .98f };
            float[] ProjectedTravel(Vector2 direction)
            {
                var poses = samplePhases
                    .Select(phase => probe.PreviewMotionPoseForQa(direction, 1, phase)).ToArray();
                var origin = new Vector2(poses[0].x, poses[0].y);
                var axis = direction.normalized;
                return poses.Select(pose =>
                    Vector2.Dot(new Vector2(pose.x, pose.y) - origin, axis)).ToArray();
            }

            var eastTravel = ProjectedTravel(Vector2.right);
            var westTravel = ProjectedTravel(Vector2.left);
            var anticipationMin = Mathf.Min(eastTravel.Take(4).Min(), westTravel.Take(4).Min());
            var forwardContact = Mathf.Min(eastTravel[6], westTravel[6]);
            var recovery = Mathf.Max(Mathf.Abs(eastTravel[^1]), Mathf.Abs(westTravel[^1]));
            var symmetry = eastTravel.Zip(westTravel, (east, west) => Mathf.Abs(east - west)).Max();

            var maximumTilt = 0f;
            var spriteIds = new HashSet<int>();
            var frameProbePhases = Enumerable.Range(0, 51).Select(index => index / 50f).ToArray();
            foreach (var direction in new[] { Vector2.right, Vector2.left })
            foreach (var phase in frameProbePhases)
            {
                var pose = probe.PreviewMotionPoseForQa(direction, 1, phase);
                maximumTilt = Mathf.Max(maximumTilt, Mathf.Abs(pose.z * 45f));
                spriteIds.Add(probe.CurrentSpriteIdForQa);
            }

            var noBackstep = anticipationMin >= -.075f;
            var commitsForward = forwardContact >= .27f;
            var returnsToGuard = recovery <= .08f;
            var balancedDirections = symmetry <= .055f;
            var spearAxisStable = maximumTilt <= 8.5f;
            var authoredProgression = spriteIds.Count >= 6;

            probe.AddExperience(9999f);
            var heroSpriteIds = new HashSet<int>();
            foreach (var phase in frameProbePhases)
            {
                probe.PreviewMotionPoseForQa(Vector2.right, 1, phase);
                heroSpriteIds.Add(probe.CurrentSpriteIdForQa);
            }
            var heroProgression = probe.IsHero && heroSpriteIds.Count >= 6;
            var rangeUnchanged = Mathf.Approximately(originalRange, definitions[UnitArchetype.Lancer].Range);
            Destroy(probe.gameObject);

            if (!Application.isBatchMode)
            {
                var lancer = new GameObject("QA 247 Live Lancer").AddComponent<PlayerUnit>();
                var lancerPosition = NearestWalkable(new Vector2(-1.15f, -6.1f), .18f);
                lancer.Initialize(this, UnitArchetype.Lancer, definition, lancerPosition);
                units.Add(lancer);
                var target = new GameObject("QA 247 Lancer Target").AddComponent<EnemyUnit>();
                target.Initialize(this, 0, 900000f, false, 0, EnemyClass.Brute);
                target.ForcePositionForQa(NearestWalkable(lancerPosition + Vector2.right * 2.25f, .18f));
                target.ApplyStun(4f);
                enemies.Add(target);
                lancer.TriggerAttackMotionForQa(target.Position);
                PerformAttack(lancer, target, definition);
                for (var frame = 0; frame < 12; frame++)
                {
                    yield return new WaitForSecondsRealtime(.052f);
                    yield return CaptureQaFrameRoutine($"Crownfront-v247-lancer-thrust-{frame:00}.ppm");
                }
            }

            var passed = noBackstep && commitsForward && returnsToGuard && balancedDirections &&
                         spearAxisStable && authoredProgression && heroProgression && rangeUnchanged;
            Debug.Log($"QA_LANCER_THRUST_247 noBackstep={noBackstep}:{anticipationMin:0.000} " +
                      $"forward={commitsForward}:{forwardContact:0.000} recovery={returnsToGuard}:{recovery:0.000} " +
                      $"symmetry={balancedDirections}:{symmetry:0.000} tilt={spearAxisStable}:{maximumTilt:0.0}deg " +
                      $"frames={authoredProgression}:{spriteIds.Count} heroFrames={heroProgression}:{heroSpriteIds.Count} " +
                      $"range={rangeUnchanged}:{originalRange:0.00}");
            Application.Quit(passed ? 0 : 89);
        }

        private IEnumerator QaVfx246Routine()
        {
            yield return null;
            showMainMenu = false;
            showFormationPanel = false;
            Phase = GamePhase.Battle;
            cameraMapCenter = new Vector2(0f, -5.55f);
            cameraZoom = cameraZoomTarget = 4.85f;
            ApplyCameraPose();

            var roster = new[]
            {
                UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Lancer, UnitArchetype.Archer,
                UnitArchetype.Musketeer, UnitArchetype.AreaMage, UnitArchetype.SingleMage,
                UnitArchetype.Bombardier, UnitArchetype.Druid, UnitArchetype.Oracle
            };
            var tiers = new[] { CombatVfxTier.Basic, CombatVfxTier.Skill, CombatVfxTier.Ultimate };
            var mappingComplete = combatVfxAnimations.Count == 30 && roster.All(archetype => tiers.All(tier =>
                CombatVfxAnimationFor(archetype, tier).Length == CombatVfxFrameCount));
            var activeComplete = activeCommandVfxAnimations.Count == 3 &&
                                 activeCommandVfxAnimations.Values.All(frames =>
                                     frames.Length == ActiveCommandVfxFrameCount);
            var bordersClear = combatVfxAnimations.Values.SelectMany(frames => frames)
                                   .Concat(activeCommandVfxAnimations.Values.SelectMany(frames => frames))
                                   .All(VfxSpriteBorderIsClear);
            var centeredContacts = roster.All(archetype =>
                CombatVfxAnimationFor(archetype, CombatVfxTier.Basic)
                    .All(sprite => VfxSpritePivotMatchesAlpha(sprite, false)));
            var groundedRoles = roster.Where(UsesGroundedCombatVfx).ToArray();
            var groundContactStable = groundedRoles.All(archetype =>
                CombatVfxAnimationFor(archetype, CombatVfxTier.Skill)
                    .Concat(CombatVfxAnimationFor(archetype, CombatVfxTier.Ultimate))
                    .All(sprite => VfxSpritePivotMatchesAlpha(sprite, true)));

            if (!Application.isBatchMode)
            {
                for (var tierIndex = 0; tierIndex < tiers.Length; tierIndex++)
                {
                    var tier = tiers[tierIndex];
                    for (var i = 0; i < roster.Length; i++)
                    {
                        var position = new Vector2(-4.25f + i % 5 * 2.12f, -6.75f + i / 5 * 2.35f);
                        SpawnCombatImpact(position, roster[i], definitions[roster[i]].Color,
                            tier == CombatVfxTier.Basic ? .62f : tier == CombatVfxTier.Skill ? .84f : 1.02f,
                            Vector2.up, tier);
                    }
                    yield return new WaitForSecondsRealtime(tier == CombatVfxTier.Basic ? .2f : .32f);
                    yield return CaptureQaFrameRoutine($"Crownfront-VFX-246-{tier.ToString().ToLowerInvariant()}-gallery.ppm");
                    ClearTransientBattlePresentation();
                    yield return null;
                }
            }

            foreach (var enemy in enemies.Where(enemy => enemy != null).ToArray()) Destroy(enemy.gameObject);
            enemies.Clear();
            foreach (var unit in units.Where(unit => unit != null).ToArray()) Destroy(unit.gameObject);
            units.Clear();
            yield return null;

            var liveTargets = new Dictionary<UnitArchetype, EnemyUnit>();
            for (var i = 0; i < roster.Length; i++)
            {
                var archetype = roster[i];
                var sourcePosition = new Vector2(-4.3f + i % 5 * 2.15f, -7.15f + i / 5 * 2.55f);
                var targetPosition = sourcePosition + Vector2.up * 1.35f;
                var source = new GameObject($"QA 246 Live Attacker {archetype}").AddComponent<PlayerUnit>();
                source.Initialize(this, archetype, definitions[archetype], sourcePosition);
                units.Add(source);
                var target = new GameObject($"QA 246 Live Target {archetype}").AddComponent<EnemyUnit>();
                target.Initialize(this, i, 900000f, false, i % Mathf.Max(1, LaneCount), EnemyClass.Brute);
                target.ForcePositionForQa(targetPosition);
                target.ApplyStun(4f);
                enemies.Add(target);
                liveTargets[archetype] = target;
                source.TriggerAttackMotionForQa(target.Position);
                PerformAttack(source, target, definitions[archetype]);
            }

            var meleeSource = units.First(unit => unit != null && unit.Archetype == UnitArchetype.Melee);
            var meleeTarget = liveTargets[UnitArchetype.Melee];
            var attackDirection = (meleeTarget.Position - meleeSource.Position).normalized;
            var weaponDirectionCorrect = false;
            var maximumTrailLayers = 0;
            var anchoredRoles = new HashSet<UnitArchetype>();
            var animationAdvanced = false;
            var observationStarted = Time.realtimeSinceStartup;
            TransientBattleEffect[] basicRoots = Array.Empty<TransientBattleEffect>();
            // Poll the real attack path instead of sampling one wall-clock instant. Null-graphics
            // QA can advance several simulation frames at once, while a rendered phone advances
            // smoothly; recording every effect as it appears makes both modes test the same rule.
            while (Time.realtimeSinceStartup - observationStarted < 1.35f &&
                   (!weaponDirectionCorrect || anchoredRoles.Count < roster.Length))
            {
                var weaponTrail = GameObject.Find("Melee Weapon Swing");
                var trailRenderers = weaponTrail == null ? Array.Empty<SpriteRenderer>() :
                    weaponTrail.GetComponentsInChildren<SpriteRenderer>(true);
                maximumTrailLayers = Mathf.Max(maximumTrailLayers, trailRenderers.Length);
                if (trailRenderers.Length == 7)
                {
                    var trailCenter = trailRenderers.Aggregate(Vector2.zero,
                        (sum, renderer) => sum + (Vector2)renderer.transform.position) / trailRenderers.Length;
                    var fromWeapon = trailCenter - meleeSource.AttackOriginFor(meleeTarget.HitPoint);
                    weaponDirectionCorrect |= fromWeapon.sqrMagnitude > .001f &&
                                              Vector2.Dot(fromWeapon.normalized, attackDirection) > .15f;
                }

                basicRoots = FindObjectsByType<TransientBattleEffect>(FindObjectsSortMode.None)
                    .Where(effect => effect != null && effect.name.EndsWith(" Basic VFX Animation",
                        StringComparison.Ordinal)).ToArray();
                foreach (var archetype in roster)
                    if (basicRoots.Any(root => root.name == $"{archetype} Basic VFX Animation" &&
                                               Vector2.Distance(root.transform.position,
                                                   liveTargets[archetype].HitPoint) <= .055f))
                        anchoredRoles.Add(archetype);
                animationAdvanced |= basicRoots.SelectMany(root =>
                        root.GetComponentsInChildren<SpriteRenderer>(true))
                    .Where(renderer => renderer.name.StartsWith("Animated Impact Frame",
                        StringComparison.Ordinal))
                    .Any(renderer => renderer.sprite != null && renderer.color.a > .05f);
                yield return null;
            }
            var actualBasicsAnchored = anchoredRoles.Count == roster.Length;
            if (!Application.isBatchMode)
                yield return CaptureQaFrameRoutine("Crownfront-VFX-246-live-basic-contact.ppm");

            var passed = mappingComplete && activeComplete && bordersClear && centeredContacts &&
                         groundContactStable && weaponDirectionCorrect && actualBasicsAnchored && animationAdvanced;
            Debug.Log($"QA_VFX_246 mapping={mappingComplete}:{combatVfxAnimations.Count}:frames={CombatVfxFrameCount} " +
                      $"active={activeComplete}:{activeCommandVfxAnimations.Count}:frames={ActiveCommandVfxFrameCount} " +
                      $"borders={bordersClear}:center={centeredContacts}:ground={groundContactStable} " +
                      $"weaponDirection={weaponDirectionCorrect}:{maximumTrailLayers} " +
                      $"liveContacts={actualBasicsAnchored}:{anchoredRoles.Count}:animated={animationAdvanced}");
            ClearTransientBattlePresentation();
            Application.Quit(passed ? 0 : 88);
        }

        private IEnumerator QaVfx245Routine()
        {
            yield return null;
            showMainMenu = false;
            showFormationPanel = false;
            Phase = GamePhase.Battle;
            cameraMapCenter = new Vector2(0f, -5.35f);
            cameraZoom = cameraZoomTarget = 3.55f;
            ApplyCameraPose();

            var roster = new[]
            {
                UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Archer,
                UnitArchetype.AreaMage, UnitArchetype.SingleMage, UnitArchetype.Bombardier,
                UnitArchetype.Lancer, UnitArchetype.Druid, UnitArchetype.Musketeer, UnitArchetype.Oracle
            };
            var tiers = new[] { CombatVfxTier.Basic, CombatVfxTier.Skill, CombatVfxTier.Ultimate };
            var mappingComplete = combatVfxAnimations.Count == roster.Length * tiers.Length &&
                                  roster.All(archetype => tiers.All(tier =>
                                      CombatVfxAnimationFor(archetype, tier).Length == CombatVfxFrameCount));
            var activeMappingComplete = activeCommandVfxAnimations.Count == 3 &&
                                        activeCommandVfxAnimations.Values.All(frames =>
                                            frames.Length == ActiveCommandVfxFrameCount);
            var tiersDistinct = roster.All(archetype =>
            {
                var basic = CombatVfxAnimationFor(archetype, CombatVfxTier.Basic);
                var skill = CombatVfxAnimationFor(archetype, CombatVfxTier.Skill);
                var ultimate = CombatVfxAnimationFor(archetype, CombatVfxTier.Ultimate);
                return basic.Length == CombatVfxFrameCount && skill.Length == CombatVfxFrameCount &&
                       ultimate.Length == CombatVfxFrameCount &&
                       basic[0] != skill[0] && skill[0] != ultimate[0] && basic[0] != ultimate[0];
            });
            var alphaHierarchy = CombatVfxPeakAlpha(UnitArchetype.Lancer, CombatVfxTier.Basic) <
                                 CombatVfxPeakAlpha(UnitArchetype.Lancer, CombatVfxTier.Skill) &&
                                 CombatVfxPeakAlpha(UnitArchetype.Lancer, CombatVfxTier.Skill) <
                                 CombatVfxPeakAlpha(UnitArchetype.Lancer, CombatVfxTier.Ultimate);
            var basicVisualBalance = CombatVfxPeakAlpha(UnitArchetype.AreaMage, CombatVfxTier.Basic) <
                                     CombatVfxPeakAlpha(UnitArchetype.Archer, CombatVfxTier.Basic) &&
                                     CombatVfxRoleScale(UnitArchetype.AreaMage, CombatVfxTier.Basic) <
                                     CombatVfxRoleScale(UnitArchetype.Melee, CombatVfxTier.Basic);
            var groundedPivot = CombatVfxAnimationFor(UnitArchetype.AreaMage, CombatVfxTier.Basic)
                                    .All(sprite => VfxSpritePivotMatchesAlpha(sprite, false)) &&
                                CombatVfxAnimationFor(UnitArchetype.AreaMage, CombatVfxTier.Skill)
                                    .All(sprite => VfxSpritePivotMatchesAlpha(sprite, true)) &&
                                CombatVfxAnimationFor(UnitArchetype.Archer, CombatVfxTier.Basic)
                                    .All(sprite => VfxSpritePivotMatchesAlpha(sprite, false));
            if (!Application.isBatchMode)
            {
                SpawnCombatImpact(new Vector2(-1.75f, -5.15f), UnitArchetype.AreaMage,
                    definitions[UnitArchetype.AreaMage].Color, .72f, Vector2.down, CombatVfxTier.Basic);
                SpawnCombatImpact(new Vector2(0f, -5.15f), UnitArchetype.Archer,
                    definitions[UnitArchetype.Archer].Color, .62f, Vector2.down, CombatVfxTier.Basic);
                SpawnCombatImpact(new Vector2(1.75f, -5.15f), UnitArchetype.Melee,
                    definitions[UnitArchetype.Melee].Color, .62f, Vector2.right, CombatVfxTier.Basic);
                yield return new WaitForSecondsRealtime(.18f);
                yield return CaptureQaFrameRoutine("Crownfront-VFX-245-basic-balance.ppm");
                ClearTransientBattlePresentation();
                yield return null;
            }
            var allSkinPalettes = true;
            foreach (var archetype in roster)
            {
                var products = monetization.Products.Where(product => product.Category == ShopCategory.Unit &&
                                                                      product.TargetUnit == archetype)
                    .OrderBy(product => product.Id).ToArray();
                var accents = new List<Color>();
                allSkinPalettes &= products.Length == 2;
                foreach (var product in products)
                {
                    monetization.GrantForQa(product.Id);
                    monetization.Equip(product);
                    var accent = GetUnitSkinAccent(archetype);
                    var secondary = GetUnitSkinSecondary(archetype);
                    accents.Add(accent);
                    allSkinPalettes &= GetUnitSkinVariant(archetype) is 1 or 2 &&
                                       accent.a > .9f && secondary.a > .9f;
                }
                allSkinPalettes &= accents.Count == 2 && Vector4.Distance(accents[0], accents[1]) > .08f;
                monetization.EquipDefault(ShopCategory.Unit, archetype);
            }

            SpawnCombatImpact(new Vector2(-1.1f, -4.9f), UnitArchetype.Lancer,
                definitions[UnitArchetype.Lancer].Color, .9f, Vector2.right, CombatVfxTier.Skill);
            SpawnCombatImpact(new Vector2(1.1f, -4.9f), UnitArchetype.Lancer,
                definitions[UnitArchetype.Lancer].Color, .9f, Vector2.left, CombatVfxTier.Skill);
            yield return null;
            var directionRoots = FindObjectsByType<TransientBattleEffect>(FindObjectsSortMode.None)
                .Where(effect => effect != null && effect.name == "Lancer Skill VFX Animation")
                .OrderBy(effect => effect.transform.position.x).ToArray();
            var directionsFollowAttack = directionRoots.Length == 2 &&
                                         Mathf.Abs(Mathf.DeltaAngle(directionRoots[0].transform.eulerAngles.z,
                                             directionRoots[1].transform.eulerAngles.z)) <= 1f;

            var skinProduct = monetization.FindProduct("crownfront.unit.lancer.a");
            if (skinProduct != null)
            {
                monetization.GrantForQa(skinProduct.Id);
                monetization.Equip(skinProduct);
            }
            var skinnedLancer = new GameObject("QA 244 Skinned Lancer").AddComponent<PlayerUnit>();
            skinnedLancer.Initialize(this, UnitArchetype.Lancer, definitions[UnitArchetype.Lancer],
                NearestWalkable(new Vector2(0f, -7.8f), .18f));
            units.Add(skinnedLancer);
            var skinPalette = ResolveCombatVfxPalette(skinnedLancer, UnitArchetype.Lancer,
                definitions[UnitArchetype.Lancer].Color);
            SpawnCombatImpact(new Vector2(0f, -5.7f), UnitArchetype.Lancer, skinPalette.primary, .9f,
                Vector2.up, CombatVfxTier.Skill, skinnedLancer);
            yield return null;
            var skinEchoReady = FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None)
                .Any(renderer => renderer != null && renderer.name == "Skin Palette Secondary Echo");
            var skinAware = skinProduct != null && skinnedLancer.SkinVariant == 1 && skinPalette.skinned &&
                            skinEchoReady && Vector4.Distance(skinPalette.primary, GetUnitSkinAccent(UnitArchetype.Lancer)) < .01f;

            ClearTransientBattlePresentation();
            var liveSkillTarget = new GameObject("QA 245 Live Skill Target").AddComponent<EnemyUnit>();
            liveSkillTarget.Initialize(this, 0, 900000f, false, 0, EnemyClass.Brute);
            liveSkillTarget.ForcePositionForQa(NearestWalkable(new Vector2(0f, -5.2f), .18f));
            enemies.Add(liveSkillTarget);
            for (var i = 0; i < roster.Length; i++)
            {
                var archetype = roster[i];
                var source = new GameObject($"QA 245 Live Skill {archetype}").AddComponent<PlayerUnit>();
                source.Initialize(this, archetype, definitions[archetype],
                    NearestWalkable(new Vector2(-3.4f + i * .72f, -7.2f - i % 2 * .28f), .18f));
                units.Add(source);
                PerformSkill(source, liveSkillTarget, definitions[archetype]);
            }
            yield return new WaitForSecondsRealtime(.34f);
            var liveSkillRoots = FindObjectsByType<TransientBattleEffect>(FindObjectsSortMode.None)
                .Where(effect => effect != null && effect.name.EndsWith(" Skill VFX Animation",
                    StringComparison.Ordinal)).Select(effect => effect.name).ToArray();
            var defensiveFieldLive = FindObjectsByType<TransientBattleEffect>(FindObjectsSortMode.None)
                .Any(effect => effect != null && effect.name == "Royal Bulwark Defensive Field");
            var allBasicSkillsLive = defensiveFieldLive && roster.Where(archetype => archetype != UnitArchetype.Tank)
                .All(archetype => liveSkillRoots.Contains($"{archetype} Skill VFX Animation"));

            ClearTransientBattlePresentation();
            SpawnActiveSkillCrest(new Vector2(-1.75f, -5.1f), new Color(1f, .66f, .16f), 0);
            SpawnActiveSkillCrest(new Vector2(0f, -5.1f), new Color(.36f, .88f, 1f), 1);
            SpawnActiveSkillCrest(new Vector2(1.75f, -5.1f), new Color(.35f, 1f, .66f), 2);
            yield return new WaitForSecondsRealtime(.18f);
            var activeRoots = FindObjectsByType<TransientBattleEffect>(FindObjectsSortMode.None)
                .Where(effect => effect != null &&
                                 (effect.name == "Royal Arrow Barrage Command Animation" ||
                                  effect.name == "Royal Signal Flare Animation" ||
                                  effect.name == "Clock Stop Animation" ||
                                  effect.name == "Citadel Field Repair Animation")).ToArray();
            var activeFrameRenderers = activeRoots.Sum(root => root.GetComponentsInChildren<SpriteRenderer>(true)
                .Count(renderer => renderer.name.StartsWith("Active Command Frame", StringComparison.Ordinal)));
            var activeSkillsLive = activeRoots.Length == 3 && activeFrameRenderers == 6;
            if (!Application.isBatchMode)
            {
                yield return new WaitForSecondsRealtime(.28f);
                yield return CaptureQaFrameRoutine("Crownfront-VFX-245-active.ppm");
            }

            ClearTransientBattlePresentation();
            foreach (var enemy in enemies.Where(enemy => enemy != null).ToArray())
                Destroy(enemy.gameObject);
            enemies.Clear();
            foreach (var unit in units.Where(unit => unit != null).ToArray())
                Destroy(unit.gameObject);
            units.Clear();
            yield return null;

            var archer = new GameObject("QA 245 Arrow Rain Hero").AddComponent<PlayerUnit>();
            archer.Initialize(this, UnitArchetype.Archer, definitions[UnitArchetype.Archer],
                NearestWalkable(new Vector2(0f, -7.4f), .18f));
            archer.AddExperience(9999f);
            units.Add(archer);
            var arrowTargets = new List<EnemyUnit>();
            for (var i = 0; i < 4; i++)
            {
                var enemy = new GameObject($"QA 245 Arrow Target {i}").AddComponent<EnemyUnit>();
                enemy.Initialize(this, 0, 9000f, false, i % 2, EnemyClass.Melee);
                enemy.ForcePositionForQa(NearestWalkable(new Vector2(-1.5f + i, -5.1f + i * .14f), .18f));
                enemies.Add(enemy);
                arrowTargets.Add(enemy);
            }
            StartCoroutine(RoyalArrowRainRoutine(archer, definitions[UnitArchetype.Archer].Color));
            yield return new WaitForSecondsRealtime(.18f);
            var arrowField = GameObject.Find("Royal Arrow Rain Global Field");
            var arrowRenderers = arrowField == null ? Array.Empty<SpriteRenderer>() :
                arrowField.GetComponentsInChildren<SpriteRenderer>(true)
                    .Where(renderer => renderer.name.StartsWith("Global Arrow", StringComparison.Ordinal))
                    .OrderBy(renderer => int.Parse(renderer.name.Substring("Global Arrow ".Length))).ToArray();
            var globalArrowCount = arrowRenderers.Length;
            var arrowsPreparedAboveTargets = globalArrowCount == arrowTargets.Count &&
                arrowRenderers.Select((renderer, index) =>
                    renderer.transform.parent != null &&
                    renderer.transform.parent.position.y >
                    arrowTargets[index].HitPoint.y + arrowTargets[index].Radius * .04f + 1.1f).All(value => value);
            var noCentralUltimate = GameObject.Find("Archer Ultimate VFX Animation") == null;

            if (!Application.isBatchMode)
                yield return CaptureQaFrameRoutine("Crownfront-VFX-245-ready.ppm");
            yield return new WaitForSecondsRealtime(.20f);
            var fallingArrows = arrowField == null ? Array.Empty<SpriteRenderer>() :
                arrowField.GetComponentsInChildren<SpriteRenderer>(true)
                    .Where(renderer => renderer.name.StartsWith("Global Arrow", StringComparison.Ordinal))
                    .OrderBy(renderer => int.Parse(renderer.name.Substring("Global Arrow ".Length))).ToArray();
            var fallDeltas = fallingArrows.Select((renderer, index) =>
            {
                var targetY = arrowTargets[index].HitPoint.y + Mathf.Max(.015f, arrowTargets[index].Radius * .04f);
                var authoredStartY = targetY + 1.72f + index % 4 * .09f;
                var actorY = renderer.transform.parent != null
                    ? renderer.transform.parent.position.y
                    : renderer.transform.position.y;
                return authoredStartY - actorY;
            }).ToArray();
            var fallProgress = fallingArrows.Select((renderer, index) =>
            {
                var targetY = arrowTargets[index].HitPoint.y + Mathf.Max(.015f, arrowTargets[index].Radius * .04f);
                var authoredStartY = targetY + 1.72f + index % 4 * .09f;
                var actorY = renderer.transform.parent != null
                    ? renderer.transform.parent.position.y
                    : renderer.transform.position.y;
                return Mathf.Clamp01((authoredStartY - actorY) /
                                     Mathf.Max(.01f, authoredStartY - targetY));
            }).ToArray();
            var synchronizedVolley = fallDeltas.Length == globalArrowCount && fallDeltas.Length > 0 &&
                                     fallDeltas.Min() > .08f && fallProgress.Max() - fallProgress.Min() < .035f;
            var globalArrowRain = globalArrowCount == arrowTargets.Count && arrowsPreparedAboveTargets && synchronizedVolley &&
                                  noCentralUltimate;
            var noFragments = FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None)
                .All(renderer => renderer == null || !renderer.name.Contains("Motif Fragment"));

            if (!Application.isBatchMode)
            {
                yield return CaptureQaFrameRoutine("Crownfront-VFX-245-fall.ppm");
                yield return new WaitForSecondsRealtime(.32f);
                yield return CaptureQaFrameRoutine("Crownfront-VFX-245-contact.ppm");
            }

            var passed = mappingComplete && activeMappingComplete && tiersDistinct && alphaHierarchy && basicVisualBalance &&
                         groundedPivot && allSkinPalettes && directionsFollowAttack && skinAware && allBasicSkillsLive &&
                         activeSkillsLive && globalArrowRain && noFragments;
            Debug.Log($"QA_VFX_245 mapping={mappingComplete}:{combatVfxAnimations.Count}:frames={CombatVfxFrameCount} " +
                      $"activeMap={activeMappingComplete}:{activeCommandVfxAnimations.Count} tiers={tiersDistinct} " +
                      $"alpha={alphaHierarchy}:balance={basicVisualBalance} grounded={groundedPivot} " +
                      $"allSkins={allSkinPalettes} direction={directionsFollowAttack}:{directionRoots.Length} " +
                      $"skin={skinAware}:variant={skinnedLancer.SkinVariant}:echo={skinEchoReady} " +
                      $"basicSkillsLive={allBasicSkillsLive}:{liveSkillRoots.Length} activeLive={activeSkillsLive}:{activeRoots.Length}/{activeFrameRenderers} " +
                      $"arrowRain={globalArrowRain}:{globalArrowCount}:above={arrowsPreparedAboveTargets}:sync={synchronizedVolley}:centralFree={noCentralUltimate} " +
                      $"noFragments={noFragments}");
            ClearTransientBattlePresentation();
            monetization.EquipDefault(ShopCategory.Unit, UnitArchetype.Lancer);
            Application.Quit(passed ? 0 : 87);
        }

        private IEnumerator QaPerformance240Routine()
        {
            yield return null;
            showMainMenu = false;
            showFormationPanel = false;
            Phase = GamePhase.Battle;
            Round = 50;
            const int stressEnemyCount = 96;
            for (var i = 0; i < stressEnemyCount; i++)
            {
                var profile = EnemyVariantCatalog.ForChapterStage(i % 10, i % 5);
                var enemy = new GameObject($"QA PERF Enemy {i:00}").AddComponent<EnemyUnit>();
                enemy.Initialize(this, i, 1800f, i % 18 == 0, i % Mathf.Max(1, LaneCount),
                    profile.CombatClass, profile);
                enemy.ForcePositionForQa(new Vector2(-5.6f + i % 12 * .95f,
                    -5.6f + i / 12 * .82f));
                enemies.Add(enemy);
            }

            // Warm every animation state and sprite metric once before measuring steady state.
            yield return new WaitForSecondsRealtime(2.4f);
            var missesBefore = EnemyUnit.OpaqueMetricCacheMisses;
            var memoryBefore = System.GC.GetTotalMemory(false);
            var frameBefore = Time.frameCount;
            var startedAt = Time.realtimeSinceStartup;
            for (var i = 0; i < 96; i++)
            {
                var point = new Vector2((i % 12 - 5.5f) * .72f, (i / 12 - 3.5f) * .64f);
                SpawnEnemyClassEffect(point + Vector2.down * .4f, point,
                    (EnemyClass)(i % 10), true);
                SpawnHitFeedback(point, Vector2.up, Color.white, 1f);
            }
            yield return new WaitForSecondsRealtime(3f);
            var elapsed = Mathf.Max(.001f, Time.realtimeSinceStartup - startedAt);
            var frames = Time.frameCount - frameBefore;
            var averageFps = frames / elapsed;
            var metricMisses = EnemyUnit.OpaqueMetricCacheMisses - missesBefore;
            var memoryDeltaMb = (System.GC.GetTotalMemory(false) - memoryBefore) / (1024f * 1024f);
            var rendererCount = FindObjectsByType<SpriteRenderer>(FindObjectsSortMode.None).Length;
            var budgetsBounded = activeEnemyClassEffects <= 14 && activeHitFeedbackEffects <= 16;
            var cacheStable = metricMisses <= 2;
            var frameStable = averageFps >= 45f;
            var memoryStable = memoryDeltaMb < 24f;
            Debug.Log($"QA_PERFORMANCE_240 enemies={stressEnemyCount} fps={averageFps:0.0} " +
                      $"metricMisses={metricMisses}:primed={enemySpriteMetricsPrimed} memoryDeltaMb={memoryDeltaMb:0.00} " +
                      $"renderers={rendererCount} vfx={activeEnemyClassEffects}/{activeHitFeedbackEffects} " +
                      $"bounded={budgetsBounded} cache={cacheStable} frame={frameStable} memory={memoryStable}");
            Application.Quit(budgetsBounded && cacheStable && frameStable && memoryStable ? 0 : 83);
        }

        private IEnumerator CaptureQaFrameRoutine(string fileName)
        {
            yield return new WaitForEndOfFrame();
            if (gameCamera == null) yield break;
            const int width = 540;
            const int height = 960;
            var target = new RenderTexture(width, height, 24, RenderTextureFormat.ARGB32);
            var previousTarget = gameCamera.targetTexture;
            var previousActive = RenderTexture.active;
            gameCamera.targetTexture = target;
            gameCamera.Render();
            RenderTexture.active = target;
            var texture = new Texture2D(width, height, TextureFormat.RGBA32, false);
            texture.ReadPixels(new Rect(0f, 0f, width, height), 0, 0);
            texture.Apply();
            var output = Path.GetFullPath(Path.Combine(Application.dataPath, "..", fileName));
            var pixels = texture.GetPixels32();
            using (var stream = File.Create(output))
            {
                var header = System.Text.Encoding.ASCII.GetBytes($"P6\n{width} {height}\n255\n");
                stream.Write(header, 0, header.Length);
                for (var y = height - 1; y >= 0; y--)
                for (var x = 0; x < width; x++)
                {
                    var pixel = pixels[y * width + x];
                    stream.WriteByte(pixel.r);
                    stream.WriteByte(pixel.g);
                    stream.WriteByte(pixel.b);
                }
            }
            gameCamera.targetTexture = previousTarget;
            RenderTexture.active = previousActive;
            Destroy(texture);
            target.Release();
            Destroy(target);
            Debug.Log($"QA_VFX_CAPTURE {output}");
        }

        private IEnumerator QaBattleRoutine()
        {
            yield return null;
            if (HasCommandLineArgument("-qaBoss"))
            {
                Round = 5;
                Money = StartBudget();
            }
            if (HasCommandLineArgument("-qaUnlock")) Money = 38;
            TryPlaceUnit(UnitArchetype.Tank, new Vector2(0f, -3.62f));
            TryPlaceUnit(UnitArchetype.Melee, new Vector2(-3.38f, -3.2f));
            TryPlaceUnit(UnitArchetype.Archer, new Vector2(3.02f, -2.35f));
            TryPlaceUnit(UnitArchetype.AreaMage, new Vector2(.72f, -2.18f));
            if (HasCommandLineArgument("-qaUnlock"))
            {
                TryPlaceUnit(UnitArchetype.SingleMage, new Vector2(-1.1f, -1.2f));
                TryPlaceUnit(UnitArchetype.Bombardier, new Vector2(1.15f, -.85f));
            }
            if (HasCommandLineArgument("-qaLevelEffect"))
                yield return new WaitForSecondsRealtime(1.4f);
            if (HasCommandLineArgument("-qaHero") || HasCommandLineArgument("-qaUltimate"))
                foreach (var unit in units) unit.AddExperience(260f);
            if (HasCommandLineArgument("-qaUltimate"))
            {
                var hero = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Archer);
                var preparationCooldown = hero != null ? hero.SkillCooldownRemaining : -1f;
                yield return new WaitForSecondsRealtime(1f);
                var preparationFrozen = hero != null &&
                                        Mathf.Abs(hero.SkillCooldownRemaining - preparationCooldown) < .02f;
                StartWave();
                yield return new WaitForSecondsRealtime(1.4f);
                var battleTicked = hero != null && hero.SkillCooldownRemaining < preparationCooldown - .8f;
                var ultimateUsed = hero != null && hero.TryUseUltimate();
                Debug.Log($"QA_ULTIMATE prepFrozen={preparationFrozen} battleTicked={battleTicked} used={ultimateUsed}");
                yield return new WaitForSecondsRealtime(1.2f);
                Application.Quit(preparationFrozen && battleTicked && ultimateUsed ? 0 : 3);
                yield break;
            }
            StartWave();
        }

        private IEnumerator QaDirectionRoutine()
        {
            yield return null;
            Money = 80;
            TryPlaceUnit(UnitArchetype.Tank, new Vector2(-3.7f, -5.8f));
            TryPlaceUnit(UnitArchetype.Melee, new Vector2(3.7f, -5.8f));
            TryPlaceUnit(UnitArchetype.Archer, new Vector2(0f, -5.9f));
            TryPlaceUnit(UnitArchetype.AreaMage, new Vector2(-.62f, -3.15f));
            TryPlaceUnit(UnitArchetype.SingleMage, new Vector2(.62f, -2.25f));
            TryPlaceUnit(UnitArchetype.Bombardier, new Vector2(0f, -.4f));
            if (HasCommandLineArgument("-qaSelection") && units.Count > 0)
                SelectOnly(units[^1]);
            if (HasCommandLineArgument("-qaHero"))
                foreach (var unit in units) unit.AddExperience(260f);
            var targets = new[]
            {
                new Vector2(-3.12f, -1.8f), new Vector2(3.12f, -1.8f), new Vector2(0f, -2.9f),
                new Vector2(-1.25f, -2.35f), new Vector2(1.22f, -1.5f), new Vector2(0f, 2.8f)
            };
            for (var i = 0; i < units.Count && i < targets.Length; i++) units[i].MoveTo(targets[i]);
            yield return new WaitForSecondsRealtime(18f);
            var moving = 0;
            foreach (var unit in units)
            {
                if (unit == null) continue;
                if (unit.IsMoving) moving++;
                Debug.Log($"QA_DIRECTION_UNIT type={unit.Archetype} position={unit.Position} moving={unit.IsMoving}");
            }
            var cliffBlocked = !HasWalkableLine(new Vector2(0f, -3.45f), new Vector2(1.45f, -3.45f), .08f);
            Debug.Log($"QA_DIRECTION_COMPLETE units={units.Count} stillMoving={moving} cliffBlocked={cliffBlocked}");
            Application.Quit(moving == 0 && cliffBlocked ? 0 : 2);
        }

        private IEnumerator QaControlRoutine()
        {
            yield return null;
            Money = 60;
            TryPlaceUnit(UnitArchetype.Archer, new Vector2(0f, -4.1f));
            TryPlaceUnit(UnitArchetype.Tank, new Vector2(-3.45f, -4.9f));
            TryPlaceUnit(UnitArchetype.Melee, new Vector2(3.45f, -5f));
            var unitCountBeforeHillPlacement = units.Count;
            var moneyBeforeHillPlacement = Money;
            TryPlaceUnit(UnitArchetype.Tank, HighGroundZones[3].Center);
            var tankHillAccepted = units.Count == unitCountBeforeHillPlacement + 1 && Money < moneyBeforeHillPlacement;
            var edgeClamp = NearestWalkable(new Vector2(99f, 0f), .2f);
            var stayedInsideMap = Mathf.Abs(edgeClamp.x) <= PlayableHalfWidth + .001f;
            var archer = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Archer);
            var tank = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Tank);
            var melee = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.Melee);

            SelectInRectangle(Vector2.zero, new Vector2(Screen.width, Screen.height));
            var groupSelected = selectedUnits.Count >= 3;
            SelectOnly(archer);
            var singleSelected = selectedUnits.Count == 1 && selectedUnits[0] == archer;

            var enemy = new GameObject("QA Target").AddComponent<EnemyUnit>();
            enemy.Initialize(this, 0, 500f, false, 1, false);
            enemies.Add(enemy);
            var autoEnemy = new GameObject("QA Auto Target").AddComponent<EnemyUnit>();
            autoEnemy.Initialize(this, 1, 500f, false, 2, false);
            enemies.Add(autoEnemy);
            // Keep the control test about command and detection behaviour, rather than how
            // long a distant corner spawn takes to reach a defender.
            if (archer != null)
                enemy.ForcePositionForQa(archer.Position + Vector2.left * (archer.AttackRange + .24f));
            if (melee != null)
                autoEnemy.ForcePositionForQa(melee.Position + Vector2.left * (melee.AttackRange + .28f));
            Phase = GamePhase.Battle;
            spawning = true;
            var archerStart = archer != null ? archer.Position : Vector2.zero;
            var meleeStart = melee != null ? melee.Position : Vector2.zero;
            var tankStart = tank != null ? tank.Position : Vector2.zero;
            var enemyStartHealth = enemy.Health;
            var outsideAttackRange = archer != null &&
                                     Vector2.Distance(archer.Position, enemy.Position) > archer.AttackRange;
            var attackOrdered = archer != null && archer.TryCommandAttack(enemy);
            if (tank != null)
            {
                tank.Stop();
                tank.TakeDamage(12f);
            }
            var tankGuardExperience = tank != null && tank.Experience > 0f;
            var detectionIsLarger = archer != null && archer.DetectionRange > archer.AttackRange &&
                                    melee != null && melee.DetectionRange > melee.AttackRange;

            yield return new WaitForSecondsRealtime(2.2f);
            var commandPursued = archer != null && Vector2.Distance(archer.Position, archerStart) > .08f;
            var autoPursued = melee != null && Vector2.Distance(melee.Position, meleeStart) > .06f;
            var stoppedUnitHeld = tank != null && tank.IsHoldingPosition &&
                                  Vector2.Distance(tank.Position, tankStart) < .04f;
            var targetDamaged = enemy != null && enemy.Health < enemyStartHealth;
            Debug.Log($"QA_CONTROL group={groupSelected} single={singleSelected} attack={attackOrdered} " +
                      $"outside={outsideAttackRange} pursued={commandPursued} auto={autoPursued} " +
                       $"held={stoppedUnitHeld} detection={detectionIsLarger} damaged={targetDamaged} " +
                       $"tankXp={tankGuardExperience} hillAccepted={tankHillAccepted} inside={stayedInsideMap}");
            Application.Quit(groupSelected && singleSelected && attackOrdered && outsideAttackRange &&
                              commandPursued && autoPursued && stoppedUnitHeld && detectionIsLarger &&
                              targetDamaged && tankGuardExperience && tankHillAccepted && stayedInsideMap ? 0 : 4);
        }

        private IEnumerator QaAugmentRoutine()
        {
