            showFormationPanel = false;
            showAugmentSummary = false;
            augmentOverlayHidden = false;
            currentOffers = HasCommandLineArgument("-qaSystems")
                ? new[]
                {
                    new AugmentOffer("응급 수리 상자", "성벽 내구도 즉시 +56",
                        "GateHeal", AugmentTier.Bronze, TierPower(AugmentTier.Bronze)),
                    new AugmentOffer("왕실 기술자 영입", "신규 유닛 시계태엽 포병 편성 해금",
                        "UnlockBombardier", AugmentTier.Gold, TierPower(AugmentTier.Gold)),
                    new AugmentOffer("성벽 수호 정령", "성벽이 받는 모든 피해 -17%",
                        "GateRepair", AugmentTier.Platinum, TierPower(AugmentTier.Platinum))
                }
