        }

        private IEnumerator QaAugmentRulesRoutine()
        {
            yield return null;
            var offers = GenerateOffers();
            var oneTierRow = offers.Length == 3 && offers.All(offer => offer.Tier == offers[0].Tier) &&
                             offers.Select(offer => offer.Name).Distinct().Count() == offers.Length;
            SelectAugment(new AugmentOffer("QA Bombardier", "", "UnlockBombardier", AugmentTier.Gold,
                TierPower(AugmentTier.Gold)));
            var removedAfterUnlock = !GetAvailableAugmentTemplates(AugmentTier.Gold)
                .Any(template => template.EffectKey == "UnlockBombardier");
            SelectAugment(new AugmentOffer("QA Musketeer", "", "UnlockMusketeer", AugmentTier.Gold,
                TierPower(AugmentTier.Gold)));
            SelectAugment(new AugmentOffer("QA Oracle", "", "UnlockOracle", AugmentTier.Diamond,
                TierPower(AugmentTier.Diamond)));
            var recruitsUnlockOnce = IsUnitUnlocked(UnitArchetype.Musketeer) && IsUnitUnlocked(UnitArchetype.Oracle) &&
                                     !GetAvailableAugmentTemplates(AugmentTier.Gold)
                                         .Any(template => template.EffectKey == "UnlockMusketeer") &&
                                     !GetAvailableAugmentTemplates(AugmentTier.Diamond)
                                         .Any(template => template.EffectKey == "UnlockOracle");
            Debug.Log($"QA_AUGMENT_RULES sameTier={oneTierRow} removedAfterUnlock={removedAfterUnlock} " +
                      $"recruitsUnlockOnce={recruitsUnlockOnce}");
            Application.Quit(oneTierRow && removedAfterUnlock && recruitsUnlockOnce ? 0 : 8);
        }

        private IEnumerator QaAreaMageRoutine()
        {
            yield return null;
            Money = 20;
            TryPlaceUnit(UnitArchetype.AreaMage, new Vector2(0f, -3.2f));
            var mage = units.Find(unit => unit != null && unit.Archetype == UnitArchetype.AreaMage);
            if (mage == null)
            {
                Debug.LogError("QA_AREA_MAGE_SETUP_FAILED");
                Application.Quit(12);
                yield break;
            }
            var primary = new GameObject("QA Area Primary").AddComponent<EnemyUnit>();
            primary.Initialize(this, 0, 250f, false, 1, EnemyClass.Melee);
            primary.transform.position = mage.transform.position + new Vector3(0f, 1.55f, 0f);
            enemies.Add(primary);
            var nearby = new GameObject("QA Area Nearby").AddComponent<EnemyUnit>();
            nearby.Initialize(this, 1, 250f, false, 1, EnemyClass.Melee);
            nearby.transform.position = primary.transform.position + new Vector3(.78f, .08f, 0f);
            enemies.Add(nearby);
            var primaryStart = primary.Health;
            var nearbyStart = nearby.Health;
            PerformAttack(mage, primary, definitions[UnitArchetype.AreaMage]);
            yield return new WaitForSecondsRealtime(1.1f);
            var primaryHit = primary.Health < primaryStart;
            var nearbyHit = nearby.Health < nearbyStart;
            Debug.Log($"QA_AREA_MAGE primaryHit={primaryHit} nearbyHit={nearbyHit} splash=" +
                      $"{definitions[UnitArchetype.AreaMage].SplashRadius:0.00}");
            Application.Quit(primaryHit && nearbyHit ? 0 : 12);
        }

