        private IEnumerator QaFullRosterRoutine()
        {
            yield return null;
            showFormationPanel = false;
            cameraMapCenter = new Vector2(0f, -6.15f);
            cameraZoom = cameraZoomTarget = 4.8f;
            ApplyCameraPose();

            var roster = new[]
            {
                UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Archer,
                UnitArchetype.AreaMage, UnitArchetype.SingleMage, UnitArchetype.Bombardier,
                UnitArchetype.Lancer, UnitArchetype.Druid, UnitArchetype.Musketeer, UnitArchetype.Oracle
            };
            var allFramesReady = true;
            var independentRecruitArt = true;
            var upgradedCoreHeroArt = true;
            var heroPaletteContrast = true;
            var scoreByCost = new Dictionary<int, List<float>>();
            foreach (var archetype in roster)
            {
                var normal = GetDirectionalAnimation(archetype, false);
                var hero = GetDirectionalAnimation(archetype, true);
                var directionSets = new[]
                {
                    normal.Down, normal.Side, normal.Up,
                    hero.Down, hero.Side, hero.Up
                };
                var framesReady = directionSets.All(frames =>
                    frames.Length >= 7 &&
                    frames.Take(4).Distinct().Count() >= 4 &&
                    frames.Skip(4).Take(3).Distinct().Count() >= 3);
                allFramesReady &= framesReady;

                if (archetype is UnitArchetype.Lancer or UnitArchetype.Druid or
                    UnitArchetype.Musketeer or UnitArchetype.Oracle)
                {
                    var expected = archetype.ToString().ToLowerInvariant();
                    independentRecruitArt &=
                        normal.Down[0].texture.name.Contains($"{expected}-direction-v1") &&
                        hero.Down[0].texture.name.Contains($"hero-{expected}-direction-v1") &&
                        normal.Down[0].texture != hero.Down[0].texture;
                }
                else
                {
                    var expectedHeroResource = archetype switch
                    {
                        UnitArchetype.Tank => "hero-tank-direction-v2",
                        UnitArchetype.Melee => "hero-melee-direction-v2",
                        UnitArchetype.Archer => "hero-archer-direction-v2",
                        UnitArchetype.AreaMage => "hero-area-mage-direction-v2",
                        UnitArchetype.SingleMage => "hero-single-mage-direction-v2",
                        UnitArchetype.Bombardier => "hero-bombardier-direction-v2",
                        _ => string.Empty
                    };
                    upgradedCoreHeroArt &= !string.IsNullOrEmpty(expectedHeroResource) &&
                                           hero.Down[0].texture.name.Contains(expectedHeroResource) &&
                                           normal.Down[0].texture != hero.Down[0].texture;
                }

                var normalTint = GetUnitSpriteTint(archetype);
                var heroTint = GetHeroSpriteTint(archetype);
                var tintDistance = Vector3.Distance(
                    new Vector3(normalTint.r, normalTint.g, normalTint.b),
                    new Vector3(heroTint.r, heroTint.g, heroTint.b));
                heroPaletteContrast &= tintDistance >= .18f;

                var score = RosterBudgetScore(definitions[archetype]);
                if (!scoreByCost.TryGetValue(definitions[archetype].Cost, out var costScores))
                {
                    costScores = new List<float>();
                    scoreByCost[definitions[archetype].Cost] = costScores;
                }
                costScores.Add(score);
                Debug.Log($"QA_ROSTER_UNIT type={archetype} cost={definitions[archetype].Cost} " +
                          $"budget={score:0.00} efficiency={score / definitions[archetype].Cost:0.00} " +
                          $"frames={framesReady} heroTint={tintDistance:0.00}");
            }

            var costAverages = scoreByCost.OrderBy(pair => pair.Key)
                .Select(pair => (Cost: pair.Key, Average: pair.Value.Average()))
                .ToArray();
            var priceCurve = costAverages.All(pair => pair.Average / pair.Cost is >= 2f and <= 3.05f);
            for (var i = 1; i < costAverages.Length; i++)
                priceCurve &= costAverages[i].Average > costAverages[i - 1].Average;

            for (var i = 0; i < roster.Length; i++)
            {
                var column = i % 5;
                var row = i / 5;
                var actor = new GameObject("QA Full Roster " + roster[i]).AddComponent<PlayerUnit>();
                actor.Initialize(this, roster[i], definitions[roster[i]],
                    new Vector2(-3.15f + column * 1.58f, -5.45f - row * 1.45f));
                units.Add(actor);
                actor.AddExperience(3000f);
                actor.PreviewProductionAction(i);
            }

            yield return new WaitForSecondsRealtime(1.25f);
            var heroPresentation = units.Count == roster.Length &&
                                   units.All(unit => unit != null && unit.IsHero &&
                                                     unit.HeroPresentationReady &&
                                                     unit.CurrentFrameTextureName.StartsWith("hero-"));
            var passed = allFramesReady && independentRecruitArt && upgradedCoreHeroArt && heroPaletteContrast &&
                         priceCurve && heroPresentation;
            Debug.Log($"QA_FULL_ROSTER frames={allFramesReady} independent={independentRecruitArt} upgradedCore={upgradedCoreHeroArt} " +
                      $"heroPalette={heroPaletteContrast} heroPresentation={heroPresentation} " +
                      $"priceCurve={priceCurve} averages={string.Join(",", costAverages.Select(pair => $"{pair.Cost}:{pair.Average:0.00}"))}");
            yield return new WaitForSecondsRealtime(2.25f);
            Application.Quit(passed ? 0 : 31);
        }

        private IEnumerator QaHillAugmentsRoutine()
        {
            yield return null;
            Money = 100;
            var hillPoint = HighGroundZones[0].Center;
            var groundPoint = new Vector2(-3.2f, 3.02f);
            TryPlaceUnit(UnitArchetype.Archer, hillPoint);
            TryPlaceUnit(UnitArchetype.Archer, groundPoint);
            var hillUnit = units.FirstOrDefault(unit => unit != null && unit.IsOnHighGround);
            var groundUnit = units.FirstOrDefault(unit => unit != null && !unit.IsOnHighGround);
            if (hillUnit == null || groundUnit == null)
            {
                Debug.LogError("QA_HILL_AUGMENT_SETUP_FAILED");
                Application.Quit(32);
                yield break;
            }

            var baseDamage = hillUnit.AttackPower;
            var baseRange = hillUnit.AttackRange;
            var baseArmor = hillUnit.Armor;
            var baseDelay = GetHighGroundAttackDelayMultiplier(hillUnit);
            var groundDamage = groundUnit.AttackPower;
            var groundRange = groundUnit.AttackRange;
            var groundArmor = groundUnit.Armor;

            var cardsPresent =
                GetAvailableAugmentTemplates(AugmentTier.Bronze).Any(card => card.EffectKey == "HillGuard") &&
                GetAvailableAugmentTemplates(AugmentTier.Silver).Any(card => card.EffectKey == "HillDamage") &&
                GetAvailableAugmentTemplates(AugmentTier.Gold).Any(card => card.EffectKey == "HillRange") &&
                GetAvailableAugmentTemplates(AugmentTier.Platinum).Any(card => card.EffectKey == "HillTempo") &&
                GetAvailableAugmentTemplates(AugmentTier.Diamond).Any(card => card.EffectKey == "HillDominion");

            augmentPower["HillGuard"] = TierPower(AugmentTier.Bronze);
            augmentPower["HillDamage"] = TierPower(AugmentTier.Silver);
            augmentPower["HillRange"] = TierPower(AugmentTier.Gold);
            augmentPower["HillTempo"] = TierPower(AugmentTier.Platinum);
            augmentPower["HillDominion"] = TierPower(AugmentTier.Diamond);

            var hillStatsApplied =
                hillUnit.AttackPower > baseDamage * 1.105f &&
                hillUnit.AttackRange > baseRange + .20f &&
                hillUnit.Armor > baseArmor + 8.5f &&
                GetHighGroundAttackDelayMultiplier(hillUnit) < baseDelay * .91f;
            var groundUnaffected =
                Mathf.Abs(groundUnit.AttackPower - groundDamage) < .001f &&
                Mathf.Abs(groundUnit.AttackRange - groundRange) < .001f &&
                Mathf.Abs(groundUnit.Armor - groundArmor) < .001f &&
                Mathf.Abs(GetHighGroundAttackDelayMultiplier(groundUnit) - 1f) < .001f;

            var oneStackDamage = hillUnit.AttackPower;
            augmentPower["HillDamage"] += TierPower(AugmentTier.Silver);
            var stackingWorks = hillUnit.AttackPower > oneStackDamage * 1.03f;

            var groundToHillPath = FindWalkPath(groundUnit.Position, hillPoint, groundUnit.Radius * .5f);
            var hillToGroundPath = FindWalkPath(hillUnit.Position, groundPoint, hillUnit.Radius * .5f);
            var groundRefusesClimb = groundToHillPath.Count == 0 ||
                                     Vector2.Distance(groundToHillPath[^1], groundUnit.Position) < .05f;
            var hillProjectsToEdge = hillToGroundPath.Count == 1 &&
                                     HighGroundZones[0].Contains(hillToGroundPath[0], hillUnit.Radius * .5f) &&
                                     Vector2.Distance(hillToGroundPath[0], hillUnit.Position) > .2f;
            var terrainSeparated = groundRefusesClimb && hillProjectsToEdge;
            var hillStart = hillUnit.Position;
            var groundStart = groundUnit.Position;
            hillUnit.MoveTo(groundPoint);
            groundUnit.MoveTo(hillPoint);
            yield return new WaitForSecondsRealtime(.8f);
            var projectedHillDestination = NearestWalkableOnSameTerrain(
                groundPoint, hillStart, hillUnit.Radius * .5f);
            var liveLock =
                Vector2.Distance(hillUnit.Position, projectedHillDestination) <
                Vector2.Distance(hillStart, projectedHillDestination) - .08f &&
                Vector2.Distance(groundUnit.Position, groundStart) < .05f &&
                hillUnit.IsOnHighGround && !groundUnit.IsOnHighGround;

            var passed = cardsPresent && hillStatsApplied && groundUnaffected &&
                         stackingWorks && terrainSeparated && liveLock;
            Debug.Log($"QA_HILL_AUGMENTS cards={cardsPresent} stats={hillStatsApplied} ground={groundUnaffected} " +
                      $"stacking={stackingWorks} separated={terrainSeparated} liveLock={liveLock} " +
                      $"hillMove={Vector2.Distance(hillStart, hillUnit.Position):0.00}:target={projectedHillDestination} " +
                      $"damage={hillUnit.AttackPower:0.00} range={hillUnit.AttackRange:0.00} armor={hillUnit.Armor:0.00} " +
                      $"delay={GetHighGroundAttackDelayMultiplier(hillUnit):0.000}");
            Application.Quit(passed ? 0 : 32);
        }

        private IEnumerator QaCombatSystemsRoutine()
        {
            yield return null;
            Phase = GamePhase.Preparation;
            Money = 100;

            var roster = new[]
            {
                UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Archer,
                UnitArchetype.AreaMage, UnitArchetype.SingleMage, UnitArchetype.Bombardier,
                UnitArchetype.Lancer, UnitArchetype.Druid, UnitArchetype.Musketeer, UnitArchetype.Oracle
            };
            var heroSources = new List<PlayerUnit>();
            for (var i = 0; i < roster.Length; i++)
            {
                var actor = new GameObject($"QA Hero Effect {roster[i]}").AddComponent<PlayerUnit>();
                actor.Initialize(this, roster[i], definitions[roster[i]],
                    new Vector2(-4.2f + i % 5 * 2.1f, -7.4f + i / 5 * 1.15f));
                actor.AddExperience(3000f);
                heroSources.Add(actor);
                SpawnHeroSkillSpectacle(actor, new Vector2(-2.8f + i % 5 * 1.4f, -.5f + i / 5), false);
                SpawnHeroSkillSpectacle(actor, new Vector2(-2.8f + i % 5 * 1.4f, 1.3f + i / 5), true);
            }
            yield return new WaitForSecondsRealtime(.08f);
            var visibleHeroEffects = UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None)
                .Count(item => item.name is "Hero Skill Spectacle" or "Hero Ultimate Spectacle");
            var heroEffects = heroSources.All(hero => hero != null && hero.IsHero) &&
                              heroSpectacleCount >= roster.Length * 2 &&
                              visibleHeroEffects >= roster.Length * 2;

            var hillPoint = HighGroundZones[0].Center;
            TryPlaceUnit(UnitArchetype.Archer, hillPoint);
            var hillDefender = units.FirstOrDefault(unit => unit != null && unit.IsOnHighGround);
            var gateFace = GetGateAttackPoint(1);
            var gateDefender = new GameObject("QA Gate Lock Defender").AddComponent<PlayerUnit>();
            gateDefender.Initialize(this, UnitArchetype.Tank, definitions[UnitArchetype.Tank],
                gateFace + Vector2.down * .62f);
            units.Add(gateDefender);
            if (hillDefender == null)
            {
                Debug.LogError("QA_COMBAT_SYSTEMS_HILL_SETUP_FAILED");
                Application.Quit(33);
                yield break;
            }

            var rangedEnemy = new GameObject("QA Detection Mage").AddComponent<EnemyUnit>();
            rangedEnemy.Initialize(this, 0, 520f, false, 0, EnemyClass.Mage);
            // Start outside weapon range but inside detection range: the mage must advance to
            // the cliff edge and then attack the elevated defender without climbing the hill.
            rangedEnemy.ForcePositionForQa(hillPoint + Vector2.down * 2.25f);
            enemies.Add(rangedEnemy);

            var gateEnemy = new GameObject("QA Ranged Gate Lock").AddComponent<EnemyUnit>();
            gateEnemy.Initialize(this, 1, 520f, false, 1, EnemyClass.Mage);
            gateEnemy.ForceAtGateForQa();
            enemies.Add(gateEnemy);

            var hillHealthBefore = hillDefender.Health;
            var gateDefenderHealthBefore = gateDefender.Health;
            var gateHealthBefore = gateHealth;
            Phase = GamePhase.Battle;
            yield return new WaitForSecondsRealtime(2.5f);
            var detectionRange = rangedEnemy != null && rangedEnemy.DetectionRange > rangedEnemy.AttackRange + .9f;
            var rangedHitsHill = hillDefender.Health < hillHealthBefore && rangedEnemy.IsEngagingDefender;
            var gateLock = gateHealth < gateHealthBefore &&
                           Mathf.Abs(gateDefender.Health - gateDefenderHealthBefore) < .001f &&
                           gateEnemy.IsAtGate;

            var bossClasses = new[]
            {
                EnemyClass.Melee, EnemyClass.Skeleton, EnemyClass.Runner,
                EnemyClass.Brute, EnemyClass.Shaman, EnemyClass.Siege,
                EnemyClass.Piercer, EnemyClass.Wisp, EnemyClass.Flyer, EnemyClass.Mage
            };
            var bossProfiles = new HashSet<string>();
            var bossPassives = new HashSet<string>();
            var passiveDescriptionsComplete = true;
            foreach (var enemyClass in bossClasses)
            {
                var probe = new GameObject($"QA Boss Profile {enemyClass}").AddComponent<EnemyUnit>();
                probe.Initialize(this, 2, 900f, true, 2, enemyClass);
                bossProfiles.Add(probe.BossSkillProfileId);
                bossPassives.Add(probe.BossPassiveProfileId);
                passiveDescriptionsComplete &= !string.IsNullOrWhiteSpace(probe.BossPassiveDescription);
                Destroy(probe.gameObject);
            }
            yield return null;
            var lich = new GameObject("QA Lich Summoner").AddComponent<EnemyUnit>();
            lich.Initialize(this, 3, 900f, true, 2, EnemyClass.Skeleton);
            lich.SetSummonedPosition(new Vector2(0f, -5.4f), 12);
            enemies.Add(lich);
            var enemyCountBeforeSummon = enemies.Count;
            lich.ForceBossSkillReadyForQa();
            lich.ForceBossSkillCastForQa();
            yield return new WaitForSecondsRealtime(1.2f);
            var bossSkills = bossProfiles.Count == bossClasses.Length &&
                             bossPassives.Count == bossClasses.Length && passiveDescriptionsComplete &&
                             lich.BossSkillCastCount > 0 &&
                             lich.LastBossSkillId == "lich_legion" &&
                             enemies.Count >= enemyCountBeforeSummon + 3 &&
                             bossSignatureEffectCount > 0;

            var passed = heroEffects && detectionRange && rangedHitsHill && gateLock && bossSkills;
            Debug.Log($"QA_COMBAT_SYSTEMS heroEffects={heroEffects} visible={visibleHeroEffects} " +
                      $"detection={detectionRange} hillTarget={rangedHitsHill} gateLock={gateLock} " +
                      $"bossProfiles={bossProfiles.Count} passives={bossPassives.Count}:{passiveDescriptionsComplete} lichSummon={enemies.Count - enemyCountBeforeSummon} " +
                      $"bossEffects={bossSignatureEffectCount}");
            Application.Quit(passed ? 0 : 33);
        }

        private static float RosterBudgetScore(UnitDefinition definition) =>
            definition.MaxHealth * .018f +
            definition.AttackPower * .18f +
            definition.MagicPower * .15f +
            definition.Range * .75f +
            (definition.Armor + definition.MagicResistance) * .035f +
            definition.SplashRadius * 3f +
            definition.MoveSpeed;

        private static bool HasCommandLineArgument(string name)
        {
            foreach (var arg in Environment.GetCommandLineArgs())
                if (string.Equals(arg, name, StringComparison.OrdinalIgnoreCase)) return true;
            return false;
        }

        private void BuildLocalizedDefinitions()
        {
            // The canonical table below already localizes every display name. Keeping a second
            // legacy copy caused stale mojibake and stat drift between Korean and English builds.
            BuildDefinitions();
            return;
            definitions[UnitArchetype.Tank] = new UnitDefinition(
                L("왕관 방패병", "Crown Shield Guard"), "◆", 5, 240f, 20f, 4f,
                .82f, .94f, .36f, 1.30f, new Color(.96f, .73f, .16f),
                armor: 56f, magicResistance: 40f, skillCooldown: 7.6f);
            definitions[UnitArchetype.Melee] = new UnitDefinition(
                L("대지 망치병", "Earthshaker Guard"), "▲", 4, 124f, 31f, 4f,
                .86f, .72f, .29f, 1.72f, new Color(1f, .42f, .35f),
                armor: 26f, magicResistance: 18f, skillCooldown: 5.8f);
            definitions[UnitArchetype.Archer] = new UnitDefinition(
                L("바람길 궁수", "Gale Pathfinder"), "➤", 4, 62f, 18f, 5f,
                4.25f, .82f, .24f, 1.56f, new Color(.31f, .88f, .68f),
                armor: 10f, magicResistance: 12f, skillCooldown: 7.3f);
            definitions[UnitArchetype.AreaMage] = new UnitDefinition(
                L("별가루 범위 마법사", "Stardust Area Mage"), "✦", 6, 60f, 4f, 42f,
                2.55f, 1.38f, .25f, 1.42f, new Color(.68f, .4f, .9f),
                1.45f, 8f, 36f, 5.8f);
            definitions[UnitArchetype.SingleMage] = new UnitDefinition(
                L("유리구슬 단일 마법사", "Glass Orb Mage"), "◇", 5, 54f, 4f, 72f,
                3.25f, 1.62f, .24f, 1.49f, new Color(.25f, .65f, .94f),
