            StartCoroutine(ImpactRoutine(position, color, UnitArchetype.None, .55f,
                Vector2.right, CombatVfxTier.Basic, null));
        }

        public void SpawnAttackCue(Vector2 position, UnitArchetype archetype, Color color,
            PlayerUnit source = null) =>
            StartCoroutine(AttackCueRoutine(position, archetype, color, source));

        public void SpawnCombatImpact(Vector2 position, UnitArchetype archetype, Color color, float radius = .62f,
            Vector2 incomingDirection = default, CombatVfxTier tier = CombatVfxTier.Basic,
            PlayerUnit source = null)
        {
            if (Use2p5DPresentation) Stylized2p5DMeshEffect.SpawnImpact(position, color, radius);
            StartCoroutine(ImpactRoutine(position, color, archetype, radius, incomingDirection, tier, source));
