        public void SpawnEnemyClassEffect(Vector2 origin, Vector2 target, EnemyClass enemyClass, bool signature)
        {
            if (Phase != GamePhase.Battle) return;
            enemyClassEffectCount++;
            if (activeEnemyClassEffects >= 14) return;
            activeEnemyClassEffects++;
            StartCoroutine(EnemyClassEffectRoutine(origin, target, enemyClass, signature));
        }

        private IEnumerator EnemyClassEffectRoutine(Vector2 origin, Vector2 target, EnemyClass enemyClass,
            bool signature)
        {
            var primary = enemyClass switch
            {
                EnemyClass.Melee => new Color(.74f, .3f, 1f),
                EnemyClass.Mage => new Color(.58f, .38f, 1f),
                EnemyClass.Skeleton => new Color(.92f, .84f, .62f),
                EnemyClass.Runner => new Color(.35f, 1f, .38f),
                EnemyClass.Brute => new Color(1f, .38f, .1f),
                EnemyClass.Shaman => new Color(.18f, 1f, .62f),
                EnemyClass.Siege => new Color(.76f, .26f, 1f),
                EnemyClass.Piercer => new Color(1f, .16f, .08f),
                EnemyClass.Wisp => new Color(.18f, .9f, 1f),
                EnemyClass.Flyer => new Color(.72f, .3f, 1f),
                EnemyClass.Silencer => new Color(.24f, .84f, .96f),
                EnemyClass.Cursebinder => new Color(.20f, .84f, .96f),
                EnemyClass.Sunderer => new Color(1f, .56f, .10f),
                _ => new Color(1f, .56f, .18f)
            };
            var secondary = enemyClass switch
            {
                EnemyClass.Skeleton => new Color(.55f, .72f, .88f),
                EnemyClass.Runner => new Color(1f, .9f, .22f),
                EnemyClass.Brute => new Color(1f, .72f, .18f),
                EnemyClass.Shaman => new Color(.42f, 1f, .9f),
                EnemyClass.Siege => new Color(.28f, .55f, 1f),
                EnemyClass.Piercer => new Color(1f, .72f, .18f),
                EnemyClass.Wisp => Color.white,
                EnemyClass.Flyer => new Color(1f, .35f, .72f),
                EnemyClass.Silencer => new Color(.64f, .28f, 1f),
                EnemyClass.Cursebinder => new Color(.66f, .34f, 1f),
                EnemyClass.Sunderer => new Color(1f, .88f, .42f),
                _ => Color.Lerp(primary, Color.white, .72f)
            };

            var root = TransientBattleEffect.Create(signature ? $"{enemyClass} Signature VFX" : $"{enemyClass} Attack VFX");
            root.transform.position = new Vector3(target.x, target.y, -4.28f);
            var delta = origin - target;
            if (delta.sqrMagnitude < .005f) delta = Vector2.down * .35f;
            var direction = (-delta).normalized;
            var angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;
            var distance = Mathf.Clamp(delta.magnitude, .24f, signature ? 3.2f : 2.1f);

            var impact = CreateSpriteChild(root.transform, "Class Impact Core", GlowSprite,
                new Color(primary.r, primary.g, primary.b, .88f), signature ? .34f : .22f, 66);
            var ring = CreateSpriteChild(root.transform, "Class Impact Ring", CommandRingSprite,
                new Color(secondary.r, secondary.g, secondary.b, .92f), .12f, 65);
            var motif = CreateSpriteChild(root.transform, "Authored Impact Motif", EnemyVfxMotifFor(enemyClass),
                Color.white, signature ? .22f : .14f, 67);
            motif.transform.localEulerAngles = new Vector3(0f, 0f, angle - 90f);
            var originEcho = CreateSpriteChild(root.transform, "Origin Echo", EnemyVfxMotifFor(enemyClass),
                new Color(primary.r, primary.g, primary.b, .5f), signature ? .09f : .055f, 63);
            originEcho.transform.localPosition = delta;
            originEcho.transform.localEulerAngles = new Vector3(0f, 0f, -angle);

            var shardCount = signature ? 16 : 10;
            if (enemyClass is EnemyClass.Brute or EnemyClass.Siege) shardCount += 4;
            var shards = new SpriteRenderer[shardCount];
            var shardDirections = new Vector2[shardCount];
            for (var i = 0; i < shardCount; i++)
            {
                var fan = Mathf.Lerp(-1.3f, 1.3f, i / (float)Mathf.Max(1, shardCount - 1));
                var baseAngle = enemyClass switch
                {
                    EnemyClass.Runner or EnemyClass.Piercer => angle * Mathf.Deg2Rad + Mathf.PI + fan * .42f,
                    EnemyClass.Flyer => angle * Mathf.Deg2Rad + Mathf.PI * .5f + fan,
                    _ => i * Mathf.PI * 2f / shardCount + fan * .12f
                };
                shardDirections[i] = new Vector2(Mathf.Cos(baseAngle), Mathf.Sin(baseAngle));
                var sprite = enemyClass is EnemyClass.Melee or EnemyClass.Wisp ? CircleSprite :
                    enemyClass is EnemyClass.Skeleton or EnemyClass.Brute ? SquareSprite : SparkSprite;
                shards[i] = CreateSpriteChild(root.transform, $"{enemyClass} Fragment {i}", sprite,
                    i % 3 == 0 ? Color.white : i % 2 == 0 ? primary : secondary,
                    signature ? .12f : .08f, 68);
                shards[i].transform.localEulerAngles = new Vector3(0f, 0f, baseAngle * Mathf.Rad2Deg);
            }

            SpriteRenderer crest = null;
            if (signature || enemyClass is EnemyClass.Mage or EnemyClass.Shaman or EnemyClass.Siege or
                EnemyClass.Silencer or EnemyClass.Cursebinder)
            {
                crest = CreateSpriteChild(root.transform, "Signature Crest", CommandRingSprite,
                    new Color(primary.r, primary.g, primary.b, .78f), .18f, 64);
                crest.transform.localEulerAngles = new Vector3(0f, 0f,
                    enemyClass is EnemyClass.Shaman or EnemyClass.Wisp ? 45f : 0f);
            }

            var duration = signature ? .48f : .3f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                var t = Mathf.Clamp01(elapsed / duration);
                var snap = Mathf.Sin(Mathf.Min(1f, t * 3f) * Mathf.PI);
                var fade = Mathf.Pow(1f - t, 1.15f);
                impact.transform.localScale = Vector3.one * Mathf.Lerp(signature ? .24f : .15f,
                    signature ? 1.72f : .94f, 1f - Mathf.Pow(1f - t, 2.7f));
                ring.transform.localScale = Vector3.one * Mathf.Lerp(.12f,
                    signature ? 2.05f : 1.18f, 1f - Mathf.Pow(1f - t, 2.5f));
                ring.transform.Rotate(0f, 0f, Time.deltaTime *
                    (enemyClass is EnemyClass.Shaman or EnemyClass.Wisp ? 260f : 150f));
                motif.transform.localScale = Vector3.one * Mathf.Lerp(signature ? .22f : .13f,
                    signature ? 1.84f : 1.08f, 1f - Mathf.Pow(1f - t, 2.2f));
                motif.transform.Rotate(0f, 0f, Time.deltaTime * (enemyClass is EnemyClass.Wisp or EnemyClass.Shaman ? 95f : 32f));
                originEcho.transform.localScale = Vector3.one * Mathf.Lerp(.06f, signature ? .72f : .42f, t);
                var ic = impact.color; ic.a = .88f * fade; impact.color = ic;
                var rc = ring.color; rc.a = .92f * fade; ring.color = rc;
                var mc = motif.color; mc.a = fade; motif.color = mc;
                var ec = originEcho.color; ec.a = .5f * fade; originEcho.color = ec;
                if (crest != null)
                {
                    crest.transform.localScale = Vector3.one * Mathf.Lerp(.18f,
                        signature ? 1.35f : .82f, t);
                    crest.transform.Rotate(0f, 0f, Time.deltaTime *
                        (enemyClass == EnemyClass.Siege ? -210f : 190f));
                    var cc = crest.color; cc.a = .78f * fade; crest.color = cc;
                }
                for (var i = 0; i < shards.Length; i++)
                {
                    var travel = (signature ? .95f : .58f) * (1f - Mathf.Pow(1f - t, 2.2f)) *
                                 (1f + (i % 3) * .16f);
                    var arc = enemyClass is EnemyClass.Brute or EnemyClass.Skeleton
                        ? Vector2.up * Mathf.Sin(t * Mathf.PI) * .18f : Vector2.zero;
                    shards[i].transform.localPosition = shardDirections[i] * travel + arc;
                    var scale = Mathf.Lerp(signature ? .14f : .095f, .012f, t);
                    if (enemyClass == EnemyClass.Piercer)
                        shards[i].transform.localScale = new Vector3(scale * 2.5f, scale * .35f, 1f);
                    else shards[i].transform.localScale = Vector3.one * scale;
                    var sc = shards[i].color; sc.a = fade; shards[i].color = sc;
                }
                yield return null;
            }
            Destroy(root);
            activeEnemyClassEffects = Mathf.Max(0, activeEnemyClassEffects - 1);
        }

        public void SpawnMeleeImpactFeedback(Vector2 position, Vector2 incomingDirection, Color color,
            float intensity = 1f, bool defenderWasHit = false)
        {
            if (Phase != GamePhase.Battle) return;
            hitFeedbackCount++;
            RequestCameraImpulse(.007f + Mathf.Clamp(intensity, .65f, 3f) * .0045f,
                .1f, CameraShakePriority.Standard);
            if (hitFeedbackFrame != Time.frameCount)
            {
                hitFeedbackFrame = Time.frameCount;
                hitFeedbackVisualsThisFrame = 0;
            }
            if ((hitFeedbackVisualsThisFrame++ >= 5 && intensity < 2f) || activeHitFeedbackEffects >= 16) return;
            activeHitFeedbackEffects++;
            StartCoroutine(MeleeImpactFeedbackRoutine(position, incomingDirection, color,
                Mathf.Clamp(intensity, .65f, 3f), defenderWasHit));
        }

        private IEnumerator MeleeImpactFeedbackRoutine(Vector2 position, Vector2 incomingDirection, Color color,
            float intensity, bool defenderWasHit)
        {
            var effect = TransientBattleEffect.Create(defenderWasHit ? "Defender Melee Impact" : "Enemy Melee Impact");
            effect.transform.position = new Vector3(position.x, position.y, -4.35f);
            var hot = defenderWasHit ? new Color(1f, .28f, .1f) : Color.Lerp(color, Color.white, .16f);
            var core = CreateSpriteChild(effect.transform, "Contact Flash", GlowSprite, Color.white, .1f, 88);
            var bloom = CreateSpriteChild(effect.transform, "Impact Bloom", GlowSprite,
                new Color(hot.r, hot.g, hot.b, .9f), .16f, 84);
            var ring = CreateSpriteChild(effect.transform, "Impact Ring", CommandRingSprite,
                new Color(hot.r, hot.g, hot.b, .92f), .12f, 86);
            const int fragmentCount = 7;
            var fragments = new SpriteRenderer[fragmentCount];
            var directions = new Vector2[fragmentCount];
            var baseAngle = incomingDirection.sqrMagnitude > .001f
                ? Mathf.Atan2(incomingDirection.y, incomingDirection.x)
                : -Mathf.PI * .5f;
            for (var i = 0; i < fragmentCount; i++)
            {
                var arc = Mathf.Lerp(-1.12f, 1.12f, i / (float)(fragmentCount - 1));
                directions[i] = new Vector2(Mathf.Cos(baseAngle + Mathf.PI + arc),
                    Mathf.Sin(baseAngle + Mathf.PI + arc));
                fragments[i] = CreateSpriteChild(effect.transform, $"Impact Chip {i + 1}",
                    i % 2 == 0 ? SparkSprite : GlowSprite, i % 3 == 0 ? Color.white : hot,
                    i % 2 == 0 ? .07f : .045f, 87);
            }
            const float duration = .17f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.unscaledDeltaTime)
            {
                var t = Mathf.Clamp01(elapsed / duration);
                var fade = Mathf.Pow(1f - t, 1.4f);
                core.transform.localScale = Vector3.one * Mathf.Lerp(.2f * intensity, .02f, t);
                bloom.transform.localScale = Vector3.one * Mathf.Lerp(.18f, .72f * intensity, t);
                ring.transform.localScale = Vector3.one * Mathf.Lerp(.12f, 1.05f * intensity, t);
                var bc = bloom.color; bc.a = .9f * fade; bloom.color = bc;
                var rc = ring.color; rc.a = .92f * fade; ring.color = rc;
                for (var i = 0; i < fragments.Length; i++)
                {
                    fragments[i].transform.localPosition = directions[i] *
                        Mathf.Lerp(.04f, (.28f + i % 3 * .08f) * intensity, t);
                    fragments[i].transform.localScale = Vector3.one * Mathf.Lerp(.11f, .01f, t);
                    var fc = fragments[i].color; fc.a = fade; fragments[i].color = fc;
                }
                yield return null;
            }
            Destroy(effect);
            activeHitFeedbackEffects = Mathf.Max(0, activeHitFeedbackEffects - 1);
        }

        public void SpawnHitFeedback(Vector2 position, Vector2 incomingDirection, Color color,
            float intensity = 1f, bool defenderWasHit = false)
        {
            if (Phase != GamePhase.Battle) return;
            hitFeedbackCount++;
            RequestCameraImpulse(.0065f + Mathf.Clamp(intensity, .65f, 3f) * .0055f +
                                 (defenderWasHit ? .002f : 0f), .115f, CameraShakePriority.Standard);
            if (hitFeedbackFrame != Time.frameCount)
            {
                hitFeedbackFrame = Time.frameCount;
                hitFeedbackVisualsThisFrame = 0;
            }
            // Keep damage/audio deterministic while bounding transient render objects in mob bursts.
            if ((hitFeedbackVisualsThisFrame++ >= 5 && intensity < 2f) || activeHitFeedbackEffects >= 16) return;
            activeHitFeedbackEffects++;
            StartCoroutine(HitFeedbackRoutine(position, incomingDirection, color,
                Mathf.Clamp(intensity, .65f, 3f), defenderWasHit));
        }

        private enum CameraShakePriority
        {
            Standard,
            Heavy,
            Ultimate
        }

        private void RequestCameraImpulse(float impulse, float duration, CameraShakePriority priority)
        {
            if (gameCamera == null || impulse <= 0f || duration <= 0f) return;
            var ceiling = priority switch
            {
                CameraShakePriority.Heavy => HeavyCameraShakeCap,
                CameraShakePriority.Ultimate => UltimateCameraShakeCap,
                _ => StandardCameraShakeCap
            };
            var gain = Mathf.Min(impulse, ceiling);
            var now = Time.unscaledTime;
            if (priority == CameraShakePriority.Standard)
            {
                // A mob pack can create dozens of hit confirms in one render frame.  Fold those
                // requests into one restrained impulse instead of restarting random camera motion
                // for every attacker; the remaining impact stays on the struck actor and VFX.
                if (now - lastStandardShakeRequestAt < .055f)
                {
                    gain *= .08f;
                    coalescedCameraShakeRequests++;
                }
                else gain *= .68f;
                if (cameraShakeEnergy > StandardCameraShakeCap * .72f) gain *= .16f;
                lastStandardShakeRequestAt = now;
            }
            else
            {
                var lastPriorityAt = priority == CameraShakePriority.Ultimate
                    ? lastUltimateShakeRequestAt
                    : lastHeavyShakeRequestAt;
                if (now - lastPriorityAt < .14f)
                {
                    gain *= .18f;
                    coalescedCameraShakeRequests++;
                }
                else gain *= priority == CameraShakePriority.Ultimate ? .92f : .78f;
                if (priority == CameraShakePriority.Ultimate) lastUltimateShakeRequestAt = now;
                else lastHeavyShakeRequestAt = now;
            }

            activeCameraShakeCap = Mathf.Max(activeCameraShakeCap, ceiling);
            cameraShakeEnergy = Mathf.Min(activeCameraShakeCap, cameraShakeEnergy + gain);
            cameraShakeTimeRemaining = Mathf.Max(cameraShakeTimeRemaining, duration);
            peakCameraShakeEnergy = Mathf.Max(peakCameraShakeEnergy, cameraShakeEnergy);
            if (cameraShakeDriverRunning) return;
            cameraShakeDriverRunning = true;
            cameraShakeDriverStarts++;
            StartCoroutine(CameraShakeBudgetRoutine());
        }

        private IEnumerator CameraShakeBudgetRoutine()
        {
            var noiseSeed = UnityEngine.Random.Range(11f, 911f);
            var burstStartedAt = Time.unscaledTime;
            while (cameraShakeTimeRemaining > 0f || cameraShakeEnergy > .00035f)
            {
                // A crowded fight may keep producing valid impacts forever. Camera motion is
                // presented as a short readable burst, never as a continuous judder that looks
                // like frame-rate loss. Actor hit flashes continue even after this camera cap.
                if (Time.unscaledTime - burstStartedAt >= .76f) break;
                var delta = Mathf.Min(.04f, Time.unscaledDeltaTime);
                cameraShakeTimeRemaining = Mathf.Max(0f, cameraShakeTimeRemaining - delta);
                var priorityBlend = Mathf.InverseLerp(StandardCameraShakeCap,
                    UltimateCameraShakeCap, activeCameraShakeCap);
                var noiseRate = Mathf.Lerp(13.5f, 9.5f, priorityBlend);
                var phase = Time.unscaledTime * noiseRate;
                var offset = new Vector2(
                    Mathf.PerlinNoise(noiseSeed, phase) * 2f - 1f,
                    Mathf.PerlinNoise(noiseSeed + 37.1f, phase * .91f) * 2f - 1f);
                if (gameCamera != null)
                    gameCamera.transform.position = new Vector3(cameraMapCenter.x, cameraMapCenter.y, -10f) +
                                                    (Vector3)(offset * cameraShakeEnergy);

                // Common hits settle rapidly.  Boss and ultimate impacts are allowed a longer,
                // smoother tail, but never exceed their explicit displacement ceiling.
                var decayRate = Mathf.Lerp(.24f, .30f, priorityBlend);
                cameraShakeEnergy = Mathf.MoveTowards(cameraShakeEnergy, 0f, delta * decayRate);
                if (cameraShakeTimeRemaining <= 0f)
                    cameraShakeEnergy = Mathf.MoveTowards(cameraShakeEnergy, 0f, delta * .42f);
                yield return null;
            }
            cameraShakeEnergy = 0f;
            cameraShakeTimeRemaining = 0f;
            activeCameraShakeCap = 0f;
            cameraShakeDriverRunning = false;
            ApplyCameraPose();
        }

        private IEnumerator HitFeedbackRoutine(Vector2 position, Vector2 incomingDirection, Color color,
            float intensity, bool defenderWasHit)
        {
            var effect = TransientBattleEffect.Create(defenderWasHit ? "Defender Hit Confirm" : "Enemy Hit Confirm");
            effect.transform.position = new Vector3(position.x, position.y, -4.35f);
            if (incomingDirection.sqrMagnitude < .001f) incomingDirection = Vector2.down;
            incomingDirection.Normalize();
            var angle = Mathf.Atan2(incomingDirection.y, incomingDirection.x) * Mathf.Rad2Deg;
            // Preserve the strike's real damage language. A universal red fire bloom made ice,
            // curses and hammer contacts look like the same misplaced flame effect.
            var hot = Color.Lerp(color, Color.white, defenderWasHit ? .12f : .22f);
            var core = CreateSpriteChild(effect.transform, "White Hit Core", GlowSprite,
                Color.white, .12f, 84);
            var bloom = CreateSpriteChild(effect.transform, "Damage Bloom", GlowSprite,
                new Color(hot.r, hot.g, hot.b, .86f), .2f, 80);
            var pressure = CreateSpriteChild(effect.transform, "Hit Pressure Ring", CommandRingSprite,
                new Color(1f, .94f, .72f, .95f), .12f, 83);
            var sparkCount = Mathf.RoundToInt(10f + intensity * 5f);
            var sparks = new SpriteRenderer[sparkCount];
            var directions = new Vector2[sparkCount];
            for (var i = 0; i < sparkCount; i++)
            {
                var spread = Mathf.Lerp(-1.18f, 1.18f, i / (float)Mathf.Max(1, sparkCount - 1));
                var biasedAngle = angle * Mathf.Deg2Rad + Mathf.PI + spread +
                                  UnityEngine.Random.Range(-.13f, .13f);
                directions[i] = new Vector2(Mathf.Cos(biasedAngle), Mathf.Sin(biasedAngle));
                sparks[i] = CreateSpriteChild(effect.transform, $"Hit Fragment {i + 1}",
                    i % 4 == 0 ? SquareSprite : SparkSprite,
                    i % 3 == 0 ? Color.white : hot, i % 4 == 0 ? .055f : .085f, 87);
                sparks[i].transform.localEulerAngles = new Vector3(0f, 0f,
                    biasedAngle * Mathf.Rad2Deg);
            }

            var duration = .19f + intensity * .025f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.unscaledDeltaTime)
            {
                var t = Mathf.Clamp01(elapsed / duration);
                var snap = Mathf.Sin(Mathf.Min(1f, t * 3.6f) * Mathf.PI);
                var fade = Mathf.Pow(1f - t, 1.35f);
                core.transform.localScale = Vector3.one * Mathf.Lerp(.18f * intensity, .025f, t);
                bloom.transform.localScale = Vector3.one * Mathf.Lerp(.16f,
                    1.02f * intensity, 1f - Mathf.Pow(1f - t, 3f));
                pressure.transform.localScale = Vector3.one * Mathf.Lerp(.1f,
                    1.18f * intensity, 1f - Mathf.Pow(1f - t, 3f));
                var bc = bloom.color; bc.a = .86f * fade; bloom.color = bc;
                var pc = pressure.color; pc.a = .95f * fade; pressure.color = pc;
                for (var i = 0; i < sparks.Length; i++)
                {
                    var distance = (.32f + i % 4 * .11f) * intensity *
                                   (1f - Mathf.Pow(1f - t, 2.5f));
                    sparks[i].transform.localPosition = directions[i] * distance +
                                                        Vector2.up * Mathf.Sin(t * Mathf.PI) * .08f;
                    sparks[i].transform.localScale = Vector3.one *
                                                     Mathf.Lerp(i % 4 == 0 ? .09f : .13f, .01f, t);
                    var c = sparks[i].color; c.a = fade; sparks[i].color = c;
                }
                yield return null;
            }
            Destroy(effect);
            activeHitFeedbackEffects = Mathf.Max(0, activeHitFeedbackEffects - 1);
        }

        public void SpawnDamageNumber(Vector2 position, float amount, DamageType damageType, bool absorbed)
        {
            if (amount <= 0f) return;
            // Dense world-space numbers obscured small enemies and inherited broken fallback
            // glyphs on Android. Damage is now communicated with a compact typed hit pip while
            // the detailed value remains available in the selected unit/enemy information UI.
            StartCoroutine(DamagePipRoutine(position, damageType, absorbed));
        }

        private IEnumerator DamagePipRoutine(Vector2 position, DamageType damageType, bool absorbed)
        {
            var root = TransientBattleEffect.Create(absorbed ? "Guarded Hit Pip" : "Damage Hit Pip");
            root.transform.position = new Vector3(position.x, position.y + .32f, -4.2f);
            var color = absorbed
                ? new Color(.34f, .86f, 1f)
                : damageType == DamageType.Magic
                    ? new Color(.72f, .38f, 1f)
                    : damageType == DamageType.Pure
                        ? new Color(1f, .24f, .14f)
                        : new Color(1f, .76f, .24f);
            var core = CreateSpriteChild(root.transform, "Typed Hit Core", SparkSprite,
                Color.Lerp(color, Color.white, .68f), .11f, 82);
            var left = CreateSpriteChild(root.transform, "Typed Hit Left", SparkSprite, color, .09f, 81);
            var right = CreateSpriteChild(root.transform, "Typed Hit Right", SparkSprite, color, .09f, 81);
            left.transform.localEulerAngles = new Vector3(0f, 0f, 58f);
            right.transform.localEulerAngles = new Vector3(0f, 0f, -58f);
            var start = root.transform.position;
            const float duration = .34f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                if (root == null || core == null || left == null || right == null) yield break;
                var t = Mathf.Clamp01(elapsed / duration);
                var ease = 1f - Mathf.Pow(1f - t, 3f);
                root.transform.position = start + Vector3.up * (ease * .28f);
                core.transform.localScale = Vector3.one * Mathf.Lerp(.16f, .025f, t);
                left.transform.localPosition = new Vector3(-ease * .22f, ease * .12f, 0f);
                right.transform.localPosition = new Vector3(ease * .22f, ease * .12f, 0f);
                left.transform.localScale = right.transform.localScale =
                    new Vector3(Mathf.Lerp(.08f, .2f, ease), Mathf.Lerp(.11f, .018f, t), 1f);
                var fade = Mathf.Pow(1f - t, 1.35f);
                var coreColor = core.color; coreColor.a = fade; core.color = coreColor;
                var leftColor = left.color; leftColor.a = fade; left.color = leftColor;
                var rightColor = right.color; rightColor.a = fade; right.color = rightColor;
                yield return null;
            }
            Destroy(root);
        }

        public void ShowBossWarning(string message)
        {
            bossWarningText = message;
            bossWarningUntil = Time.unscaledTime + 2.2f;
        }

        public void SpawnBossTelegraph(Vector2 position, float radius, float duration) =>
            StartCoroutine(BossTelegraphRoutine(position, radius, duration));

        public void BossGroundSlam(Vector2 position, float radius, float damage,
            float physicalPenetration = 0f, float magicPenetration = 0f)
        {
            foreach (var unit in units.ToArray())
            {
                if (unit == null || !unit.IsAlive || unit.IsOnHighGround ||
                    Vector2.Distance(position, unit.Position) > radius) continue;
                unit.ReactToContact(position, .62f);
                unit.TakeDamage(damage, DamageType.Magic, false,
                    physicalPenetration, magicPenetration);
            }
            SpawnCombatImpact(position, UnitArchetype.AreaMage, new Color(1f, .22f, .16f), radius);
            SpawnEnemySlam(position, radius, new Color(1f, .22f, .16f));
        }

        public void SpawnEnemySlam(Vector2 position, float radius, Color color)
        {
            if (Use2p5DPresentation) Stylized2p5DMeshEffect.SpawnSlam(position, color, radius);
            StartCoroutine(EnemySlamRoutine(position, radius, color));
        }

        private void SpawnHeroSkillSpectacle(PlayerUnit source, Vector2 target, bool ultimate)
        {
            if (source == null || !source.IsAlive) return;
            heroSpectacleCount++;
            var primary = definitions.TryGetValue(source.Archetype, out var definition)
                ? definition.Color
                : new Color(.55f, .72f, 1f);
            if (source.Archetype == UnitArchetype.Bombardier)
                primary = new Color(.12f, .54f, .68f);
            var fallbackSecondary = source.Archetype switch
            {
                UnitArchetype.Tank => new Color(.3f, .72f, 1f),
                UnitArchetype.Melee => new Color(1f, .25f, .08f),
                UnitArchetype.Archer => new Color(.28f, 1f, .58f),
                UnitArchetype.AreaMage => new Color(.9f, .26f, 1f),
                UnitArchetype.SingleMage => new Color(.2f, .9f, 1f),
                UnitArchetype.Bombardier => new Color(.18f, .78f, 1f),
                UnitArchetype.Lancer => new Color(.16f, 1f, .72f),
                UnitArchetype.Druid => new Color(.42f, 1f, .45f),
                UnitArchetype.Musketeer => new Color(1f, .72f, .16f),
                UnitArchetype.Oracle => new Color(.48f, .72f, 1f),
                _ => Color.white
            };
            var style = ResolveCombatSkinVfxStyle(source, source.Archetype, primary);
            primary = style.Primary;
            var secondary = style.Skinned ? style.Secondary : fallbackSecondary;
            StartCoroutine(HeroSkillSpectacleRoutine(source.Position, target, source.Archetype,
                primary, secondary, ultimate, style.Variant));
        }

        private void SpawnDefensiveStanceEffect(PlayerUnit source, Color color, float duration) =>
            StartCoroutine(DefensiveStanceRoutine(source, color, duration));

        private IEnumerator DefensiveStanceRoutine(PlayerUnit source, Color color, float duration)
        {
            if (source == null) yield break;
            var style = ResolveCombatSkinVfxStyle(source, source.Archetype, color);
            color = style.Primary;
            var root = TransientBattleEffect.Create("Royal Bulwark Defensive Field");
            var rings = new SpriteRenderer[3];
            for (var i = 0; i < rings.Length; i++)
                rings[i] = CreateSpriteChild(root.transform, $"Bulwark Layer {i + 1}", CommandRingSprite,
                    i == 1 ? Color.white : new Color(color.r, color.g, color.b, .96f), 1f, 72 + i);
            var core = CreateSpriteChild(root.transform, "Bulwark Core", GlowSprite,
                new Color(style.Secondary.r, style.Secondary.g, style.Secondary.b, .68f), 1f, 70);
            var plates = new SpriteRenderer[8];
            for (var i = 0; i < plates.Length; i++)
                plates[i] = CreateSpriteChild(root.transform, $"Shield Plate {i + 1}", SquareSprite,
                    i % 3 == 0 ? style.Core : i % 2 == 0 ? style.Secondary : color, 1f, 76);
            for (var elapsed = 0f; elapsed < duration && source != null && source.IsAlive &&
                 root != null && core != null;
                 elapsed += Time.deltaTime)
            {
                root.transform.position = new Vector3(source.Position.x, source.Position.y, -4.18f);
                var entrance = Mathf.Clamp01(elapsed / .22f);
                var exit = Mathf.Clamp01((duration - elapsed) / .3f);
                var alpha = Mathf.Min(entrance, exit);
                var pulse = 1f + Mathf.Sin(elapsed * 7.5f) * .06f;
                for (var i = 0; i < rings.Length; i++)
                {
                    rings[i].transform.localScale = Vector3.one * source.Radius *
                                                    (3.2f + i * .52f) * pulse;
                    rings[i].transform.Rotate(0f, 0f, Time.deltaTime * (i % 2 == 0 ? 76f : -64f));
                    var rc = rings[i].color; rc.a = alpha * (.92f - i * .16f); rings[i].color = rc;
                }
                core.transform.localScale = Vector3.one * source.Radius * 4.1f * pulse;
                var cc = core.color; cc.a = alpha * .42f; core.color = cc;
                for (var i = 0; i < plates.Length; i++)
                {
                    var angle = i * Mathf.PI * 2f / plates.Length + elapsed * .42f;
                    plates[i].transform.localPosition = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle) * .54f) *
                                                        source.Radius * 2.05f;
                    plates[i].transform.localEulerAngles = new Vector3(0f, 0f, angle * Mathf.Rad2Deg + 45f);
                    plates[i].transform.localScale = new Vector3(source.Radius * .34f,
                        source.Radius * .12f, 1f);
                    var pc = plates[i].color; pc.a = alpha * .9f; plates[i].color = pc;
                }
                yield return null;
            }
            Destroy(root);
        }

        private void SpawnSacredBulwarkSphereEffect(PlayerUnit source, Color color, float duration)
        {
            sacredBulwarkSphereCount++;
            StartCoroutine(SacredBulwarkSphereRoutine(source, color, duration));
        }

        private IEnumerator SacredBulwarkSphereRoutine(PlayerUnit source, Color color, float duration)
        {
            if (source == null) yield break;
            var style = ResolveCombatSkinVfxStyle(source, UnitArchetype.Tank, color);
            var root = TransientBattleEffect.Create($"Sacred Bulwark Sphere Skin {style.Variant}");
            var rearLight = CreateSpriteChild(root.transform, "Bulwark Rear Hemisphere", GlowSprite,
                new Color(style.Primary.r, style.Primary.g, style.Primary.b, .38f), 1f, 2);
            var innerLight = CreateSpriteChild(root.transform, "Bulwark Consecrated Core", GlowSprite,
                new Color(style.Core.r, style.Core.g, style.Core.b, .22f), 1f, 69);
            var frontGlass = CreateSpriteChild(root.transform, "Bulwark Front Glass", CircleSprite,
                new Color(style.Primary.r, style.Primary.g, style.Primary.b, .20f), 1f, 89);
            var outerRim = CreateSpriteChild(root.transform, "Bulwark Spherical Rim", CommandRingSprite,
                Color.Lerp(style.Primary, Color.white, .58f), 1f, 92);
            var outerEcho = CreateSpriteChild(root.transform, "Bulwark Spherical Rim Echo", CommandRingSprite,
                style.Secondary, 1f, 94);
            var equator = CreateSpriteChild(root.transform, "Bulwark Equator", CommandRingSprite,
                style.Secondary, 1f, 93);
            var meridians = new SpriteRenderer[3];
            for (var i = 0; i < meridians.Length; i++)
            {
                meridians[i] = CreateSpriteChild(root.transform, $"Bulwark Meridian {i + 1}",
                    CommandRingSprite, i == 1 ? style.Core : style.Primary, 1f, 90 + i);
                meridians[i].transform.localEulerAngles = new Vector3(0f, 0f, -34f + i * 34f);
            }
            var seals = new SpriteRenderer[12];
            for (var i = 0; i < seals.Length; i++)
                seals[i] = CreateSpriteChild(root.transform, $"Bulwark Sacred Seal {i + 1}",
                    i % 3 == 0 ? CommandRingSprite : SparkSprite,
                    i % 2 == 0 ? style.Secondary : Color.Lerp(style.Primary, Color.white, .72f),
                    1f, 96);

            for (var elapsed = 0f; elapsed < duration && source != null && source.IsAlive;
                 elapsed += Time.deltaTime)
            {
                if (root == null || rearLight == null || innerLight == null || frontGlass == null ||
                    outerRim == null || outerEcho == null || equator == null ||
                    meridians.Any(item => item == null) || seals.Any(item => item == null))
                    yield break;
                var entrance = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(elapsed / .3f));
                var exit = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((duration - elapsed) / .36f));
                var alpha = Mathf.Min(entrance, exit);
                var pulse = 1f + Mathf.Sin(elapsed * 5.8f) * .045f;
                var center = source.Position + Vector2.up * source.Radius * .78f;
                root.transform.position = new Vector3(center.x, center.y, -4.24f);
                var sphereX = source.Radius * 7.20f * pulse;
                var sphereY = source.Radius * 8.10f * pulse;
                rearLight.transform.localScale = new Vector3(sphereX * .96f, sphereY * .96f, 1f);
                innerLight.transform.localScale = new Vector3(sphereX * .68f, sphereY * .72f, 1f);
                frontGlass.transform.localScale = new Vector3(sphereX * .91f, sphereY * .91f, 1f);
                outerRim.transform.localScale = new Vector3(sphereX, sphereY, 1f);
                outerEcho.transform.localScale = new Vector3(sphereX * 1.075f, sphereY * 1.075f, 1f);
                outerEcho.transform.Rotate(0f, 0f, Time.deltaTime * -20f);
                equator.transform.localScale = new Vector3(sphereX, sphereY * .34f, 1f);
                equator.transform.Rotate(0f, 0f, Time.deltaTime * 34f);
                for (var i = 0; i < meridians.Length; i++)
                {
                    meridians[i].transform.localScale = new Vector3(sphereX * (.72f + i * .1f),
                        sphereY, 1f);
                    meridians[i].transform.Rotate(0f, 0f,
                        Time.deltaTime * (i % 2 == 0 ? 18f : -22f));
                    var mc = meridians[i].color; mc.a = alpha * (.48f + i * .1f); meridians[i].color = mc;
                }
                for (var i = 0; i < seals.Length; i++)
                {
                    var angle = i * Mathf.PI * 2f / seals.Length + elapsed * (i % 2 == 0 ? .42f : -.34f);
                    seals[i].transform.localPosition = new Vector2(Mathf.Cos(angle) * sphereX * .48f,
                        Mathf.Sin(angle) * sphereY * .48f);
                    seals[i].transform.localScale = Vector3.one * source.Radius *
                                                    (i % 3 == 0 ? .42f : .22f) *
                                                    (1f + Mathf.Sin(elapsed * 8f + i) * .14f);
                    var sc = seals[i].color; sc.a = alpha * .56f; seals[i].color = sc;
                }
                var rearColor = rearLight.color; rearColor.a = alpha * .48f; rearLight.color = rearColor;
                var innerColor = innerLight.color; innerColor.a = alpha * .18f; innerLight.color = innerColor;
                var glassColor = frontGlass.color; glassColor.a = alpha * .19f; frontGlass.color = glassColor;
                var rimColor = outerRim.color; rimColor.a = alpha; outerRim.color = rimColor;
                var echoColor = outerEcho.color; echoColor.a = alpha * .94f; outerEcho.color = echoColor;
                var equatorColor = equator.color; equatorColor.a = alpha * .88f; equator.color = equatorColor;
                yield return null;
            }
            Destroy(root);
        }

        private void SpawnCoralHammerSkillEffect(PlayerUnit source, Vector2 target, Color color)
        {
            coralHammerEffectCount++;
            StartCoroutine(CoralHammerSkillEffectRoutine(source, target, color));
        }

        private IEnumerator CoralHammerSkillEffectRoutine(PlayerUnit source, Vector2 target, Color color)
        {
            if (source == null) yield break;
            var style = ResolveCombatSkinVfxStyle(source, UnitArchetype.Melee, color);
            var root = TransientBattleEffect.Create($"Earthshaker Grounding Arc Skin {style.Variant}");
            var arc = new SpriteRenderer[14];
            for (var i = 0; i < arc.Length; i++)
                arc[i] = CreateSpriteChild(root.transform, $"Hammer Swing Trail {i + 1}", SparkSprite,
                    i % 3 == 0 ? Color.white : i % 2 == 0 ? style.Primary : style.Secondary, 1f, 88);
            var impact = CreateSpriteChild(root.transform, "Hammer Contact Core", GlowSprite,
                Color.Lerp(style.Primary, Color.white, .74f), 1f, 94);
            var shock = CreateSpriteChild(root.transform, "Hammer Ground Shock", CommandRingSprite,
                style.Secondary, 1f, 92);
            var cracks = new SpriteRenderer[10];
            for (var i = 0; i < cracks.Length; i++)
                cracks[i] = CreateSpriteChild(root.transform, $"Hammer Ground Crack {i + 1}", SparkSprite,
                    i % 2 == 0 ? style.Primary : style.Core, 1f, 91);

            var origin = source.AttackOriginFor(target);
            var direction = (target - source.Position).normalized;
            if (direction.sqrMagnitude < .01f) direction = Vector2.up;
            var side = new Vector2(-direction.y, direction.x);
            const float duration = .68f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                if (root == null || source == null || impact == null || shock == null ||
                    arc.Any(item => item == null) || cracks.Any(item => item == null)) yield break;
                var t = Mathf.Clamp01(elapsed / duration);
                var contact = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((t - .30f) / .28f));
                var fade = 1f - Mathf.SmoothStep(.72f, 1f, t);
                origin = source.AttackOriginFor(target);
                for (var i = 0; i < arc.Length; i++)
                {
                    var phase = Mathf.Clamp01(t * 1.42f - i * .025f);
                    var point = Vector2.Lerp(origin, target, phase) +
                                side * Mathf.Sin(phase * Mathf.PI) * source.Radius * 1.32f;
                    arc[i].transform.position = new Vector3(point.x, point.y, -4.34f);
                    arc[i].transform.localEulerAngles = new Vector3(0f, 0f,
                        Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg - 18f + phase * 36f);
                    arc[i].transform.localScale = new Vector3(.34f, .08f, 1f) *
                                                  (1f - i / (float)arc.Length * .48f);
                    var ac = arc[i].color; ac.a = fade * Mathf.Clamp01(phase * 4f); arc[i].color = ac;
                }
                impact.transform.position = new Vector3(target.x, target.y, -4.42f);
                impact.transform.localScale = Vector3.one * Mathf.Lerp(.16f, 2.05f, contact) * fade;
                shock.transform.position = new Vector3(target.x, target.y, -4.38f);
                shock.transform.localScale = new Vector3(1.55f, .64f, 1f) *
                                             Mathf.Lerp(.08f, 1.45f, contact);
                var ic = impact.color; ic.a = fade * contact; impact.color = ic;
                var hc = shock.color; hc.a = fade * contact * .9f; shock.color = hc;
                for (var i = 0; i < cracks.Length; i++)
                {
                    var angle = i * Mathf.PI * 2f / cracks.Length;
                    cracks[i].transform.position = new Vector3(target.x, target.y, -4.36f) +
                        (Vector3)(new Vector2(Mathf.Cos(angle), Mathf.Sin(angle) * .46f) *
                                  Mathf.Lerp(.05f, .78f + i % 3 * .1f, contact));
                    cracks[i].transform.localEulerAngles = new Vector3(0f, 0f, angle * Mathf.Rad2Deg);
                    cracks[i].transform.localScale = new Vector3(.28f, .055f, 1f) * contact;
                    var cc = cracks[i].color; cc.a = fade * contact; cracks[i].color = cc;
                }
                yield return null;
            }
            Destroy(root);
        }

        private void SpawnSkillClarityCrest(PlayerUnit source, Vector2 target, bool ultimate)
        {
            if (source == null) return;
            var fallback = definitions.TryGetValue(source.Archetype, out var definition)
                ? definition.Color : Color.white;
            var style = ResolveCombatSkinVfxStyle(source, source.Archetype, fallback);
            StartCoroutine(SkillClarityCrestRoutine(target, style, source.Archetype, ultimate));
        }

        private IEnumerator SkillClarityCrestRoutine(Vector2 target, CombatSkinVfxStyle style,
            UnitArchetype archetype, bool ultimate)
        {
            var root = TransientBattleEffect.Create($"{archetype} {(ultimate ? "Ultimate" : "Skill")} Clarity Crest");
            root.transform.position = new Vector3(target.x, target.y, -4.46f);
            var core = CreateSpriteChild(root.transform, "Readable Contact Core", GlowSprite,
                Color.Lerp(style.Primary, Color.white, .78f), 1f, ultimate ? 101 : 86);
            var rim = CreateSpriteChild(root.transform, "Readable Contact Rim", CommandRingSprite,
                style.Secondary, 1f, ultimate ? 100 : 85);
            var rayCount = ultimate ? 16 : 10;
            var rays = new SpriteRenderer[rayCount];
            for (var i = 0; i < rays.Length; i++)
                rays[i] = CreateSpriteChild(root.transform, $"Readable Signature Ray {i + 1}", SparkSprite,
                    i % 3 == 0 ? style.Core : i % 2 == 0 ? style.Secondary : style.Primary,
                    1f, ultimate ? 102 : 87);
            var duration = ultimate ? .72f : .48f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                if (root == null || core == null || rim == null || rays.Any(item => item == null)) yield break;
                var t = Mathf.Clamp01(elapsed / duration);
                var burst = 1f - Mathf.Pow(1f - t, 3.2f);
                var fade = 1f - Mathf.SmoothStep(.58f, 1f, t);
                core.transform.localScale = Vector3.one * Mathf.Lerp(ultimate ? .55f : .32f,
                    ultimate ? 3.15f : 1.72f, burst);
                rim.transform.localScale = Vector3.one * Mathf.Lerp(.08f, ultimate ? 3.8f : 2.08f, burst);
                rim.transform.Rotate(0f, 0f, Time.deltaTime * (ultimate ? 320f : 220f));
                var kc = core.color; kc.a = fade * .9f; core.color = kc;
                var rc = rim.color; rc.a = fade; rim.color = rc;
                for (var i = 0; i < rays.Length; i++)
                {
                    var angle = i * Mathf.PI * 2f / rays.Length + (int)archetype * .17f;
                    rays[i].transform.localPosition = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) *
                                                     Mathf.Lerp(.06f, ultimate ? 2.25f : 1.16f, burst);
                    rays[i].transform.localEulerAngles = new Vector3(0f, 0f, angle * Mathf.Rad2Deg);
                    rays[i].transform.localScale = new Vector3(ultimate ? .52f : .34f,
                        ultimate ? .12f : .08f, 1f) * fade;
                    var rayColor = rays[i].color; rayColor.a = fade; rays[i].color = rayColor;
                }
                yield return null;
            }
            Destroy(root);
        }

        private void SpawnLancerDiveEffect(Vector2 origin, Vector2 target, Color color) =>
            StartCoroutine(LancerDiveEffectRoutine(origin, target, color));

        private IEnumerator LancerDiveEffectRoutine(Vector2 origin, Vector2 target, Color color)
        {
            var root = TransientBattleEffect.Create("Emerald Dragon Dive Corridor");
            root.transform.position = new Vector3(0f, 0f, -4.28f);
            var direction = target - origin;
            var length = Mathf.Max(.1f, direction.magnitude);
            direction /= length;
            var angle = Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg;
            var rails = new SpriteRenderer[18];
            for (var i = 0; i < rails.Length; i++)
                rails[i] = CreateSpriteChild(root.transform, $"Emerald Thrust {i + 1}", SparkSprite,
                    i % 3 == 0 ? Color.white : color, 1f, 88 - i % 3);
            var impact = CreateSpriteChild(root.transform, "Emerald Piercing Core", GlowSprite,
                Color.white, 1f, 91);
            const float duration = .62f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                var t = Mathf.Clamp01(elapsed / duration);
                var surge = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(t * 1.7f));
                var fade = 1f - Mathf.SmoothStep(.62f, 1f, t);
                for (var i = 0; i < rails.Length; i++)
                {
                    var along = Mathf.Clamp01(surge - i * .025f);
                    var side = new Vector2(-direction.y, direction.x) *
                               Mathf.Sin(i * 2.399f) * (.08f + i % 3 * .025f);
                    var point = Vector2.Lerp(origin, target, along) + side;
                    rails[i].transform.position = new Vector3(point.x, point.y, -4.3f - i * .001f);
                    rails[i].transform.localEulerAngles = new Vector3(0f, 0f, angle);
                    rails[i].transform.localScale = new Vector3(.42f + i % 3 * .08f, .13f, 1f);
                    var rc = rails[i].color; rc.a = fade * .98f; rails[i].color = rc;
                }
                impact.transform.position = new Vector3(target.x, target.y, -4.35f);
                impact.transform.localScale = Vector3.one * Mathf.Lerp(.35f, 3.6f, Mathf.Sin(t * Mathf.PI));
                var ic = impact.color; ic.a = fade; impact.color = ic;
                yield return null;
            }
            Destroy(root);
        }

        private void SpawnUltimateImpactFlash(Vector2 position, Color color, UnitArchetype archetype,
            PlayerUnit source = null)
        {
            ultimateImpactFlashCount++;
            StartCoroutine(UltimateImpactFlashRoutine(position, color, archetype, source));
        }

        private IEnumerator UltimateImpactFlashRoutine(Vector2 position, Color color,
            UnitArchetype archetype, PlayerUnit source)
        {
            var style = ResolveCombatSkinVfxStyle(source, archetype, color);
            color = style.Primary;
            var root = TransientBattleEffect.Create($"Hero Ultimate Impact {archetype}");
            root.transform.position = new Vector3(position.x, position.y, -4.48f);
            var whiteCore = CreateSpriteChild(root.transform, "Ultimate White Core", GlowSprite,
                Color.white, .25f, 96);
            var colorBloom = CreateSpriteChild(root.transform, "Ultimate Color Bloom", GlowSprite,
                new Color(color.r, color.g, color.b, .94f), .35f, 94);
            var shock = CreateSpriteChild(root.transform, "Ultimate Shock Crest", CommandRingSprite,
                Color.Lerp(color, Color.white, .72f), .18f, 95);
            var secondaryShock = CreateSpriteChild(root.transform, "Ultimate Secondary Crest",
                CommandRingSprite, new Color(style.Secondary.r, style.Secondary.g,
                    style.Secondary.b, .92f), .12f, 93);
            var fieldBloom = CreateSpriteChild(root.transform, "Ultimate Battlefield Bloom", GlowSprite,
                new Color(color.r, color.g, color.b, .58f), .85f, 91);
            var skinSignature = style.Skinned
                ? CreateSpriteChild(root.transform, $"Ultimate Skin {style.Variant} Signature",
                    style.Variant == 1 ? SparkSprite : CommandRingSprite,
                    style.Secondary, .12f, 100)
                : null;
            var motifClass = archetype switch
            {
                UnitArchetype.Tank or UnitArchetype.Melee => EnemyClass.Melee,
                UnitArchetype.Lancer => EnemyClass.Piercer,
                UnitArchetype.Archer or UnitArchetype.Musketeer => EnemyClass.Runner,
                UnitArchetype.Bombardier => EnemyClass.Siege,
                UnitArchetype.Druid => EnemyClass.Shaman,
                _ => EnemyClass.Mage
            };
            var authoredMotif = CreateSpriteChild(root.transform, "Ultimate Authored Motif",
                EnemyVfxMotifFor(motifClass), Color.white, .35f, 99);
            var impactPillar = CreateSpriteChild(root.transform, "Ultimate Impact Pillar", GlowSprite,
                Color.Lerp(color, Color.white, .86f), 1f, 98);
            impactPillar.transform.localScale = new Vector3(.42f, 6.8f, 1f);
            var heavyRays = new SpriteRenderer[8];
            for (var i = 0; i < heavyRays.Length; i++)
            {
                heavyRays[i] = CreateSpriteChild(root.transform, $"Ultimate Heavy Ray {i}", GlowSprite,
                    i % 2 == 0 ? Color.white : Color.Lerp(color, Color.white, .45f), 1f, 98);
                heavyRays[i].transform.localEulerAngles = new Vector3(0f, 0f, i * 45f);
                heavyRays[i].transform.localScale = new Vector3(.15f, .28f, 1f);
            }
            var spokeCount = 40 + (style.Skinned ? style.Variant * 12 : 0);
            var spokes = new SpriteRenderer[spokeCount];
            for (var i = 0; i < spokes.Length; i++)
            {
                var angle = i * 360f / spokes.Length;
                spokes[i] = CreateSpriteChild(root.transform, $"Ultimate Impact Spoke {i}",
                    i % 4 == 0 ? GlowSprite : SparkSprite,
                    i % 3 == 0 ? style.Core : i % 2 == 0 ? style.Secondary : color, .08f, 97);
                spokes[i].transform.localEulerAngles = new Vector3(0f, 0f, angle);
            }
            var aftershocks = new SpriteRenderer[3];
            for (var i = 0; i < aftershocks.Length; i++)
            {
                aftershocks[i] = CreateSpriteChild(root.transform, $"Ultimate Aftershock {i}",
                    CommandRingSprite, i == 1 ? style.Core :
                    new Color(style.Secondary.r, style.Secondary.g, style.Secondary.b, .86f),
                    .08f, 92 - i);
                aftershocks[i].transform.localEulerAngles = new Vector3(0f, 0f, i * 24f);
            }
            RequestCameraImpulse(.128f, .62f, CameraShakePriority.Ultimate);
            const float duration = 1.08f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.unscaledDeltaTime)
            {
                if (root == null || whiteCore == null || colorBloom == null || shock == null ||
                    secondaryShock == null || fieldBloom == null || authoredMotif == null ||
                    impactPillar == null || heavyRays.Any(ray => ray == null) ||
                    spokes.Any(spoke => spoke == null) || aftershocks.Any(aftershock => aftershock == null) ||
                    style.Skinned && skinSignature == null)
                    yield break;
                var t = Mathf.Clamp01(elapsed / duration);
                var burst = 1f - Mathf.Pow(1f - t, 3.6f);
                var fade = 1f - Mathf.SmoothStep(.68f, 1f, t);
                whiteCore.transform.localScale = Vector3.one * Mathf.Lerp(2.05f, .07f, burst);
                colorBloom.transform.localScale = Vector3.one * Mathf.Lerp(.75f, 6.4f, burst);
                fieldBloom.transform.localScale = Vector3.one * Mathf.Lerp(1.2f, 8.2f, burst);
                authoredMotif.transform.localScale = Vector3.one * Mathf.Lerp(.55f, 4.8f, burst);
                authoredMotif.transform.Rotate(0f, 0f, Time.unscaledDeltaTime * 42f);
                shock.transform.localScale = Vector3.one * Mathf.Lerp(.2f, 5.85f, burst);
                secondaryShock.transform.localScale = Vector3.one * Mathf.Lerp(.14f, 4.65f, burst);
                impactPillar.transform.localScale = new Vector3(
                    Mathf.Lerp(.58f, .06f, burst), Mathf.Lerp(7.6f, 3.2f, burst), 1f);
                shock.transform.Rotate(0f, 0f, Time.unscaledDeltaTime * 310f);
                secondaryShock.transform.Rotate(0f, 0f, -Time.unscaledDeltaTime * 390f);
                var wc = whiteCore.color; wc.a = Mathf.Min(1f, fade * 1.25f); whiteCore.color = wc;
                var bc = colorBloom.color; bc.a = fade * .92f; colorBloom.color = bc;
                var fc = fieldBloom.color; fc.a = fade * .58f; fieldBloom.color = fc;
                var am = authoredMotif.color; am.a = Mathf.Min(1f, fade * 1.18f); authoredMotif.color = am;
                var pc = impactPillar.color; pc.a = fade * Mathf.Clamp01(1.35f - t * 1.25f); impactPillar.color = pc;
                var sc = shock.color; sc.a = fade; shock.color = sc;
                var ssc = secondaryShock.color; ssc.a = fade * .86f; secondaryShock.color = ssc;
                if (skinSignature != null)
                {
                    skinSignature.transform.localScale = style.Variant == 1
                        ? new Vector3(Mathf.Lerp(.24f, 5.2f, burst),
                            Mathf.Lerp(.06f, .46f, burst), 1f)
                        : Vector3.one * Mathf.Lerp(.18f, 5.6f, burst);
                    skinSignature.transform.Rotate(0f, 0f,
                        Time.unscaledDeltaTime * (style.Variant == 1 ? -360f : 440f));
                    var signatureColor = style.Secondary;
                    signatureColor.a = fade * .94f;
                    skinSignature.color = signatureColor;
                }
                for (var i = 0; i < heavyRays.Length; i++)
                {
                    var stagger = Mathf.Clamp01((t - i * .012f) / .34f);
                    heavyRays[i].transform.localScale = new Vector3(
                        Mathf.Lerp(.18f, .055f, burst), Mathf.Lerp(.28f, 4.15f + i % 2 * .8f, stagger), 1f);
                    var hc = heavyRays[i].color;
                    hc.a = fade * Mathf.Clamp01(1.2f - t * .75f);
                    heavyRays[i].color = hc;
                }
                for (var i = 0; i < aftershocks.Length; i++)
                {
                    var delayed = Mathf.Clamp01((t - i * .075f) / Mathf.Max(.01f, 1f - i * .075f));
                    var afterBurst = 1f - Mathf.Pow(1f - delayed, 3.1f);
                    aftershocks[i].transform.localScale = Vector3.one *
                                                          Mathf.Lerp(.08f, 6.25f + i * .82f, afterBurst);
                    aftershocks[i].transform.Rotate(0f, 0f,
                        Time.unscaledDeltaTime * (i % 2 == 0 ? 230f : -270f));
                    var ac = aftershocks[i].color;
                    ac.a = (1f - delayed) * (.78f - i * .12f);
                    aftershocks[i].color = ac;
                }
                for (var i = 0; i < spokes.Length; i++)
                {
                    var angle = i * Mathf.PI * 2f / spokes.Length + t * (i % 2 == 0 ? .55f : -.38f);
                    var distance = Mathf.Lerp(.08f, 3.45f + i % 5 * .2f, burst);
                    spokes[i].transform.localPosition =
                        new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * distance;
                    spokes[i].transform.localScale = new Vector3(
                        Mathf.Lerp(.22f, .025f, t), Mathf.Lerp(.5f, .045f, t), 1f);
                    var c = spokes[i].color; c.a = fade; spokes[i].color = c;
                }
                yield return null;
            }
            Destroy(root);
        }

        public void SpawnBossSignatureEffect(Vector2 position, Color color, float radius, int pattern)
        {
            bossSignatureEffectCount++;
            StartCoroutine(SignatureBurstRoutine(position, color, radius, pattern));
        }

        private IEnumerator HeroSkillSpectacleRoutine(Vector2 source, Vector2 target, UnitArchetype archetype,
            Color primary, Color secondary, bool ultimate, int skinVariant = 0)
        {
            var root = TransientBattleEffect.Create(ultimate ? "Hero Ultimate Spectacle" : "Hero Skill Spectacle");
            root.transform.position = new Vector3(target.x, target.y, -4.35f);
            var origin = new GameObject("Hero Casting Crest").transform;
            origin.SetParent(root.transform, false);
            origin.position = new Vector3(source.x, source.y, -4.34f);

            var ringCount = (ultimate ? 10 : 5) + (skinVariant > 0 ? skinVariant + 1 : 0);
            var rings = new SpriteRenderer[ringCount];
            for (var i = 0; i < ringCount; i++)
            {
                rings[i] = CreateSpriteChild(root.transform, $"Royal Ring {i}", CommandRingSprite,
                    i % 3 == 0 && skinVariant > 0 ? Color.Lerp(secondary, Color.white, .34f) :
                    i % 2 == 0 ? secondary : Color.Lerp(primary, Color.white, .62f),
                    .12f + i * .045f, 72 + i);
                rings[i].transform.localEulerAngles = new Vector3(0f, 0f, i * 27f);
            }
            var core = CreateSpriteChild(root.transform, "Prismatic Impact Core", GlowSprite,
                Color.Lerp(secondary, Color.white, .58f), .24f, 80);
            var originRing = CreateSpriteChild(origin, "Sovereign Casting Ring", CommandRingSprite,
                Color.Lerp(primary, Color.white, .7f), .2f, 78);
            var originGlow = CreateSpriteChild(origin, "Sovereign Casting Glow", GlowSprite,
                new Color(primary.r, primary.g, primary.b, .62f), .32f, 76);
            var skinSignature = skinVariant > 0
                ? CreateSpriteChild(root.transform,
                    $"{(ultimate ? "Ultimate" : "Skill")} Skin {skinVariant} Signature",
                    skinVariant == 1 ? SparkSprite : CommandRingSprite,
                    secondary, .1f, 84)
                : null;

            var rayCount = (ultimate ? 32 : 14) + (skinVariant > 0 ? skinVariant * 6 : 0);
            var rays = new SpriteRenderer[rayCount];
            for (var i = 0; i < rays.Length; i++)
            {
                var angle = i * Mathf.PI * 2f / rays.Length;
                rays[i] = CreateSpriteChild(root.transform, $"Crown Burst {i}", SparkSprite,
                    i % 3 == 0 ? Color.white : i % 2 == 0 ? primary : secondary, 1f, 79);
                rays[i].transform.localEulerAngles = new Vector3(0f, 0f, angle * Mathf.Rad2Deg);
                rays[i].transform.localScale = Vector3.one * (ultimate ? .24f : .14f);
            }

            var sparkCount = (ultimate ? 88 : 34) + (skinVariant > 0 ? skinVariant * 12 : 0);
            var sparks = new SpriteRenderer[sparkCount];
            var sparkAngles = new float[sparkCount];
            for (var i = 0; i < sparks.Length; i++)
            {
                sparkAngles[i] = i * Mathf.PI * 2f / sparks.Length;
                sparks[i] = CreateSpriteChild(root.transform, $"Prismatic Spark {i}",
                    i % 4 == 0 ? GlowSprite : SparkSprite,
                    i % 3 == 0 ? Color.white : i % 2 == 0 ? secondary : primary,
                    i % 4 == 0 ? .095f : .055f + (i % 3) * .012f, 82);
            }

            var trailCount = ultimate ? 34 : 18;
            var trail = new SpriteRenderer[trailCount];
            for (var i = 0; i < trail.Length; i++)
                trail[i] = CreateSpriteChild(root.transform, $"Royal Trail {i}", GlowSprite,
                    Color.Lerp(primary, Color.white, i / (float)Mathf.Max(1, trail.Length - 1)),
                    .075f + (trail.Length - i) * .004f, 75 + i % 3);

            var closeCombat = archetype is UnitArchetype.Tank or UnitArchetype.Melee or UnitArchetype.Lancer;
            var magicOrbit = archetype is UnitArchetype.AreaMage or UnitArchetype.SingleMage or
                UnitArchetype.Druid or UnitArchetype.Oracle;
            var duration = ultimate ? 1.38f : .78f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                // Round cleanup, death and QA teardown may remove transient roots while this
                // spectacle is mid-flight. Treat that as a normal cancellation, not as a frame
                // of access through Unity's destroyed-object proxy.
                if (root == null || origin == null || core == null || originRing == null ||
                    originGlow == null || skinVariant > 0 && skinSignature == null) yield break;
                var t = Mathf.Clamp01(elapsed / duration);
                var burst = 1f - Mathf.Pow(1f - t, 3f);
                var fade = 1f - Mathf.SmoothStep(.62f, 1f, t);
                var pulse = 1f + Mathf.Sin(t * Mathf.PI * (ultimate ? 10f : 7f)) * .12f;
                for (var i = 0; i < rings.Length; i++)
                {
                    var scale = Mathf.Lerp(.12f + i * .05f,
                        (ultimate ? 3.75f : 1.75f) * (1f - i * .045f), burst) * pulse;
                    rings[i].transform.localScale = Vector3.one * scale;
                    rings[i].transform.Rotate(0f, 0f,
                        Time.deltaTime * (i % 2 == 0 ? 180f + i * 22f : -210f - i * 18f));
                    var color = rings[i].color; color.a = fade * (.9f - i * .08f); rings[i].color = color;
                }
                core.transform.localScale = Vector3.one *
                                            (Mathf.Lerp(ultimate ? .72f : .52f, .06f, burst) * pulse);
                var coreColor = core.color; coreColor.a = fade; core.color = coreColor;
                originRing.transform.localScale = Vector3.one *
                                                  Mathf.Lerp(.2f, ultimate ? 2.85f : 1.36f, burst);
                originRing.transform.Rotate(0f, 0f, Time.deltaTime * 240f);
                originGlow.transform.localScale = Vector3.one *
                                                  Mathf.Lerp(.3f, ultimate ? 2.35f : 1.05f, Mathf.Sin(t * Mathf.PI));
                var oc = originRing.color; oc.a = fade; originRing.color = oc;
                var og = originGlow.color; og.a = .62f * fade; originGlow.color = og;
                if (skinSignature != null)
                {
                    skinSignature.transform.localScale = skinVariant == 1
                        ? new Vector3(Mathf.Lerp(.12f, ultimate ? 3.8f : 1.9f, burst),
                            Mathf.Lerp(.035f, ultimate ? .42f : .22f, burst), 1f)
                        : Vector3.one * Mathf.Lerp(.12f, ultimate ? 4.15f : 2.05f, burst);
                    skinSignature.transform.Rotate(0f, 0f,
                        Time.deltaTime * (skinVariant == 1 ? -300f : 380f));
                    var signatureColor = secondary;
                    signatureColor.a = fade * .92f;
                    skinSignature.color = signatureColor;
                }

                for (var i = 0; i < rays.Length; i++)
                {
                    var skinSpin = skinVariant == 1 ? -.82f : skinVariant == 2 ? 1.35f : 1f;
                    var angle = i * Mathf.PI * 2f / rays.Length +
                                t * (magicOrbit ? 2.4f : .75f) * skinSpin;
                    var rayRadius = Mathf.Lerp(.05f, ultimate ? 1.22f : .78f, burst);
                    rays[i].transform.localPosition = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * rayRadius;
                    var burstScale = Mathf.Lerp(.08f, ultimate ? .44f : .28f,
                        Mathf.Sin(t * Mathf.PI)) * fade;
                    rays[i].transform.localScale = Vector3.one * burstScale;
                    var rc = rays[i].color; rc.a = fade * .88f; rays[i].color = rc;
                }

                for (var i = 0; i < sparks.Length; i++)
                {
                    var spiral = sparkAngles[i] + t * (magicOrbit ? 7.2f : 4.4f) * (i % 2 == 0 ? 1f : -1f);
                    var distance = Mathf.Lerp(.08f, (ultimate ? 2.35f : 1.45f) * (.72f + i % 5 * .07f), burst);
                    var height = Mathf.Sin(t * Mathf.PI) * (closeCombat ? .32f : .58f);
                    sparks[i].transform.localPosition =
                        new Vector2(Mathf.Cos(spiral) * distance, Mathf.Sin(spiral) * distance + height);
                    sparks[i].transform.Rotate(0f, 0f, Time.deltaTime * (i % 2 == 0 ? 320f : -280f));
                    var sc = sparks[i].color; sc.a = fade; sparks[i].color = sc;
                }

                for (var i = 0; i < trail.Length; i++)
                {
                    var localT = Mathf.Clamp01(t * 1.5f - i * .025f);
                    var point = Vector2.Lerp(source, target, localT);
                    var wave = new Vector2(-.0f, Mathf.Sin(localT * Mathf.PI * 3f + i) *
                                                  (magicOrbit ? .18f : .07f));
                    trail[i].transform.position = new Vector3(point.x + wave.x, point.y + wave.y, -4.31f);
                    var tc = trail[i].color; tc.a = fade * Mathf.Sin(localT * Mathf.PI); trail[i].color = tc;
                }
                yield return null;
            }
            Destroy(root);
        }

        private IEnumerator SignatureBurstRoutine(Vector2 position, Color color, float radius, int pattern)
        {
            var root = TransientBattleEffect.Create($"Boss Signature {pattern}");
            root.transform.position = new Vector3(position.x, position.y, -4.28f);
            var outer = CreateSpriteChild(root.transform, "Boss Sigil Outer", CommandRingSprite,
                Color.Lerp(color, Color.white, .35f), .16f, 66);
            var inner = CreateSpriteChild(root.transform, "Boss Sigil Inner", CommandRingSprite,
                color, .11f, 67);
            var core = CreateSpriteChild(root.transform, "Boss Sigil Core", GlowSprite,
                new Color(color.r, color.g, color.b, .72f), .24f, 65);
            var count = 30 + pattern * 4;
            var motes = new SpriteRenderer[count];
            for (var i = 0; i < motes.Length; i++)
                motes[i] = CreateSpriteChild(root.transform, $"Boss Rune {i}",
                    i % 3 == 0 ? SparkSprite : GlowSprite,
                    i % 4 == 0 ? Color.white : color, i % 3 == 0 ? .07f : .045f, 69);
            const float duration = 1.06f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                var t = Mathf.Clamp01(elapsed / duration);
                var burst = 1f - Mathf.Pow(1f - t, 3f);
                var fade = 1f - t;
                outer.transform.localScale = Vector3.one * Mathf.Lerp(.18f, radius * 3.55f, burst);
                inner.transform.localScale = Vector3.one * Mathf.Lerp(.13f, radius * 2.62f, burst);
                core.transform.localScale = Vector3.one * Mathf.Lerp(radius * 1.42f, .05f, burst);
                outer.transform.Rotate(0f, 0f, Time.deltaTime * (150f + pattern * 24f));
                inner.transform.Rotate(0f, 0f, -Time.deltaTime * (205f + pattern * 18f));
                var oc = outer.color; oc.a = fade; outer.color = oc;
                var ic = inner.color; ic.a = fade * .86f; inner.color = ic;
                var cc = core.color; cc.a = fade * .72f; core.color = cc;
                for (var i = 0; i < motes.Length; i++)
                {
                    var angle = i * Mathf.PI * 2f / motes.Length +
                                t * (3.4f + pattern * .55f) * (i % 2 == 0 ? 1f : -1f);
                    var spread = Mathf.Lerp(.08f, radius * (.68f + i % 4 * .12f), burst);
                    motes[i].transform.localPosition =
                        new Vector2(Mathf.Cos(angle) * spread, Mathf.Sin(angle) * spread) +
                        Vector2.up * Mathf.Sin(t * Mathf.PI) * .38f;
                    motes[i].transform.Rotate(0f, 0f, Time.deltaTime * 260f);
                    var mc = motes[i].color; mc.a = fade; motes[i].color = mc;
                }
                yield return null;
            }
            Destroy(root);
        }

        private void SpawnMoveCommandPing(Vector2 position, int unitCount)
        {
            StartCoroutine(MoveCommandPingRoutine(position, Mathf.Clamp(unitCount, 1, 8)));
        }

        private IEnumerator MoveCommandPingRoutine(Vector2 position, int unitCount)
        {
            var effect = TransientBattleEffect.Create("Move Command Ping");
            effect.transform.position = new Vector3(position.x, position.y, -4.25f);
            var primary = new Color(.05f, .96f, 1f, 1f);
            var secondary = new Color(.84f, 1f, 1f, .96f);
            var plate = CreateSpriteChild(effect.transform, "Destination Ground Plate",
                CircleSprite, new Color(.02f, .82f, 1f, .34f), 1f, 77);
            var halo = CreateSpriteChild(effect.transform, "Destination Halo",
                GlowSprite, new Color(.02f, .82f, 1f, .68f), 1f, 78);
            var outer = CreateSpriteChild(effect.transform, "Destination Ring Outer",
                CommandRingSprite, primary, 1f, 81);
            var inner = CreateSpriteChild(effect.transform, "Destination Ring Inner",
                CommandRingSprite, secondary, 1f, 82);
            var echo = CreateSpriteChild(effect.transform, "Destination Echo",
                CommandRingSprite, new Color(.18f, .7f, 1f, .8f), 1f, 79);
            var confirm = CreateSpriteChild(effect.transform, "Destination Diamond",
                SparkSprite, Color.white, 1f, 84);
            confirm.transform.localEulerAngles = new Vector3(0f, 0f, 45f);
            var crossA = CreateSpriteChild(effect.transform, "Destination Cross Horizontal",
                SquareSprite, Color.white, 1f, 85);
            var crossB = CreateSpriteChild(effect.transform, "Destination Cross Vertical",
                SquareSprite, Color.white, 1f, 85);

            var chevrons = new SpriteRenderer[4];
            for (var i = 0; i < chevrons.Length; i++)
            {
                chevrons[i] = CreateSpriteChild(effect.transform, $"Destination Bracket {i + 1}",
                    SparkSprite, i % 2 == 0 ? primary : secondary, .16f, 83);
                chevrons[i].transform.localEulerAngles = new Vector3(0f, 0f, i * 90f + 45f);
            }
            var ticks = new SpriteRenderer[12];
            for (var i = 0; i < ticks.Length; i++)
                ticks[i] = CreateSpriteChild(effect.transform, $"Destination Tick {i + 1}",
                    SquareSprite, i % 3 == 0 ? Color.white : primary, 1f, 86);

            var sizeBoost = Mathf.Clamp01((unitCount - 1f) / 7f) * .2f;
            const float duration = .92f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.unscaledDeltaTime)
            {
                var t = Mathf.Clamp01(elapsed / duration);
                var firstWave = Mathf.Repeat(t * 1.6f, 1f);
                var ease = 1f - Mathf.Pow(1f - firstWave, 3f);
                var fade = 1f - Mathf.SmoothStep(.62f, 1f, t);
                outer.transform.localScale = new Vector3(
                    Mathf.Lerp(.42f, 1.62f + sizeBoost, ease),
                    Mathf.Lerp(.24f, .88f + sizeBoost * .55f, ease), 1f);
                inner.transform.localScale = new Vector3(
                    .96f + sizeBoost * .45f + Mathf.Sin(t * Mathf.PI * 6f) * .055f,
                    .52f + sizeBoost * .25f + Mathf.Sin(t * Mathf.PI * 6f) * .03f, 1f);
                echo.transform.localScale = new Vector3(
                    Mathf.Lerp(.3f, 1.26f + sizeBoost, t),
                    Mathf.Lerp(.17f, .69f + sizeBoost * .5f, t), 1f);
                halo.transform.localScale = new Vector3(
                    1.42f + sizeBoost + Mathf.Sin(t * Mathf.PI * 5f) * .11f,
                    .76f + sizeBoost * .5f + Mathf.Sin(t * Mathf.PI * 5f) * .06f, 1f);
                plate.transform.localScale = new Vector3(
                    .72f + sizeBoost * .35f + Mathf.Sin(t * Mathf.PI * 6f) * .04f,
                    .39f + sizeBoost * .2f + Mathf.Sin(t * Mathf.PI * 6f) * .022f, 1f);
                var outerColor = primary;
                outerColor.a = (.82f - firstWave * .34f) * fade;
                outer.color = outerColor;
                var innerColor = secondary;
                innerColor.a = (.72f + Mathf.Sin(t * Mathf.PI * 6f) * .22f) * fade;
                inner.color = innerColor;
                var echoColor = echo.color;
                echoColor.a = .54f * (1f - t) * fade;
                echo.color = echoColor;
                var haloColor = halo.color;
                haloColor.a = (.5f + Mathf.Sin(t * Mathf.PI * 5f) * .16f) * fade;
                halo.color = haloColor;
                var plateColor = plate.color;
                plateColor.a = (.24f + Mathf.Sin(t * Mathf.PI * 6f) * .08f) * fade;
                plate.color = plateColor;

                var confirmPulse = .19f + Mathf.Sin(t * Mathf.PI * 7f) * .035f;
                confirm.transform.localScale = Vector3.one * confirmPulse;
                confirm.transform.Rotate(0f, 0f, Time.unscaledDeltaTime * 110f);
                var confirmColor = Color.white;
                confirmColor.a = fade;
                confirm.color = confirmColor;
                var crossPulse = 1f + Mathf.Sin(t * Mathf.PI * 7f) * .16f;
                crossA.transform.localScale = new Vector3(.2f * crossPulse, .028f, 1f);
                crossB.transform.localScale = new Vector3(.028f, .2f * crossPulse, 1f);
                var crossColor = Color.white;
                crossColor.a = .88f * fade;
                crossA.color = crossColor;
                crossB.color = crossColor;
                for (var i = 0; i < chevrons.Length; i++)
                {
                    var angle = i * Mathf.PI * .5f;
                    var bracketRadius = Mathf.Lerp(.72f + sizeBoost * .4f, .48f + sizeBoost * .24f,
                        .5f + Mathf.Sin(t * Mathf.PI * 4f) * .5f);
                    chevrons[i].transform.localPosition = new Vector3(
                        Mathf.Cos(angle) * bracketRadius,
                        Mathf.Sin(angle) * bracketRadius * .56f, 0f);
                    var bracketColor = i % 2 == 0 ? primary : secondary;
                    bracketColor.a = (.72f + Mathf.Sin(t * Mathf.PI * 6f + i) * .2f) * fade;
                    chevrons[i].color = bracketColor;
                }
                for (var i = 0; i < ticks.Length; i++)
                {
                    var angle = i * Mathf.PI * 2f / ticks.Length + t * .34f;
                    ticks[i].transform.localPosition = new Vector3(
                        Mathf.Cos(angle) * (.61f + sizeBoost * .35f),
                        Mathf.Sin(angle) * (.34f + sizeBoost * .18f), 0f);
                    ticks[i].transform.localEulerAngles = new Vector3(0f, 0f,
                        angle * Mathf.Rad2Deg + 90f);
                    ticks[i].transform.localScale = new Vector3(
                        i % 3 == 0 ? .15f : .1f, i % 3 == 0 ? .038f : .025f, 1f);
                    var tickColor = i % 3 == 0 ? Color.white : primary;
                    tickColor.a = (.68f + Mathf.Sin(t * Mathf.PI * 6f + i * .5f) * .22f) * fade;
                    ticks[i].color = tickColor;
                }
                yield return null;
            }
            Destroy(effect);
        }

        private IEnumerator EnemySlamRoutine(Vector2 position, float radius, Color color)
        {
            var effect = TransientBattleEffect.Create("Enemy Ground Slam");
            effect.transform.position = new Vector3(position.x, position.y - .04f, -3.65f);
            var dustColor = Color.Lerp(color, new Color(.55f, .34f, .16f), .48f);
            dustColor.a = .4f;
            var ring = CreateSpriteChild(effect.transform, "Shock Ring", CommandRingSprite, dustColor, .18f, 18);
            var ringEdge = CreateSpriteChild(effect.transform, "White Pressure Edge", CommandRingSprite,
                new Color(1f, .92f, .78f, .54f), .12f, 20);
            var core = CreateSpriteChild(effect.transform, "Slam Core", GlowSprite,
                Color.Lerp(color, Color.white, .45f), .12f, 21);
            const int shardCount = 10;
            var shards = new SpriteRenderer[shardCount];
            var cracks = new SpriteRenderer[shardCount];
            var directions = new Vector2[shardCount];
            for (var i = 0; i < shardCount; i++)
            {
                var angle = i * Mathf.PI * 2f / shardCount + UnityEngine.Random.Range(-.14f, .14f);
                directions[i] = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle));
                shards[i] = CreateSpriteChild(effect.transform, "Slam Debris", SparkSprite,
                    i % 2 == 0 ? dustColor : color, .07f, 22);
                shards[i].transform.localEulerAngles = new Vector3(0f, 0f, angle * Mathf.Rad2Deg + 35f);
                cracks[i] = CreateSpriteChild(effect.transform, "Ground Crack", SquareSprite,
                    new Color(.72f, .25f, .07f, .42f), 1f, 17);
                cracks[i].transform.localEulerAngles = new Vector3(0f, 0f, angle * Mathf.Rad2Deg);
            }
            RequestCameraImpulse(Mathf.Min(.064f, radius * .034f), .30f,
                CameraShakePriority.Heavy);
            const float duration = .34f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                var t = Mathf.Clamp01(elapsed / duration);
                var expand = 1f - Mathf.Pow(1f - t, 3f);
                ring.transform.localScale = Vector3.one * Mathf.Lerp(.15f, radius * 2.75f, expand);
                ringEdge.transform.localScale = Vector3.one * Mathf.Lerp(.1f, radius * 2.35f, expand);
                core.transform.localScale = Vector3.one * Mathf.Lerp(radius * .38f, .02f, expand);
                var rc = ring.color; rc.a = .4f * (1f - t); ring.color = rc;
                var re = ringEdge.color; re.a = .54f * Mathf.Pow(1f - t, 1.6f); ringEdge.color = re;
                var cc = core.color; cc.a = .85f * (1f - t); core.color = cc;
                for (var i = 0; i < shards.Length; i++)
                {
                    shards[i].transform.localPosition = directions[i] * Mathf.Lerp(.05f, radius * 1.15f, expand)
                        + Vector2.up * Mathf.Sin(t * Mathf.PI) * .16f;
                    var shardColor = shards[i].color; shardColor.a = .78f * (1f - t); shards[i].color = shardColor;
                    cracks[i].transform.localPosition = directions[i] * radius * .32f * expand;
                    cracks[i].transform.localScale = new Vector3(radius * Mathf.Lerp(.06f, .58f, expand),
                        Mathf.Lerp(.028f, .009f, t), 1f);
                    var crackColor = cracks[i].color; crackColor.a = .42f * Mathf.Pow(1f - t, .7f); cracks[i].color = crackColor;
                }
                yield return null;
            }
            Destroy(effect);
        }

        private IEnumerator AttackCueRoutine(Vector2 position, UnitArchetype archetype, Color color,
            PlayerUnit source)
        {
            var style = ResolveCombatSkinVfxStyle(source, archetype, color);
            color = style.Primary;
            var effect = TransientBattleEffect.Create($"{archetype} Attack Cue");
            effect.transform.position = new Vector3(position.x, position.y, -3.5f);
            var glowColor = color;
            var magicCaster = archetype is UnitArchetype.AreaMage or UnitArchetype.SingleMage or
                UnitArchetype.Druid or UnitArchetype.Oracle;
            glowColor.a = magicCaster ? .48f : .3f;
            var glow = CreateSpriteChild(effect.transform, "Windup Glow", GlowSprite, glowColor, .18f, 18);
            var focusRing = CreateSpriteChild(effect.transform, "Windup Focus Ring", CommandRingSprite,
                new Color(style.Secondary.r, style.Secondary.g, style.Secondary.b,
                    magicCaster ? .72f : .42f), .2f, 19);
            var runes = new SpriteRenderer[(magicCaster ? 8 : 4) + (style.Skinned ? style.Variant + 2 : 0)];
            for (var i = 0; i < runes.Length; i++)
            {
                runes[i] = CreateSpriteChild(effect.transform,
                    style.Skinned ? $"Skin {style.Variant} Windup Signature {i}" :
                    magicCaster ? $"Windup Rune {i}" : $"Weapon Glint {i}",
                    style.Skinned && style.Variant == 2 && i % 3 == 0 ? CommandRingSprite : SparkSprite,
                    i % 3 == 0 ? style.Core : i % 2 == 0 ? style.Secondary : color, .075f, 20);
                runes[i].transform.localEulerAngles = new Vector3(0f, 0f, i * 45f);
            }
            var duration = magicCaster ? .32f : .22f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                if (effect == null || glow == null || focusRing == null ||
                    runes.Any(rune => rune == null)) yield break;
                var t = Mathf.Clamp01(elapsed / duration);
                var pulse = Mathf.Sin(t * Mathf.PI);
                var scale = archetype is UnitArchetype.AreaMage or UnitArchetype.Druid or UnitArchetype.Oracle
                    ? 1.65f : 1.05f;
                glow.transform.localScale = Vector3.one * Mathf.Lerp(.35f, scale, t);
                focusRing.transform.localScale = Vector3.one * Mathf.Lerp(scale * 1.05f, .22f, t);
                focusRing.transform.Rotate(0f, 0f, Time.deltaTime * (magicCaster ? 210f : 90f));
                var c = glowColor;
                c.a = glowColor.a * pulse;
                glow.color = c;
                var fc = focusRing.color; fc.a = (magicCaster ? .72f : .42f) * pulse; focusRing.color = fc;
                for (var i = 0; i < runes.Length; i++)
                {
                    var spin = style.Skinned && style.Variant == 1 ? -1f : 1f;
                    var angle = i * Mathf.PI * 2f / runes.Length + t * Mathf.PI * spin;
                    runes[i].transform.localPosition = new Vector3(Mathf.Cos(angle), Mathf.Sin(angle), 0f) *
                                                       Mathf.Lerp(scale * .58f, .12f, t);
                    var runeColor = runes[i].color; runeColor.a = pulse; runes[i].color = runeColor;
                }
                yield return null;
            }
            Destroy(effect);
        }

        private readonly struct CombatSkinVfxStyle
        {
            public readonly Color Primary;
            public readonly Color Secondary;
            public readonly Color Core;
            public readonly int Variant;
            public readonly bool Skinned;

            public CombatSkinVfxStyle(Color primary, Color secondary, Color core, int variant, bool skinned)
            {
                Primary = primary;
                Secondary = secondary;
                Core = core;
                Variant = variant;
                Skinned = skinned;
            }
        }

        private CombatSkinVfxStyle ResolveCombatSkinVfxStyle(PlayerUnit source,
            UnitArchetype archetype, Color fallback)
        {
            var variant = source != null ? source.SkinVariant : 0;
            var primary = fallback;
            var secondary = Color.Lerp(fallback, Color.white, .72f);
            if (variant > 0)
            {
                var skinPrimary = GetUnitSkinAccent(archetype);
                var skinSecondary = GetUnitSkinSecondary(archetype);
                if (skinPrimary.a > .01f) primary = skinPrimary;
                if (skinSecondary.a > .01f) secondary = skinSecondary;
            }
            primary.a = secondary.a = 1f;
            var core = variant switch
            {
                1 => Color.Lerp(secondary, Color.white, .34f),
                2 => Color.Lerp(primary, Color.white, .84f),
                _ => Color.Lerp(primary, Color.white, .72f)
            };
            core.a = 1f;
            return new CombatSkinVfxStyle(primary, secondary, core, variant, variant > 0);
        }

        private (Color primary, Color secondary, bool skinned) ResolveCombatVfxPalette(
            PlayerUnit source, UnitArchetype archetype, Color fallback)
        {
            var style = ResolveCombatSkinVfxStyle(source, archetype, fallback);
            return (style.Primary, style.Secondary, style.Skinned);
        }

        private static bool IsDirectionalCombatVfx(UnitArchetype archetype, CombatVfxTier tier)
        {
            // V4 atlases contain localized contact art only. Projectile flight and source-side
            // weapon trails own direction; rotating contact paintings made their ground plane and
            // highlights point away from the victim (the floating crescent regression).
            return false;
        }

        private static float CombatVfxDuration(UnitArchetype archetype, CombatVfxTier tier)
        {
            if (tier == CombatVfxTier.Ultimate) return archetype == UnitArchetype.Archer ? 1.18f : 1.22f;
            if (tier == CombatVfxTier.Skill)
                return archetype is UnitArchetype.Lancer or UnitArchetype.Archer or UnitArchetype.Musketeer
                    ? .82f : .94f;
            return archetype is UnitArchetype.Lancer or UnitArchetype.Archer or UnitArchetype.Musketeer
                ? .42f : archetype is UnitArchetype.AreaMage or UnitArchetype.Druid or UnitArchetype.Oracle
                    ? .52f : .46f;
        }

        private static float CombatVfxPeakAlpha(UnitArchetype archetype, CombatVfxTier tier)
        {
            var baseAlpha = tier switch
            {
                CombatVfxTier.Ultimate => 1f,
                CombatVfxTier.Skill => .99f,
                _ => .88f
            };
            if (tier == CombatVfxTier.Basic && archetype == UnitArchetype.AreaMage) return .7f;
            if (tier == CombatVfxTier.Basic && archetype is UnitArchetype.Druid or UnitArchetype.Oracle)
                return .82f;
            if (tier == CombatVfxTier.Basic && archetype is UnitArchetype.Tank or UnitArchetype.Melee or
                    UnitArchetype.Lancer or UnitArchetype.Archer or UnitArchetype.Musketeer)
                return .93f;
            return baseAlpha;
        }

        private static float CombatVfxRoleScale(UnitArchetype archetype, CombatVfxTier tier)
        {
            if (tier == CombatVfxTier.Basic)
                return archetype switch
                {
                    UnitArchetype.AreaMage => .66f,
                    UnitArchetype.Druid or UnitArchetype.Oracle => .86f,
                    UnitArchetype.Tank or UnitArchetype.Melee => 1.16f,
                    UnitArchetype.Lancer or UnitArchetype.Archer or UnitArchetype.Musketeer => 1.12f,
                    UnitArchetype.SingleMage => 1.02f,
                    _ => .96f
                };
            return archetype is UnitArchetype.AreaMage or UnitArchetype.Druid or UnitArchetype.Oracle
                ? 1.08f : archetype == UnitArchetype.SingleMage ? .98f : 1f;
        }

        private static float CombatVfxTierScale(CombatVfxTier tier) => tier switch
        {
            CombatVfxTier.Ultimate => 2.72f,
            CombatVfxTier.Skill => 1.72f,
            _ => 1.04f
        };

        private IEnumerator ImpactRoutine(Vector2 position, Color color, UnitArchetype archetype, float radius,
            Vector2 incomingDirection, CombatVfxTier tier, PlayerUnit source)
        {
            var effect = TransientBattleEffect.Create($"{archetype} {tier} VFX Animation");
            effect.transform.position = new Vector3(position.x, position.y, -3.56f);
            var direction = incomingDirection.sqrMagnitude > .001f ? incomingDirection.normalized : Vector2.right;
            if (IsDirectionalCombatVfx(archetype, tier))
                effect.transform.localEulerAngles = new Vector3(0f, 0f,
                    Mathf.Atan2(direction.y, direction.x) * Mathf.Rad2Deg);

            var frames = CombatVfxAnimationFor(archetype, tier);
            if (frames.Length == 0)
                frames = Enumerable.Repeat(SparkSprite, CombatVfxFrameCount).ToArray();

            var style = ResolveCombatSkinVfxStyle(source, archetype, color);
            var tintStrength = style.Skinned
                ? tier == CombatVfxTier.Basic ? .68f : tier == CombatVfxTier.Skill ? .78f : .86f
                : .08f;
            var frameTint = Color.Lerp(Color.white, style.Primary, tintStrength);
            frameTint.a = 0f;
            var frameA = CreateSpriteChild(effect.transform, "Animated Impact Frame A",
                frames[0], frameTint, 1f, 59);
            var frameB = CreateSpriteChild(effect.transform, "Animated Impact Frame B",
                frames[Mathf.Min(1, frames.Length - 1)], frameTint, 1f, 60);
            var clarityCore = tier == CombatVfxTier.Basic ? null :
                CreateSpriteChild(effect.transform, $"{tier} White Contact Core", GlowSprite,
                    new Color(1f, 1f, 1f, 0f), 1f, 66);
            var clarityRing = tier == CombatVfxTier.Basic ? null :
                CreateSpriteChild(effect.transform, $"{tier} Readability Ring", CommandRingSprite,
                    new Color(style.Core.r, style.Core.g, style.Core.b, 0f), 1f, 65);

            SpriteRenderer skinEcho = null;
            if (style.Skinned)
                skinEcho = CreateSpriteChild(effect.transform, "Skin Palette Secondary Echo", GlowSprite,
                    new Color(style.Secondary.r, style.Secondary.g, style.Secondary.b, 0f), 1f, 54);

            var signatureCount = !style.Skinned ? 0 : tier switch
            {
                CombatVfxTier.Ultimate => style.Variant == 1 ? 12 : 16,
                CombatVfxTier.Skill => style.Variant == 1 ? 7 : 9,
                _ => style.Variant == 1 ? 4 : 6
            };
            var skinSignatures = new SpriteRenderer[signatureCount];
            for (var i = 0; i < skinSignatures.Length; i++)
            {
                var signatureSprite = style.Variant == 1 || i % 3 != 0 ? SparkSprite : CommandRingSprite;
                var signatureColor = i % 3 == 0 ? style.Core : i % 2 == 0
                    ? style.Secondary : style.Primary;
                signatureColor.a = 0f;
                skinSignatures[i] = CreateSpriteChild(effect.transform,
                    $"Skin VFX {tier} V{style.Variant} Signature {i + 1}", signatureSprite,
                    signatureColor, .08f, 63 + i % 3);
                skinSignatures[i].transform.localEulerAngles = new Vector3(0f, 0f,
                    i * 360f / Mathf.Max(1, signatureCount) + (style.Variant == 1 ? 45f : 0f));
            }

            var tierScale = CombatVfxTierScale(tier);
            var roleScale = CombatVfxRoleScale(archetype, tier);
            var targetScale = Mathf.Max(.32f, radius * tierScale * roleScale);
            var duration = CombatVfxDuration(archetype, tier);
            var peakAlpha = CombatVfxPeakAlpha(archetype, tier);

            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                if (effect == null || frameA == null || frameB == null) yield break;
                var t = Mathf.Clamp01(elapsed / duration);
                var framePosition = t * (frames.Length - 1);
                var frameIndex = Mathf.Min(frames.Length - 1, Mathf.FloorToInt(framePosition));
                var nextIndex = Mathf.Min(frames.Length - 1, frameIndex + 1);
                var frameBlend = Mathf.SmoothStep(0f, 1f, framePosition - frameIndex);
                frameA.sprite = frames[frameIndex];
                frameB.sprite = frames[nextIndex];

                var fadeIn = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(t / .09f));
                var fadeOut = 1f - Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((t - .7f) / .3f));
                var opacity = peakAlpha * fadeIn * fadeOut;
                var aColor = frameTint;
                aColor.a = opacity * (nextIndex == frameIndex ? 1f : 1f - frameBlend);
                frameA.color = aColor;
                var bColor = frameTint;
                bColor.a = nextIndex == frameIndex ? 0f : opacity * frameBlend;
                frameB.color = bColor;

                var settle = Mathf.SmoothStep(0f, 1f, t);
                var scale = targetScale * Mathf.Lerp(.9f, 1.035f, settle);
                frameA.transform.localScale = frameB.transform.localScale = Vector3.one * scale;

                if (clarityCore != null)
                {
                    var corePulse = Mathf.Sin(Mathf.Clamp01(t / .56f) * Mathf.PI);
                    clarityCore.transform.localScale = Vector3.one * targetScale *
                                                       Mathf.Lerp(.22f, .96f, settle);
                    var coreColor = style.Core;
                    coreColor.a = corePulse * fadeOut *
                                  (tier == CombatVfxTier.Ultimate ? 1f : .94f);
                    clarityCore.color = coreColor;
                }
                if (clarityRing != null)
                {
                    clarityRing.transform.localScale = Vector3.one * targetScale *
                        Mathf.Lerp(.16f, tier == CombatVfxTier.Ultimate ? 1.2f : .96f,
                            1f - Mathf.Pow(1f - settle, 2.2f));
                    clarityRing.transform.Rotate(0f, 0f, Time.deltaTime *
                        (tier == CombatVfxTier.Ultimate ? 210f : 145f));
                    var ringColor = Color.Lerp(style.Primary, Color.white, .58f);
                    ringColor.a = Mathf.Sin(Mathf.Clamp01(t / .78f) * Mathf.PI) * fadeOut *
                                  (tier == CombatVfxTier.Ultimate ? .96f : .84f);
                    clarityRing.color = ringColor;
                }

                if (skinEcho != null)
                {
                    var echoPulse = Mathf.Sin(Mathf.Clamp01((t - .08f) / .72f) * Mathf.PI);
                    skinEcho.transform.localScale = Vector3.one * targetScale *
                                                    Mathf.Lerp(.26f, tier == CombatVfxTier.Ultimate ? 1.62f :
                                                        tier == CombatVfxTier.Skill ? 1.08f : .72f, settle);
                    var echoColor = skinEcho.color;
                    echoColor.a = echoPulse * (tier == CombatVfxTier.Ultimate ? .34f :
                        tier == CombatVfxTier.Skill ? .24f : .19f) * fadeOut;
                    skinEcho.color = echoColor;
                }
                for (var i = 0; i < skinSignatures.Length; i++)
                {
                    var phase = i / (float)Mathf.Max(1, skinSignatures.Length);
                    var rotation = (style.Variant == 1 ? -1f : 1f) * t *
                                   (style.Variant == 1 ? 2.2f : 4.1f);
                    var angle = phase * Mathf.PI * 2f + rotation;
                    var burst = Mathf.Sin(Mathf.Clamp01((t - phase * .055f) / .82f) * Mathf.PI);
                    var distance = targetScale * Mathf.Lerp(.12f,
                        style.Variant == 1 ? .78f : .96f, settle) * (.82f + i % 3 * .1f);
                    skinSignatures[i].transform.localPosition = new Vector3(
                        Mathf.Cos(angle) * distance,
                        Mathf.Sin(angle) * distance * (style.Variant == 1 ? .62f : .82f), -.01f);
                    skinSignatures[i].transform.localScale = style.Variant == 1
                        ? new Vector3(targetScale * (.15f + i % 2 * .04f),
                            targetScale * .045f, 1f) * Mathf.Max(.16f, burst)
                        : Vector3.one * targetScale * (.055f + i % 3 * .018f) * Mathf.Max(.2f, burst);
                    skinSignatures[i].transform.Rotate(0f, 0f,
                        Time.deltaTime * (style.Variant == 1 ? -320f : 420f));
                    var signatureColor = i % 3 == 0 ? style.Core : i % 2 == 0
                        ? style.Secondary : style.Primary;
                    signatureColor.a = burst * fadeOut * (tier == CombatVfxTier.Basic ? .94f : 1f);
                    skinSignatures[i].color = signatureColor;
                }
                yield return null;
            }
            Destroy(effect);
        }

        private int movementDustSequence;

        private IEnumerator MovementDustRoutine(Vector2 position, Color color, float radius, Vector2 direction)
        {
            var effect = TransientBattleEffect.Create("Movement Dust");
            effect.transform.position = new Vector3(position.x, position.y, -2.8f);
            // The former brown mesh fragments belonged to the discarded 2.5D prototype.
            // A very light, flat foot puff keeps speed readable without looking like debris.
            var dustColor = Color.Lerp(new Color(.9f, .93f, .91f), color, .08f);
            dustColor.a = .11f;
            var forward = direction.sqrMagnitude > .001f ? direction.normalized : Vector2.up;
            var side = new Vector2(-forward.y, forward.x);
            var footSign = (++movementDustSequence & 1) == 0 ? -1f : 1f;
            var puff = CreateSpriteChild(effect.transform,
                footSign < 0f ? "Left Foot Plant" : "Right Foot Plant",
                GlowSprite, dustColor, radius * .24f, 12);
            var contact = side * (radius * .2f * footSign);
            puff.transform.localPosition = new Vector3(contact.x, contact.y, 0f);
            puff.transform.localEulerAngles = new Vector3(0f, 0f,
                Mathf.Atan2(forward.y, forward.x) * Mathf.Rad2Deg);
            const float duration = .22f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                if (effect == null || puff == null) yield break;
                var t = Mathf.Clamp01(elapsed / duration);
                var ease = 1f - Mathf.Pow(1f - t, 2f);
                var drift = -forward * (Time.deltaTime * radius * .3f) +
                            side * (Time.deltaTime * radius * .12f * footSign);
                puff.transform.localPosition += new Vector3(drift.x, drift.y, 0f);
                puff.transform.localScale = new Vector3(radius * Mathf.Lerp(.24f, .46f, ease),
                    radius * Mathf.Lerp(.12f, .2f, ease), 1f);
                var faded = dustColor;
                faded.a = dustColor.a * Mathf.Pow(1f - t, 1.6f);
                puff.color = faded;
                yield return null;
            }
            Destroy(effect);
        }

        private IEnumerator ContactEffectRoutine(Vector2 position, bool boss)
        {
            var effect = TransientBattleEffect.Create(boss ? "Boss Contact Shock" : "Contact Shock");
            effect.transform.position = new Vector3(position.x, position.y, -3.6f);
            var color = boss ? new Color(1f, .23f, .12f) : new Color(1f, .78f, .28f);
            var glow = CreateSpriteChild(effect.transform, "Contact Bloom", GlowSprite,
                new Color(color.r, color.g, color.b, boss ? .58f : .42f), boss ? .34f : .22f, 21);
            var ring = CreateSpriteChild(effect.transform, "Contact Ring", CommandRingSprite,
                new Color(color.r, color.g, color.b, .42f), .18f, 22);
            var bars = new SpriteRenderer[boss ? 8 : 6];
            for (var i = 0; i < bars.Length; i++)
            {
                bars[i] = CreateSpriteChild(effect.transform, $"Contact Ray {i}", SparkSprite,
                    i % 2 == 0 ? color : Color.white, boss ? .16f : .11f, 23);
                bars[i].transform.localEulerAngles = new Vector3(0f, 0f, i * (360f / bars.Length) + 20f);
            }
            var duration = boss ? .38f : .24f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                var t = Mathf.Clamp01(elapsed / duration);
                ring.transform.localScale = Vector3.one * Mathf.Lerp(.18f, boss ? 1.25f : .72f, t);
                glow.transform.localScale = Vector3.one * Mathf.Lerp(boss ? .34f : .22f, boss ? 1.5f : .82f, t);
                var rc = ring.color;
                rc.a = .42f * (1f - t);
                ring.color = rc;
                var gc = glow.color; gc.a = (boss ? .58f : .42f) * Mathf.Pow(1f - t, 1.8f); glow.color = gc;
                for (var i = 0; i < bars.Length; i++)
                {
                    var bar = bars[i];
                    var angle = (i * (360f / bars.Length) + 20f) * Mathf.Deg2Rad;
                    bar.transform.localPosition = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) *
                                                  Mathf.Lerp(.04f, boss ? .66f : .38f, t);
                    var bc = i % 2 == 0 ? color : Color.white;
                    bc.a = 1f - t;
                    bar.color = bc;
                    bar.transform.localScale = Vector3.one * Mathf.Lerp(boss ? .16f : .11f, .025f, t);
                }
                yield return null;
            }
            Destroy(effect);
        }

        private IEnumerator DamageNumberRoutine(Vector2 position, float amount, DamageType damageType, bool absorbed)
        {
            if (amount <= 0f) yield break;
            var effect = TransientBattleEffect.Create("Damage Number");
            effect.transform.position = new Vector3(position.x, position.y + .36f, -4.2f);
            var text = effect.AddComponent<TextMesh>();
            text.text = absorbed ? $"방벽 {Mathf.CeilToInt(amount)}" : $"-{Mathf.CeilToInt(amount)}";
            text.anchor = TextAnchor.MiddleCenter;
            text.alignment = TextAlignment.Center;
            text.fontSize = 44;
            text.characterSize = .032f;
            text.fontStyle = FontStyle.Bold;
            if (koreanFont != null) text.font = koreanFont;
            text.color = absorbed
                ? new Color(.35f, .85f, 1f)
                : damageType == DamageType.Magic ? new Color(.66f, .42f, 1f) : new Color(1f, .72f, .28f);
            text.GetComponent<MeshRenderer>().sortingOrder = 30;
            var start = effect.transform.position;
            for (var elapsed = 0f; elapsed < .62f; elapsed += Time.deltaTime)
            {
                var t = Mathf.Clamp01(elapsed / .62f);
                effect.transform.position = start + Vector3.up * (t * .42f);
                var c = text.color;
                c.a = 1f - Mathf.Pow(t, 2f);
                text.color = c;
                effect.transform.localScale = Vector3.one * Mathf.Lerp(.78f, 1.08f, Mathf.Sin(t * Mathf.PI));
                yield return null;
            }
            Destroy(effect);
        }

        private IEnumerator BossTelegraphRoutine(Vector2 position, float radius, float duration)
        {
            var effect = TransientBattleEffect.Create("Boss Skill Telegraph");
            effect.transform.position = new Vector3(position.x, position.y, -2.7f);
            var danger = CreateSpriteChild(effect.transform, "Danger Zone", GlowSprite,
                new Color(1f, .08f, .06f, .045f), radius * 2f, 15);
            var border = CreateSpriteChild(effect.transform, "Danger Border", CommandRingSprite,
                new Color(1f, .16f, .08f, .72f), radius * 2f, 17);
            var pulse = CreateSpriteChild(effect.transform, "Danger Pulse", CommandRingSprite,
                new Color(1f, .72f, .2f, .32f), .18f, 16);
            var ticks = new SpriteRenderer[12];
            for (var i = 0; i < ticks.Length; i++)
            {
                var angle = i * Mathf.PI * 2f / ticks.Length;
                ticks[i] = CreateSpriteChild(effect.transform, $"Danger Tick {i}", SparkSprite,
                    i % 2 == 0 ? new Color(1f, .25f, .12f) : new Color(1f, .82f, .28f),
                    .09f, 18);
                ticks[i].transform.localPosition = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * radius * .84f;
                ticks[i].transform.localEulerAngles = new Vector3(0f, 0f, -angle * Mathf.Rad2Deg);
            }
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                var t = Mathf.Clamp01(elapsed / duration);
                var beat = .7f + Mathf.Sin(t * Mathf.PI * 10f) * .3f;
                // Keep the danger area readable as an outline without placing a flat red disk
                // behind the monster art.
                danger.color = new Color(1f, .08f, .06f, .025f + beat * .04f);
                pulse.transform.localScale = Vector3.one * Mathf.Lerp(.2f, radius * 2f, t);
                border.transform.localScale = Vector3.one * radius * 2f * (.96f + beat * .04f);
                border.transform.Rotate(0f, 0f, Time.deltaTime * 42f);
                var pc = pulse.color;
                pc.a = (1f - t) * .45f;
                pulse.color = pc;
                var borderColor = border.color; borderColor.a = .5f + beat * .24f; border.color = borderColor;
                for (var i = 0; i < ticks.Length; i++)
                {
                    ticks[i].transform.localScale = Vector3.one * (.065f + beat * .045f);
                    var tickColor = ticks[i].color; tickColor.a = .46f + beat * .5f; ticks[i].color = tickColor;
                }
                yield return null;
            }
            Destroy(effect);
        }

        private IEnumerator LevelUpEffectRoutine(Vector2 position, bool hero)
        {
            var effect = TransientBattleEffect.Create(hero ? "Hero Evolution Effect" : "Level Up Effect");
            effect.transform.position = new Vector3(position.x, position.y, -4f);
            var gold = hero ? new Color(1f, .68f, .1f) : new Color(.28f, .85f, 1f);
            var core = CreateSpriteChild(effect.transform, "Level Core", GlowSprite,
                new Color(gold.r, gold.g, gold.b, .42f), .2f, 27);
            var ringA = CreateSpriteChild(effect.transform, "Level Ring A", CommandRingSprite,
                new Color(gold.r, gold.g, gold.b, .26f), .25f, 25);
            var ringB = CreateSpriteChild(effect.transform, "Level Ring B", CommandRingSprite,
                new Color(1f, 1f, 1f, .22f), .18f, 26);
            var rays = new SpriteRenderer[hero ? 10 : 8];
            for (var i = 0; i < rays.Length; i++)
            {
                rays[i] = CreateSpriteChild(effect.transform, $"Level Ray {i}", GlowSprite,
                    i % 2 == 0 ? gold : Color.white, 1f, 26);
                rays[i].transform.localScale = new Vector3(hero ? .05f : .038f, .32f, 1f);
                rays[i].transform.localEulerAngles = new Vector3(0f, 0f, i * (360f / rays.Length));
            }
            var stars = new SpriteRenderer[hero ? 18 : 12];
            var starDirections = new Vector2[stars.Length];
            for (var i = 0; i < stars.Length; i++)
            {
                var angle = i / (float)stars.Length * Mathf.PI * 2f + .2f;
                starDirections[i] = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle));
                stars[i] = CreateSpriteChild(effect.transform, $"Level Spark {i}", SparkSprite,
                    i % 2 == 0 ? gold : Color.white, hero ? .085f : .065f, 29);
                stars[i].transform.localEulerAngles = new Vector3(0f, 0f, 45f + i * 23f);
            }
            var pillar = CreateSpriteChild(effect.transform, "Ascension Pillar", GlowSprite,
                new Color(gold.r, gold.g, gold.b, hero ? .32f : .2f), 1f, 24);
            pillar.transform.localScale = new Vector3(hero ? .58f : .42f, .12f, 1f);

            var labelObject = new GameObject("Level Up Label");
            labelObject.transform.SetParent(effect.transform, false);
            labelObject.transform.localPosition = new Vector3(0f, .62f, -.2f);
            var label = labelObject.AddComponent<TextMesh>();
            // Short labels do not collide with nearby unit level markers on the small mobile
            // viewport. The previous long strings could overlap into unreadable fragments.
            label.text = hero ? "HERO" : "LV UP";
            label.anchor = TextAnchor.MiddleCenter;
            label.alignment = TextAlignment.Center;
            label.fontSize = 48;
            label.characterSize = hero ? .038f : .036f;
            label.fontStyle = FontStyle.Bold;
            label.color = gold;
            label.GetComponent<MeshRenderer>().sortingOrder = 31;
            var shadowObject = new GameObject("Level Up Label Shadow");
            shadowObject.transform.SetParent(labelObject.transform, false);
            shadowObject.transform.localPosition = new Vector3(.018f, -.025f, .04f);
            var labelShadow = shadowObject.AddComponent<TextMesh>();
            labelShadow.text = label.text;
            labelShadow.anchor = TextAnchor.MiddleCenter;
            labelShadow.alignment = TextAlignment.Center;
            labelShadow.fontSize = label.fontSize;
            labelShadow.characterSize = label.characterSize;
            labelShadow.fontStyle = FontStyle.Bold;
            labelShadow.color = new Color(.035f, .02f, .055f, .8f);
            labelShadow.GetComponent<MeshRenderer>().sortingOrder = 30;

            const float duration = 1.25f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                // Battle cleanup removes transient presentation immediately. A coroutine may
                // resume for one final frame, so destroyed renderers cancel the effect cleanly.
                if (effect == null || core == null || ringA == null || ringB == null ||
                    pillar == null || labelObject == null || label == null || labelShadow == null ||
                    rays.Any(item => item == null) || stars.Any(item => item == null)) yield break;
                var t = Mathf.Clamp01(elapsed / duration);
                var burst = 1f - Mathf.Pow(1f - Mathf.Min(1f, t * 2.3f), 3f);
                core.transform.localScale = Vector3.one * Mathf.Lerp(.18f, hero ? .9f : .68f, burst);
                ringA.transform.localScale = Vector3.one * Mathf.Lerp(.25f, hero ? 2.8f : 2.2f, t);
                ringB.transform.localScale = Vector3.one * Mathf.Lerp(.18f, hero ? 2.1f : 1.65f, Mathf.Clamp01(t * 1.25f));
                ringA.transform.Rotate(0f, 0f, Time.deltaTime * (hero ? 120f : 82f));
                ringB.transform.Rotate(0f, 0f, -Time.deltaTime * (hero ? 165f : 105f));
                pillar.transform.localPosition = new Vector3(0f, Mathf.Lerp(-.12f, .52f, t), 0f);
                pillar.transform.localScale = new Vector3(
                    Mathf.Lerp(hero ? .58f : .42f, .14f, t),
                    Mathf.Lerp(.12f, hero ? 2.9f : 2.1f, burst), 1f);
                var pillarColor = pillar.color;
                pillarColor.a = (hero ? .32f : .2f) * Mathf.Sin(t * Mathf.PI);
                pillar.color = pillarColor;
                var fade = 1f - t;
                var rc = ringA.color; rc.a = .28f * fade; ringA.color = rc;
                var rb = ringB.color; rb.a = .24f * fade; ringB.color = rb;
                var cc = core.color; cc.a = .42f * fade; core.color = cc;
                for (var i = 0; i < rays.Length; i++)
                {
                    rays[i].transform.localScale = new Vector3(rays[i].transform.localScale.x,
                        Mathf.Lerp(.2f, hero ? 1.35f : .95f, burst) * fade, 1f);
                    var rayColor = rays[i].color; rayColor.a = fade; rays[i].color = rayColor;
                    rays[i].transform.localEulerAngles += new Vector3(0f, 0f, Time.deltaTime * (hero ? 78f : 52f));
                }
                for (var i = 0; i < stars.Length; i++)
                {
                    stars[i].transform.localPosition = starDirections[i] * Mathf.Lerp(.1f, hero ? 1.35f : 1f, burst)
                        + Vector2.up * (t * .35f);
                    stars[i].transform.Rotate(0f, 0f, Time.deltaTime * 180f);
                    var sc = stars[i].color; sc.a = fade; stars[i].color = sc;
                }
                labelObject.transform.localPosition = new Vector3(0f, Mathf.Lerp(.42f, .92f, t), -.2f);
                var lc = gold; lc.a = Mathf.Sin(t * Mathf.PI); label.color = lc;
                var shadowColor = labelShadow.color;
                shadowColor.a = .8f * Mathf.Sin(t * Mathf.PI);
                labelShadow.color = shadowColor;
                yield return null;
            }
            Destroy(effect);
        }

        private void StartWave()
        {
            if (Round > MaxRounds)
            {
                Phase = GamePhase.Victory;
                return;
            }
            if (Phase != GamePhase.Preparation || units.Count == 0)
            {
                ShowToast(units.Count == 0
                    ? L("최소 한 명은 배치해야 합니다.", "DEPLOY AT LEAST ONE DEFENDER.")
                    : L("지금은 시작할 수 없습니다.", "THE WAVE CANNOT START NOW."));
                return;
            }
            // Persist the fully arranged formation immediately before combat. A forced close
            // during the wave restarts this stage from this deterministic safe point.
            SaveRunCheckpoint(true);
            buildMode = UnitArchetype.None;
            ClearSelection();
            showFormationPanel = false;
            showAugmentSummary = false;
            Phase = GamePhase.Battle;
            ApplyBattlefieldMood(MonsterClassForRound(Round));
            var chapter = Mathf.Clamp((Round - 1) / 5, 0, 9);
            var chapterStage = (Round - 1) % 5 + 1;
            ShowToast(L($"{EnemyVariantCatalog.FamilyNameForChapter(chapter)} 계열 · {chapterStage}/5 라운드",
                $"{EnemyVariantCatalog.FamilyNameForChapter(chapter)} FRONT · ROUND {chapterStage}/5"));
            // Replace any legacy damaged localized toast immediately with the canonical text.
            ShowToast(L($"{EnemyVariantCatalog.FamilyNameForChapter(chapter)} 전선 · {chapterStage}/5 라운드",
                $"{EnemyVariantCatalog.FamilyNameForChapter(chapter)} FRONT · ROUND {chapterStage}/5"));
            nextMeteorAt = Time.time + 2.2f;
            if (!runInProgress)
            {
                monetization?.BeginRun();
                runInProgress = true;
            }
            var count = WaveEnemyCount(Round);
            StartCoroutine(SpawnWaveRoutine(count));
        }

        public static int WaveEnemyCount(int round)
        {
            round = Mathf.Clamp(round, 1, MaxRounds);
            // Every round has an authored body budget. A chapter opener introduces its new
            // family with a slightly smaller formation; stages 2-4 widen it, and stage 5 spends
            // part of the budget on a separately spawned boss and five honour guards.
            return AuthoredWaveEnemyCounts[round - 1];
        }

        private static readonly int[] AuthoredWaveEnemyCounts =
        {
            12, 15, 18, 21, 24,
            22, 25, 28, 31, 30,
            28, 31, 34, 37, 36,
            34, 38, 42, 46, 44,
            40, 44, 48, 52, 50,
            46, 50, 54, 58, 56,
            52, 56, 60, 64, 62,
            58, 62, 66, 70, 68,
            64, 68, 72, 76, 74,
            72, 78, 84, 90, 88
        };

        private static readonly int[] WaveSquadBaseByChapter = { 4, 5, 5, 6, 6, 7, 7, 8, 8, 9 };

        private static int WaveSquadSize(int round)
        {
            round = Mathf.Clamp(round, 1, MaxRounds);
            var chapter = (round - 1) / 5;
            var stage = (round - 1) % 5;
            return Mathf.Clamp(WaveSquadBaseByChapter[chapter] + (stage >= 2 ? 1 : 0), 4, 10);
        }

        private static int WaveSpawnBurstSize(int round)
        {
            var chapter = (Mathf.Clamp(round, 1, MaxRounds) - 1) / 5;
            return chapter switch { <= 1 => 2, <= 5 => 3, _ => 4 };
        }

        private static float WaveMemberInterval(int round) =>
            Mathf.Lerp(.045f, .022f, Mathf.Clamp01((round - 1) / 49f));

        private static float WaveSquadInterval(int round) =>
            Mathf.Lerp(.46f, .23f, Mathf.Clamp01((round - 1) / 49f));

        // Four of every ten regular bodies use the side doors. This raises side pressure from
        // one third without starving either of the four southern tactical routes.
        private static readonly int[] DeploymentLaneOrder = { 4, 5, 0, 3, 4, 1, 2, 5, 0, 3 };

        private static int DeploymentLaneForIndex(int index)
        {
            // First four members appear from all authored gates together.  Remaining members
            // then fill the two inner south routes, so no opening squad collapses into one lane.
            return DeploymentLaneOrder[Mathf.Abs(index) % DeploymentLaneOrder.Length];
        }

        private IEnumerator SpawnSquadsRoutine(int count, Func<int, EnemyVariantProfile> profileForIndex)
        {
            var squadSize = WaveSquadSize(Round);
            for (var first = 0; first < count && Phase == GamePhase.Battle; first += squadSize)
            {
                var members = Mathf.Min(squadSize, count - first);
                var burstSize = WaveSpawnBurstSize(Round);
                for (var member = 0; member < members && Phase == GamePhase.Battle; member++)
                {
                    var index = first + member;
                    SpawnEnemy(index, profileForIndex(index));
                    if (member < members - 1 && (member + 1) % burstSize == 0)
                        yield return new WaitForSeconds(WaveMemberInterval(Round));
                }
                if (first + members < count) yield return new WaitForSeconds(WaveSquadInterval(Round));
            }
        }

        private IEnumerator SpawnWaveRoutine(int count)
        {
            spawning = true;
            var bossRound = Round % 5 == 0;
            if (!bossRound)
            {
                yield return SpawnSquadsRoutine(count, index => EnemyVariantCatalog.ForWaveMember(Round, index));
            }
            else
            {
                // A chapter finale first deploys every enemy introduced in the previous four
                // rounds. The boss then receives a separate south-gate entrance instead of
                // appearing as the first and visually weakest member of the wave.
                var chapter = Mathf.Clamp((Round - 1) / 5, 0, 9);
                var regularCount = Mathf.Max(14, count - 10);
                yield return SpawnSquadsRoutine(regularCount,
                    index => EnemyVariantCatalog.ForWaveMember(Round, index));
                if (Phase == GamePhase.Battle)
                {
                    ShowBossWarning(L("적 선봉대 뒤에서 보스 부대가 접근합니다",
                        "A BOSS FORMATION APPROACHES BEHIND THE VANGUARD"));
                    // The screen-space warning is the only boss-arrival label. It uses a normal
                    // Unicode UI font and replaces the legacy damaged TextMesh payload.
                    ShowBossWarning(L("보스 부대가 선봉대 뒤에서 접근합니다.",
                        "A BOSS FORMATION APPROACHES BEHIND THE VANGUARD"));
                    yield return new WaitForSeconds(1.65f);
                    var bossProfile = EnemyVariantCatalog.ForChapterStage(chapter, 4);
                    var escortProfile = EnemyVariantCatalog.ForChapterStage(chapter, 3);
                    var baseHealth = BaseEnemyHealth(Round);
                    SpawnBossFormation(bossProfile, escortProfile,
                        baseHealth * (6.80f + chapter * .34f), baseHealth * 1.08f);
                    // Boss rounds add a simultaneous ten-body flank push. Side entrances no
                    // longer go quiet while the southern boss procession is on screen.
                    for (var flank = 0; flank < 10; flank++)
                        SpawnEnemy(regularCount + flank,
                            EnemyVariantCatalog.ForChapterStage(chapter, flank % 4));
                }
            }
            spawning = false;
        }

        private void SpawnEnemy(int index)
        {
            SpawnEnemy(index, EnemyVariantCatalog.ForRound(Round));
        }

        private static float BaseEnemyHealth(int round) =>
            (53f + round * 5.05f + Mathf.Pow(round, 1.22f) * 1.42f) *
            RoundHealthPressureMultiplier(round) * WaveCadenceHealthSmoothing(round);

        private static float WaveCadenceHealthSmoothing(int round)
        {
            // Formation size already supplies the reinforcement rhythm. Oscillating health on top
            // of it caused an artificial dip followed by a sharp rebound.
            return 1f;
        }

        private static float RoundHealthPressureMultiplier(int round)
        {
            var chapter = Mathf.Clamp((round - 1) / 5, 0, 9);
            var stage = Mathf.Clamp((round - 1) % 5, 0, 4);
            return chapter switch
            {
                // The opening eight families now carry enough durability to require formation
                // choices instead of functioning as an extended tutorial.  The curve descends
                // gradually as kit complexity increases, rather than banking all pressure for
                // chapter ten.
                0 => 1.08f,
                1 => 1.07f,
                2 => 1.06f,
                3 => 1.05f,
                4 => 1.04f,
                5 => 1.03f,
                6 => 1.02f,
                // Spirit/Wisp used to combine the normal global curve with extreme Armor and
                // caster density, creating an abrupt wall. Its five stages now ramp smoothly.
                7 => 1.005f + stage * .003f,
                8 => 1f,
                // The abyss roster already combines runner, spirit, support and siege tools.
                // Its statistics therefore enter below the sky chapter and climb gently across
                // 46-50 instead of producing a one-round wall.
                _ => stage switch
                {
                    0 => .96f,
                    1 => .90f,
                    2 => .85f,
                    3 => .80f,
                    _ => .78f
                }
            };
        }

        public float EnemyRoundDamageMultiplier => EnemyRoundDamageMultiplierFor(Round);

        private static float EnemyRoundDamageMultiplierFor(int round)
        {
            var chapter = Mathf.Clamp((round - 1) / 5, 0, 9);
            var stage = Mathf.Clamp((round - 1) % 5, 0, 4);
            return chapter switch
            {
                0 => 1.07f,
                1 => 1.06f,
                2 => 1.05f,
                3 => 1.04f,
                4 => 1.03f,
                5 => 1.02f,
                6 => 1.01f,
                7 => 1f + stage * .002f,
                8 => .995f,
                _ => stage switch
                {
                    0 => .94f,
                    1 => .89f,
                    2 => .84f,
                    3 => .80f,
                    _ => .78f
                }
            };
        }

        private void SpawnEnemy(int index, EnemyVariantProfile profile)
        {
            var enemyClass = profile?.CombatClass ?? ChooseEnemyClass(index);
            var ranged = enemyClass is EnemyClass.Mage or EnemyClass.Shaman or EnemyClass.Siege or EnemyClass.Wisp or
                EnemyClass.Silencer or EnemyClass.Cursebinder;
            var health = BaseEnemyHealth(Round) * (ranged ? .84f : 1f);
            var enemy = new GameObject($"{profile?.Name ?? enemyClass.ToString()} Enemy")
                .AddComponent<EnemyUnit>();
            var lane = Mathf.Clamp(DeploymentLaneForIndex(index), 0, Mathf.Max(0, LaneCount - 1));
            enemy.Initialize(this, index, health, false, lane, enemyClass, profile);
            enemies.Add(enemy);
            if (index == 0 && HasCommandLineArgument("-qaGate")) enemy.ForceAtGateForQa();
        }

        private void SpawnBossFormation(EnemyVariantProfile bossProfile, EnemyVariantProfile escortProfile,
            float bossHealth, float escortHealth)
        {
            var enemyClass = bossProfile.CombatClass;
            var boss = new GameObject($"{bossProfile.Name} Chapter Boss").AddComponent<EnemyUnit>();
            boss.Initialize(this, 0, bossHealth, true, 0, enemyClass, bossProfile);
            boss.ConfigureBossEntrance(0f, 0f);
            enemies.Add(boss);
            RegisterBossSilhouetteExclusion(boss);
            bossFormationSpawnCount = 1;

            var escortOffsets = new[] { -1.72f, -.86f, 0f, .86f, 1.72f };
            var escortBackRows = new[] { .62f, 1.18f, 1.72f, 1.18f, .62f };
            for (var i = 0; i < escortOffsets.Length; i++)
            {
                var escort = new GameObject($"{escortProfile.Name} Boss Honour Guard {i + 1}")
                    .AddComponent<EnemyUnit>();
                escort.Initialize(this, i + 1, escortHealth * (i == 2 ? 1.08f : .92f),
                    false, 0, escortProfile.CombatClass, escortProfile);
                escort.ConfigureBossEntrance(escortOffsets[i], escortBackRows[i]);
                enemies.Add(escort);
                bossFormationSpawnCount++;
            }
            ShowBossWarning(L("보스 부대가 남쪽 관문에서 진입합니다", "BOSS FORMATION ENTERING"));
            StartCoroutine(BossEntrancePresentationRoutine(boss, bossProfile.FamilyClass));
        }

        private IEnumerator BossEntrancePresentationRoutine(EnemyUnit boss, EnemyClass enemyClass)
        {
            var entrance = GetBossEntrancePathTarget(0, 0f, 0f);
            var familyColor = enemyClass switch
            {
                EnemyClass.Skeleton => new Color(.62f, .78f, 1f),
                EnemyClass.Runner => new Color(.42f, 1f, .36f),
                EnemyClass.Brute => new Color(1f, .42f, .1f),
                EnemyClass.Shaman => new Color(.16f, 1f, .58f),
                EnemyClass.Siege => new Color(.72f, .24f, 1f),
                EnemyClass.Piercer => new Color(1f, .16f, .08f),
                EnemyClass.Wisp => new Color(.18f, .9f, 1f),
                EnemyClass.Flyer => new Color(1f, .54f, .18f),
                EnemyClass.Mage => new Color(.5f, .36f, 1f),
                _ => new Color(.78f, .25f, 1f)
            };
            var root = TransientBattleEffect.Create("Boss South Gate Entrance");
            root.transform.position = new Vector3(entrance.x, entrance.y, -4.1f);
            var ground = CreateSpriteChild(root.transform, "Boss Portal Ground", CommandRingSprite,
                new Color(familyColor.r, familyColor.g, familyColor.b, .78f), 2.1f, 14);
            ground.transform.localScale = new Vector3(2.7f, .68f, 1f);
            var core = CreateSpriteChild(root.transform, "Boss Portal Core", GlowSprite,
                new Color(familyColor.r, familyColor.g, familyColor.b, .46f), 1f, 13);
            core.transform.localScale = new Vector3(2.25f, .72f, 1f);
            var pillars = new SpriteRenderer[7];
            for (var i = 0; i < pillars.Length; i++)
            {
                pillars[i] = CreateSpriteChild(root.transform, $"Boss Gate Ray {i}", GlowSprite,
                    i % 2 == 0 ? familyColor : Color.white, 1f, 15);
                pillars[i].transform.localPosition = new Vector3((i - 3) * .26f, .18f, -.04f);
                pillars[i].transform.localScale = new Vector3(.075f, .25f, 1f);
            }
            // The localized warning already lives in the screen-space HUD. A second TextMesh in
            // world space used a platform-dependent font atlas and could turn into mojibake above
            // the boss on Android. Keep this entrance purely pictorial and therefore locale-safe.

            const float duration = 1.85f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                var t = Mathf.Clamp01(elapsed / duration);
                var arrival = Mathf.SmoothStep(0f, 1f, Mathf.Min(1f, t * 1.8f));
                var fade = 1f - Mathf.Clamp01((t - .62f) / .38f);
                ground.transform.Rotate(0f, 0f, Time.deltaTime * 95f);
                ground.transform.localScale = new Vector3(Mathf.Lerp(.35f, 2.7f, arrival),
                    Mathf.Lerp(.12f, .68f, arrival), 1f);
                core.transform.localScale = new Vector3(2.25f, .72f, 1f) *
                                            (1f + Mathf.Sin(Time.time * 9f) * .08f);
                var gc = ground.color; gc.a = .78f * fade; ground.color = gc;
                var cc = core.color; cc.a = .46f * fade; core.color = cc;
                for (var i = 0; i < pillars.Length; i++)
                {
                    pillars[i].transform.localScale = new Vector3(.075f,
                        Mathf.Lerp(.2f, 2.45f + (i % 3) * .28f, arrival) * fade, 1f);
                    var pc = pillars[i].color; pc.a = fade * (.4f + arrival * .46f); pillars[i].color = pc;
                }
                yield return null;
            }
            Destroy(root);
        }

        public int SpawnBossMinions(EnemyUnit source, EnemyClass minionClass, int count)
        {
            if (source == null || !source.IsAlive || Phase != GamePhase.Battle) return 0;
            var spawned = 0;
            var health = Mathf.Max(48f + Round * 3f, source.MaxHealth * .075f);
            for (var i = 0; i < Mathf.Clamp(count, 1, 6); i++)
            {
                // A boss may request a runner-like combat role, but the summoned body must stay
                // in its own chapter family: jelly creates jelly, lich creates skeletons, etc.
                var profile = EnemyVariantCatalog.ForFamilyStage(source.VisualClass, i % 2);
                var minion = new GameObject($"{profile.EnglishName} Summoned Minion").AddComponent<EnemyUnit>();
                var spawnIndex = enemies.Count + i;
                minion.Initialize(this, spawnIndex, health, false, source.LaneIndex,
                    profile.CombatClass, profile);
                var angle = i * Mathf.PI * 2f / Mathf.Max(1, count) + Mathf.PI * .25f;
                var minimumRadius = source.Radius + minion.Radius + .34f;
                var summonPosition = FindSeparatedBossSummonPosition(source, minion.Radius,
                    angle, minimumRadius, i);
                minion.SetSummonedPosition(summonPosition, source.PathIndex, source.UsesBossEntrance);
                enemies.Add(minion);
                spawned++;
            }
            return spawned;
        }

        private Vector2 FindSeparatedBossSummonPosition(EnemyUnit source, float minionRadius,
            float preferredAngle, float minimumRadius, int ordinal)
        {
            var best = source.Position + new Vector2(Mathf.Cos(preferredAngle), Mathf.Sin(preferredAngle)) *
                minimumRadius;
            var bestClearance = float.MinValue;
            // Search the actual assault route first. Four radial points around a wide boss cannot
            // all fit inside a narrow curved road; projecting those points afterwards collapses
            // several minions onto the same centreline. Forward/back route samples produce a
            // readable procession and cannot appear inside the boss artwork.
            var route = source.UsesBossEntrance
                ? (IReadOnlyList<Vector2>)bossEntrancePath
                : paths[Mathf.Clamp(source.LaneIndex, 0, paths.Count - 1)];
            for (var offset = 1; offset < Mathf.Min(72, route.Count); offset++)
            {
                var signedOffset = (offset + ordinal) % 2 == 0 ? offset : -offset;
                var routeIndex = source.PathIndex + signedOffset;
                if (routeIndex < 0 || routeIndex >= route.Count) continue;
                foreach (var lateral in new[] { 0f, -.46f, .46f })
                {
                    var candidate = GetOffsetPathTarget(route, routeIndex, lateral, 0f, .34f, .42f);
                    if (Vector2.Distance(candidate, source.Position) < minimumRadius ||
                        !IsWithinGroundEnemyRoadCorridor(candidate, minionRadius * .42f) ||
                        !IsWalkableWithClearance(candidate, minionRadius * .48f)) continue;
                    var clearance = enemies.Where(enemy => enemy != null && enemy.IsAlive)
                        .Select(enemy => Vector2.Distance(candidate, enemy.Position) -
                                         enemy.Radius - minionRadius)
                        .DefaultIfEmpty(10f).Min();
                    if (clearance > bestClearance)
                    {
                        best = candidate;
                        bestClearance = clearance;
                    }
                    if (clearance >= .22f) return candidate;
                }
            }
            for (var ring = 0; ring < 3; ring++)
            for (var turn = 0; turn < 16; turn++)
            {
                var angle = preferredAngle + (turn % 2 == 0 ? turn : -turn) * Mathf.PI / 16f;
                var radius = minimumRadius + ring * (.34f + minionRadius * .22f) + ordinal % 2 * .08f;
                var candidate = source.Position + new Vector2(Mathf.Cos(angle), Mathf.Sin(angle)) * radius;
                if (!IsWithinGroundEnemyRoadCorridor(candidate, minionRadius * .42f) ||
                    !IsWalkableWithClearance(candidate, minionRadius * .48f)) continue;
                var clearance = enemies.Where(enemy => enemy != null && enemy.IsAlive)
                    .Select(enemy => Vector2.Distance(candidate, enemy.Position) - enemy.Radius - minionRadius)
                    .DefaultIfEmpty(10f).Min();
                if (clearance > bestClearance)
                {
                    best = candidate;
                    bestClearance = clearance;
                }
                if (clearance >= .22f) return candidate;
            }
            return NearestGroundEnemyRoadPosition(best, minionRadius * .48f);
        }

        public static EnemyClass MonsterClassForRound(int round)
        {
            return EnemyVariantCatalog.ForRound(Mathf.Clamp(round, 1, MaxRounds)).FamilyClass;
        }

        private EnemyClass ChooseEnemyClass(int index) => MonsterClassForRound(Round);

        private void CompleteRound()
        {
            roundsCleared++;
            lifetimeRoundsCleared++;
            SaveLifetimeProgress();
            if (Round >= MaxRounds)
            {
                ClearRunCheckpoint();
                foreach (var survivor in units)
                    if (survivor != null && survivor.IsAlive)
                        survivor.PrepareForNextRound(RoundClearRecoveryFraction);
                ClearSelection();
                Phase = GamePhase.Victory;
                spawning = false;
                var reward = monetization?.GrantRandomVictoryCosmetic();
                victoryRewardText = reward == null
                    ? L("모든 스킨을 이미 보유해 추가 선물을 지급할 수 없습니다.",
                        "YOU ALREADY OWN EVERY SKIN, SO THERE IS NO NEW GIFT TO AWARD.")
                    : L($"50라운드 보상 · {reward.Name} 스킨을 획득했습니다!",
                        $"ROUND 50 REWARD · {reward.Name.ToUpperInvariant()} UNLOCKED!");
                monetization?.NotifyRunEnded();
                runInProgress = false;
                ShowToast(L("50단계 전선을 모두 정복했습니다!", "ALL 50 FRONTS CONQUERED!"));
                return;
            }
            Phase = GamePhase.Augment;
            foreach (var unit in units)
                if (unit != null && unit.IsAlive)
                    unit.PrepareForNextRound(RoundClearRecoveryFraction);
            ClearSelection();
            showFormationPanel = false;
            showAugmentSummary = false;
            augmentOverlayHidden = false;
            currentOffers = GenerateOffers();
            SaveRunCheckpoint();
        }

        private AugmentOffer[] GenerateOffers()
        {
            var offers = new AugmentOffer[3];
            // One rarity is selected first. Every choice in the row then comes from that exact
            // pool, so a Bronze round never presents an unrelated Silver or Gold card.
            var tier = RollTier(Round % 5 == 0);
            var candidates = GetAvailableAugmentTemplates(tier);
            if (candidates.Count < offers.Length)
            {
                // Never fall back to the raw pool here: that could reintroduce a recruit that
                // has already been accepted. The normal pools have far more than three cards;
                // this is only a defensive path for future content changes.
                candidates = GetAugmentPool(tier)
                    .Where(template => !TryGetUnlockUnit(template.EffectKey, out _))
                    .Concat(FixedRecruitAugments(tier))
                    .Where(IsAugmentAvailable)
                    .GroupBy(template => template.EffectKey)
                    .Select(group => group.First())
                    .ToList();
            }
            for (var i = 0; i < offers.Length; i++)
            {
                var pick = UnityEngine.Random.Range(0, candidates.Count);
                var template = candidates[pick];
                candidates.RemoveAt(pick);
                var power = TierPower(tier);
                offers[i] = new AugmentOffer(GameLocalization.AugmentName(template.EffectKey, template.Name),
                    GameLocalization.AugmentDescription(template.EffectKey, power, DescribeAugment(template, power)), template.EffectKey,
                    tier, power);
            }
            return offers;
        }

