        private static IEnumerable<AugmentTemplate> FixedRecruitAugments(AugmentTier tier)
        {
            // A recruit belongs to exactly one rarity. The tier expresses the unit's complete
            // combat budget; the same contract can never leak into another rarity pool.
            return tier switch
            {
                AugmentTier.Gold => new[]
                {
                    new AugmentTemplate("Clockwork Contract", "Recruit the Clockwork Bombardier.", "UnlockBombardier"),
                    new AugmentTemplate("Royal Contract", "Recruit the Royal Musketeer.", "UnlockMusketeer")
                },
                AugmentTier.Platinum => new[]
                {
                    new AugmentTemplate("Dragonvein Contract", "Recruit the Dragonvein Lancer.", "UnlockLancer"),
                    new AugmentTemplate("Grove Contract", "Recruit the Grove Spiritcaller.", "UnlockDruid")
                },
                AugmentTier.Diamond => new[]
                {
                    new AugmentTemplate("Moonlight Contract", "Recruit the Moonlight Oracle.", "UnlockOracle")
                },
                _ => Array.Empty<AugmentTemplate>()
            };
        }

        private List<AugmentTemplate> GetAvailableAugmentTemplates(AugmentTier tier)
        {
            return GetAugmentPool(tier)
                .Where(template => !TryGetUnlockUnit(template.EffectKey, out _))
                .Concat(FixedRecruitAugments(tier))
                .Where(IsAugmentAvailable)
                .GroupBy(template => template.EffectKey)
                .Select(group => group.First())
                .ToList();
        }

        private bool IsAugmentAvailable(AugmentTemplate template)
        {
            if (TryGetUnlockUnit(template.EffectKey, out var unit) && unlockedUnits.Contains(unit)) return false;
            return !IsUniqueAugmentKey(template.EffectKey) || !acquiredAugments.ContainsKey(template.EffectKey);
        }

        private static bool IsUniqueAugmentKey(string effectKey) =>
            TryGetUnlockUnit(effectKey, out _) || effectKey is
                "Meteor" or "Duplicate" or "ActiveVolley" or "ActiveFreeze" or
                "DoubleShot" or "RangedRicochet" or "MageEcho" or "SupportSanctuary" or
                "TankRally" or "MageBurn" or "SupportHaste" or "TankBulwark" or
                "RangedPierce" or "MageResonance" or "SupportRescue" or "TankCitadel" or
                "RangedTempest" or "MageSingularity" or "SupportMiracle";

        private AugmentTier RollTier(bool boss)
        {
            var tier = ResolveAugmentTier(lastTier, boss, augmentOffersWithoutHighTier,
                UnityEngine.Random.value);
            augmentOffersWithoutHighTier = tier >= AugmentTier.Platinum
                ? 0
                : augmentOffersWithoutHighTier + 1;
            return tier;
        }

        private static AugmentTier ResolveAugmentTier(AugmentTier previousTier, bool boss,
            int offersWithoutHighTier, float normalizedRoll)
        {
            // Diamond is intentionally rare. Previous rarity still changes the next table, boss
            // clears improve the upper tiers, and pity primarily awards Platinum rather than
            // turning Diamond into a frequent guaranteed outcome.
            var weights = previousTier switch
            {
                AugmentTier.Bronze => new[] { 48f, 29f, 16f, 6.5f, .5f },
                AugmentTier.Silver => new[] { 42f, 30f, 18f, 9f, 1f },
                AugmentTier.Gold => new[] { 36f, 30f, 21f, 11.5f, 1.5f },
                AugmentTier.Platinum => new[] { 39f, 31f, 20f, 8f, 2f },
                _ => new[] { 50f, 30f, 15f, 4.5f, .5f }
            };
            if (offersWithoutHighTier >= 4)
                weights = new[] { 0f, 0f, 12f, 85f, 3f };
            else if (boss)
            {
                weights[2] *= 1.15f;
                weights[3] *= 1.6f;
                weights[4] *= 2f;
            }
            var total = 0f; foreach (var weight in weights) total += weight;
            var roll = Mathf.Clamp01(normalizedRoll) * total;
            var cumulative = 0f;
            for (var i = 0; i < weights.Length; i++)
            {
                if (weights[i] <= 0f) continue;
                cumulative += weights[i];
                if (roll < cumulative) return (AugmentTier)i;
            }
            return AugmentTier.Diamond;
        }

        private static float TierPower(AugmentTier tier) => tier switch
        {
            AugmentTier.Bronze => .21f, AugmentTier.Silver => .38f, AugmentTier.Gold => .60f,
            AugmentTier.Platinum => .85f, _ => 1.09f
        };

