        private void SelectAugment(AugmentOffer offer)
        {
            var previousPower = StackPower(offer.EffectKey);
            var persistentStat = !TryGetUnlockUnit(offer.EffectKey, out _) &&
                                 offer.EffectKey is not ("LastStand" or "ActiveVolley" or
                                     "ActiveFreeze" or "ActiveFortify");
            var addedPower = persistentStat
                ? offer.Power / (1f + previousPower * .55f)
                : offer.Power;
            augmentPower[offer.EffectKey] = previousPower + addedPower;
            augmentCount[offer.Name] = augmentCount.TryGetValue(offer.Name, out var count) ? count + 1 : 1;
            acquiredAugments[offer.EffectKey] = offer;
            inspectedAugmentKey = offer.EffectKey;
            if (TryGetUnlockUnit(offer.EffectKey, out var unlocked)) unlockedUnits.Add(unlocked);
            if (offer.EffectKey == "LastStand") lastStandCharges += 3;
            if (offer.EffectKey is "ActiveVolley" or "ActiveFreeze" or "ActiveFortify")
            {
                if (!activeAugmentReadyAt.ContainsKey(offer.EffectKey))
                    activeAugmentReadyAt[offer.EffectKey] = 0f;
            }
            var repaired = 0f;
            if (offer.EffectKey == "GateHeal")
            {
                var before = gateHealth;
                gateHealth = Mathf.Min(GateMaxHealth, gateHealth + 28f + offer.Power * 14f);
                repaired = gateHealth - before;
            }
            else if (offer.EffectKey == "GateHealMajor")
            {
                var before = gateHealth;
                gateHealth = Mathf.Min(GateMaxHealth, gateHealth + 78f + offer.Power * 18f);
                repaired = gateHealth - before;
            }
            lastTier = offer.Tier;
            Round++;
            Money = StartBudget();
            Phase = GamePhase.Preparation;
            showFormationPanel = true;
            showAugmentSummary = false;
            augmentOverlayHidden = false;
            currentOffers = Array.Empty<AugmentOffer>();
            SaveRunCheckpoint();
            ShowToast(repaired > 0f
                ? L($"성벽 수리 +{Mathf.RoundToInt(repaired)} · 라운드 {Round}",
                    $"GATE REPAIR +{Mathf.RoundToInt(repaired)} · ROUND {Round}")
                : L($"라운드 {Round} · 생존 유닛 유지 · 성벽 내구도 유지",
                    $"ROUND {Round} · SURVIVORS AND GATE DURABILITY RETAINED"));
        }

        private static bool TryGetUnlockUnit(string effectKey, out UnitArchetype archetype)
        {
            archetype = effectKey switch
            {
                "UnlockBombardier" => UnitArchetype.Bombardier,
                "UnlockLancer" => UnitArchetype.Lancer,
                "UnlockDruid" => UnitArchetype.Druid,
                "UnlockMusketeer" => UnitArchetype.Musketeer,
                "UnlockOracle" => UnitArchetype.Oracle,
                _ => UnitArchetype.None
            };
            return archetype != UnitArchetype.None;
        }

        private bool IsUnitUnlocked(UnitArchetype archetype) =>
            archetype is not (UnitArchetype.Bombardier or UnitArchetype.Lancer or UnitArchetype.Druid or
                UnitArchetype.Musketeer or UnitArchetype.Oracle) ||
            unlockedUnits.Contains(archetype) || HasCommandLineArgument("-qaUnlock");

        // The standard preparation budget is flat. Only Royal Supply augments change it.
        private int StartBudget() => Mathf.RoundToInt(19f + StackPower("Budget") * 4f);
        private float StackPower(string name) => augmentPower.TryGetValue(name, out var value) ? value : 0f;

        public float GetCriticalChance(PlayerUnit unit)
        {
            if (unit == null) return 0f;
            const float baseCriticalChance = .25f;
            if (RoleFor(unit.Archetype) != DefenderRole.Ranged) return baseCriticalChance;
            var rangedBonus = StackPower("RangedCrit") * .13f +
                              StackPower("RangedMark") * .12f +
                              StackPower("RangedTempest") * .06f;
            // Every defender owns the same 25% baseline. Ranged augments remain meaningful,
            // but their combined ceiling prevents a high-roll build from becoming deterministic.
            return Mathf.Clamp(baseCriticalChance + rangedBonus, baseCriticalChance, .55f);
        }

        public float GetCriticalDamageMultiplier(PlayerUnit unit)
        {
            // Critical hits start at 150%. Weak-point Shot raises the multiplier as its
            // diminishing stack power grows; it no longer leaves every stack fixed at 165%.
            // The 225% ceiling keeps repeated Gold offerings from invalidating later waves.
            var rangedPower = unit != null && RoleFor(unit.Archetype) == DefenderRole.Ranged
                ? StackPower("RangedCrit")
                : 0f;
            return 1.5f + Mathf.Clamp(rangedPower * .24f, 0f, .75f);
        }

        public static DefenderRole RoleFor(UnitArchetype archetype) => archetype switch
        {
            UnitArchetype.Tank => DefenderRole.Tank,
            UnitArchetype.Melee or UnitArchetype.Lancer => DefenderRole.Melee,
            UnitArchetype.Archer or UnitArchetype.Bombardier or UnitArchetype.Musketeer => DefenderRole.Ranged,
            UnitArchetype.AreaMage or UnitArchetype.SingleMage => DefenderRole.Mage,
            _ => DefenderRole.Support
        };

        public float GetRoleDamageMultiplier(PlayerUnit unit)
        {
            if (unit == null) return 1f;
            var bonus = StackPower("FormationDiscipline") * .05f;
            bonus += RoleFor(unit.Archetype) switch
            {
                DefenderRole.Tank => StackPower("TankDrill") * .06f,
                DefenderRole.Melee => StackPower("MeleeEdge") * .10f +
                                      (unit.HealthRatio <= .5f ? StackPower("MeleeOverdrive") * .10f : 0f),
                DefenderRole.Ranged => StackPower("RangedPractice") * .10f +
                                       (unit.IsHoldingPosition ? StackPower("RangedFocus") * .08f : 0f) +
                                       StackPower("RangedTempest") * .05f,
                DefenderRole.Mage => StackPower("MageFocus") * .11f +
                                     StackPower("MageOverload") * .16f +
                                     StackPower("MageCataclysm") * .16f,
                _ => 0f
            };
            return 1f + bonus;
        }

        public float GetRoleAttackDelayMultiplier(PlayerUnit unit)
        {
            if (unit == null) return 1f;
            var speed = StackPower("AttackSpeed") * .05f;
            speed += RoleFor(unit.Archetype) switch
            {
                DefenderRole.Melee => StackPower("MeleeTempo") * .10f,
                DefenderRole.Ranged => StackPower("RangedBarrage") * .10f +
                                       StackPower("RangedTempest") * .05f,
                _ => 0f
            };
            if (RoleFor(unit.Archetype) == DefenderRole.Melee && unit.HealthRatio <= .5f)
                speed += StackPower("MeleeRelentless") * .10f + StackPower("MeleeOverdrive") * .07f;
            return 1f / (1f + speed);
        }

        public float GetRoleRangeBonus(PlayerUnit unit)
        {
            if (unit == null || RoleFor(unit.Archetype) != DefenderRole.Ranged) return 0f;
            return StackPower("RangedRange") * .20f + StackPower("RangedBarrage") * .11f +
                   StackPower("RangedTempest") * .06f;
        }

        public float GetRoleDetectionRangeBonus(PlayerUnit unit)
        {
            if (unit == null) return 0f;
            return RoleFor(unit.Archetype) switch
            {
                DefenderRole.Melee => StackPower("MeleePursuit") * .18f,
                DefenderRole.Ranged => StackPower("RangedSpotter") * .28f,
                _ => 0f
            };
        }

        public float GetRoleMoveSpeedMultiplier(PlayerUnit unit)
        {
            if (unit == null) return 1f;
            var bonus = RoleFor(unit.Archetype) == DefenderRole.Melee
                ? StackPower("MeleeMarch") * .05f + StackPower("MeleePursuit") * .06f
                : 0f;
            return 1f + Mathf.Clamp(bonus, 0f, .18f);
        }

        public float GetRoleDefenseBonus(PlayerUnit unit)
        {
            if (unit == null || RoleFor(unit.Archetype) != DefenderRole.Tank) return 0f;
            var anchor = unit.IsHoldingPosition ? StackPower("TankAnchor") * 8f : 0f;
            var citadel = unit.HealthRatio <= .35f ? StackPower("TankCitadel") * 8f : 0f;
            return StackPower("TankPlating") * 9f + StackPower("TankUnbroken") * 10f + anchor + citadel;
        }

        public float GetRoleResistanceBonus(PlayerUnit unit)
        {
            if (unit == null || RoleFor(unit.Archetype) != DefenderRole.Tank) return 0f;
            var anchor = unit.IsHoldingPosition ? StackPower("TankAnchor") * 6f : 0f;
            var citadel = unit.HealthRatio <= .35f ? StackPower("TankCitadel") * 7f : 0f;
            return StackPower("TankPlating") * 6f + StackPower("TankUnbroken") * 8f + anchor + citadel;
        }

        public float GetRoleDamageTakenMultiplier(PlayerUnit unit)
        {
            if (unit == null || RoleFor(unit.Archetype) != DefenderRole.Tank) return 1f;
            var reduction = StackPower("TankDrill") * .03f + StackPower("TankAegis") * .08f +
                            StackPower("TankUnbroken") * .10f;
            if (unit.HealthRatio <= .35f) reduction += StackPower("TankCitadel") * .12f;
            return 1f - Mathf.Clamp(reduction, 0f, .42f);
        }

        public float GetFormationDamageTakenMultiplier(PlayerUnit unit)
        {
            if (unit == null || RoleFor(unit.Archetype) == DefenderRole.Tank) return 1f;
            var escort = StackPower("TankEscort");
            var bulwark = StackPower("TankBulwark");
            if (escort <= 0f && bulwark <= 0f) return 1f;
            var protectedByTank = units.Any(ally => ally != null && ally.IsAlive && ally != unit &&
                                                    RoleFor(ally.Archetype) == DefenderRole.Tank &&
                                                    Vector2.Distance(ally.Position, unit.Position) <= 1.55f);
            if (!protectedByTank) return 1f;
            var reduction = escort * .04f + bulwark * .09f;
            return 1f - Mathf.Clamp(reduction, 0f, .18f);
        }

        public float GetRoleSkillCooldownMultiplier(PlayerUnit unit)
        {
            if (unit == null) return 1f;
            var reduction = RoleFor(unit.Archetype) switch
            {
                DefenderRole.Mage => StackPower("MageConserve") * .05f + StackPower("MagePrimer") * .08f,
                DefenderRole.Support => StackPower("SupportCooldown") * .10f +
                                         StackPower("SupportAscension") * .10f +
                                         StackPower("SupportMiracle") * .05f,
                _ => 0f
            };
            return 1f - Mathf.Clamp(reduction, 0f, .28f);
        }

        public float GetRoleSplashBonus(PlayerUnit unit)
        {
            if (unit == null || RoleFor(unit.Archetype) != DefenderRole.Mage) return 0f;
            return StackPower("MageRadius") * .18f + StackPower("MageOverload") * .12f +
                   StackPower("MageCataclysm") * .16f + StackPower("MageResonance") * .12f +
                   StackPower("MageSingularity") * .08f;
        }

        public float GetHighGroundDamageMultiplier(PlayerUnit unit)
        {
            if (unit == null || !unit.IsOnHighGround) return 1f;
            return 1f + StackPower("HillDamage") * .09f + StackPower("HillDominion") * .07f;
        }

        public float GetHighGroundRangeBonus(PlayerUnit unit)
        {
            if (unit == null || !unit.IsOnHighGround) return 0f;
            return StackPower("HillRange") * .16f + StackPower("HillDominion") * .08f;
        }

        public float GetHighGroundDefenseBonus(PlayerUnit unit)
        {
            if (unit == null || !unit.IsOnHighGround) return 0f;
            return StackPower("HillGuard") * 6f + StackPower("HillDominion") * 6f;
        }

        public float GetHighGroundAttackDelayMultiplier(PlayerUnit unit)
        {
            if (unit == null || !unit.IsOnHighGround) return 1f;
            var speed = StackPower("HillTempo") * .06f + StackPower("HillDominion") * .04f;
            return 1f / (1f + speed);
        }

        private void UpdateBattleAugments()
        {
            var power = StackPower("Meteor");
            if (power <= 0f || Time.time < nextMeteorAt || enemies.Count == 0) return;

            EnemyUnit target = null;
            var progress = -1;
            foreach (var enemy in enemies)
                if (enemy != null && enemy.IsAlive && enemy.PathIndex > progress)
                {
                    target = enemy;
                    progress = enemy.PathIndex;
                }
            if (target != null)
            {
                DamageEnemies(target.Position, .84f + power * .08f, 45f + power * 22f, target,
                    null, DamageType.Magic);
                StartCoroutine(MeteorEffectRoutine(target.Position, .84f + power * .08f));
            }
            nextMeteorAt = Time.time + Mathf.Max(5.8f, 7.2f - power * .4f);
        }

        private float ActiveAugmentRemaining(string key) => activeAugmentReadyAt.TryGetValue(key, out var readyAt)
            ? Mathf.Max(0f, readyAt - Time.time)
            : 0f;

        private void UseActiveAugment(string key)
        {
            if (Phase != GamePhase.Battle || !activeAugmentReadyAt.ContainsKey(key)) return;
            var remaining = ActiveAugmentRemaining(key);
            if (remaining > 0f)
            {
                ShowToast(L($"재사용까지 {remaining:0.0}초", $"COOLDOWN {remaining:0.0}s"));
                return;
            }
            var power = StackPower(key);
            switch (key)
            {
                case "ActiveVolley":
                {
                    var target = FindEnemyInRange(GatePosition, 99f);
                    if (target == null)
                    {
                        ShowToast(L("화살 포화를 명령할 적이 없습니다.", "NO TARGET FOR ARROW BARRAGE."));
                        return;
                    }
                    voiceBarks?.Play(transform, 510, VoiceCue.Skill, .94f);
                    StartCoroutine(RoyalArrowBarrageRoutine(power));
                    ShowToast(L("왕실 화살 포화 명령", "ROYAL ARROW BARRAGE"));
                    activeAugmentReadyAt[key] = Time.time + 18f;
                    break;
                }
                case "ActiveFreeze":
                {
                    var duration = 1f + power * .20f;
                    voiceBarks?.Play(transform, 511, VoiceCue.Skill, .9f);
                    SpawnActiveSkillCrest(GatePosition + Vector2.down * 1.2f,
                        new Color(.36f, .88f, 1f), 1);
                    enemyActionsFrozenUntil = Mathf.Max(enemyActionsFrozenUntil, Time.time + duration);
                    foreach (var enemy in enemies)
                        if (enemy != null && enemy.IsAlive) enemy.ApplyTimeFreeze(duration);
                    ShowToast(L($"시간 고정 {duration:0.0}초", $"CLOCK STOP {duration:0.0}s"));
                    activeAugmentReadyAt[key] = Time.time + 25f;
                    break;
                }
                case "ActiveFortify":
                {
                    voiceBarks?.Play(transform, 512, VoiceCue.Skill, .92f);
                    SpawnActiveSkillCrest(GatePosition, new Color(.35f, 1f, .66f), 2);
                    var before = gateHealth;
                    gateHealth = Mathf.Min(GateMaxHealth, gateHealth + 42f + power * 20f);
                    var repaired = Mathf.RoundToInt(gateHealth - before);
                    ShowToast(repaired > 0
                        ? L($"성문 비상 수리 +{repaired}", $"EMERGENCY GATE REPAIR +{repaired}")
                        : L("성벽 내구도가 가득합니다.", "GATE DURABILITY IS FULL."));
                    activeAugmentReadyAt[key] = Time.time + 30f;
                    break;
                }
            }
        }

        private IEnumerator RoyalArrowBarrageRoutine(float power)
        {
            var living = enemies.Where(enemy => enemy != null && enemy.IsAlive).ToArray();
            if (living.Length == 0) yield break;
            var radius = 1.02f + power * .08f;
            var anchors = living
                .Select(candidate => new
                {
                    enemy = candidate,
                    score = living.Count(other => Vector2.Distance(candidate.Position, other.Position) <= radius) * 10f +
                            candidate.PathIndex * .025f + (candidate.IsBoss ? 3.5f : 0f)
                })
                .OrderByDescending(entry => entry.score)
                .ThenByDescending(entry => entry.enemy.PathIndex)
                .Select(entry => entry.enemy)
                .Aggregate(new List<EnemyUnit>(), (selected, candidate) =>
                {
                    if (selected.Count < 3 && selected.All(existing =>
                            Vector2.Distance(existing.Position, candidate.Position) >= radius * 1.25f))
                        selected.Add(candidate);
                    return selected;
                });
            if (anchors.Count == 0) anchors.Add(living[0]);
            foreach (var anchor in anchors)
                SpawnActiveSkillCrest(anchor.Position, new Color(1f, .66f, .16f), 0);
            yield return new WaitForSeconds(.44f);
            var damage = 76f + power * 30f;
            foreach (var anchor in anchors)
            {
                if (anchor == null || !anchor.IsAlive) continue;
                var impactPosition = anchor.Position;
                DamageEnemies(impactPosition, radius, damage, anchor, null, DamageType.Physical);
                yield return StartCoroutine(VolleyEffectRoutine(impactPosition, radius));
                yield return new WaitForSeconds(.08f);
            }
        }

        private void SpawnActiveSkillCrest(Vector2 position, Color color, int pattern)
        {
            activeSkillEffectCount++;
            StartCoroutine(ActiveCommandVfxRoutine(position, color, pattern));
        }

        private IEnumerator ActiveCommandVfxRoutine(Vector2 position, Color color, int pattern)
        {
            var root = TransientBattleEffect.Create(pattern switch
            {
                0 => "Royal Arrow Barrage Command Animation",
                1 => "Clock Stop Animation",
                _ => "Citadel Field Repair Animation"
            });
            root.transform.position = new Vector3(position.x, position.y, -4.42f);
            var frames = activeCommandVfxAnimations.TryGetValue(Mathf.Clamp(pattern, 0, 2), out var authored)
                ? authored
                : Array.Empty<Sprite>();
            if (frames.Length == 0)
                frames = Enumerable.Repeat(SparkSprite, ActiveCommandVfxFrameCount).ToArray();

            // The atlas already owns the command palette. Extra tinting amplifies any residual
            // chroma matte into a visible rectangular card on bright battlefields.
            var tint = Color.white;
            tint.a = 0f;
            var frameA = CreateSpriteChild(root.transform, "Active Command Frame A", frames[0], tint, 1f, 91);
            var frameB = CreateSpriteChild(root.transform, "Active Command Frame B",
                frames[Mathf.Min(1, frames.Length - 1)], tint, 1f, 92);
            var targetScale = ActiveCommandVfxScale(pattern);
            var duration = pattern == 0 ? 1.12f : 1.08f;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                if (root == null || frameA == null || frameB == null) yield break;
                var t = Mathf.Clamp01(elapsed / duration);
                var framePosition = t * (frames.Length - 1);
                var frameIndex = Mathf.Min(frames.Length - 1, Mathf.FloorToInt(framePosition));
                var nextIndex = Mathf.Min(frames.Length - 1, frameIndex + 1);
                var blend = Mathf.SmoothStep(0f, 1f, framePosition - frameIndex);
                frameA.sprite = frames[frameIndex];
                frameB.sprite = frames[nextIndex];
                var fadeIn = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(t / .06f));
                var fadeOut = 1f - Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((t - .82f) / .18f));
                var opacity = .98f * fadeIn * fadeOut;
                var colorA = tint;
                colorA.a = opacity * (nextIndex == frameIndex ? 1f : 1f - blend);
                frameA.color = colorA;
                var colorB = tint;
                colorB.a = nextIndex == frameIndex ? 0f : opacity * blend;
                frameB.color = colorB;
                var settle = Mathf.SmoothStep(0f, 1f, t);
                var scale = targetScale * Mathf.Lerp(.96f, 1.02f, settle);
                frameA.transform.localScale = frameB.transform.localScale = Vector3.one * scale;
                yield return null;
            }
            Destroy(root);
        }

        private static float ActiveCommandVfxScale(int pattern) => pattern switch
        {
            0 => 2.12f,
            1 => 2.52f,
            _ => 2.72f
        };

        private IEnumerator MeteorEffectRoutine(Vector2 impactPosition, float radius)
        {
            var effect = TransientBattleEffect.Create("Royal Meteor Effect");
            effect.transform.position = new Vector3(impactPosition.x, impactPosition.y, -4f);
            var meteor = CreateSpriteChild(effect.transform, "Meteor Core", GlowSprite,
                new Color(1f, .94f, .66f, 1f), .28f, 31);
            var shell = CreateSpriteChild(effect.transform, "Meteor Shell", CommandRingSprite,
                new Color(1f, .34f, .08f, .9f), .42f, 30);
            var trail = CreateSpriteChild(effect.transform, "Meteor Trail", GlowSprite,
                new Color(1f, .28f, .06f, .62f), 1f, 29);
            var sparks = new SpriteRenderer[9];
            for (var i = 0; i < sparks.Length; i++)
                sparks[i] = CreateSpriteChild(effect.transform, $"Meteor Ember {i}", SparkSprite,
                    i % 2 == 0 ? new Color(1f, .86f, .24f) : new Color(1f, .28f, .06f),
                    .07f + (i % 3) * .018f, 32);

            const float fallDuration = .24f;
            for (var elapsed = 0f; elapsed < fallDuration; elapsed += Time.deltaTime)
            {
                var t = Mathf.Clamp01(elapsed / fallDuration);
                var ease = t * t;
                var offset = new Vector2(Mathf.Lerp(-1.15f, 0f, ease), Mathf.Lerp(2.35f, 0f, ease));
                meteor.transform.localPosition = offset;
                shell.transform.localPosition = offset;
                shell.transform.Rotate(0f, 0f, Time.deltaTime * 520f);
                trail.transform.localPosition = offset + new Vector2(-.36f, .72f);
                trail.transform.localScale = new Vector3(.18f, Mathf.Lerp(1.65f, .46f, ease), 1f);
                trail.transform.localEulerAngles = new Vector3(0f, 0f, -27f);
                for (var i = 0; i < sparks.Length; i++)
                {
                    var emberT = Mathf.Repeat(t + i / (float)sparks.Length, 1f);
                    sparks[i].transform.localPosition = offset +
                        new Vector2(-.18f - i * .035f, .24f + emberT * .78f) +
                        Vector2.right * Mathf.Sin(i * 2.7f + t * 9f) * .12f;
                    var sc = sparks[i].color; sc.a = 1f - emberT; sparks[i].color = sc;
                }
                yield return null;
            }
            SpawnEnemySlam(impactPosition, Mathf.Max(.8f, radius), new Color(1f, .3f, .08f));
            SpawnCombatImpact(impactPosition, UnitArchetype.AreaMage, new Color(1f, .68f, .12f),
                Mathf.Max(.9f, radius));
            Destroy(effect);
        }

        private IEnumerator VolleyEffectRoutine(Vector2 impactPosition, float radius)
        {
            var effect = TransientBattleEffect.Create("Royal Volley Effect");
            effect.transform.position = new Vector3(impactPosition.x, impactPosition.y, -4f);
            var frames = CombatVfxAnimationFor(UnitArchetype.Archer, CombatVfxTier.Basic);
            if (frames.Length == 0)
                frames = Enumerable.Repeat(SparkSprite, CombatVfxFrameCount).ToArray();
            const int count = 16;
            var arrows = new SpriteRenderer[count];
            var starts = new Vector2[count];
            var ends = new Vector2[count];
            for (var i = 0; i < count; i++)
            {
                var angle = i * 2.399963f;
                var spread = Mathf.Lerp(.2f, radius * .62f, (i % 8) / 7f);
                ends[i] = new Vector2(Mathf.Cos(angle), Mathf.Sin(angle) * .55f) * spread;
                starts[i] = ends[i] + new Vector2(((i * 13) % 5 - 2) * .08f, 1.9f + i % 3 * .1f);
                arrows[i] = CreateSpriteChild(effect.transform, $"Signal Volley Arrow {i + 1}", frames[0],
                    i % 3 == 0 ? Color.white : new Color(1f, .68f, .18f), .46f, 30);
                var travel = ends[i] - starts[i];
                arrows[i].transform.localEulerAngles = new Vector3(0f, 0f,
                    Mathf.Atan2(travel.y, travel.x) * Mathf.Rad2Deg);
                arrows[i].transform.localPosition = starts[i];
            }
            const float readyDuration = .08f;
            const float fallDuration = .25f;
            const float impactDuration = .18f;
            const float duration = readyDuration + fallDuration + impactDuration;
            for (var elapsed = 0f; elapsed < duration; elapsed += Time.deltaTime)
            {
                if (effect == null) yield break;
                var ready = Mathf.Clamp01(elapsed / readyDuration);
                var fall = Mathf.Clamp01((elapsed - readyDuration) / fallDuration);
                var impact = Mathf.Clamp01((elapsed - readyDuration - fallDuration) / impactDuration);
                for (var i = 0; i < arrows.Length; i++)
                {
                    if (arrows[i] == null) yield break;
                    if (elapsed < readyDuration)
                    {
                        arrows[i].sprite = frames[Mathf.Min(1, frames.Length - 1)];
                        arrows[i].transform.localPosition = starts[i];
                        var readyColor = arrows[i].color;
                        readyColor.a = ready;
                        arrows[i].color = readyColor;
                        continue;
                    }
                    if (elapsed < readyDuration + fallDuration)
                    {
                        var eased = fall * fall * (3f - 2f * fall);
                        arrows[i].transform.localPosition = Vector2.Lerp(starts[i], ends[i], eased);
                        arrows[i].sprite = frames[Mathf.Clamp(Mathf.RoundToInt(Mathf.Lerp(1f, 4f, fall)),
                            0, frames.Length - 1)];
                        var fallColor = arrows[i].color;
                        fallColor.a = .96f;
                        arrows[i].color = fallColor;
                        continue;
                    }
                    arrows[i].transform.localPosition = ends[i];
                    arrows[i].sprite = frames[Mathf.Clamp(
                        Mathf.RoundToInt(Mathf.Lerp(5f, frames.Length - 1, impact)), 0, frames.Length - 1)];
                    arrows[i].transform.localScale = Vector3.one * Mathf.Lerp(.46f, .64f, impact);
                    var impactColor = arrows[i].color;
                    impactColor.a = .96f * (1f - Mathf.SmoothStep(.52f, 1f, impact));
                    arrows[i].color = impactColor;
                }
                yield return null;
            }
            Destroy(effect);
        }

        private IEnumerator FreezeWaveRoutine(Vector2 center, float holdDuration)
        {
            SpawnActiveSkillCrest(center, new Color(.36f, .88f, 1f), 1);
            yield return new WaitForSeconds(Mathf.Min(.92f, Mathf.Max(.1f, holdDuration)));
        }

        private IEnumerator FortifyBarrierRoutine(Vector2 center)
        {
            SpawnActiveSkillCrest(center, new Color(.35f, 1f, .66f), 2);
            yield return new WaitForSeconds(.92f);
        }

        public SpriteRenderer CreateSpriteChild(Transform parent, string objectName, Sprite sprite, Color color, float scale, int order)
        {
            var child = new GameObject(objectName);
            child.transform.SetParent(parent, false);
            child.transform.localScale = new Vector3(scale, scale, 1f);
            var renderer = child.AddComponent<SpriteRenderer>();
            renderer.sprite = sprite;
            renderer.color = color;
            renderer.sortingOrder = order;
            return renderer;
        }

        private static Sprite MakeCircleSprite(int size)
        {
            var texture = new Texture2D(size, size, TextureFormat.RGBA32, false) { name = "Runtime Circle" };
            var pixels = new Color[size * size];
            var center = (size - 1) * .5f;
            var radius = center - 1f;
            for (var y = 0; y < size; y++)
            for (var x = 0; x < size; x++)
            {
                var distance = Vector2.Distance(new Vector2(x, y), new Vector2(center, center));
                pixels[y * size + x] = new Color(1f, 1f, 1f, Mathf.Clamp01(radius - distance + 1f));
            }
            texture.SetPixels(pixels); texture.Apply();
            return Sprite.Create(texture, new Rect(0, 0, size, size), new Vector2(.5f, .5f), size);
        }

        private static Sprite MakeHalfRingSprite(int size, bool front)
        {
            var texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
                { name = front ? "Selection Front Arc" : "Selection Rear Arc" };
            var pixels = new Color[size * size];
            var center = (size - 1) * .5f;
            var outerRadius = center - 2f;
            var innerRadius = outerRadius - 8f;
            for (var y = 0; y < size; y++)
            for (var x = 0; x < size; x++)
            {
                var distance = Vector2.Distance(new Vector2(x, y), new Vector2(center, center));
                var outerAlpha = Mathf.Clamp01(outerRadius - distance + 1f);
                var innerAlpha = Mathf.Clamp01(distance - innerRadius + 1f);
                var correctHalf = front ? y < center + 1f : y >= center - 1f;
                pixels[y * size + x] = new Color(1f, 1f, 1f,
                    correctHalf ? outerAlpha * innerAlpha : 0f);
            }
            texture.SetPixels(pixels);
            texture.Apply();
            return Sprite.Create(texture, new Rect(0, 0, size, size), new Vector2(.5f, .5f), size);
        }

        private static Sprite MakeSoftRingSprite(int size)
        {
            var texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
            {
                name = "Soft Command Ring",
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp
            };
            var pixels = new Color[size * size];
            var center = (size - 1) * .5f;
            var radius = center - 3f;
            var lineCenter = radius * .82f;
            var halfWidth = Mathf.Max(2f, size * .035f);
            for (var y = 0; y < size; y++)
            for (var x = 0; x < size; x++)
            {
                var distance = Vector2.Distance(new Vector2(x, y), new Vector2(center, center));
                var bandDistance = Mathf.Abs(distance - lineCenter);
                var alpha = 1f - Mathf.SmoothStep(halfWidth * .25f, halfWidth, bandDistance);
                var edge = Mathf.Clamp01(radius - distance + 1f);
                pixels[y * size + x] = new Color(1f, 1f, 1f, alpha * edge);
            }
            texture.SetPixels(pixels);
            texture.Apply(false, true);
            return Sprite.Create(texture, new Rect(0, 0, size, size), new Vector2(.5f, .5f), size);
        }

        private static Sprite MakeRadialGlowSprite(int size)
        {
            var texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
            {
                name = "Runtime Radial Glow",
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp
            };
            var pixels = new Color[size * size];
            var center = (size - 1) * .5f;
            var radius = center - 1f;
            for (var y = 0; y < size; y++)
            for (var x = 0; x < size; x++)
            {
                var normalized = Vector2.Distance(new Vector2(x, y), new Vector2(center, center)) / radius;
                var alpha = Mathf.Pow(Mathf.Clamp01(1f - normalized), 2.35f);
                pixels[y * size + x] = new Color(1f, 1f, 1f, alpha);
            }
            texture.SetPixels(pixels);
            texture.Apply(false, true);
            return Sprite.Create(texture, new Rect(0, 0, size, size), new Vector2(.5f, .5f), size);
        }

        private static Sprite MakeSparkSprite(int size)
        {
            var texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
            {
                name = "Runtime Four Point Spark",
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp
            };
            var pixels = new Color[size * size];
            var center = (size - 1) * .5f;
            var radius = center - 2f;
            for (var y = 0; y < size; y++)
            for (var x = 0; x < size; x++)
            {
                var dx = Mathf.Abs(x - center) / radius;
                var dy = Mathf.Abs(y - center) / radius;
                var longRay = Mathf.Min(dx + dy * 5.8f, dy + dx * 5.8f);
                var diamond = dx + dy;
                var alpha = Mathf.Clamp01(1f - Mathf.Min(longRay, diamond * 1.65f));
                alpha = Mathf.SmoothStep(0f, 1f, alpha);
                pixels[y * size + x] = new Color(1f, 1f, 1f, alpha);
            }
            texture.SetPixels(pixels);
            texture.Apply(false, true);
            return Sprite.Create(texture, new Rect(0, 0, size, size), new Vector2(.5f, .5f), size);
        }

        private static Sprite MakeArrowheadSprite(int size)
        {
            var texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
            {
                name = "Runtime Razor Arrowhead",
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp
            };
            var pixels = new Color[size * size];
            var center = (size - 1) * .5f;
            for (var y = 0; y < size; y++)
            for (var x = 0; x < size; x++)
            {
                var nx = x / (float)(size - 1);
                var halfHeight = Mathf.Lerp(.42f, .015f, Mathf.InverseLerp(.12f, .92f, nx));
                var ny = Mathf.Abs((y - center) / Mathf.Max(1f, size - 1));
                var inside = nx >= .1f && nx <= .94f && ny <= halfHeight;
                var edge = inside ? Mathf.Clamp01((halfHeight - ny) * size * .38f) : 0f;
                pixels[y * size + x] = new Color(1f, 1f, 1f, edge);
            }
            texture.SetPixels(pixels);
            texture.Apply(false, true);
            return Sprite.Create(texture, new Rect(0, 0, size, size), new Vector2(.5f, .5f), size);
        }

        private static Sprite MakeArrowFeatherSprite(int size)
        {
            var texture = new Texture2D(size, size, TextureFormat.RGBA32, false)
            {
                name = "Runtime Split Arrow Fletching",
                filterMode = FilterMode.Bilinear,
                wrapMode = TextureWrapMode.Clamp
            };
            var pixels = new Color[size * size];
            var center = (size - 1) * .5f;
            for (var y = 0; y < size; y++)
            for (var x = 0; x < size; x++)
            {
                var nx = (x - center) / Mathf.Max(1f, center);
                var ny = Mathf.Abs((y - center) / Mathf.Max(1f, center));
                var vane = nx > -.72f && nx < .58f && ny > .12f &&
                           ny < Mathf.Lerp(.68f, .18f, Mathf.InverseLerp(-.72f, .58f, nx));
                pixels[y * size + x] = vane ? Color.white : Color.clear;
            }
            texture.SetPixels(pixels);
            texture.Apply(false, true);
            return Sprite.Create(texture, new Rect(0, 0, size, size), new Vector2(.5f, .5f), size);
        }

        private static Sprite MakeSquareSprite()
        {
            var texture = new Texture2D(2, 2, TextureFormat.RGBA32, false) { name = "Runtime Square" };
            texture.SetPixels(new[] { Color.white, Color.white, Color.white, Color.white }); texture.Apply();
            return Sprite.Create(texture, new Rect(0, 0, 2, 2), new Vector2(.5f, .5f), 2f);
        }

