        private void OnGUI()
        {
            var previousMatrix = GUI.matrix;
            GUI.matrix = Matrix4x4.Scale(new Vector3(UiScale, UiScale, 1f));
            SetupGuiStyles();
            if (HasCommandLineArgument("-qaBossGallery263"))
            {
                DrawQaBossGallery263();
                GUI.matrix = previousMatrix;
                return;
            }
            if (HasCommandLineArgument("-qaBossGallery259"))
            {
                DrawQaBossGallery259();
                GUI.matrix = previousMatrix;
                return;
            }
            if (showMainMenu)
            {
                var resumePromptVisible = showResumePrompt;
                var previousEnabled = GUI.enabled;
                if (resumePromptVisible) GUI.enabled = false;
                DrawMainMenu();
                GUI.enabled = previousEnabled;
                if (showSettings) DrawSettingsOverlay();
                if (showMissionPanel) DrawMissionOverlay();
                if (showShopPanel) DrawShopOverlay();
                if (showSkinPanel) DrawSkinVaultOverlay();
                if (showGuidePanel) DrawGuideOverlay();
                if (showExitConfirm) DrawExitConfirm();
                if (resumePromptVisible) DrawResumeRunPrompt();
                GUI.matrix = previousMatrix;
                return;
            }
            // Art capture runs without HUD occlusion so a visual regression cannot be hidden
            // behind the formation bar during automated review.
            if (HasCommandLineArgument("-qaArt") || HasCommandLineArgument("-qaProductionRoster"))
            {
                GUI.matrix = previousMatrix;
                return;
            }
            var returnSavePromptVisible = showReturnToMainMenuSavePrompt;
            var gameplayGuiEnabled = GUI.enabled;
            if (returnSavePromptVisible) GUI.enabled = false;
            DrawTopHud();
            DrawTacticalMiniMap();
            DrawBottomHud();
            if (showAugmentSummary && Phase != GamePhase.Augment) DrawAugmentSummary();
            DrawSelectedUnitStatus();
            DrawSelectedSquadPortraitRail();
            if (pointerHeld && pointerDragged && pressedUnit == null && buildMode == UnitArchetype.None) DrawSelectionBox();
            if (Time.unscaledTime < toastUntil)
            {
                var safe = SafeGuiRect;
                var selectedOffset = selectedUnits.Count == 1 && selectedUnits[0] != null
                    ? SelectedUnitStatusRect().height + 5f
                    : 0f;
                var rect = new Rect(safe.x + safe.width * .16f,
                    safe.yMax - BottomHudHeight - 47f - selectedOffset, safe.width * .68f, 36f);
                DrawOrnatePanel(rect, new Color(.025f, .04f, .085f, .96f), new Color(.5f, .62f, .8f), 2f);
                GUI.Label(rect, toastText, centeredStyle);
            }
            if (Time.unscaledTime < bossWarningUntil)
            {
                var safe = SafeGuiRect;
                var warningRect = new Rect(safe.x + safe.width * .15f, safe.y + TopHudHeight + 8f, safe.width * .7f, 44f);
                DrawOrnatePanel(warningRect, new Color(.16f, .025f, .045f, .97f), new Color(1f, .38f, .2f), 3f);
                GUI.Label(warningRect, bossWarningText, centeredStyle);
            }
            if (Phase == GamePhase.Augment)
            {
                if (augmentOverlayHidden) DrawAugmentRestoreButton();
                else DrawAugmentOverlay();
            }
            if (Phase == GamePhase.Defeat) DrawDefeatOverlay();
            if (Phase == GamePhase.Victory) DrawVictoryOverlay();
            if (showSystemMenu) DrawSystemMenu();
            if (showSettings) DrawSettingsOverlay();
            if (showMissionPanel) DrawMissionOverlay();
            if (showExitConfirm) DrawExitConfirm();
            GUI.enabled = gameplayGuiEnabled;
            if (returnSavePromptVisible) DrawReturnToMainMenuSavePrompt();
            GUI.matrix = previousMatrix;
        }

        private void DrawMainMenu()
