            if (DrawPremiumButton(new Rect(menuX, menuY + 133f, menuWidth, 38f), "게임 종료",
                    new Color(.04f, .045f, .075f, .94f), new Color(.5f, .54f, .66f), true))
                showExitConfirm = true;

            var versionRect = new Rect(safe.x + 18f, safe.yMax - 30f, safe.width * .55f, 22f);
            GUI.Label(versionRect, $"CROWNFRONT  ·  v{Application.version}", subStyle);
        }

        // This is a deliberately in-engine composition: the menu hero and invaders are the
        // exact textures used by the live units, not a look-alike title illustration.
        private void DrawToyfrontMainMenu()
        {
            DrawToyfrontMainMenuV4();
            return;
            var screen = new Rect(0f, 0f, GuiWidth, GuiHeight);
            if (mapTexture != null) GUI.DrawTexture(screen, mapTexture, ScaleMode.ScaleAndCrop, true);
            else DrawPanel(screen, new Color(.025f, .055f, .13f));
            // The menu is a view into the same battlefield, not a flat character catalogue.
            DrawPanel(screen, new Color(.005f, .018f, .055f, .24f));
            var safe = SafeGuiRect;
            var title = new GUIStyle(menuTitleStyle) { fontSize = 40, alignment = TextAnchor.MiddleCenter };
            var subtitle = new GUIStyle(menuSubtitleStyle) { fontSize = 13, alignment = TextAnchor.MiddleCenter };
            var titlePanel = new Rect(safe.center.x - Mathf.Min(300f, safe.width * .82f) * .5f, safe.y + 18f,
                Mathf.Min(300f, safe.width * .82f), 74f);
            DrawOrnatePanel(titlePanel, new Color(.025f, .045f, .095f, .82f), new Color(.89f, .73f, .33f, .88f), 2f);
            GUI.Label(new Rect(titlePanel.x + 10f, titlePanel.y + 6f, titlePanel.width - 20f, 43f), "CROWNFRONT", title);
            GUI.Label(new Rect(titlePanel.x + 12f, titlePanel.y + 46f, titlePanel.width - 24f, 20f),
                L("왕관을 향한 세 갈래 전선", "THREE ROADS TO THE CROWN"), subtitle);

            var hero = GetHeroSprite(UnitArchetype.Tank) ?? GetUnitCardSprite(UnitArchetype.Tank);
            var jellyFrames = GetEnemyAnimationFrames(EnemyClass.Melee);
            var mageFrames = GetEnemyAnimationFrames(EnemyClass.Mage);
            DrawSpriteInGui(hero, new Rect(safe.x + 8f, safe.y + safe.height * .34f, safe.width * .49f, safe.height * .39f), Color.white);
            if (jellyFrames.Length > 0)
            {
                DrawSpriteInGui(jellyFrames[0], new Rect(safe.xMax - safe.width * .37f, safe.y + safe.height * .38f, safe.width * .28f, safe.width * .28f), Color.white);
                if (jellyFrames.Length > 1)
                    DrawSpriteInGui(jellyFrames[1], new Rect(safe.xMax - safe.width * .24f, safe.y + safe.height * .55f, safe.width * .19f, safe.width * .19f), Color.white);
            }
            if (mageFrames.Length > 0)
                DrawSpriteInGui(mageFrames[0], new Rect(safe.xMax - safe.width * .25f, safe.y + safe.height * .27f, safe.width * .21f, safe.width * .21f), Color.white);

            DrawPanel(new Rect(0f, safe.yMax - 164f, GuiWidth, 164f), new Color(.008f, .018f, .045f, .74f));
            var actionWidth = Mathf.Min(312f, safe.width - 38f);
            var actionX = safe.center.x - actionWidth * .5f;
            var actionY = safe.yMax - 142f;
            if (DrawPremiumButton(new Rect(actionX, actionY, actionWidth, 60f), L("전선 시작", "START FRONT"),
                    new Color(.12f, .18f, .28f, .98f), new Color(.98f, .76f, .3f), true))
            {
                showMainMenu = false;
                voiceBarks?.SetBattleMusic(true, true);
                ShowToast(L("병사를 배치하고 전선을 지키세요.", "Place your guard and hold the front."));
            }
            var smallWidth = (actionWidth - 16f) * .5f;
            if (DrawPremiumButton(new Rect(actionX, actionY + 70f, smallWidth, 39f), L("도전 목록", "CHALLENGES"),
                    new Color(.04f, .08f, .14f, .96f), new Color(.42f, .67f, .87f), true)) showMissionPanel = true;
            if (DrawPremiumButton(new Rect(actionX + smallWidth + 16f, actionY + 70f, smallWidth, 39f), L("설정", "SETTINGS"),
                    new Color(.04f, .08f, .14f, .96f), new Color(.42f, .67f, .87f), true)) showSettings = true;
            GUI.Label(new Rect(safe.x, safe.yMax - 29f, safe.width, 20f),
                $"CROWNFRONT  ·  v{Application.version}", subtitle);
        }

