        private Texture2D ResolveEquippedMenuTexture()
        {
            if (monetization == null) return mainMenuTexture;
            return monetization.EquippedMenu switch
            {
                "crownfront.menu.sunrise" => mainMenuSunriseTexture ?? mainMenuTexture,
                "crownfront.menu.moonlit" => mainMenuMoonlitTexture ?? mainMenuTexture,
                _ => mainMenuTexture
            };
        }

        private void DrawToyfrontMainMenuV4Legacy()
        {
            var screen = new Rect(0f, 0f, GuiWidth, GuiHeight);
