            else DrawPanel(screen, new Color(.02f, .04f, .10f));
            var safe = SafeGuiRect;

            // One authored key-art scene replaces the previous runtime sprite arrangement.
            // All combat energy—shield pressure, enemy charge, rune blast, dust and impact—is
            // therefore visible as a single coherent illustration before a match begins.
            DrawCrownfrontKeyArtLogo(safe);

            var actionWidth = Mathf.Min(326f, safe.width - 34f);
            var actionX = safe.center.x - actionWidth * .5f;
            // Independent, equal action buttons: no enclosing menu box and the whole cluster
            // sits higher so it frames the key art rather than sagging into the lower edge.
            var actionY = safe.y + safe.height * .585f;
            if (DrawPremiumButton(new Rect(actionX, actionY, actionWidth, 56f), L("전선 출전", "PLAY FRONT"),
                    new Color(.21f, .13f, .035f, .98f), new Color(1f, .79f, .27f), true))
