                    new Color(.025f, .055f, .11f, .97f), new Color(.44f, .71f, .98f), true)) showMissionPanel = true;
            if (DrawPremiumButton(new Rect(actionX, actionY + 144f, smallWidth, 56f), L("게임 설정", "SETTINGS"),
                    new Color(.045f, .045f, .09f, .97f), new Color(.64f, .72f, .88f), true)) showSettings = true;
            GUI.Label(new Rect(safe.x, safe.yMax - 20f, safe.width, 15f), $"v{Application.version}",
