        private void DrawCrownfrontKeyArtLogo(Rect safe)
        {
            var width = Mathf.Min(505f, safe.width * 1.02f);
            var crest = new Rect(safe.center.x - width * .5f, safe.y + 1f, width, 248f);
            if (titleLogoSprite != null)
            {
                // The title is a finished crest illustration, not a generic font over a panel.
                DrawSpriteInGui(titleLogoSprite, crest, Color.white);
                return;
            }
            if (titleCrestSprite != null) DrawSpriteInGui(titleCrestSprite, crest, Color.white);
            else DrawOrnatePanel(crest, new Color(.018f, .028f, .075f, .88f), new Color(.92f, .72f, .25f, .94f), 3f);
            var title = new GUIStyle(menuTitleStyle)
            {
                fontSize = 52,
                alignment = TextAnchor.MiddleCenter,
                fontStyle = FontStyle.Bold
            };
            DrawOutlinedGuiLabel(new Rect(crest.x + 35f, crest.y + 108f, crest.width - 70f, 64f), "CROWNFRONT", title,
                new Color(.47f, .84f, 1f), new Color(.025f, .045f, .12f), 3f);
        }

        private void DrawToyfrontMainMenuV3()
        {
            var screen = new Rect(0f, 0f, GuiWidth, GuiHeight);
            if (mainMenuTexture != null) GUI.DrawTexture(screen, mainMenuTexture, ScaleMode.ScaleAndCrop, true);
            else DrawPanel(screen, new Color(.025f, .055f, .13f));
            var safe = SafeGuiRect;
            DrawPanel(screen, new Color(.008f, .016f, .045f, .18f));

            DrawCrownfrontLogo(safe);

            // This is a looping battle vignette, not a character catalogue.  The same combat
            // sprites used in play lunge, recoil, cast, and collide on the courtyard floor.
            var cycle = Mathf.Repeat(Time.unscaledTime, 1.55f) / 1.55f;
            var strike = Mathf.Sin(cycle * Mathf.PI);
            var lunge = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01(strike)) * safe.width * .075f;
            var floorY = safe.y + safe.height * .70f;
            var hero = GetHeroSprite(UnitArchetype.Tank) ?? GetUnitCardSprite(UnitArchetype.Tank);
            var archer = GetUnitCardSprite(UnitArchetype.Archer);
            var goblin = GetEnemyStaticSprite(EnemyClass.Runner, false);
            var skeleton = GetEnemyStaticSprite(EnemyClass.Skeleton, false);
            var mageGolem = GetEnemyStaticSprite(EnemyClass.Siege, false);

            DrawMenuSpriteWithShadow(hero, new Rect(safe.x + safe.width * .02f + lunge, floorY - safe.height * .43f,
                safe.width * .52f, safe.height * .43f), new Rect(safe.x + safe.width * .08f + lunge, floorY - 13f,
                safe.width * .35f, 15f));
            DrawMenuSpriteWithShadow(archer, new Rect(safe.x + safe.width * .31f + lunge * .35f, floorY - safe.height * .25f,
                safe.width * .20f, safe.height * .25f), new Rect(safe.x + safe.width * .35f, floorY - 9f,
                safe.width * .17f, 9f));
            DrawMenuSpriteWithShadow(goblin, new Rect(safe.x + safe.width * .55f - lunge * .24f, floorY - safe.height * .22f,
                safe.width * .22f, safe.height * .22f), new Rect(safe.x + safe.width * .59f, floorY - 9f,
                safe.width * .16f, 9f));
            DrawMenuSpriteWithShadow(skeleton, new Rect(safe.x + safe.width * .70f - lunge * .12f, floorY - safe.height * .25f,
                safe.width * .20f, safe.height * .25f), new Rect(safe.x + safe.width * .74f, floorY - 10f,
                safe.width * .15f, 10f));
            DrawMenuSpriteWithShadow(mageGolem, new Rect(safe.x + safe.width * .66f, floorY - safe.height * .43f,
                safe.width * .36f, safe.height * .43f), new Rect(safe.x + safe.width * .73f, floorY - 14f,
                safe.width * .25f, 14f));

            var clash = new Vector2(safe.x + safe.width * .55f + lunge * .25f, floorY - safe.height * .19f);
            DrawMenuCombatGlow(clash, .24f + strike * .15f, new Color(1f, .72f, .22f, .55f));
            if (strike > .18f)
            {
                DrawMenuSlash(new Rect(clash.x - 34f, clash.y - 4f, 68f, 5f), -30f, new Color(1f, .92f, .54f, strike));
                DrawMenuSlash(new Rect(clash.x - 29f, clash.y + 11f, 58f, 4f), 23f, new Color(1f, .5f, .15f, strike * .92f));
                DrawMenuSlash(new Rect(clash.x - 20f, clash.y - 18f, 40f, 3f), 63f, new Color(1f, .95f, .78f, strike * .78f));
            }
            var boltT = Mathf.Clamp01((cycle - .18f) / .66f);
            var boltStart = new Vector2(safe.x + safe.width * .82f, floorY - safe.height * .30f);
            var boltEnd = new Vector2(safe.x + safe.width * .44f, floorY - safe.height * .23f);
            var bolt = Vector2.Lerp(boltStart, boltEnd, boltT);
            DrawMenuCombatGlow(bolt, .11f + Mathf.Sin(Time.unscaledTime * 9f) * .025f, new Color(.74f, .28f, 1f, .8f));
            DrawMenuCombatGlow(new Vector2(bolt.x + 3f, bolt.y - 2f), .045f, Color.white);

            var actionWidth = Mathf.Min(314f, safe.width - 42f);
            var actionX = safe.center.x - actionWidth * .5f;
            var actionY = safe.y + safe.height * .765f;
            DrawOrnatePanel(new Rect(actionX - 11f, actionY - 10f, actionWidth + 22f, 123f),
                new Color(.006f, .014f, .042f, .76f), new Color(.82f, .66f, .28f, .82f), 2f);
            if (DrawPremiumButton(new Rect(actionX, actionY, actionWidth, 57f), L("플레이", "PLAY"),
                    new Color(.20f, .12f, .035f, .98f), new Color(1f, .78f, .26f), true))
            {
                showMainMenu = false;
                voiceBarks?.SetBattleMusic(true, true);
