        private static void DrawOutlinedGuiLabel(Rect rect, string text, GUIStyle style, Color fill, Color outline, float offset)
        {
            var previous = GUI.color;
            GUI.color = outline;
            for (var x = -1; x <= 1; x++)
            for (var y = -1; y <= 1; y++)
            {
                if (x == 0 && y == 0) continue;
                GUI.Label(new Rect(rect.x + x * offset, rect.y + y * offset, rect.width, rect.height), text, style);
            }
            GUI.color = fill;
            GUI.Label(rect, text, style);
            GUI.color = previous;
        }

