        private static void DrawSpriteInGui(Sprite sprite, Rect rect, Color tint)
        {
            DrawSpriteInGui(sprite, rect, tint, false);
        }

        private static void DrawSpriteInGui(Sprite sprite, Rect rect, Color tint, bool flipX)
        {
            if (sprite == null || sprite.texture == null) return;
            var texture = sprite.texture;
            var uv = sprite.textureRect;
            var aspect = uv.width / Mathf.Max(1f, uv.height);
            var drawWidth = rect.width;
            var drawHeight = drawWidth / Mathf.Max(.01f, aspect);
            if (drawHeight > rect.height)
            {
                drawHeight = rect.height;
                drawWidth = drawHeight * aspect;
            }
            rect = new Rect(rect.center.x - drawWidth * .5f, rect.yMax - drawHeight, drawWidth, drawHeight);
            var texCoords = new Rect(uv.x / texture.width, uv.y / texture.height,
                uv.width / texture.width, uv.height / texture.height);
            if (flipX)
            {
                texCoords.x += texCoords.width;
                texCoords.width = -texCoords.width;
            }
            var previous = GUI.color;
            GUI.color = tint;
            GUI.DrawTextureWithTexCoords(rect, texture, texCoords, true);
            GUI.color = previous;
        }

