            GUI.Label(new Rect(panel.x + 14f, panel.y + 13f, panel.width - 28f, 34f), "전투 메뉴", modalTitleStyle);
            var labels = new[] { "계속하기", "메인 메뉴", "설정", "게임 종료" };
            for (var i = 0; i < labels.Length; i++)
            {
                var rect = new Rect(panel.x + 18f, panel.y + 58f + i * 55f, panel.width - 36f, 45f);
