        private void DrawShopOverlay()
        {
            var screen = new Rect(0f, 0f, GuiWidth, GuiHeight);
            DrawPanel(screen, new Color(0f, 0f, .02f, .76f));
            var safe = SafeGuiRect;
            var width = Mathf.Min(388f, safe.width * .94f);
            var height = Mathf.Min(620f, safe.height * .91f);
            var panel = new Rect(safe.center.x - width * .5f, safe.center.y - height * .5f, width, height);
            DrawOrnatePanel(panel, new Color(.018f, .04f, .085f, .995f),
                new Color(.94f, .7f, .24f), 4f);
            DrawFittedLabel(new Rect(panel.x + 16f, panel.y + 12f, panel.width - 32f, 39f),
                L("왕실 상점", "ROYAL SHOP"), modalTitleStyle, 13);
            DrawFittedLabel(new Rect(panel.x + 18f, panel.y + 48f, panel.width - 36f, 20f),
                L("능력치 판매 없이 외형만 변경됩니다.", "COSMETICS ONLY · NO STAT POWER"),
                centeredStyle, 9);

            var categories = new[]
            {
                ShopCategory.Castle, ShopCategory.Unit, ShopCategory.MainMenu, ShopCategory.Utility
            };
            var labels = new[]
            {
                L("성", "CASTLE"), L("유닛", "UNITS"), L("메인", "MENU"), L("기능", "UTILITY")
            };
            var tabGap = 5f;
            var tabWidth = (panel.width - 32f - tabGap * 3f) / 4f;
            for (var i = 0; i < categories.Length; i++)
            {
                var selected = shopCategory == categories[i];
                var rect = new Rect(panel.x + 16f + i * (tabWidth + tabGap), panel.y + 77f, tabWidth, 38f);
                if (DrawPremiumButton(rect, labels[i],
                        selected ? new Color(.18f, .12f, .035f, .99f) : new Color(.035f, .065f, .12f, .99f),
                        selected ? new Color(1f, .76f, .24f) : new Color(.4f, .58f, .78f), true))
                {
                    shopCategory = categories[i];
                    shopScroll = Vector2.zero;
                }
            }

            if (monetization == null)
            {
                GUI.Label(new Rect(panel.x + 20f, panel.y + 150f, panel.width - 40f, 80f),
                    L("상점 서비스를 초기화하지 못했습니다.", "SHOP SERVICE IS UNAVAILABLE."), centeredStyle);
            }
            else
            {
                var visible = monetization.Products.Where(product => product.Category == shopCategory).ToArray();
                const float rowStep = 154f;
                var listRect = new Rect(panel.x + 10f, panel.y + 126f, panel.width - 20f, panel.height - 242f);
                var contentWidth = listRect.width - 18f;
                var contentHeight = Mathf.Max(listRect.height - 2f, visible.Length * rowStep);
                var blockProductClick = HandleShopTouchDrag(listRect, contentHeight);
                shopScroll = GUI.BeginScrollView(listRect, shopScroll,
                    new Rect(0f, 0f, contentWidth, contentHeight), false, true);
                for (var i = 0; i < visible.Length; i++)
                {
                    var product = visible[i];
                    var row = new Rect(4f, i * rowStep, contentWidth - 8f, 142f);
                    var owned = monetization.IsOwned(product.Id);
                    DrawOrnatePanel(row, new Color(.026f, .055f, .105f, .99f),
                        owned ? Color.Lerp(product.Accent, Color.white, .28f) : product.Accent, 3f);
                    DrawShopProductPreview(product, new Rect(row.x + 11f, row.y + 12f, 88f, 94f));
                    var nameRect = new Rect(row.x + 108f, row.y + 9f, row.width - 207f, 28f);
                    DrawFittedLabel(nameRect, product.Name,
                        new GUIStyle(smallStyle) { alignment = TextAnchor.MiddleLeft, fontStyle = FontStyle.Bold }, 10);
                    var descriptionStyle = new GUIStyle(statStyle)
                    {
                        alignment = TextAnchor.UpperLeft,
                        wordWrap = true,
                        fontSize = GameLocalization.English ? 11 : 12,
                        clipping = TextClipping.Clip
                    };
                    GUI.Label(new Rect(row.x + 108f, row.y + 39f, row.width - 120f, 55f),
                        product.Description, descriptionStyle);
                    var price = owned ? L("보유", "OWNED") : monetization.PriceFor(product);
                    DrawFittedLabel(new Rect(row.xMax - 94f, row.y + 10f, 82f, 25f), price, centeredStyle, 10);
                    var waitingForThisProduct = monetization.PurchaseInProgress &&
                                                monetization.LastRequestedProductId == product.Id;
                    var actionText = waitingForThisProduct ? L("처리 중…", "WAITING…") : product.Category == ShopCategory.Utility
                        ? owned ? L("적용됨", "ACTIVE") : L("구매", "BUY")
                        : owned ? L("보유", "OWNED") : L("구매", "BUY");
                    var actionEnabled = !owned && !blockProductClick && !waitingForThisProduct;
                    if (DrawPremiumButton(new Rect(row.xMax - 103f, row.yMax - 48f, 91f, 37f), actionText,
                            new Color(.08f, .075f, .12f, .99f), product.Accent, actionEnabled))
                    {
                        monetization.Purchase(product);
                    }
                    var skinState = owned && product.Category != ShopCategory.Utility
                        ? L("보유 · 스킨 보관함에서 선택", "OWNED · SELECT IN SKIN VAULT") :
                        product.Category == ShopCategory.Unit ? L("일반 · 영웅 외형 동시 변경", "BASE + HERO DESIGNS") :
                        product.Category == ShopCategory.Utility ? L("계정 영구 적용", "PERMANENT") :
                        L("실제 적용 외형 미리보기", "LIVE COSMETIC PREVIEW");
                    DrawFittedLabel(new Rect(row.x + 10f, row.yMax - 29f, row.width - 122f, 18f),
                        skinState, new GUIStyle(statStyle)
                        {
                            alignment = TextAnchor.MiddleLeft,
                            normal = { textColor = owned ? new Color(.46f, 1f, .72f) : new Color(.7f, .8f, .92f) }
                        }, 9);
                }
                GUI.EndScrollView();
            }
            var purchaseStatus = monetization?.PurchaseStatusMessage;
            if (!string.IsNullOrWhiteSpace(purchaseStatus))
            {
                DrawFittedLabel(new Rect(panel.x + 20f, panel.yMax - 106f, panel.width - 40f, 38f),
                    purchaseStatus, new GUIStyle(statStyle)
                    {
                        alignment = TextAnchor.MiddleCenter,
                        wordWrap = true,
                        normal = { textColor = monetization.PurchaseInProgress
                            ? new Color(1f, .84f, .36f) : new Color(.68f, .84f, 1f) }
                    }, 8);
            }
            if (DrawPremiumButton(new Rect(panel.x + 22f, panel.yMax - 62f, panel.width - 44f, 42f),
                    L("닫기", "CLOSE"), new Color(.06f, .075f, .11f, .98f),
                    new Color(.58f, .68f, .82f), true)) showShopPanel = false;
        }

        private bool HandleShopTouchDrag(Rect viewport, float contentHeight)
        {
            var evt = Event.current;
            var suppressProductClick = false;
            if (evt.type == EventType.MouseDown && evt.button == 0 && viewport.Contains(evt.mousePosition))
            {
                shopDragTracking = true;
                shopDragActive = false;
                shopDragStart = shopDragLast = evt.mousePosition;
            }
            else if (evt.type == EventType.MouseDrag && shopDragTracking)
            {
                if (!shopDragActive && Vector2.Distance(shopDragStart, evt.mousePosition) >= 7f)
                    shopDragActive = true;
                if (shopDragActive)
                {
                    var delta = evt.mousePosition - shopDragLast;
                    shopScroll.y = Mathf.Clamp(shopScroll.y - delta.y, 0f,
                        Mathf.Max(0f, contentHeight - viewport.height));
                    suppressProductClick = true;
                    evt.Use();
                }
                shopDragLast = evt.mousePosition;
            }
            else if (evt.type == EventType.MouseUp && shopDragTracking)
            {
                suppressProductClick = shopDragActive;
                shopDragTracking = false;
                shopDragActive = false;
                if (suppressProductClick) evt.Use();
            }
            return suppressProductClick || shopDragActive;
        }

        private void DrawShopProductPreview(CrownfrontShopProduct product, Rect rect)
        {
            DrawOrnatePanel(rect, new Color(.012f, .028f, .06f, .99f), product.Accent, 2f);
            var inner = new Rect(rect.x + 4f, rect.y + 4f, rect.width - 8f, rect.height - 8f);
            var previous = GUI.color;
            switch (product.Category)
            {
                case ShopCategory.Unit:
                {
                    var variant = product.Id.EndsWith(".b", StringComparison.Ordinal) ? 2 : 1;
                    var normalAnimation = GetAuthoredSkinAnimation(product.TargetUnit, variant, false);
                    var heroAnimation = GetAuthoredSkinAnimation(product.TargetUnit, variant, true);
                    if (normalAnimation != null && normalAnimation.Down.Length > 0 &&
                        heroAnimation != null && heroAnimation.Down.Length > 0)
                    {
                        canonicalSkinCardSprites.TryGetValue(
                            AuthoredSkinAnimationKey(product.TargetUnit, variant, false), out var normalCard);
                        canonicalSkinCardSprites.TryGetValue(
                            AuthoredSkinAnimationKey(product.TargetUnit, variant, true), out var heroCard);
                        DrawUnitSkinPairPreview(inner, product.TargetUnit, Color.white, Color.white,
                            product.Accent, 0, false,
                            normalCard ?? normalAnimation.Down[0], heroCard ?? heroAnimation.Down[0]);
                        break;
                    }
                    if (unitSkinReferenceTextures.TryGetValue(product.TargetUnit, out var authoredTexture) &&
                        authoredTexture != null)
                    {
                        DrawAuthoredSkinReferencePreview(inner, authoredTexture, variant, product.Accent);
                        break;
                    }
                    var normalTint = variant == 1
                        ? Color.Lerp(Color.white, product.Accent, .48f)
                        : Color.Lerp(new Color(.72f, .74f, .82f), product.Accent, .64f);
                    var heroTint = Color.Lerp(normalTint, Color.white, variant == 1 ? .2f : .34f);
                    DrawUnitSkinPairPreview(inner, product.TargetUnit, normalTint, heroTint,
                        product.Accent, variant);
                    break;
                }
                case ShopCategory.Castle:
                {
                    var castleTexture = product.Id == "crownfront.castle.azure"
                        ? castleAzureTexture
                        : product.Id == "crownfront.castle.ember" ? castleEmberTexture : mapTexture;
                    if (castleTexture != null)
                        GUI.DrawTextureWithTexCoords(inner, castleTexture,
                            new Rect(0f, .54f, 1f, .46f), true);
                    else DrawPanel(inner, new Color(.08f, .12f, .18f));
                    break;
                }
                case ShopCategory.MainMenu:
                {
                    var menuTexture = product.Id == "crownfront.menu.sunrise"
                        ? mainMenuSunriseTexture
                        : product.Id == "crownfront.menu.moonlit" ? mainMenuMoonlitTexture : mainMenuTexture;
                    if (menuTexture != null) GUI.DrawTexture(inner, menuTexture, ScaleMode.ScaleAndCrop, true);
                    else DrawPanel(inner, new Color(.06f, .09f, .16f));
                    break;
                }
                default:
                    DrawPanel(inner, new Color(.035f, .065f, .11f, 1f));
                    if (titleCrestSprite != null)
                        DrawSpriteInGui(titleCrestSprite, new Rect(inner.x + 12f, inner.y + 6f,
                            inner.width - 24f, inner.height * .58f), Color.white);
                    DrawFittedLabel(new Rect(inner.x + 4f, inner.yMax - 29f, inner.width - 8f, 23f),
                        L("광고 제거", "NO ADS"), new GUIStyle(centeredStyle)
                        {
                            fontStyle = FontStyle.Bold,
                            normal = { textColor = product.Accent }
                        }, 9);
                    break;
            }
            GUI.color = previous;
        }

        private void DrawArcherSkinReferencePreview(Rect rect, int variant)
        {
            if (archerSkinReferenceTexture != null)
                DrawAuthoredSkinReferencePreview(rect, archerSkinReferenceTexture, variant,
                    variant == 1 ? new Color(.74f, .44f, 1f) : new Color(1f, .82f, .24f));
        }

        private void DrawAuthoredSkinReferencePreview(Rect rect, Texture2D texture, int variant, Color accent)
        {
            DrawPanel(rect, Color.Lerp(new Color(.012f, .02f, .05f, .99f),
                new Color(accent.r, accent.g, accent.b, .99f), variant == 1 ? .1f : .14f));
            GUI.BeginGroup(rect);
            var local = new Rect(0f, 0f, rect.width, rect.height);
            var slots = SkinPairSlots(local);
            DrawMenuGroundShadow(new Rect(slots.normal.x + 3f, local.yMax - 12f,
                slots.normal.width - 6f, 9f));
            DrawMenuGroundShadow(new Rect(slots.hero.x + 3f, local.yMax - 12f,
                slots.hero.width - 6f, 9f));

            var normalUv = GetAuthoredSkinUv(texture, variant, false);
            var heroUv = GetAuthoredSkinUv(texture, variant, true);
            DrawTextureUvAspectFit(texture, slots.normal, normalUv, Color.white);
            DrawTextureUvAspectFit(texture, slots.hero, heroUv, Color.white);
            GUI.EndGroup();
        }

        private void DrawUnitSkinPairPreview(Rect rect, UnitArchetype archetype,
            Color normalTint, Color heroTint, Color accent, int variant, bool flipHero = false,
            Sprite overrideNormal = null, Sprite overrideHero = null)
        {
            GUI.BeginGroup(rect);
            var local = new Rect(0f, 0f, rect.width, rect.height);
            var slots = SkinPairSlots(local);
            if (variant > 0) DrawSkinPreviewOrnaments(local, accent, variant, archetype);
            DrawMenuGroundShadow(new Rect(slots.normal.x + 3f, local.yMax - 12f,
                slots.normal.width - 6f, 9f));
            DrawMenuGroundShadow(new Rect(slots.hero.x + 3f, local.yMax - 12f,
                slots.hero.width - 6f, 9f));

            var normal = overrideNormal != null ? overrideNormal : GetUnitCardSprite(archetype);
            var hero = overrideHero != null ? overrideHero : GetHeroSprite(archetype) ?? normal;
            if (variant > 0)
            {
                var outline = Color.Lerp(accent, Color.black, variant == 1 ? .28f : .12f);
                outline.a = .86f;
                DrawSpriteInGui(normal, ExpandPreviewSlot(slots.normal, 1.08f), outline);
                DrawSpriteInGui(hero, ExpandPreviewSlot(slots.hero, 1.08f), outline, flipHero);
            }
            DrawSpriteInGui(normal, slots.normal, normalTint);
            DrawSpriteInGui(hero, slots.hero, heroTint, flipHero);
            if (variant > 0)
            {
                DrawSkinCharacterEmblem(slots.normal, accent, variant, false, archetype);
                DrawSkinCharacterEmblem(slots.hero, accent, variant, true, archetype);
            }
            GUI.EndGroup();
        }

        private static (Rect normal, Rect hero) SkinPairSlots(Rect rect)
        {
            // Both figures use equal slots and one baseline. Their fixed 384x320 canvases
            // carry the only intentional size difference (220px normal / 260px hero), so source
            // crop proportions can no longer change the apparent height or foot position.
            var baseline = rect.yMax - 5f;
            var slotWidth = rect.width * .49f;
            var slotHeight = Mathf.Max(1f, rect.height - 8f);
            return (
                new Rect(rect.x + rect.width * .005f, baseline - slotHeight, slotWidth, slotHeight),
                new Rect(rect.xMax - slotWidth - rect.width * .005f, baseline - slotHeight, slotWidth, slotHeight)
            );
        }

        private static Rect ExpandPreviewSlot(Rect rect, float scale)
        {
            var width = rect.width * scale;
            var height = rect.height * scale;
            return new Rect(rect.center.x - width * .5f, rect.yMax - height, width, height);
        }

        private static void DrawTextureUvAspectFit(Texture2D texture, Rect slot, Rect uv, Color tint)
        {
            if (texture == null) return;
            var aspect = uv.width * texture.width /
                         Mathf.Max(1f, uv.height * texture.height);
            var width = slot.width;
            var height = width / Mathf.Max(.01f, aspect);
            if (height > slot.height)
            {
                height = slot.height;
                width = height * aspect;
            }
            var drawRect = new Rect(slot.center.x - width * .5f,
                slot.yMax - height, width, height);
            var previous = GUI.color;
            GUI.color = tint;
            GUI.DrawTextureWithTexCoords(drawRect, texture, uv, true);
            GUI.color = previous;
        }

        private void DrawSkinCharacterEmblem(Rect slot, Color accent, int variant,
            bool hero, UnitArchetype archetype)
        {
            if (SparkSprite == null) return;
            var caster = archetype is UnitArchetype.AreaMage or UnitArchetype.SingleMage or
                UnitArchetype.Druid or UnitArchetype.Oracle;
            var size = hero ? 15f : 11f;
            var color = hero
                ? Color.Lerp(accent, Color.white, .68f)
                : Color.Lerp(accent, variant == 1 ? Color.white : Color.black, .28f);
            DrawSpriteInGui(SparkSprite,
                new Rect(slot.center.x - size * .5f, slot.y + (hero ? 0f : 4f), size, size), color);
            if (hero && CommandRingSprite != null)
                DrawSpriteInGui(CommandRingSprite,
                    new Rect(slot.center.x - 13f, slot.y + (caster ? 8f : 12f), 26f, 12f),
                    new Color(accent.r, accent.g, accent.b, .74f));
        }

        private void DrawSkinPreviewOrnaments(Rect rect, Color accent, int variant, UnitArchetype archetype)
        {
            var secondary = variant == 1
                ? Color.Lerp(accent, Color.white, .72f)
                : Color.Lerp(accent, new Color(.04f, .03f, .08f), .68f);
            DrawPanel(new Rect(rect.x + 3f, rect.y + 5f, rect.width - 6f, rect.height - 10f),
                new Color(secondary.r, secondary.g, secondary.b, variant == 1 ? .12f : .22f));
            var crest = new Rect(rect.center.x - 8f, rect.y + 2f, 16f, 16f);
            if (SparkSprite != null) DrawSpriteInGui(SparkSprite, crest, secondary);
            if (CommandRingSprite != null)
            {
                var halo = variant == 1
                    ? new Color(accent.r, accent.g, accent.b, .3f)
                    : new Color(secondary.r, secondary.g, secondary.b, .42f);
                DrawSpriteInGui(CommandRingSprite,
                    new Rect(rect.xMax - rect.width * .56f, rect.y + 13f,
                        rect.width * .52f, rect.height * .62f), halo);
            }
            var caster = archetype is UnitArchetype.AreaMage or UnitArchetype.SingleMage or
                UnitArchetype.Druid or UnitArchetype.Oracle;
            var heavy = archetype is UnitArchetype.Tank or UnitArchetype.Melee or UnitArchetype.Lancer;
            if (SparkSprite != null)
            {
                var edgeHeight = heavy ? 28f : caster ? 22f : 25f;
                DrawSpriteInGui(SparkSprite,
                    new Rect(rect.x + 2f, rect.center.y - edgeHeight * .5f, 8f, edgeHeight), secondary);
                DrawSpriteInGui(SparkSprite,
                    new Rect(rect.xMax - 10f, rect.center.y - edgeHeight * .5f, 8f, edgeHeight), secondary);
            }
        }

