        private void DrawDefaultSkinPreview(ShopCategory category, UnitArchetype unit, Rect rect)
        {
            DrawOrnatePanel(rect, new Color(.012f, .028f, .06f, .99f),
                new Color(.55f, .66f, .82f), 2f);
            var inner = new Rect(rect.x + 4f, rect.y + 4f, rect.width - 8f, rect.height - 8f);
            switch (category)
            {
                case ShopCategory.Castle:
                    if (mapTexture != null)
                        GUI.DrawTextureWithTexCoords(inner, mapTexture, new Rect(0f, .69f, 1f, .31f), true);
                    break;
                case ShopCategory.MainMenu:
                    if (mainMenuTexture != null)
                        GUI.DrawTexture(inner, mainMenuTexture, ScaleMode.ScaleAndCrop, true);
                    break;
                default:
                    var normalPose = GetUnitCardSprite(unit);
                    var heroPose = GetHeroSprite(unit) ?? normalPose;
                    DrawUnitSkinPairPreview(inner, unit, Color.white, Color.white,
                        new Color(.55f, .66f, .82f), 0, false, normalPose, heroPose);
                    break;
            }
        }

        private void RefreshEquippedCosmetics()
        {
            ApplyCastleSkinAccent();
            foreach (var unit in units)
                if (unit != null) unit.RefreshCosmeticPresentation();
        }

