                    new Color(.05f, .09f, .15f, .98f), new Color(.48f, .7f, .9f), true)) showMissionPanel = false;
        }

        private void HandleChallengeTouchDrag(Rect viewport, float contentHeight)
        {
            // Android receives a dedicated Input.touch path in Update(). Consuming Unity's
            // touch-to-mouse compatibility event here as well would apply each drag twice.
            if (Application.isMobilePlatform) return;
            var evt = Event.current;
            if (evt.type == EventType.MouseDown && evt.button == 0 && viewport.Contains(evt.mousePosition))
            {
                challengeDragTracking = true;
                challengeDragActive = false;
                challengeDragStart = challengeDragLast = evt.mousePosition;
            }
            else if (evt.type == EventType.MouseDrag && challengeDragTracking)
            {
                if (!challengeDragActive && Vector2.Distance(challengeDragStart, evt.mousePosition) >= 7f)
                    challengeDragActive = true;
                if (!challengeDragActive) return;
                var delta = evt.mousePosition - challengeDragLast;
                ApplyChallengeDragDelta(delta.y, viewport, contentHeight);
                challengeDragLast = evt.mousePosition;
                evt.Use();
            }
            else if (evt.type == EventType.MouseUp && challengeDragTracking)
            {
                challengeDragTracking = false;
                challengeDragActive = false;
            }
        }

        private Rect CurrentChallengeViewportRect()
        {
            var safe = SafeGuiRect;
            var width = Mathf.Min(410f, safe.width * .96f);
            var height = Mathf.Min(640f, safe.height * .92f);
            var panel = new Rect(safe.center.x - width * .5f, safe.center.y - height * .5f,
                width, height);
            return new Rect(panel.x + 12f, panel.y + 78f, panel.width - 24f, panel.height - 143f);
        }

        private float ChallengeContentHeight(Rect viewport) =>
            Mathf.Max(viewport.height, BuildChallengeItems().Count * ChallengeRowStride);

        private void UpdateChallengeTouchInput()
        {
            if (!Application.isMobilePlatform || challengeTouchProcessedFrame == Time.frameCount) return;
            challengeTouchProcessedFrame = Time.frameCount;
            var viewport = CurrentChallengeViewportRect();
            var trackedTouchFound = false;
            for (var index = 0; index < Input.touchCount; index++)
            {
                var touch = Input.GetTouch(index);
                var guiPosition = ChallengeTouchToGuiPosition(touch.position);
                if (challengeTouchFingerId < 0 && touch.phase == TouchPhase.Began &&
                    viewport.Contains(guiPosition))
                {
                    challengeTouchFingerId = touch.fingerId;
                    challengeTouchLast = guiPosition;
                    trackedTouchFound = true;
                    continue;
                }
                if (touch.fingerId != challengeTouchFingerId) continue;
                trackedTouchFound = true;
                if (touch.phase is TouchPhase.Ended or TouchPhase.Canceled)
                {
                    challengeTouchFingerId = -1;
                    continue;
                }
                var delta = guiPosition - challengeTouchLast;
                challengeTouchLast = guiPosition;
                ApplyChallengeDragDelta(delta.y, viewport, ChallengeContentHeight(viewport));
            }
            if (challengeTouchFingerId >= 0 && !trackedTouchFound)
                challengeTouchFingerId = -1;
        }

        private Vector2 ChallengeTouchToGuiPosition(Vector2 screenPosition)
        {
            var scaleX = GuiWidth / Mathf.Max(1f, Screen.width);
            var scaleY = GuiHeight / Mathf.Max(1f, Screen.height);
            return new Vector2(screenPosition.x * scaleX, (Screen.height - screenPosition.y) * scaleY);
        }

        private void ApplyChallengeDragDelta(float guiDeltaY, Rect viewport, float contentHeight)
        {
            challengeScroll.y = Mathf.Clamp(challengeScroll.y - guiDeltaY, 0f,
                Mathf.Max(0f, contentHeight - viewport.height));
        }

        internal bool VerifyChallengeTouchScrollForQa()
        {
            var savedScroll = challengeScroll;
            var savedFingerId = challengeTouchFingerId;
            var viewport = new Rect(0f, 0f, 380f, 450f);
            var contentHeight = 48f * ChallengeRowStride;
            challengeScroll = Vector2.zero;
            ApplyChallengeDragDelta(-190f, viewport, contentHeight);
            var movedDown = Mathf.Abs(challengeScroll.y - 190f) < .01f;
            ApplyChallengeDragDelta(500f, viewport, contentHeight);
            var clampedTop = challengeScroll.y == 0f;
            ApplyChallengeDragDelta(-10000f, viewport, contentHeight);
            var max = contentHeight - viewport.height;
            var clampedBottom = Mathf.Abs(challengeScroll.y - max) < .01f;
            challengeScroll = savedScroll;
            challengeTouchFingerId = savedFingerId;
            return movedDown && clampedTop && clampedBottom && BuildChallengeItems().Count == 48;
        }

