        private void CompleteChallenge(string key)
        {
            if (!completedMissionKeys.Add(key)) return;
            PlayerPrefs.SetInt("Crownfront.Challenge." + key, 1);
            PlayerPrefs.Save();
            SavePortableProgressBackup();
        }

        private const float ChallengeRowHeight = 70f;
        private const float ChallengeRowStride = 78f;

        internal static Rect ChallengeTitleRectForQa(Rect row) =>
            new(row.x + 45f, row.y + 6f, Mathf.Max(40f, row.width - 123f), 22f);

        internal static Rect ChallengeDescriptionRectForQa(Rect row) =>
            new(row.x + 45f, row.y + 29f, Mathf.Max(40f, row.width - 123f), 34f);

        internal static Rect ChallengeStatusRectForQa(Rect row) =>
            new(row.xMax - 72f, row.y + 20f, 62f, 28f);

        private void DrawChallengeRow(Rect row, ChallengeItem item)
        {
            var complete = completedMissionKeys.Contains(item.Key);
            DrawFramedPanel(row, complete ? new Color(.035f, .115f, .105f, .98f) : new Color(.035f, .065f, .12f, .98f),
                complete ? new Color(.38f, .93f, .64f) : new Color(.38f, .56f, .76f), 2f);
            DrawPanel(new Rect(row.x + 10f, row.y + 21f, 25f, 25f),
                complete ? new Color(.3f, .92f, .58f) : new Color(.16f, .22f, .3f));
            GUI.Label(new Rect(row.x + 10f, row.y + 19f, 25f, 29f), complete ? "✓" : "·", centeredStyle);
            var titleStyle = new GUIStyle(smallStyle)
            {
                fontSize = 12, alignment = TextAnchor.MiddleLeft, clipping = TextClipping.Clip
            };
            var descriptionStyle = new GUIStyle(statStyle)
            {
                fontSize = 10, alignment = TextAnchor.UpperLeft, wordWrap = true,
                clipping = TextClipping.Clip
            };
            GUI.Label(ChallengeTitleRectForQa(row), item.Title, titleStyle);
            GUI.Label(ChallengeDescriptionRectForQa(row), item.Description, descriptionStyle);
            GUI.Label(ChallengeStatusRectForQa(row),
                complete ? L("완료", "DONE") : $"{Mathf.Min(item.Progress, item.Goal)}/{item.Goal}",
                new GUIStyle(centeredStyle) { fontSize = 10 });
        }

        private void DrawMissionRow(Rect panel, int index, string key, string title, int progress, int goal, int reward, string description)
        {
            var y = panel.y + 60f + index * 80f;
            var row = new Rect(panel.x + 15f, y, panel.width - 30f, 69f);
            var complete = progress >= goal;
            var claimed = completedMissionKeys.Contains(key);
            DrawFramedPanel(row, new Color(.035f, .07f, .125f, .98f), complete ? new Color(.45f, .95f, .68f) : new Color(.4f, .58f, .76f), 2f);
            GUI.Label(new Rect(row.x + 12f, row.y + 7f, row.width - 112f, 20f), title, smallStyle);
            GUI.Label(new Rect(row.x + 12f, row.y + 29f, row.width - 112f, 25f), $"{description}  {progress}/{goal}", statStyle);
            var rewardLabel = key == "skills" ? $"+{reward} HP" : $"+{reward} ●";
            if (DrawPremiumButton(new Rect(row.xMax - 96f, row.y + 14f, 82f, 39f), claimed ? L("완료", "DONE") : rewardLabel,
                    new Color(.08f, .13f, .18f, .98f), complete && !claimed ? new Color(.98f, .76f, .27f) : new Color(.34f, .4f, .48f), complete && !claimed))
            {
                completedMissionKeys.Add(key);
                if (key == "skills") gateHealth = Mathf.Min(GateMaxHealth, gateHealth + reward);
                else Money += reward;
            }
        }

        private void DrawTopHud()
        {
            var safe = SafeGuiRect;
            const float margin = 8f;
            const float chipHeight = 44f;
            var chipWidth = Mathf.Clamp(safe.width * .14f, 86f, 104f);
            var roundRect = new Rect(safe.x + margin, safe.y + margin, chipWidth, chipHeight);
            var coinRect = new Rect(roundRect.xMax + 6f, margin, chipWidth, chipHeight);
            coinRect.y = safe.y + margin;
            var bossRound = Round % 5 == 0;
            DrawOrnatePanel(roundRect,
                bossRound ? new Color(.24f, .025f, .035f, .98f) : new Color(.025f, .045f, .09f, .97f),
                bossRound ? new Color(1f, .22f, .18f) : new Color(.37f, .59f, .88f), bossRound ? 3f : 2f);
            DrawOrnatePanel(coinRect, new Color(.025f, .045f, .09f, .97f), new Color(.89f, .68f, .24f), 2f);
            GUI.Label(roundRect, bossRound ? $"BOSS {Round}" : $"ROUND {Round}", centeredStyle);
            GUI.Label(coinRect, $"●  {Money}", centeredStyle);

            var buttonWidth = Mathf.Clamp(safe.width * .145f, 88f, 106f);
            var augmentRect = new Rect(safe.xMax - margin - buttonWidth, safe.y + margin, buttonWidth, chipHeight);
            var formationRect = new Rect(augmentRect.x - buttonWidth - 7f, margin, buttonWidth, chipHeight);
            formationRect.y = safe.y + margin;
            if (DrawPremiumButton(formationRect, L("▦ 편성", "▦ ROSTER"),
                    showFormationPanel ? new Color(.18f, .13f, .055f, .98f) : new Color(.035f, .065f, .12f, .98f),
                    showFormationPanel ? new Color(.95f, .72f, .26f) : new Color(.38f, .56f, .8f),
                    Phase == GamePhase.Preparation))
            {
                showFormationPanel = !showFormationPanel;
                if (showFormationPanel) showAugmentSummary = false;
            }
            if (DrawPremiumButton(augmentRect, L("◆ 증강", "◆ AUGMENTS"),
                    showAugmentSummary ? new Color(.11f, .065f, .16f, .98f) : new Color(.045f, .055f, .11f, .98f),
                    showAugmentSummary ? new Color(.74f, .52f, .98f) : new Color(.52f, .46f, .72f)))
            {
                showAugmentSummary = !showAugmentSummary;
                if (showAugmentSummary) showFormationPanel = false;
            }

            var gateRect = new Rect(safe.x + safe.width * .14f, safe.y + 61f, safe.width * .72f, 40f);
            DrawOrnatePanel(gateRect, new Color(.025f, .035f, .07f, .97f), new Color(.88f, .69f, .3f), 2f);
            var fillColor = gateHealth / GateMaxHealth > .5f
                ? new Color(.25f, .86f, .58f, .95f)
                : gateHealth / GateMaxHealth > .2f
                    ? new Color(1f, .72f, .2f, .95f)
                    : new Color(1f, .25f, .22f, .95f);
            var fillRect = new Rect(gateRect.x + 5f, gateRect.y + 5f,
                (gateRect.width - 10f) * gateHealth / GateMaxHealth, gateRect.height - 10f);
            DrawPanel(fillRect, fillColor);
            for (var i = 1; i < 10; i++)
                DrawPanel(new Rect(gateRect.x + gateRect.width * i / 10f, gateRect.y + 5f, 1.5f, gateRect.height - 10f),
                    new Color(.02f, .03f, .06f, .36f));
            GUI.Label(gateRect, L($"왕성 성문 내구도  {Mathf.CeilToInt(gateHealth)} / {GateMaxHealth:0}",
                $"CITADEL GATE  {Mathf.CeilToInt(gateHealth)} / {GateMaxHealth:0}"), centeredStyle);

            var boss = FindBoss();
            if (boss == null) return;
            var bossRect = new Rect(safe.x + safe.width * .1f, safe.y + 107f, safe.width * .8f, 34f);
            DrawOrnatePanel(bossRect, new Color(.07f, .025f, .085f, .97f), new Color(.69f, .29f, .86f), 2f);
            DrawPanel(new Rect(bossRect.x + 4f, bossRect.y + 4f,
                (bossRect.width - 8f) * boss.HealthRatio, bossRect.height - 8f),
                boss.HealthRatio > .5f ? new Color(.75f, .16f, .86f) : new Color(1f, .18f, .18f));
            var shieldText = boss.Barrier > 0f
                ? L($" · 방벽 {Mathf.CeilToInt(boss.Barrier)}", $" · BARRIER {Mathf.CeilToInt(boss.Barrier)}")
                : string.Empty;
            GUI.Label(bossRect, L($"보스  {Mathf.CeilToInt(boss.Health)} / {Mathf.CeilToInt(boss.MaxHealth)}{shieldText} · {boss.BossSkillLabel}",
                    $"BOSS  {Mathf.CeilToInt(boss.Health)} / {Mathf.CeilToInt(boss.MaxHealth)}{shieldText} · {boss.BossSkillLabel}"),
                statStyle);
            GUI.Label(new Rect(bossRect.x, bossRect.yMax + 2f, bossRect.width, 22f),
                L($"패시브 · {boss.BossPassiveLabel}", $"PASSIVE · {boss.BossPassiveLabel}"), statStyle);
        }

        private void DrawTacticalMiniMap()
        {
            if (mapTexture == null || gameCamera == null) return;
            var frame = TacticalMiniMapRect();
            var content = TacticalMiniMapContentRect();
            DrawOrnatePanel(frame, new Color(.012f, .028f, .055f, .94f), new Color(.52f, .69f, .88f, .9f), 2f);
            GUI.DrawTexture(content, mapTexture, ScaleMode.StretchToFill, true);
            DrawPanel(content, new Color(.01f, .025f, .07f, .12f));

            var keep = MapToMiniMap(GatePosition, content);
            DrawPanel(new Rect(keep.x - 2.5f, keep.y - 2.5f, 5f, 5f), new Color(1f, .77f, .24f, .98f));
            foreach (var unit in units)
                if (unit != null && unit.IsAlive)
                    DrawMiniMapDot(MapToMiniMap(unit.Position, content), new Color(.32f, .85f, 1f, .98f), 3.3f);
            foreach (var enemy in enemies)
                if (enemy != null && enemy.IsAlive)
                    DrawMiniMapDot(MapToMiniMap(enemy.Position, content), new Color(1f, .34f, .32f, .98f), enemy.IsBoss ? 5f : 3.1f);

            var halfHeight = gameCamera.orthographicSize;
            var halfWidth = halfHeight * Mathf.Max(.32f, Screen.width / (float)Mathf.Max(1, Screen.height));
            var lower = MapToMiniMap(cameraMapCenter - new Vector2(halfWidth, halfHeight), content);
            var upper = MapToMiniMap(cameraMapCenter + new Vector2(halfWidth, halfHeight), content);
            var cameraRect = Rect.MinMaxRect(Mathf.Min(lower.x, upper.x), Mathf.Min(lower.y, upper.y),
                Mathf.Max(lower.x, upper.x), Mathf.Max(lower.y, upper.y));
            DrawMiniMapFrame(cameraRect, new Color(.95f, .98f, 1f, .9f));
            GUI.Label(new Rect(frame.x + 2f, frame.y + 1f, frame.width - 4f, 16f), "MAP", new GUIStyle(statStyle)
            {
                fontSize = 9,
                normal = { textColor = new Color(.94f, .97f, 1f, .92f) }
            });
        }

        private static Vector2 MapToMiniMap(Vector2 world, Rect content)
        {
            var u = Mathf.InverseLerp(-MapWidth * .5f, MapWidth * .5f, world.x);
            var v = Mathf.InverseLerp(MapHeight * .5f, -MapHeight * .5f, world.y);
            return new Vector2(Mathf.Lerp(content.xMin, content.xMax, u), Mathf.Lerp(content.yMin, content.yMax, v));
        }

        private void DrawMiniMapDot(Vector2 position, Color color, float size)
        {
            var rect = new Rect(position.x - size * .5f, position.y - size * .5f, size, size);
            GUI.DrawTexture(rect, CircleSprite.texture, ScaleMode.StretchToFill, true, 0f, color, 0f, 0f);
        }

        private void DrawMiniMapFrame(Rect rect, Color color)
        {
            const float thickness = 1.25f;
            DrawPanel(new Rect(rect.xMin, rect.yMin, rect.width, thickness), color);
            DrawPanel(new Rect(rect.xMin, rect.yMax - thickness, rect.width, thickness), color);
            DrawPanel(new Rect(rect.xMin, rect.yMin, thickness, rect.height), color);
            DrawPanel(new Rect(rect.xMax - thickness, rect.yMin, thickness, rect.height), color);
        }

        private void DrawBottomHud()
        {
            var safe = SafeGuiRect;
            if (showFormationPanel && Phase == GamePhase.Preparation)
            {
                var panel = new Rect(safe.x + 7f, safe.yMax - 174f, safe.width - 14f, 103f);
                DrawOrnatePanel(panel, new Color(.02f, .035f, .075f, .97f), new Color(.28f, .46f, .68f), 2f);
                var kinds = new List<UnitArchetype>
                {
                    UnitArchetype.Tank, UnitArchetype.Melee, UnitArchetype.Archer,
                    UnitArchetype.AreaMage, UnitArchetype.SingleMage
                };
                if (IsUnitUnlocked(UnitArchetype.Bombardier)) kinds.Add(UnitArchetype.Bombardier);
                if (IsUnitUnlocked(UnitArchetype.Lancer)) kinds.Add(UnitArchetype.Lancer);
                if (IsUnitUnlocked(UnitArchetype.Druid)) kinds.Add(UnitArchetype.Druid);
                if (IsUnitUnlocked(UnitArchetype.Musketeer)) kinds.Add(UnitArchetype.Musketeer);
                if (IsUnitUnlocked(UnitArchetype.Oracle)) kinds.Add(UnitArchetype.Oracle);
                const int pageSize = 6;
                const float gap = 4f;
                var maxFirst = Mathf.Max(0, kinds.Count - pageSize);
                formationPage = Mathf.Clamp(formationPage, 0, maxFirst);
                var first = formationPage;
                var shown = Mathf.Min(pageSize, kinds.Count - first);
                var hasCarousel = maxFirst > 0;
                var arrowWidth = hasCarousel ? 33f : 0f;
                var cardWidth = (panel.width - arrowWidth * 2f - gap * (shown + 1f)) / shown;
                if (hasCarousel && DrawPremiumButton(
                        new Rect(panel.x + 3f, panel.center.y - 25f, 28f, 50f), "<",
                        new Color(.035f, .055f, .1f, .98f), new Color(.42f, .68f, .96f), true))
                    formationPage = formationPage <= 0 ? maxFirst : formationPage - 1;
                if (hasCarousel && DrawPremiumButton(
                        new Rect(panel.xMax - 31f, panel.center.y - 25f, 28f, 50f), ">",
                        new Color(.035f, .055f, .1f, .98f), new Color(.42f, .68f, .96f), true))
                    formationPage = formationPage >= maxFirst ? 0 : formationPage + 1;
                for (var i = 0; i < shown; i++)
                {
                    var rect = new Rect(panel.x + arrowWidth + gap + i * (cardWidth + gap), panel.y + 6f,
                        cardWidth, panel.height - 12f);
                    DrawUnitCard(kinds[first + i], rect);
                }
            }

            var actionY = safe.yMax - 66f;
            if (Phase == GamePhase.Battle && activeAugmentReadyAt.Count > 0)
            {
                var skillY = actionY - 52f;
                var keys = new[] { "ActiveVolley", "ActiveFreeze", "ActiveFortify" };
                var shown = new List<string>();
                foreach (var key in keys)
                    if (activeAugmentReadyAt.ContainsKey(key)) shown.Add(key);
                var width = Mathf.Min(138f, (safe.width - 20f) / Mathf.Max(1, shown.Count));
                for (var i = 0; i < shown.Count; i++)
                {
                    var key = shown[i];
                    var remaining = ActiveAugmentRemaining(key);
                    var label = key switch
                    {
                        "ActiveVolley" => L("화살 포화", "ARROW BARRAGE"),
                        "ActiveFreeze" => L("시간 고정", "CLOCK STOP"),
                        _ => L("성문 수리", "GATE REPAIR")
                    };
                    if (remaining > 0f) label += $"\n{remaining:0}s";
                    var rect = new Rect(safe.center.x - shown.Count * width * .5f + i * width + 3f,
                        skillY, width - 6f, 44f);
                    if (DrawPremiumButton(rect, label,
                            remaining > 0f ? new Color(.05f, .07f, .11f, .94f) : new Color(.1f, .065f, .17f, .98f),
                            remaining > 0f ? new Color(.38f, .44f, .56f) : new Color(.82f, .55f, 1f), remaining <= 0f))
                        UseActiveAugment(key);
                }
            }
            GetBottomActionRects(actionY, out var leftRect, out var stopRect, out var undoRect,
                out var waveRect);
            var leftLabel = buildMode != UnitArchetype.None
                ? L("배치 취소", "CANCEL")
                : selectedUnits.Count > 0 ? L("선택 해제", "DESELECT") : L("▦ 편성", "▦ ROSTER");
            if (DrawPremiumButton(leftRect, leftLabel, new Color(.045f, .065f, .1f, .98f),
                    new Color(.48f, .6f, .76f)))
            {
                if (buildMode != UnitArchetype.None) CancelBuildMode();
                else if (selectedUnits.Count > 0) ClearSelection();
                else if (Phase == GamePhase.Preparation) showFormationPanel = !showFormationPanel;
            }
            var allSelectedHeld = selectedUnits.Count > 0 &&
                                  selectedUnits.TrueForAll(unit => unit != null && unit.IsHoldingPosition);
            if (DrawPremiumButton(stopRect, allSelectedHeld ? L("Ⅱ 정지 중", "Ⅱ HOLDING") : L("Ⅱ 정지", "Ⅱ HOLD"),
                    allSelectedHeld ? new Color(.16f, .095f, .025f, .98f) : new Color(.055f, .075f, .075f, .98f),
                    allSelectedHeld ? new Color(1f, .68f, .18f) : new Color(.48f, .64f, .54f),
                    selectedUnits.Count > 0)) StopSelected();
            if (Phase == GamePhase.Preparation && DrawPlacementUndoButton(undoRect,
                    CanUndoCurrentRoundPlacement))
                UndoLastCurrentRoundPlacement();
            var waveLabel = Phase switch
            {
                GamePhase.Preparation => L("✦ 웨이브 시작", "✦ START WAVE"),
                GamePhase.Battle => L("전투 진행", "BATTLE"),
                GamePhase.Augment => L("◆ 증강 선택", "◆ AUGMENT"),
                _ => L("패배", "DEFEAT")
            };
            var waveReady = Phase == GamePhase.Preparation;
            if (DrawPremiumButton(waveRect, waveLabel,
                    waveReady ? new Color(.18f, .075f, .035f, .98f) : new Color(.06f, .065f, .08f, .98f),
                    waveReady ? new Color(.96f, .51f, .21f) : new Color(.32f, .36f, .44f), waveReady))
                StartWave();
        }

        private bool DrawPlacementUndoButton(Rect rect, bool enabled)
        {
            DrawOrnatePanel(rect,
                enabled ? new Color(.035f, .075f, .125f, .98f) : new Color(.045f, .052f, .065f, .94f),
                enabled ? new Color(.44f, .78f, 1f) : new Color(.22f, .25f, .3f), 2f);
            var clicked = GUI.Button(rect, GUIContent.none, GUIStyle.none);
            if (placementUndoIcon != null)
            {
                var previous = GUI.color;
                GUI.color = enabled ? Color.white : new Color(.42f, .45f, .5f, .72f);
                // This icon is authored for the final mobile footprint. Four-pixel insets preserve
                // the ornate button frame without shrinking the arrow into illegibility.
                GUI.DrawTexture(new Rect(rect.x + 4f, rect.y + 4f, rect.width - 8f, rect.height - 8f),
                    placementUndoIcon, ScaleMode.ScaleToFit, true);
                GUI.color = previous;
            }
            else
            {
                DrawFittedLabel(new Rect(rect.x + 6f, rect.y + 5f, rect.width - 12f, rect.height - 10f),
                    "↶", premiumButtonLabelStyle, 18);
            }
            return enabled && clicked;
        }

        private void DrawUnitCard(UnitArchetype kind, Rect rect)
        {
            var definition = definitions[kind];
            var affordable = Money >= definition.Cost;
            var cardAccent = buildMode == kind
                ? new Color(.98f, .76f, .22f)
                : affordable ? new Color(.34f, .52f, .76f) : new Color(.22f, .25f, .3f);
            DrawOrnatePanel(rect, affordable ? new Color(.035f, .055f, .105f, .98f) : new Color(.04f, .045f, .055f, .98f),
                cardAccent, 2f);
            if (GUI.Button(rect, GUIContent.none, GUIStyle.none))
            {
                buildMode = buildMode == kind ? UnitArchetype.None : kind;
                ClearSelection();
                ShowToast(buildMode == UnitArchetype.None
                    ? L("배치 취소", "DEPLOYMENT CANCELLED")
                    : L($"{definition.Name} 배치", $"DEPLOY {definition.Name}"));
            }
            var skinVariant = GetUnitSkinVariant(kind);
            var sprite = GetEquippedUnitCardSprite(kind);
            if (sprite != null)
            {
                var previousColor = GUI.color;
                GUI.color = skinVariant > 0 ? Color.white : GetUnitSpriteTint(kind);
                DrawSpriteContained(new Rect(rect.x + 5f, rect.y + 3f,
                    rect.width - 10f, rect.height - 32f), sprite);
                GUI.color = previousColor;
            }
            var priceRect = new Rect(rect.x + 2f, rect.yMax - 28f, rect.width - 4f, 26f);
            DrawPanel(priceRect, new Color(.02f, .035f, .08f, .78f));
            GUI.Label(priceRect, $"● {definition.Cost}", centeredStyle);
        }

        private static void DrawSpriteContained(Rect bounds, Sprite sprite)
        {
            if (sprite == null || sprite.texture == null) return;
            try
            {
                var textureRect = SpriteGuiOpaquePixelRect(sprite);
                var spriteAspect = textureRect.width / Mathf.Max(1f, textureRect.height);
                var boundsAspect = bounds.width / Mathf.Max(1f, bounds.height);
                var draw = new Rect(bounds.x + 1f, bounds.y + 1f,
                    Mathf.Max(1f, bounds.width - 2f), Mathf.Max(1f, bounds.height - 2f));
                if (spriteAspect > boundsAspect)
                {
                    draw.height = bounds.width / spriteAspect;
                    draw.y = bounds.center.y - draw.height * .5f;
                }
                else
                {
                    draw.width = bounds.height * spriteAspect;
                    draw.x = bounds.center.x - draw.width * .5f;
                }
                var uv = new Rect(textureRect.x / sprite.texture.width, textureRect.y / sprite.texture.height,
                    textureRect.width / sprite.texture.width, textureRect.height / sprite.texture.height);
                GUI.DrawTextureWithTexCoords(draw, sprite.texture, uv, true);
            }
            catch (System.Exception exception)
            {
                // A non-readable runtime portrait must never abort the whole IMGUI pass.  On
                // Android that previously left a blank boss card and prevented the Close button
                // below it from being drawn. Text and modal controls remain functional even if a
                // single optional portrait fails.
                Debug.LogWarning($"Portrait draw skipped for {sprite.name}: {exception.GetType().Name}");
            }
        }

        private static Rect SpriteGuiOpaquePixelRect(Sprite sprite)
        {
            if (sprite == null || sprite.texture == null) return new Rect(0f, 0f, 1f, 1f);
            if (GuiOpaqueUvCache.TryGetValue(sprite, out var cached)) return cached;
            var textureRect = sprite.textureRect;
            var textureName = sprite.texture.name ?? string.Empty;
            if (textureName.Contains("-canonical-card-", StringComparison.Ordinal))
            {
                var width = CanonicalCardMetric(textureName, "-w");
                var height = CanonicalCardMetric(textureName, "-h");
                var baseline = CanonicalCardMetric(textureName, "-b");
                if (width > 0 && height > 0 && baseline >= 0)
                {
                    cached = new Rect(textureRect.x + (textureRect.width - width) * .5f,
                        textureRect.y + baseline, width, height);
                    GuiOpaqueUvCache[sprite] = cached;
                    return cached;
                }
            }
            try
            {
                var pixels = sprite.texture.GetPixels32();
                var textureWidth = sprite.texture.width;
                var left = Mathf.Clamp(Mathf.FloorToInt(textureRect.xMin), 0, textureWidth - 1);
                var right = Mathf.Clamp(Mathf.CeilToInt(textureRect.xMax), left + 1, textureWidth);
                var bottom = Mathf.Clamp(Mathf.FloorToInt(textureRect.yMin), 0, sprite.texture.height - 1);
                var top = Mathf.Clamp(Mathf.CeilToInt(textureRect.yMax), bottom + 1, sprite.texture.height);
                var minX = right;
                var minY = top;
                var maxX = left - 1;
                var maxY = bottom - 1;
                for (var y = bottom; y < top; y++)
                for (var x = left; x < right; x++)
                {
                    if (pixels[y * textureWidth + x].a <= 18) continue;
                    minX = Mathf.Min(minX, x);
                    minY = Mathf.Min(minY, y);
                    maxX = Mathf.Max(maxX, x);
                    maxY = Mathf.Max(maxY, y);
                }
                if (maxX >= minX && maxY >= minY)
                    textureRect = Rect.MinMaxRect(minX, minY, maxX + 1f, maxY + 1f);
            }
            catch (System.Exception)
            {
                // Imported production textures may be uploaded non-readable. Their authored
                // textureRect remains the safe fallback.
            }
            GuiOpaqueUvCache[sprite] = textureRect;
            return textureRect;
        }

        private static int CanonicalCardMetric(string textureName, string marker)
        {
            var start = textureName.LastIndexOf(marker, StringComparison.Ordinal);
            if (start < 0) return -1;
            start += marker.Length;
            var end = start;
            while (end < textureName.Length && char.IsDigit(textureName[end])) end++;
            return end > start && int.TryParse(textureName.Substring(start, end - start), out var value)
                ? value
                : -1;
        }

        internal static float SpriteGuiOpaqueFillForQa(Sprite sprite)
        {
            if (sprite == null || sprite.textureRect.height <= 0f) return 0f;
            return SpriteGuiOpaquePixelRect(sprite).height / sprite.textureRect.height;
        }

        private void DrawSelectedUnitStatus()
        {
            if (selectedUnits.Count != 1 || selectedUnits[0] == null) return;
            var unit = selectedUnits[0];
            var rect = SelectedUnitStatusRect();
            DrawOrnatePanel(rect, new Color(.02f, .04f, .085f, .97f), new Color(.32f, .62f, .86f), 2f);
            var level = unit.IsHero ? "HERO" : $"Lv.{unit.Level}";
            var titleStyle = new GUIStyle(statStyle)
            {
                fontSize = 14, fontStyle = FontStyle.Bold, alignment = TextAnchor.MiddleCenter,
                clipping = TextClipping.Clip
            };
            DrawFittedLabel(new Rect(rect.x + 9f, rect.y + 3f, rect.width - 18f, 21f),
                $"{unit.DisplayName} · {level}", titleStyle, 11);
            DrawPanel(new Rect(rect.x + 10f, rect.y + 27f, rect.width - 20f, 2f),
                new Color(.36f, .68f, .91f, .92f));
            var statsRect = SelectedUnitStatsRect();
            var compactStatStyle = new GUIStyle(statStyle)
            {
                fontSize = 14, alignment = TextAnchor.MiddleLeft, clipping = TextClipping.Clip
            };
            var statCells = SelectedUnitStatCells(unit);
            const int statColumns = 4;
            const float statColumnGap = 6f;
            var statRowHeight = SelectedUnitStatRowHeight();
            var statColumnWidth = (statsRect.width - statColumnGap * (statColumns - 1)) / statColumns;
            for (var i = 0; i < statCells.Length; i++)
            {
                var column = i % statColumns;
                var row = i / statColumns;
                var cell = new Rect(statsRect.x + column * (statColumnWidth + statColumnGap),
                    statsRect.y + row * statRowHeight, statColumnWidth, statRowHeight);
                var needsWrappedCell = GameLocalization.Current != GameLanguage.Korean ||
                                       SafeGuiRect.width < 370f || i == 6;
                if (!needsWrappedCell)
                    DrawFittedLabel(cell, statCells[i], compactStatStyle, 10);
                else
                    DrawFittedWrappedLabel(cell, statCells[i], compactStatStyle, 8);
            }

            var skillRect = SelectedUnitSkillRect();
            var skillState = unit.SkillCooldownRemaining <= 0f
                ? L("준비", "READY")
                : L($"{unit.SkillCooldownRemaining:0.0}초", $"{unit.SkillCooldownRemaining:0.0}s");
            DrawPanel(new Rect(skillRect.x, skillRect.y + 3f, 3f, skillRect.height - 6f),
                new Color(.48f, .82f, 1f, .92f));
            var skillStyle = new GUIStyle(statStyle)
            {
                fontSize = 13, fontStyle = FontStyle.Bold, alignment = TextAnchor.MiddleLeft,
                clipping = TextClipping.Clip
            };
            var skillLabel = L($"스킬 : {unit.SkillName}  {skillState}",
                $"SKILL: {unit.SkillName}  {skillState}");
            var skillLabelRect = new Rect(skillRect.x + 9f, skillRect.y, skillRect.width - 9f,
                skillRect.height);
            if (GameLocalization.Current == GameLanguage.Korean)
                DrawFittedLabel(skillLabelRect, skillLabel, skillStyle, 10);
            else
                DrawFittedWrappedLabel(skillLabelRect, skillLabel, skillStyle, 8);

            if (!unit.IsHero) return;
            var ultimateRect = SelectedUnitUltimateRect();
            var ultimateLabel = unit.UltimateCooldownRemaining <= 0f
                ? L($"궁극기 : {unit.UltimateName}  사용", $"ULTIMATE: {unit.UltimateName}  USE")
                : L($"궁극기 : {unit.UltimateName}  {unit.UltimateCooldownRemaining:0.0}초",
                    $"ULTIMATE: {unit.UltimateName}  {unit.UltimateCooldownRemaining:0.0}s");
            if (DrawSelectedUnitUltimateButton(ultimateRect, ultimateLabel, unit.CanUseUltimate))
            {
                if (!unit.TryUseUltimate()) ShowToast(UltimateContextRequirement(unit));
            }
        }

        private bool DrawSelectedUnitUltimateButton(Rect rect, string label, bool enabled)
        {
            var fill = enabled ? new Color(.18f, .08f, .22f, .98f) : new Color(.055f, .06f, .08f, .96f);
            var accent = enabled ? new Color(.9f, .54f, 1f) : new Color(.34f, .37f, .46f);
            DrawOrnatePanel(rect, fill, accent, 2f);
            var clicked = GUI.Button(rect, GUIContent.none, GUIStyle.none);
            var previous = GUI.color;
            GUI.color = enabled ? Color.white : new Color(.66f, .69f, .76f);
            var labelRect = new Rect(rect.x + 7f, rect.y + 3f, rect.width - 14f, rect.height - 6f);
            var labelStyle = new GUIStyle(premiumButtonLabelStyle)
            {
                fontSize = GameLocalization.Current == GameLanguage.Korean ? 13 : 11,
                fontStyle = FontStyle.Bold,
                alignment = TextAnchor.MiddleCenter,
                clipping = TextClipping.Clip
            };
            if (rect.width >= 175f && GameLocalization.Current == GameLanguage.Korean)
                DrawFittedLabel(labelRect, label, labelStyle, 10);
            else
                DrawFittedWrappedLabel(labelRect, label, labelStyle, 8);
            GUI.color = previous;
            return enabled && clicked;
        }

        private string SelectedUnitPrimaryStats(PlayerUnit unit) =>
            L($"HP {Mathf.CeilToInt(unit.Health)}/{Mathf.CeilToInt(unit.MaxHealth)}  |  공격 {unit.AttackPower:0}  |  마력 {unit.MagicPower:0}",
                $"HP {Mathf.CeilToInt(unit.Health)}/{Mathf.CeilToInt(unit.MaxHealth)}  |  ATK {unit.AttackPower:0}  |  MAG {unit.MagicPower:0}");

        private string SelectedUnitDefenseAndPenetration(PlayerUnit unit) =>
            L($"방어 {unit.Armor:0}  |  마저 {unit.MagicResistance:0}  |  방관 {unit.PhysicalPenetration:0}  |  마관 {unit.MagicPenetration:0}",
                $"DEF {unit.Armor:0}  |  RES {unit.MagicResistance:0}  |  ARM PEN {unit.PhysicalPenetration:0}  |  MAG PEN {unit.MagicPenetration:0}");

        private string SelectedUnitCombatRangesAndCritical(PlayerUnit unit)
        {
            var chance = Mathf.RoundToInt(GetCriticalChance(unit) * 100f);
            var damage = Mathf.RoundToInt(GetCriticalDamageMultiplier(unit) * 100f);
            return L($"사거리 {unit.AttackRange:0.00}  |  탐지 {unit.DetectionRange:0.00}  |  치명 {chance}%  |  치피 {damage}%",
                $"RNG {unit.AttackRange:0.00}  |  DET {unit.DetectionRange:0.00}  |  CRIT {chance}%  |  C.DMG {damage}%");
        }

        private string[] SelectedUnitStatCells(PlayerUnit unit)
        {
            var chance = Mathf.RoundToInt(GetCriticalChance(unit) * 100f);
            var damage = Mathf.RoundToInt(GetCriticalDamageMultiplier(unit) * 100f);
            var usesMagic = SelectedUnitUsesMagicStats(unit);
            var primaryPower = usesMagic
                ? L($"마력 {unit.MagicPower:0}", $"MAGIC {unit.MagicPower:0}")
                : L($"공격력 {unit.AttackPower:0}", $"ATTACK {unit.AttackPower:0}");
            var primaryPenetration = usesMagic
                ? L($"마법 관통 {unit.MagicPenetration:0}",
                    $"MAGIC PENETRATION {unit.MagicPenetration:0}")
                : L($"방어력 관통 {unit.PhysicalPenetration:0}",
                    $"ARMOR PENETRATION {unit.PhysicalPenetration:0}");
            return new[]
            {
                $"HP {Mathf.CeilToInt(unit.Health)}/{Mathf.CeilToInt(unit.MaxHealth)}",
                primaryPower,
                L($"방어력 {unit.Armor:0}", $"ARMOR {unit.Armor:0}"),
                L($"마법 저항 {unit.MagicResistance:0}", $"MAGIC RESIST {unit.MagicResistance:0}"),
                primaryPenetration,
                L($"공격 사거리 {unit.AttackRange:0.00}", $"ATTACK RANGE {unit.AttackRange:0.00}"),
                L($"치명타 {chance}% · 피해 {damage}%", $"CRITICAL {chance}% · DAMAGE {damage}%"),
                unit.IsHero
                    ? L("경험치 MAX", "EXPERIENCE MAX")
                    : L($"경험치 {Mathf.FloorToInt(unit.ExperienceWithinCurrentLevel())}/" +
                        $"{Mathf.CeilToInt(unit.ExperienceRequiredForCurrentLevel())}",
                        $"EXPERIENCE {Mathf.FloorToInt(unit.ExperienceWithinCurrentLevel())}/" +
                        $"{Mathf.CeilToInt(unit.ExperienceRequiredForCurrentLevel())}")
            };
        }

        // The HUD follows the unit's authored basic-combat identity, never whichever live stat
        // happens to be numerically larger after augments. Hybrid bombardiers remain physical
        // because their basic shell uses attack/armor penetration; their magic is skill support.
        private static bool SelectedUnitUsesMagicStats(PlayerUnit unit) =>
            unit != null && unit.Archetype is UnitArchetype.AreaMage or UnitArchetype.SingleMage or
                UnitArchetype.Druid or UnitArchetype.Oracle;

        private Rect SelectedSquadPortraitRailRect()
        {
            var alive = selectedUnits.Count(unit => unit != null && unit.IsAlive);
            if (alive <= 1) return Rect.zero;
            var safe = SafeGuiRect;
            var top = safe.y + TopHudHeight + 8f;
            if (selectionPortraitRailCollapsed)
                return new Rect(safe.x + 6f, top, 44f, 38f);
            var available = Mathf.Max(72f, safe.yMax - BottomHudHeight - top - 8f);
            var visible = Mathf.Clamp(Mathf.FloorToInt((available - 34f) / 52f), 1, 7);
            visible = Mathf.Min(visible, alive);
            return new Rect(safe.x + 6f, top, 64f, 37f + visible * 52f);
        }

        private void DrawSelectedSquadPortraitRail()
        {
            var roster = selectedUnits.Where(unit => unit != null && unit.IsAlive)
                .OrderByDescending(unit => unit.IsHero).ThenByDescending(unit => unit.Level).ToArray();
            if (roster.Length <= 1) return;
            var panel = SelectedSquadPortraitRailRect();
            if (panel.width <= 0f) return;
            DrawOrnatePanel(panel, new Color(.018f, .035f, .07f, .78f),
                new Color(.36f, .66f, .86f, .82f), 1.5f);
            var toggle = selectionPortraitRailCollapsed
                ? panel
                : new Rect(panel.x + 5f, panel.y + 4f, panel.width - 10f, 25f);
            if (GUI.Button(toggle, selectionPortraitRailCollapsed ? $"> {roster.Length}" : "<", centeredStyle))
            {
                selectionPortraitRailCollapsed = !selectionPortraitRailCollapsed;
                return;
            }
            if (selectionPortraitRailCollapsed) return;

            var visible = Mathf.Min(roster.Length, Mathf.FloorToInt((panel.height - 35f) / 52f));
            for (var i = 0; i < visible; i++)
            {
                var unit = roster[i];
                var card = new Rect(panel.x + 7f, panel.y + 33f + i * 52f, panel.width - 14f, 46f);
                DrawOrnatePanel(card,
                    unit.IsHero ? new Color(.15f, .075f, .02f, .9f) : new Color(.025f, .07f, .12f, .88f),
                    unit.IsHero ? new Color(1f, .76f, .22f) : new Color(.34f, .67f, .9f), 1.5f);
                // The rail is tactical UI, not another live actor viewport. Always use the
                // normalized front card for the unit's equipped skin and current hero state so
                // walking direction, attack frames and unequal sprite padding cannot resize it.
                var portrait = FixedSelectionPortrait(unit);
                if (portrait != null)
                    DrawSpriteContained(new Rect(card.x + 3f, card.y + 2f, card.width - 6f, 38f), portrait);
                GUI.Label(new Rect(card.x + 1f, card.yMax - 14f, card.width - 2f, 13f),
                    unit.IsHero ? "HERO" : $"Lv.{unit.Level}",
                    new GUIStyle(centeredStyle) { fontSize = 9 });
                if (!GUI.Button(card, GUIContent.none, GUIStyle.none)) continue;
                SelectOnly(unit);
                return;
            }
            if (roster.Length > visible)
                GUI.Label(new Rect(panel.x, panel.yMax - 17f, panel.width, 14f), $"+{roster.Length - visible}",
                    new GUIStyle(centeredStyle) { fontSize = 9 });
        }

        private Sprite FixedSelectionPortrait(PlayerUnit unit) => unit == null
            ? null
            : GetEquippedUnitCardSprite(unit.Archetype, unit.IsHero);

