        private void DrawAugmentSummary()
        {
            DrawAugmentSummaryV2();
            return;
            var panel = AugmentSummaryRect();
            DrawOrnatePanel(panel, new Color(.025f, .04f, .085f, .97f), new Color(.48f, .39f, .68f), 3f);
            GUI.Label(new Rect(panel.x + 12f, panel.y + 9f, panel.width - 24f, 36f), "보유 증강", modalTitleStyle);
            if (augmentCount.Count == 0)
            {
                GUI.Label(new Rect(panel.x + 10f, panel.y + 52f, panel.width - 20f, 40f), "아직 선택한 증강이 없습니다.", centeredStyle);
                return;
            }

            var y = panel.y + 51f;
            var shown = 0;
            foreach (var pair in augmentCount)
            {
                if (shown >= 8 || y + 27f > panel.yMax - 8f) break;
