        private void DrawAugmentSummaryV2()
        {
            var safe = SafeGuiRect;
            var panel = new Rect(safe.x + safe.width * .16f, safe.y + 116f,
                safe.width * .72f, Mathf.Min(400f, safe.height * .56f));
            DrawOrnatePanel(panel, new Color(.018f, .03f, .07f, .985f), new Color(.62f, .53f, .82f), 3f);
            var header = new GUIStyle(modalTitleStyle) { fontSize = 26, alignment = TextAnchor.MiddleCenter };
            GUI.Label(new Rect(panel.x + 10f, panel.y + 8f, panel.width - 20f, 34f),
                L("획득한 증강", "OWNED AUGMENTS"), header);
            if (acquiredAugments.Count == 0)
            {
                GUI.Label(new Rect(panel.x + 12f, panel.y + 52f, panel.width - 24f, 38f),
                    L("아직 획득한 증강이 없습니다.", "No augments acquired yet."), centeredStyle);
                return;
            }

            var offers = acquiredAugments.Values.OrderBy(offer => offer.Tier).ThenBy(offer => offer.Name).ToList();
            if (string.IsNullOrEmpty(inspectedAugmentKey) || !acquiredAugments.ContainsKey(inspectedAugmentKey))
                inspectedAugmentKey = offers[0].EffectKey;
            var detail = acquiredAugments[inspectedAugmentKey];
            var rowY = panel.y + 48f;
            const float rowHeight = 36f;
            var listViewport = new Rect(panel.x + 10f, rowY, panel.width - 20f,
                Mathf.Max(92f, panel.height - 166f));
            var contentWidth = listViewport.width - 18f;
            var contentHeight = Mathf.Max(listViewport.height, offers.Count * (rowHeight + 4f));
            var blockOfferClick = HandleAugmentSummaryTouchDrag(listViewport, contentHeight);
            augmentSummaryScroll = GUI.BeginScrollView(listViewport, augmentSummaryScroll,
                new Rect(0f, 0f, contentWidth, contentHeight), false, true);
            for (var i = 0; i < offers.Count; i++)
            {
                var offer = offers[i];
                var tier = TierColor(offer.Tier);
                var rect = new Rect(2f, i * (rowHeight + 4f), contentWidth - 4f, rowHeight);
                DrawFramedPanel(rect, offer.EffectKey == inspectedAugmentKey
                    ? new Color(.08f, .095f, .15f, .98f)
                    : new Color(.035f, .05f, .10f, .95f), tier, 2f);
                if (!blockOfferClick && GUI.Button(rect, GUIContent.none, GUIStyle.none))
                    inspectedAugmentKey = offer.EffectKey;
                var chip = new Rect(rect.x + 5f, rect.y + 5f, 72f, rect.height - 10f);
                DrawFramedPanel(chip, new Color(.02f, .03f, .07f, .98f), tier, 1.5f);
                GUI.Label(chip, TierName(offer.Tier), new GUIStyle(smallStyle) { alignment = TextAnchor.MiddleCenter, fontSize = 11 });
                var stacks = augmentCount.TryGetValue(offer.Name, out var count) ? count : 1;
                GUI.Label(new Rect(chip.xMax + 8f, rect.y + 2f, rect.width - chip.width - 55f, rect.height - 4f),
                    offer.Name, new GUIStyle(smallStyle) { fontSize = 16, alignment = TextAnchor.MiddleLeft });
                GUI.Label(new Rect(rect.xMax - 40f, rect.y + 2f, 34f, rect.height - 4f), $"x{stacks}",
                    new GUIStyle(smallStyle) { fontSize = 15, alignment = TextAnchor.MiddleCenter });
            }
            GUI.EndScrollView();

            var detailTop = listViewport.yMax + 6f;
            var detailRect = new Rect(panel.x + 12f, detailTop, panel.width - 24f, Mathf.Max(58f, panel.yMax - detailTop - 11f));
            var detailColor = TierColor(detail.Tier);
            DrawFramedPanel(detailRect, new Color(.025f, .04f, .085f, .98f), detailColor, 2f);
            GUI.Label(new Rect(detailRect.x + 10f, detailRect.y + 5f, detailRect.width - 20f, 22f),
                $"{TierName(detail.Tier)}  ·  {detail.Name}",
                new GUIStyle(smallStyle) { alignment = TextAnchor.MiddleCenter, fontSize = 15 });
            GUI.Label(new Rect(detailRect.x + 12f, detailRect.y + 28f, detailRect.width - 24f, detailRect.height - 32f),
                detail.Description, new GUIStyle(augmentDescriptionStyle) { fontSize = 14, alignment = TextAnchor.MiddleCenter });
        }

        private bool HandleAugmentSummaryTouchDrag(Rect viewport, float contentHeight)
        {
            var evt = Event.current;
            var suppressOfferClick = false;
            if (evt.type == EventType.MouseDown && evt.button == 0 && viewport.Contains(evt.mousePosition))
            {
                augmentSummaryDragTracking = true;
                augmentSummaryDragActive = false;
                augmentSummaryDragStart = augmentSummaryDragLast = evt.mousePosition;
            }
            else if (evt.type == EventType.MouseDrag && augmentSummaryDragTracking)
            {
                if (!augmentSummaryDragActive &&
                    Vector2.Distance(augmentSummaryDragStart, evt.mousePosition) >= 7f)
                    augmentSummaryDragActive = true;
                if (augmentSummaryDragActive)
                {
                    var delta = evt.mousePosition - augmentSummaryDragLast;
                    augmentSummaryScroll.y = Mathf.Clamp(augmentSummaryScroll.y - delta.y, 0f,
                        Mathf.Max(0f, contentHeight - viewport.height));
                    suppressOfferClick = true;
                    evt.Use();
                }
                augmentSummaryDragLast = evt.mousePosition;
            }
            else if (evt.type == EventType.MouseUp && augmentSummaryDragTracking)
            {
                suppressOfferClick = augmentSummaryDragActive;
                augmentSummaryDragTracking = false;
                augmentSummaryDragActive = false;
                if (suppressOfferClick) evt.Use();
            }
            return suppressOfferClick || augmentSummaryDragActive;
        }

        private static void DrawPanel(Rect rect, Color color)
        {
            var previous = GUI.color;
            GUI.color = color;
            GUI.DrawTexture(rect, Texture2D.whiteTexture);
            GUI.color = previous;
        }

        private static void DrawFramedPanel(Rect rect, Color fill, Color border, float thickness)
        {
            DrawPanel(rect, border);
            DrawPanel(new Rect(rect.x + thickness, rect.y + thickness,
                Mathf.Max(0f, rect.width - thickness * 2f), Mathf.Max(0f, rect.height - thickness * 2f)), fill);
        }

        private static void DrawOrnatePanel(Rect rect, Color fill, Color accent, float thickness = 3f)
        {
            DrawPanel(new Rect(rect.x + 3f, rect.y + 5f, rect.width, rect.height), new Color(.01f, .015f, .03f, .5f));
            DrawPanel(rect, new Color(.015f, .025f, .055f, .98f));
            DrawPanel(new Rect(rect.x + 2f, rect.y + 2f, rect.width - 4f, rect.height - 4f), accent);
            DrawPanel(new Rect(rect.x + 2f + thickness, rect.y + 2f + thickness,
                rect.width - 4f - thickness * 2f, rect.height - 4f - thickness * 2f), fill);

            const float corner = 13f;
            const float line = 3f;
            DrawPanel(new Rect(rect.x + 2f, rect.y + 2f, corner, line), accent);
            DrawPanel(new Rect(rect.x + 2f, rect.y + 2f, line, corner), accent);
            DrawPanel(new Rect(rect.xMax - corner - 2f, rect.y + 2f, corner, line), accent);
            DrawPanel(new Rect(rect.xMax - line - 2f, rect.y + 2f, line, corner), accent);
            DrawPanel(new Rect(rect.x + 2f, rect.yMax - line - 2f, corner, line), accent);
            DrawPanel(new Rect(rect.x + 2f, rect.yMax - corner - 2f, line, corner), accent);
            DrawPanel(new Rect(rect.xMax - corner - 2f, rect.yMax - line - 2f, corner, line), accent);
            DrawPanel(new Rect(rect.xMax - line - 2f, rect.yMax - corner - 2f, line, corner), accent);
        }

        private bool DrawPremiumButton(Rect rect, string label, Color fill, Color accent, bool enabled = true)
        {
            DrawOrnatePanel(rect, enabled ? fill : new Color(.055f, .065f, .08f, .94f),
                enabled ? accent : new Color(.22f, .25f, .3f), 2f);
            var clicked = GUI.Button(rect, GUIContent.none, GUIStyle.none);
            var previous = GUI.color;
            GUI.color = enabled ? Color.white : new Color(.55f, .58f, .64f);
            DrawFittedLabel(new Rect(rect.x + 7f, rect.y + 3f, rect.width - 14f, rect.height - 6f),
                label, premiumButtonLabelStyle, 8);
            GUI.color = previous;
            return enabled && clicked;
        }

        private static void DrawFittedLabel(Rect rect, string text, GUIStyle source, int minimumFontSize)
        {
            var style = new GUIStyle(source)
            {
                wordWrap = false,
                clipping = TextClipping.Clip
            };
            var content = new GUIContent(text ?? string.Empty);
            var availableWidth = Mathf.Max(1f, rect.width - 2f);
            var availableHeight = Mathf.Max(1f, rect.height - 2f);
            style.fontSize = Mathf.Max(minimumFontSize, style.fontSize);
            while (style.fontSize > minimumFontSize)
            {
                var size = style.CalcSize(content);
                if (size.x <= availableWidth && size.y <= availableHeight) break;
                style.fontSize--;
            }
            GUI.Label(rect, content, style);
        }

        internal static bool FittedLabelFitsForQa(Rect rect, string text, GUIStyle source,
            int minimumFontSize)
        {
            var style = new GUIStyle(source)
            {
                wordWrap = false,
                clipping = TextClipping.Clip,
                fontSize = Mathf.Max(minimumFontSize, source.fontSize)
            };
            var content = new GUIContent(text ?? string.Empty);
            var availableWidth = Mathf.Max(1f, rect.width - 2f);
            var availableHeight = Mathf.Max(1f, rect.height - 2f);
            while (style.fontSize > minimumFontSize)
            {
                var current = style.CalcSize(content);
                if (current.x <= availableWidth && current.y <= availableHeight) break;
                style.fontSize--;
            }
            var size = style.CalcSize(content);
            return size.x <= availableWidth + .01f && size.y <= availableHeight + .01f;
        }

        private static void DrawFittedWrappedLabel(Rect rect, string text, GUIStyle source,
            int minimumFontSize)
        {
            var style = new GUIStyle(source)
            {
                wordWrap = true,
                clipping = TextClipping.Clip,
                fontSize = Mathf.Max(minimumFontSize, source.fontSize)
            };
            var content = new GUIContent(text ?? string.Empty);
            var availableHeight = Mathf.Max(1f, rect.height - 2f);
            while (style.fontSize > minimumFontSize &&
                   style.CalcHeight(content, Mathf.Max(1f, rect.width - 2f)) > availableHeight)
                style.fontSize--;
            GUI.Label(rect, content, style);
        }

        internal static bool FittedWrappedLabelFitsForQa(Rect rect, string text, GUIStyle source,
            int minimumFontSize)
        {
            var style = new GUIStyle(source)
            {
                wordWrap = true,
                clipping = TextClipping.Clip,
                fontSize = Mathf.Max(minimumFontSize, source.fontSize)
            };
            var content = new GUIContent(text ?? string.Empty);
            var availableHeight = Mathf.Max(1f, rect.height - 2f);
            while (style.fontSize > minimumFontSize &&
                   style.CalcHeight(content, Mathf.Max(1f, rect.width - 2f)) > availableHeight)
                style.fontSize--;
            return style.CalcHeight(content, Mathf.Max(1f, rect.width - 2f)) <= availableHeight + .01f;
        }

        private void DrawSelectionBox()
        {
            var scale = UiScale;
