                var rect = new Rect(panel.x + 17f, cardTop + i * (cardHeight + gap), panel.width - 34f, cardHeight);
                var tierColor = TierColor(offer.Tier);
                DrawOrnatePanel(rect, new Color(.03f, .045f, .09f, .99f), tierColor, 3f);
                if (GUI.Button(rect, GUIContent.none, GUIStyle.none)) SelectAugment(offer);
                var tierChip = new Rect(rect.center.x - 62f, rect.y + 10f, 124f, 30f);
                DrawFramedPanel(tierChip, new Color(.025f, .035f, .07f, .98f), tierColor, 2f);
                GUI.Label(tierChip, $"◆  {TierName(offer.Tier)}", centeredStyle);
                GUI.Label(new Rect(rect.x + 20f, rect.y + 43f, rect.width - 40f, 42f),
                    offer.Name, augmentNameStyle);
                GUI.Label(new Rect(rect.x + 24f, rect.y + 84f, rect.width - 48f, rect.height - 92f),
                    offer.Description, augmentDescriptionStyle);
            }
        }

        private void DrawToyfrontAugmentOverlay()
        {
            var safe = SafeGuiRect;
            var panelWidth = safe.width * .94f;
            var panelHeight = safe.height * .86f;
            var panel = new Rect(safe.center.x - panelWidth * .5f, safe.center.y - panelHeight * .5f, panelWidth, panelHeight);
            DrawPanel(new Rect(0f, 0f, GuiWidth, GuiHeight), new Color(0f, 0f, .025f, .54f));
            DrawOrnatePanel(panel, new Color(.018f, .03f, .075f, .985f), new Color(.68f, .52f, .92f), 4f);
            var title = new GUIStyle(overlayTitleStyle) { fontSize = 38, alignment = TextAnchor.MiddleCenter };
            var desc = new GUIStyle(augmentDescriptionStyle) { fontSize = 19, alignment = TextAnchor.MiddleCenter };
            GUI.Label(new Rect(panel.x + 14f, panel.y + 15f, panel.width - 28f, 52f), L("증강 선택", "CHOOSE AN AUGMENT"), title);
            GUI.Label(new Rect(panel.x + 24f, panel.y + 66f, panel.width - 48f, 28f),
                L("이번 전선의 전략을 완성하세요", "DEFINE THIS FRONTLINE'S STRATEGY"), desc);
            if (DrawPremiumButton(new Rect(panel.xMax - 112f, panel.y + 16f, 92f, 40f), L("숨기기", "HIDE"),
                    new Color(.05f, .07f, .12f, .98f), new Color(.5f, .62f, .82f), true)) augmentOverlayHidden = true;
            var cardTop = panel.y + 105f;
            var gap = 12f;
            var cardHeight = (panel.height - 124f - gap * 2f) / 3f;
            for (var i = 0; i < currentOffers.Length; i++)
            {
                var offer = currentOffers[i];
                var rect = new Rect(panel.x + 15f, cardTop + i * (cardHeight + gap), panel.width - 30f, cardHeight);
                var tierColor = TierColor(offer.Tier);
                DrawOrnatePanel(rect, new Color(.035f, .052f, .105f, .99f), tierColor, 3f);
                if (GUI.Button(rect, GUIContent.none, GUIStyle.none)) SelectAugment(offer);
                var tierChip = new Rect(rect.center.x - 72f, rect.y + 9f, 144f, 30f);
                DrawFramedPanel(tierChip, new Color(.025f, .04f, .08f, .98f), tierColor, 2f);
                GUI.Label(tierChip, GameLocalization.Tier(offer.Tier), centeredStyle);
                GUI.Label(new Rect(rect.x + 18f, rect.y + 43f, rect.width - 36f, 39f), offer.Name, augmentNameStyle);
                GUI.Label(new Rect(rect.x + 22f, rect.y + 81f, rect.width - 44f, rect.height - 88f), offer.Description, desc);
            }
        }

        private void DrawAugmentRestoreButton()
        {
            var safe = SafeGuiRect;
            var rect = new Rect(safe.x + safe.width * .22f, safe.y + safe.height * .72f, safe.width * .56f, 66f);
            if (DrawPremiumButton(rect, L("증강 선택 다시 열기", "REOPEN AUGMENT CHOICE"), new Color(.075f, .045f, .12f, .98f),
