        private void DrawVictoryOverlay()
        {
            DrawPanel(new Rect(0f, 0f, GuiWidth, GuiHeight), new Color(.015f, .035f, .08f, .9f));
            var safe = SafeGuiRect;
            var panel = new Rect(safe.x + safe.width * .08f, safe.y + safe.height * .31f,
                safe.width * .84f, safe.height * .34f);
            DrawOrnatePanel(panel, new Color(.035f, .065f, .105f, .99f),
                new Color(1f, .78f, .25f), 5f);
            GUI.Label(new Rect(panel.x + 14f, panel.y + 24f, panel.width - 28f, 56f),
                L("50단계 정복 완료", "50 FRONTS CONQUERED"), overlayTitleStyle);
            GUI.Label(new Rect(panel.x + 24f, panel.y + 83f, panel.width - 48f, 52f),
                L("열 개의 몬스터 전선을 모두 돌파했습니다.", "ALL TEN MONSTER CAMPAIGNS DEFEATED."),
                centeredStyle);
            if (!string.IsNullOrEmpty(victoryRewardText))
                GUI.Label(new Rect(panel.x + 24f, panel.y + 124f, panel.width - 48f, 44f),
                    victoryRewardText, centeredStyle);
            var buttonY = panel.yMax - 68f;
            if (DrawPremiumButton(new Rect(panel.x + 18f, buttonY, panel.width * .48f - 22f, 50f),
                    L("다시 도전", "PLAY AGAIN"), new Color(.16f, .1f, .025f, .98f),
                    new Color(1f, .76f, .24f), true)) RestartGame();
            if (DrawPremiumButton(new Rect(panel.center.x + 4f, buttonY, panel.width * .48f - 22f, 50f),
                    L("메인 메뉴", "MAIN MENU"), new Color(.035f, .06f, .1f, .98f),
                    new Color(.45f, .68f, .9f), true))
            {
                RestartGame();
                showMainMenu = true;
                mainMenuInputReadyAt = Time.unscaledTime + .42f;
                voiceBarks?.SetBattleMusic(false, true);
            }
        }

        private void DrawDefeatOverlay()
        {
            GUI.color = new Color(.02f, .04f, .1f, .9f);
            GUI.DrawTexture(new Rect(0, 0, GuiWidth, GuiHeight), Texture2D.whiteTexture);
            GUI.color = Color.white;
            var safe = SafeGuiRect;
            var panel = new Rect(safe.x + safe.width * .12f, safe.y + safe.height * .35f, safe.width * .76f, safe.height * .25f);
            DrawOrnatePanel(panel, new Color(.035f, .045f, .075f, .98f), new Color(.82f, .35f, .25f), 4f);
            GUI.Label(new Rect(panel.x, panel.y + 18f, panel.width, 52f),
                L("성문이 파괴됐습니다", "THE GATE HAS FALLEN"), overlayTitleStyle);
            if (DrawPremiumButton(new Rect(panel.x + 18f, panel.y + panel.height - 68f, panel.width * .48f - 22f, 50f),
                    L("처음부터 다시", "RESTART"), new Color(.14f, .06f, .045f, .98f), new Color(.92f, .45f, .28f))) RestartGame();
            if (DrawPremiumButton(new Rect(panel.center.x + 4f, panel.y + panel.height - 68f, panel.width * .48f - 22f, 50f),
                    L("메인 메뉴", "MAIN MENU"), new Color(.04f, .055f, .085f, .98f), new Color(.42f, .56f, .72f)))
            {
                RestartGame();
                showMainMenu = true;
                mainMenuInputReadyAt = Time.unscaledTime + .42f;
            }
        }

        private void RestartGame(bool clearCheckpoint = true)
        {
            if (clearCheckpoint) ClearRunCheckpoint();
            StopAllCoroutines();
            ClearTransientBattlePresentation();
            ClearAttackOrderMarker();
            foreach (var unit in units) if (unit != null) Destroy(unit.gameObject);
            foreach (var enemy in enemies) if (enemy != null) Destroy(enemy.gameObject);
            units.Clear(); enemies.Clear(); ClearSelection(); augmentPower.Clear(); augmentCount.Clear();
            acquiredAugments.Clear(); activeAugmentReadyAt.Clear(); unlockedUnits.Clear();
            monstersDefeated = 0; skillsCast = 0; roundsCleared = 0; unitsPlaced = 0;
            nextPlacementBatchId = 1;
            Round = 1;
            Money = 19;
            gateHealth = GateMaxHealth;
            lastTier = AugmentTier.Bronze;
            augmentOffersWithoutHighTier = 0;
            buildMode = UnitArchetype.None;
            spawning = false;
            runInProgress = false;
            lastStandCharges = 0;
            bossFormationSpawnCount = 0;
            Phase = GamePhase.Preparation;
            toastText = bossWarningText = string.Empty;
            toastUntil = bossWarningUntil = 0f;
            pointerHeld = pointerDragged = false;
            pressedUnit = null;
            pressedEnemy = null;
            showShopPanel = showSkinPanel = showMissionPanel = showGuidePanel = showSettings = false;
            victoryRewardText = string.Empty;
            showFormationPanel = true; showAugmentSummary = false; augmentOverlayHidden = false; inspectedAugmentKey = string.Empty;
            currentOffers = Array.Empty<AugmentOffer>();
            ApplyBattlefieldMood(MonsterClassForRound(1), true);
        }

        private void ClearTransientBattlePresentation()
        {
            TransientBattleEffect.ClearAll();
            activeEnemyClassEffects = 0;
            activeHitFeedbackEffects = 0;
            hitFeedbackVisualsThisFrame = 0;
            movementDustVisualsThisFrame = 0;
        }

        private static Color TierColor(AugmentTier tier) => tier switch
        {
            AugmentTier.Bronze => new Color(.78f, .55f, .38f), AugmentTier.Silver => new Color(.7f, .77f, .86f),
            AugmentTier.Gold => new Color(1f, .78f, .22f), AugmentTier.Platinum => new Color(.35f, .85f, .78f),
            _ => new Color(.68f, .5f, .95f)
        };

        private static string TierName(AugmentTier tier) => GameLocalization.Tier(tier);
#pragma warning restore CS0162
    }
}
